(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-024"]={"sura":24,"name_ar":"النور","name_en":"An-Nur","verses":64,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":64,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=2\" class=\"link\">24:2</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:2 ஐ பார்க்கவும்"},"2":{"html":"<strong>மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>ஸூரத்துந் நூரின் முக்கியத்துவம்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُورَةٌ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَـهَا</span><br />\r\n<br />\r\n(இது நாம் இறக்கிய ஓர் அத்தியாயமாகும்.) இங்கே அல்லாஹ் இந்த அத்தியாயத்திற்கு (ஸூரா) தான் வழங்கும் உயர் கண்ணியத்தைச் சுட்டிக்காட்டுகிறான். இதன் பொருள் மற்ற அத்தியாயங்கள் முக்கியமற்றவை என்பதல்ல.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَفَرَضْنَـهَا</span><br />\r\n<br />\r\n(இதனை நாம் கடமையாக்கினோம்.) முஜாஹித் (ரஹ்) மற்றும் கதாதா (ரஹ்) ஆகியோர் கூறினார்கள்: \"இதன் பொருள்: அனுமதிக்கப்பட்டவை (ஹலால்), விலக்கப்பட்டவை (ஹராம்), கட்டளைகள், விலக்கல்கள் மற்றும் விதிக்கப்பட்ட தண்டனைகளை நாம் இதில் விளக்கியுள்ளோம் என்பதாகும்.\" இமாம் புகாரி (ரஹ்) அவர்கள் கூறுகையில், \"இதனை 'ஃபரழ்னாஹா' என்று ஓதுபவர்கள், 'இதனை உங்கள் மீதும் உங்களுக்குப் பின் வருபவர்கள் மீதும் நாம் கடமையாக்கினோம்' என்று இதற்குப் பொருள் கொள்கின்றனர்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَآ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتٍ</span> <span class=\"quran-arabic-font text-success\">بَيِّنَـتٍ</span><br />\r\n<br />\r\n(மேலும், இதில் தெளிவான வசனங்களை நாம் அருளியுள்ளோம்,) அதாவது, தெளிவாக விளக்கப்பட்ட வசனங்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span><br />\r\n<br />\r\n(நீங்கள் நினைவு கூர்வதற்காக.)<br />\r\n<br />\r\n<strong>விபச்சாரத்திற்கான (ஸினா) தண்டனை குறித்த விளக்கம்</strong><br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الزَّانِيَةُ</span> <span class=\"quran-arabic-font text-success\">وَالزَّانِى</span> <span class=\"quran-arabic-font text-success\">فَاجْلِدُواْ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">وَاحِدٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمَا</span> <span class=\"quran-arabic-font text-success\">مِاْئَةَ</span> <span class=\"quran-arabic-font text-success\">جَلْدَةٍ</span><br />\r\n<br />\r\n(விபச்சாரம் செய்யும் பெண்ணுக்கும், விபச்சாரம் செய்யும் ஆணுக்கும், அவர்கள் ஒவ்வொருவருக்கும் நூறு கசையடிகள் வழங்குங்கள்.) இந்த கண்ணியமிக்க வசனம், சட்டவிரோத உடலுறவில் ஈடுபடும் நபருக்கான தண்டனைச் சட்டத்தையும், அதன் விவரங்களையும் உள்ளடக்கியுள்ளது. அத்தகைய நபர் ஒன்று திருமணமாகாதவராக இருப்பார் — அதாவது அவர் ஒருபோதும் திருமணம் செய்திருக்க மாட்டார்; அல்லது அவர் திருமணமானவராக இருப்பார் — அதாவது முறையான திருமண பந்தத்திற்குள் தாம்பத்திய உறவு கொண்ட சுதந்திரமான, பருவமடைந்த மற்றும் தெளிவான புத்தியுள்ள ஒருவராக இருப்பார். திருமணமாகாத கன்னிப் பெண்ணைப் பொறுத்தவரை, இந்த வசனத்தில் கூறப்பட்டுள்ளபடி நூறு கசையடிகளே தண்டனையாகும். அத்துடன் கூடுதலாக, அவர் தனது ஊரிலிருந்து ஒரு வருட காலத்திற்கு நாடு கடத்தப்பட வேண்டும். இது அபூ ஹுரைரா (ரழி) மற்றும் ஸைத் பின் காலித் அல்-ஜுஹானி (ரழி) ஆகியோரால் அறிவிக்கப்பட்டு புகாரி, முஸ்லிம் ஆகிய இரு பெரும் நூல்களிலும் பதிவாகியுள்ள ஒரு ஹதீஸில் இடம்பெற்றுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்த இரு கிராமவாசிகளில் ஒருவர் கூறினார்: \"அல்லாஹ்வின் தூதரே! என் மகன் இந்த மனிதரிடம் வேலைக்கு இருந்தான். அப்போது அவனுடைய மனைவியுடன் ஸினா செய்துவிட்டான். இதற்காக என் மகனின் சார்பாக நூறு ஆடுகளையும் ஓர் அடிமைப் பெண்ணையும் ஈட்டுத் தொகையாகக் கொடுத்தேன். பிறகு இது குறித்து அறிஞர்களிடம் நான் கேட்டபோது, என் மகனுக்கு நூறு கசையடிகளும் ஓராண்டு நாடு கடத்தப்படுதலுமே தண்டனை என்றும், இந்த மனிதனின் மனைவிக்குக் கல்லெறிந்து மரண தண்டனை (ரஜம்) விதிக்கப்பட வேண்டும் என்றும் அவர்கள் கூறினார்கள்.\" அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَأَقْضِيَنَّ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمَا</span> <span class=\"quran-arabic-font text-success\">بِكِتَابِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">تَعَالى،</span> <span class=\"quran-arabic-font text-success\">الْوَلِيدَةُ</span> <span class=\"quran-arabic-font text-success\">وَالْغَنَمُ</span> <span class=\"quran-arabic-font text-success\">رَدٌّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ،</span> <span class=\"quran-arabic-font text-success\">وَعَلى</span> <span class=\"quran-arabic-font text-success\">ابْنِكَ</span> <span class=\"quran-arabic-font text-success\">جَلْدُ</span> <span class=\"quran-arabic-font text-success\">مِائَةٍ</span> <span class=\"quran-arabic-font text-success\">وَتَغْرِيبُ</span> <span class=\"quran-arabic-font text-success\">عَامٍ،</span> <span class=\"quran-arabic-font text-success\">وَاغْدُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أُنَيْسُ</span> <span class=\"quran-arabic-font text-success\">لِرَجُلٍ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَسْلَمَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">امْرَأَةِ</span> <span class=\"quran-arabic-font text-success\">هذَا،فَإِنِ</span> <span class=\"quran-arabic-font text-success\">اعْتَرَفَتْ</span> <span class=\"quran-arabic-font text-success\">فَارْجُمْهَا</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! உங்கள் இருவருக்கும் இடையில் அல்லாஹ்வின் வேதத்தின்படி நான் தீர்ப்பளிப்பேன். அந்த அடிமைப் பெண்ணையும் ஆடுகளையும் நீ திரும்பப் பெற்றுக்கொள். உன் மகனுக்கு நூறு கசையடிகளும் ஓராண்டு நாடு கடத்தப்படுதலுமே தண்டனையாகும். உனைஸே! — அஸ்லம் கோத்திரத்தைச் சேர்ந்த ஒருவரிடம் கூறினார்கள் — நீ இந்த மனிதனின் மனைவியிடம் செல். அவள் தன் குற்றத்தை ஒப்புக்கொண்டால், அவளுக்குக் கல்லெறிந்து மரண தண்டனை நிறைவேற்று.) உனைஸ் (ரழி) அவளிடம் சென்றார், அவளும் ஒப்புக்கொண்டாள். எனவே அவர் அவளுக்குக் கல்லெறிந்து மரண தண்டனை நிறைவேற்றினார். சட்டவிரோத உடலுறவில் ஈடுபட்டவர் திருமணமாகாதவராக இருந்தால், நூறு கசையடிகளுடன் நாடு கடத்தலும் தண்டனையாகும் என்பதை இது காட்டுகிறது. ஆனால், முறையான திருமண பந்தத்தில் தாம்பத்திய உறவு கொண்ட, சுதந்திரமான, பருவமடைந்த, புத்தி சுவாதீனமுள்ள திருமணமானவராக இருந்தால், அவருக்குக் கல்லெறிந்து மரண தண்டனை வழங்கப்பட வேண்டும். இமாம் மாலிக் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் (ரழி) அவர்கள் எழுந்து நின்று அல்லாஹ்வைப் புகழ்ந்து போற்றிய பிறகு கூறினார்கள்: \"மக்களே! அல்லாஹ் முஹம்மது (ஸல்) அவர்களை சத்தியத்துடன் அனுப்பினான்; அவருக்கு வேதத்தையும் அருளினான். அவருக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி)களில் கல்லெறிந்து மரண தண்டனை விதிக்கும் வசனமும் ஒன்றாகும். அதை நாங்கள் ஓதினோம், விளங்கிக் கொண்டோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அத்தண்டனையை நிறைவேற்றினார்கள்; அவர்களுக்குப் பிறகு நாங்களும் அதனை நிறைவேற்றினோம். ஆனால் காலம் செல்லச் செல்ல, 'அல்லாஹ்வின் வேதத்தில் கல்லெறிந்து மரண தண்டனை விதிக்கும் வசனத்தை நாங்கள் காணவில்லை' என்று யாராவது கூறி, அல்லாஹ் விதித்த ஒரு கடமையை விட்டதன் காரணமாக அவர்கள் வழிதவறி விடுவார்களோ என்று நான் அஞ்சுகிறேன். திருமணமான ஒருவன் அல்லது ஒருத்தி விபச்சாரம் செய்து, அதற்குரிய சாட்சியங்கள் நிரூபிக்கப்பட்டாலோ அல்லது கர்ப்பம் ஏற்பட்டாலோ அல்லது அவர்களே ஒப்புக்கொண்டாலோ, அவர்களுக்குக் கல்லெறிந்து மரண தண்டனை விதிப்பது அல்லாஹ்வின் வேதத்தில் உள்ள ஒரு கடமையாகும்.\" இமாம் மாலிக் (ரஹ்) அவர்களின் இந்த நீண்ட ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது. அதன் ஒரு பகுதியை மட்டுமே நாம் இங்கே சுருக்கமாகக் குறிப்பிட்டுள்ளோம்.<br />\r\n<br />\r\n<strong>தண்டனையை நிறைவேற்றும்போது அவர்கள் மீது இரக்கம் காட்டாதீர்கள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَأْخُذْكُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِمَا</span> <span class=\"quran-arabic-font text-success\">رَأْفَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">دِينِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் சட்டத்தை நிறைவேற்றும் விஷயத்தில், அவர்கள் மீது உங்களுக்கு ஏற்படும் இரக்கம் உங்களைத் தடுக்க வேண்டாம்.) அதாவது, அல்லாஹ் விதித்த தீர்ப்பின் அடிப்படையில். எனவே இந்த வசனத்தின் பொருள் என்னவென்றால்: \"அல்லாஹ்வின் சட்டங்கள் நிலைநாட்டப்படும்போது அவர்கள் மீது அளவுக்கு மீறிய பரிதாபம் கொள்ளாதீர்கள்\" என்பதாகும். இதன் பொருள், தண்டனையை நிறைவேற்றும்போது இயல்பான இரக்கமே இருக்கக்கூடாது என்பதல்ல; மாறாக, அத்தண்டனையை முற்றிலுமாகத் தவிர்க்கச் செய்யும் வகையிலான இரக்கமே இங்கே தடுக்கப்பட்டுள்ளது. நீதிபதிக்கு அத்தகைய இரக்கம் காட்ட அனுமதியில்லை. முஜாஹித் (ரஹ்) கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَأْخُذْكُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِمَا</span> <span class=\"quran-arabic-font text-success\">رَأْفَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">دِينِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(அல்லாஹ்வின் சட்டத்தை நிறைவேற்றும் விஷயத்தில், அவர்கள் மீது உங்களுக்கு ஏற்படும் இரக்கம் உங்களைத் தடுக்க வேண்டாம்.) \"ஒரு விஷயம் ஆட்சியாளரிடம் கொண்டு செல்லப்பட்டுவிட்டால், தண்டனை கண்டிப்பாக நிறைவேற்றப்பட வேண்டும்; அதனை நிறுத்த முடியாது.\" இது ஸயீத் பின் ஜுபைர் (ரஹ்) மற்றும் அதா பின் அபீ ரபாஹ் (ரஹ்) ஆகியோராலும் அறிவிக்கப்பட்டுள்ளது. ஒரு ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تَعَافَوُا</span> <span class=\"quran-arabic-font text-success\">الْحُدُودَ</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ،</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَنِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَدٍّ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">وَجَبَ</span>»<br />\r\n<br />\r\n(உங்களுக்குள் தண்டனைக்குரிய குற்றங்களை மன்னித்துக் கொள்ளுங்கள். ஏனெனில், ஒரு தண்டனைக்குரிய விஷயம் என்னிடம் வந்து சேர்ந்துவிட்டால், அதனை நிறைவேற்றுவது என் மீது கடமையாகிவிடும்.) அல்லாஹ்வின் வாக்கு:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَالْيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرِ</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வையும் இறுதி நாளையும் நம்புபவர்களாக இருந்தால்.) அதாவது, விபச்சாரம் செய்தவர்களுக்கு அத்தண்டனைகளை நிறைவேற்றுங்கள். காயம் ஏற்படுத்தாத வகையில் அவர்களைக் கடுமையாக அடியுங்கள்; அதன் மூலம் அவரும் அவரைப் போன்ற பிறரும் அஞ்சிக் குற்றங்களிலிருந்து விலகுவார்கள். முஸ்னது அஹ்மதில், ஒரு தோழர், \"அல்லாஹ்வின் தூதரே! நான் ஓர் ஆட்டை அறுக்கும்போது அதன் மீது எனக்கு இரக்கம் ஏற்படுகிறது\" என்று கூறியபோது, நபியவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَلَكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span>»<br />\r\n<br />\r\n(அதற்காக உனக்கு நற்கூலி உண்டு) என்று கூறினார்கள்.<br />\r\n<br />\r\n<strong>தண்டனையை பகிரங்கமாக நிறைவேற்றுங்கள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَشْهَدْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَهُمَا</span> <span class=\"quran-arabic-font text-success\">طَآئِفَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களில் ஒரு கூட்டத்தினர் அவர்கள் தண்டிக்கப்படுவதை நேரில் பார்க்கட்டும்.) மக்கள் முன்னிலையில் கசையடி வழங்கப்படும்போது, அது விபச்சாரம் செய்தவர்களுக்கு மிகுந்த அவமானத்தைத் தரும். இது ஒரு சிறந்த எச்சரிக்கையாகவும், கண்டனமாகவும் அமையும் என்பதால் அதிக பலன் தரும். ஹஸன் அல்-பஸரி (ரஹ்) கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَشْهَدْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَهُمَا</span> <span class=\"quran-arabic-font text-success\">طَآئِفَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்களில் ஒரு கூட்டத்தினர் அவர்கள் தண்டிக்கப்படுவதை நேரில் பார்க்கட்டும்.) அதாவது \"பகிரங்கமாக.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஸூரத்துந் நூரின் முக்கியத்துவம்\n\r\n\n\r\nسُورَةٌ أَنزَلْنَـهَا\n\r\n\n\r\n(இது நாம் இறக்கிய ஓர் அத்தியாயமாகும்.) இங்கே அல்லாஹ் இந்த அத்தியாயத்திற்கு (ஸூரா) தான் வழங்கும் உயர் கண்ணியத்தைச் சுட்டிக்காட்டுகிறான். இதன் பொருள் மற்ற அத்தியாயங்கள் முக்கியமற்றவை என்பதல்ல.\n\r\n\n\r\nوَفَرَضْنَـهَا\n\r\n\n\r\n(இதனை நாம் கடமையாக்கினோம்.) முஜாஹித் (ரஹ்) மற்றும் கதாதா (ரஹ்) ஆகியோர் கூறினார்கள்: \"இதன் பொருள்: அனுமதிக்கப்பட்டவை (ஹலால்), விலக்கப்பட்டவை (ஹராம்), கட்டளைகள், விலக்கல்கள் மற்றும் விதிக்கப்பட்ட தண்டனைகளை நாம் இதில் விளக்கியுள்ளோம் என்பதாகும்.\" இமாம் புகாரி (ரஹ்) அவர்கள் கூறுகையில், \"இதனை 'ஃபரழ்னாஹா' என்று ஓதுபவர்கள், 'இதனை உங்கள் மீதும் உங்களுக்குப் பின் வருபவர்கள் மீதும் நாம் கடமையாக்கினோம்' என்று இதற்குப் பொருள் கொள்கின்றனர்.\"\n\r\n\n\r\nوَأَنزَلْنَا فِيهَآ ءَايَـتٍ بَيِّنَـتٍ\n\r\n\n\r\n(மேலும், இதில் தெளிவான வசனங்களை நாம் அருளியுள்ளோம்,) அதாவது, தெளிவாக விளக்கப்பட்ட வசனங்கள்,\n\r\n\n\r\nلَعَلَّكُمْ تَذَكَّرُونَ\n\r\n\n\r\n(நீங்கள் நினைவு கூர்வதற்காக.)\n\r\n\n\r\nவிபச்சாரத்திற்கான (ஸினா) தண்டனை குறித்த விளக்கம்\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nالزَّانِيَةُ وَالزَّانِى فَاجْلِدُواْ كُلَّ وَاحِدٍ مِّنْهُمَا مِاْئَةَ جَلْدَةٍ\n\r\n\n\r\n(விபச்சாரம் செய்யும் பெண்ணுக்கும், விபச்சாரம் செய்யும் ஆணுக்கும், அவர்கள் ஒவ்வொருவருக்கும் நூறு கசையடிகள் வழங்குங்கள்.) இந்த கண்ணியமிக்க வசனம், சட்டவிரோத உடலுறவில் ஈடுபடும் நபருக்கான தண்டனைச் சட்டத்தையும், அதன் விவரங்களையும் உள்ளடக்கியுள்ளது. அத்தகைய நபர் ஒன்று திருமணமாகாதவராக இருப்பார் — அதாவது அவர் ஒருபோதும் திருமணம் செய்திருக்க மாட்டார்; அல்லது அவர் திருமணமானவராக இருப்பார் — அதாவது முறையான திருமண பந்தத்திற்குள் தாம்பத்திய உறவு கொண்ட சுதந்திரமான, பருவமடைந்த மற்றும் தெளிவான புத்தியுள்ள ஒருவராக இருப்பார். திருமணமாகாத கன்னிப் பெண்ணைப் பொறுத்தவரை, இந்த வசனத்தில் கூறப்பட்டுள்ளபடி நூறு கசையடிகளே தண்டனையாகும். அத்துடன் கூடுதலாக, அவர் தனது ஊரிலிருந்து ஒரு வருட காலத்திற்கு நாடு கடத்தப்பட வேண்டும். இது அபூ ஹுரைரா (ரழி) மற்றும் ஸைத் பின் காலித் அல்-ஜுஹானி (ரழி) ஆகியோரால் அறிவிக்கப்பட்டு புகாரி, முஸ்லிம் ஆகிய இரு பெரும் நூல்களிலும் பதிவாகியுள்ள ஒரு ஹதீஸில் இடம்பெற்றுள்ளது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்த இரு கிராமவாசிகளில் ஒருவர் கூறினார்: \"அல்லாஹ்வின் தூதரே! என் மகன் இந்த மனிதரிடம் வேலைக்கு இருந்தான். அப்போது அவனுடைய மனைவியுடன் ஸினா செய்துவிட்டான். இதற்காக என் மகனின் சார்பாக நூறு ஆடுகளையும் ஓர் அடிமைப் பெண்ணையும் ஈட்டுத் தொகையாகக் கொடுத்தேன். பிறகு இது குறித்து அறிஞர்களிடம் நான் கேட்டபோது, என் மகனுக்கு நூறு கசையடிகளும் ஓராண்டு நாடு கடத்தப்படுதலுமே தண்டனை என்றும், இந்த மனிதனின் மனைவிக்குக் கல்லெறிந்து மரண தண்டனை (ரஜம்) விதிக்கப்பட வேண்டும் என்றும் அவர்கள் கூறினார்கள்.\" அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَالَّذِي نَفْسِي بِيَدِهِ لَأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللهِ تَعَالى، الْوَلِيدَةُ وَالْغَنَمُ رَدٌّ عَلَيْكَ، وَعَلى ابْنِكَ جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ، وَاغْدُ يَا أُنَيْسُ لِرَجُلٍ مِنْ أَسْلَمَ إِلَى امْرَأَةِ هذَا،فَإِنِ اعْتَرَفَتْ فَارْجُمْهَا»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! உங்கள் இருவருக்கும் இடையில் அல்லாஹ்வின் வேதத்தின்படி நான் தீர்ப்பளிப்பேன். அந்த அடிமைப் பெண்ணையும் ஆடுகளையும் நீ திரும்பப் பெற்றுக்கொள். உன் மகனுக்கு நூறு கசையடிகளும் ஓராண்டு நாடு கடத்தப்படுதலுமே தண்டனையாகும். உனைஸே! — அஸ்லம் கோத்திரத்தைச் சேர்ந்த ஒருவரிடம் கூறினார்கள் — நீ இந்த மனிதனின் மனைவியிடம் செல். அவள் தன் குற்றத்தை ஒப்புக்கொண்டால், அவளுக்குக் கல்லெறிந்து மரண தண்டனை நிறைவேற்று.) உனைஸ் (ரழி) அவளிடம் சென்றார், அவளும் ஒப்புக்கொண்டாள். எனவே அவர் அவளுக்குக் கல்லெறிந்து மரண தண்டனை நிறைவேற்றினார். சட்டவிரோத உடலுறவில் ஈடுபட்டவர் திருமணமாகாதவராக இருந்தால், நூறு கசையடிகளுடன் நாடு கடத்தலும் தண்டனையாகும் என்பதை இது காட்டுகிறது. ஆனால், முறையான திருமண பந்தத்தில் தாம்பத்திய உறவு கொண்ட, சுதந்திரமான, பருவமடைந்த, புத்தி சுவாதீனமுள்ள திருமணமானவராக இருந்தால், அவருக்குக் கல்லெறிந்து மரண தண்டனை வழங்கப்பட வேண்டும். இமாம் மாலிக் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள்: உமர் (ரழி) அவர்கள் எழுந்து நின்று அல்லாஹ்வைப் புகழ்ந்து போற்றிய பிறகு கூறினார்கள்: \"மக்களே! அல்லாஹ் முஹம்மது (ஸல்) அவர்களை சத்தியத்துடன் அனுப்பினான்; அவருக்கு வேதத்தையும் அருளினான். அவருக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி)களில் கல்லெறிந்து மரண தண்டனை விதிக்கும் வசனமும் ஒன்றாகும். அதை நாங்கள் ஓதினோம், விளங்கிக் கொண்டோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அத்தண்டனையை நிறைவேற்றினார்கள்; அவர்களுக்குப் பிறகு நாங்களும் அதனை நிறைவேற்றினோம். ஆனால் காலம் செல்லச் செல்ல, 'அல்லாஹ்வின் வேதத்தில் கல்லெறிந்து மரண தண்டனை விதிக்கும் வசனத்தை நாங்கள் காணவில்லை' என்று யாராவது கூறி, அல்லாஹ் விதித்த ஒரு கடமையை விட்டதன் காரணமாக அவர்கள் வழிதவறி விடுவார்களோ என்று நான் அஞ்சுகிறேன். திருமணமான ஒருவன் அல்லது ஒருத்தி விபச்சாரம் செய்து, அதற்குரிய சாட்சியங்கள் நிரூபிக்கப்பட்டாலோ அல்லது கர்ப்பம் ஏற்பட்டாலோ அல்லது அவர்களே ஒப்புக்கொண்டாலோ, அவர்களுக்குக் கல்லெறிந்து மரண தண்டனை விதிப்பது அல்லாஹ்வின் வேதத்தில் உள்ள ஒரு கடமையாகும்.\" இமாம் மாலிக் (ரஹ்) அவர்களின் இந்த நீண்ட ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் இடம்பெற்றுள்ளது. அதன் ஒரு பகுதியை மட்டுமே நாம் இங்கே சுருக்கமாகக் குறிப்பிட்டுள்ளோம்.\n\r\n\n\r\nதண்டனையை நிறைவேற்றும்போது அவர்கள் மீது இரக்கம் காட்டாதீர்கள்\n\r\n\n\r\nوَلاَ تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ فِى دِينِ اللَّهِ\n\r\n\n\r\n(அல்லாஹ்வின் சட்டத்தை நிறைவேற்றும் விஷயத்தில், அவர்கள் மீது உங்களுக்கு ஏற்படும் இரக்கம் உங்களைத் தடுக்க வேண்டாம்.) அதாவது, அல்லாஹ் விதித்த தீர்ப்பின் அடிப்படையில். எனவே இந்த வசனத்தின் பொருள் என்னவென்றால்: \"அல்லாஹ்வின் சட்டங்கள் நிலைநாட்டப்படும்போது அவர்கள் மீது அளவுக்கு மீறிய பரிதாபம் கொள்ளாதீர்கள்\" என்பதாகும். இதன் பொருள், தண்டனையை நிறைவேற்றும்போது இயல்பான இரக்கமே இருக்கக்கூடாது என்பதல்ல; மாறாக, அத்தண்டனையை முற்றிலுமாகத் தவிர்க்கச் செய்யும் வகையிலான இரக்கமே இங்கே தடுக்கப்பட்டுள்ளது. நீதிபதிக்கு அத்தகைய இரக்கம் காட்ட அனுமதியில்லை. முஜாஹித் (ரஹ்) கூறினார்கள்:\n\r\n\n\r\nوَلاَ تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ فِى دِينِ اللَّهِ\n\r\n\n\r\n(அல்லாஹ்வின் சட்டத்தை நிறைவேற்றும் விஷயத்தில், அவர்கள் மீது உங்களுக்கு ஏற்படும் இரக்கம் உங்களைத் தடுக்க வேண்டாம்.) \"ஒரு விஷயம் ஆட்சியாளரிடம் கொண்டு செல்லப்பட்டுவிட்டால், தண்டனை கண்டிப்பாக நிறைவேற்றப்பட வேண்டும்; அதனை நிறுத்த முடியாது.\" இது ஸயீத் பின் ஜுபைர் (ரஹ்) மற்றும் அதா பின் அபீ ரபாஹ் (ரஹ்) ஆகியோராலும் அறிவிக்கப்பட்டுள்ளது. ஒரு ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:\n\r\n\n\r\n«تَعَافَوُا الْحُدُودَ فِيمَا بَيْنَكُمْ، فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ»\n\r\n\n\r\n(உங்களுக்குள் தண்டனைக்குரிய குற்றங்களை மன்னித்துக் கொள்ளுங்கள். ஏனெனில், ஒரு தண்டனைக்குரிய விஷயம் என்னிடம் வந்து சேர்ந்துவிட்டால், அதனை நிறைவேற்றுவது என் மீது கடமையாகிவிடும்.) அல்லாஹ்வின் வாக்கு:\n\r\n\n\r\nإِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الاٌّخِرِ\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வையும் இறுதி நாளையும் நம்புபவர்களாக இருந்தால்.) அதாவது, விபச்சாரம் செய்தவர்களுக்கு அத்தண்டனைகளை நிறைவேற்றுங்கள். காயம் ஏற்படுத்தாத வகையில் அவர்களைக் கடுமையாக அடியுங்கள்; அதன் மூலம் அவரும் அவரைப் போன்ற பிறரும் அஞ்சிக் குற்றங்களிலிருந்து விலகுவார்கள். முஸ்னது அஹ்மதில், ஒரு தோழர், \"அல்லாஹ்வின் தூதரே! நான் ஓர் ஆட்டை அறுக்கும்போது அதன் மீது எனக்கு இரக்கம் ஏற்படுகிறது\" என்று கூறியபோது, நபியவர்கள்:\n\r\n\n\r\n«وَلَكَ فِي ذلِكَ أَجْرٌ»\n\r\n\n\r\n(அதற்காக உனக்கு நற்கூலி உண்டு) என்று கூறினார்கள்.\n\r\n\n\r\nதண்டனையை பகிரங்கமாக நிறைவேற்றுங்கள்\n\r\n\n\r\nوَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ الْمُؤْمِنِينَ\n\r\n\n\r\n(நம்பிக்கையாளர்களில் ஒரு கூட்டத்தினர் அவர்கள் தண்டிக்கப்படுவதை நேரில் பார்க்கட்டும்.) மக்கள் முன்னிலையில் கசையடி வழங்கப்படும்போது, அது விபச்சாரம் செய்தவர்களுக்கு மிகுந்த அவமானத்தைத் தரும். இது ஒரு சிறந்த எச்சரிக்கையாகவும், கண்டனமாகவும் அமையும் என்பதால் அதிக பலன் தரும். ஹஸன் அல்-பஸரி (ரஹ்) கூறினார்கள்:\n\r\n\n\r\nوَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ الْمُؤْمِنِينَ\n\r\n\n\r\n(நம்பிக்கையாளர்களில் ஒரு கூட்டத்தினர் அவர்கள் தண்டிக்கப்படுவதை நேரில் பார்க்கட்டும்.) அதாவது \"பகிரங்கமாக.\""},"3":{"html":"<span class=\"quran-arabic-font text-success\">الزَّانِى</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنكِحُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">زَانِيَةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكَةً</span><br />\r\n(விபச்சாரம் செய்த ஓர் ஆண், விபச்சாரம் செய்த ஒரு பெண்ணையோ அல்லது ஒரு முஷ்ரிக்காவையோ தவிர வேறு பெண்ணைத் திருமணம் செய்யமாட்டான்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالزَّانِيَةُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنكِحُهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">زَانٍ</span><br />\r\n(விபச்சாரம் செய்த பெண்ணை, விபச்சாரம் செய்த ஓர் ஆணைத் தவிர வேறு எவரும் திருமணம் புரிவதில்லை) - அதாவது விபச்சாரக் குற்றம் புரிந்த ஒரு பாவியான ஆண்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكٌ</span><br />\r\n(அல்லது ஒரு முஷ்ரிக்) - அதாவது, அது ஹராம் (விலக்கப்பட்டது) என்று கருதாத ஒரு மனிதன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحُرِّمَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n(இத்தகைய காரியம் முஃமின்களுக்குத் தடை செய்யப்பட்டுள்ளது.) இதன் பொருள், இச்செயலில் ஈடுபடுவது, அல்லது விபச்சாரிகளைத் திருமணம் செய்வது, அல்லது கற்புள்ள பெண்களை ஒழுக்கமற்ற ஆண்களுக்குத் திருமணம் செய்து கொடுப்பது (விலக்கப்பட்டுள்ளது) என்பதாகும். கதாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறினார்கள்: \"விபச்சாரிகளைத் திருமணம் செய்வதை முஃமின்களுக்கு அல்லாஹ் தடுத்தான்.\" இந்த வசனம் (அடிமைப் பெண்களைத் திருமணம் செய்வது தொடர்பான) பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُحْصَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مُسَافِحَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مُتَّخِذَاتِ</span> <span class=\"quran-arabic-font text-success\">أَخْدَانٍ</span><br />\r\n(அவர்கள் கற்புள்ளவர்களாக இருக்க வேண்டும்; பகிரங்கமாக விபச்சாரம் செய்பவர்களாகவோ அல்லது கள்ளக்காதலர்களை வைத்துக்கொள்பவர்களாகவோ இருக்கக்கூடாது.) <a href=\"qurandisp.php?sura=4&ayah=25\" class=\"link\">4:25</a> மற்றும் அவனது (அல்லாஹ்வின்) கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُحْصِنِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مُسَافِحِينَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مُتَّخِذِى</span> <span class=\"quran-arabic-font text-success\">أَخْدَانٍ</span><br />\r\n(கற்பைப் பேணுபவர்களாக இருக்க வேண்டும்; சட்டவிரோத தாம்பத்திய உறவில் ஈடுபடுபவர்களாகவோ அல்லது அவர்களைக் கள்ளக்காதலிகளாக வைத்துக்கொள்பவர்களாகவோ இருக்கக்கூடாது.) <a href=\"qurandisp.php?sura=5&ayah=5\" class=\"link\">5:5</a>.<br />\r\n<br />\r\nஇமாம் அஹ்மத் மற்றும் நஸயீ, திர்மிதீ ஆகியோர் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறினார்கள், முஃமின்களில் ஒரு மனிதர் உம்மு மஹ்ஸூல் என்று அழைக்கப்பட்ட ஒரு பெண்ணைத் திருமணம் செய்ய அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அனுமதி கோரினார். அப்பெண் விபச்சாரம் செய்பவளாக இருந்தாள்; மேலும் அந்த மனிதருக்குத் தானே செலவு செய்வதாகவும் ஒரு நிபந்தனை விதித்திருந்தாள். எனவே அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அனுமதி கேட்டார் அல்லது அந்த விஷயத்தை அவர்களிடம் தெரிவித்தார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம், ‘‘அவளைத் திருமணம் செய்யாதீர்!’’ என்று கூறினார்கள். மேலும், அவருக்குப் பின்வரும் வசனத்தை ஓதிக் காட்டினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الزَّانِى</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنكِحُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">زَانِيَةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكَةً</span> <span class=\"quran-arabic-font text-success\">وَالزَّانِيَةُ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنكِحُهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">زَانٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مُشْرِكٌ</span> <span class=\"quran-arabic-font text-success\">وَحُرِّمَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span><br />\r\n(விபச்சாரம் செய்த ஓர் ஆண், விபச்சாரம் செய்த ஒரு பெண்ணையோ அல்லது ஒரு முஷ்ரிக்காவையோ தவிர வேறு பெண்ணைத் திருமணம் செய்யமாட்டான். விபச்சாரம் செய்த ஒரு பெண்ணை, விபச்சாரம் செய்த ஓர் ஆணோ அல்லது ஒரு முஷ்ரிக்கோ தவிர வேறு எவரும் திருமணம் செய்யமாட்டான். இத்தகைய காரியம் முஃமின்களுக்குத் தடை செய்யப்பட்டுள்ளது.) <a href=\"qurandisp.php?sura=24&ayah=3\" class=\"link\">24:3</a><br />\r\n<br />\r\nஇப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூஹுரைரா (ரழி) அவர்கள் கூறினார்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَنْكِحُ</span> <span class=\"quran-arabic-font text-success\">الزَّانِي</span> <span class=\"quran-arabic-font text-success\">الْمَجْلُودُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِثْلَهُ</span>»<br />\r\n(கசையடி வழங்கப்பட்ட விபச்சாரம் செய்த ஒருவன், தன்னைப்போன்ற ஒருவரைத் தவிர வேறு எவரையும் திருமணம் செய்யக்கூடாது.)<br />\r\n<br />\r\nஇதே போன்றதொரு செய்தி அபூதாவூத் அவர்களால் தமது சுனன் நூலில் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />","text":"الزَّانِى لاَ يَنكِحُ إِلاَّ زَانِيَةً أَوْ مُشْرِكَةً\n\r\n(விபச்சாரம் செய்த ஓர் ஆண், விபச்சாரம் செய்த ஒரு பெண்ணையோ அல்லது ஒரு முஷ்ரிக்காவையோ தவிர வேறு பெண்ணைத் திருமணம் செய்யமாட்டான்.)\n\r\n\n\r\nوَالزَّانِيَةُ لاَ يَنكِحُهَآ إِلاَّ زَانٍ\n\r\n(விபச்சாரம் செய்த பெண்ணை, விபச்சாரம் செய்த ஓர் ஆணைத் தவிர வேறு எவரும் திருமணம் புரிவதில்லை) - அதாவது விபச்சாரக் குற்றம் புரிந்த ஒரு பாவியான ஆண்,\n\r\n\n\r\nأَوْ مُشْرِكٌ\n\r\n(அல்லது ஒரு முஷ்ரிக்) - அதாவது, அது ஹராம் (விலக்கப்பட்டது) என்று கருதாத ஒரு மனிதன்.\n\r\n\n\r\nوَحُرِّمَ ذلِكَ عَلَى الْمُؤْمِنِينَ\n\r\n(இத்தகைய காரியம் முஃமின்களுக்குத் தடை செய்யப்பட்டுள்ளது.) இதன் பொருள், இச்செயலில் ஈடுபடுவது, அல்லது விபச்சாரிகளைத் திருமணம் செய்வது, அல்லது கற்புள்ள பெண்களை ஒழுக்கமற்ற ஆண்களுக்குத் திருமணம் செய்து கொடுப்பது (விலக்கப்பட்டுள்ளது) என்பதாகும். கதாதா மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோர் கூறினார்கள்: \"விபச்சாரிகளைத் திருமணம் செய்வதை முஃமின்களுக்கு அல்லாஹ் தடுத்தான்.\" இந்த வசனம் (அடிமைப் பெண்களைத் திருமணம் செய்வது தொடர்பான) பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nمُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلاَ مُتَّخِذَاتِ أَخْدَانٍ\n\r\n(அவர்கள் கற்புள்ளவர்களாக இருக்க வேண்டும்; பகிரங்கமாக விபச்சாரம் செய்பவர்களாகவோ அல்லது கள்ளக்காதலர்களை வைத்துக்கொள்பவர்களாகவோ இருக்கக்கூடாது.) 4:25 மற்றும் அவனது (அல்லாஹ்வின்) கூற்று:\n\r\n\n\r\nمُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلاَ مُتَّخِذِى أَخْدَانٍ\n\r\n(கற்பைப் பேணுபவர்களாக இருக்க வேண்டும்; சட்டவிரோத தாம்பத்திய உறவில் ஈடுபடுபவர்களாகவோ அல்லது அவர்களைக் கள்ளக்காதலிகளாக வைத்துக்கொள்பவர்களாகவோ இருக்கக்கூடாது.) 5:5.\n\r\n\n\r\nஇமாம் அஹ்மத் மற்றும் நஸயீ, திர்மிதீ ஆகியோர் பதிவு செய்துள்ளார்கள்: அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறினார்கள், முஃமின்களில் ஒரு மனிதர் உம்மு மஹ்ஸூல் என்று அழைக்கப்பட்ட ஒரு பெண்ணைத் திருமணம் செய்ய அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அனுமதி கோரினார். அப்பெண் விபச்சாரம் செய்பவளாக இருந்தாள்; மேலும் அந்த மனிதருக்குத் தானே செலவு செய்வதாகவும் ஒரு நிபந்தனை விதித்திருந்தாள். எனவே அவர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் அனுமதி கேட்டார் அல்லது அந்த விஷயத்தை அவர்களிடம் தெரிவித்தார். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவரிடம், ‘‘அவளைத் திருமணம் செய்யாதீர்!’’ என்று கூறினார்கள். மேலும், அவருக்குப் பின்வரும் வசனத்தை ஓதிக் காட்டினார்கள்:\n\r\n\n\r\nالزَّانِى لاَ يَنكِحُ إِلاَّ زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لاَ يَنكِحُهَآ إِلاَّ زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذلِكَ عَلَى الْمُؤْمِنِينَ\n\r\n(விபச்சாரம் செய்த ஓர் ஆண், விபச்சாரம் செய்த ஒரு பெண்ணையோ அல்லது ஒரு முஷ்ரிக்காவையோ தவிர வேறு பெண்ணைத் திருமணம் செய்யமாட்டான். விபச்சாரம் செய்த ஒரு பெண்ணை, விபச்சாரம் செய்த ஓர் ஆணோ அல்லது ஒரு முஷ்ரிக்கோ தவிர வேறு எவரும் திருமணம் செய்யமாட்டான். இத்தகைய காரியம் முஃமின்களுக்குத் தடை செய்யப்பட்டுள்ளது.) 24:3\n\r\n\n\r\nஇப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூஹுரைரா (ரழி) அவர்கள் கூறினார்கள்,\n\r\n\n\r\n«لَا يَنْكِحُ الزَّانِي الْمَجْلُودُ إِلَّا مِثْلَهُ»\n\r\n(கசையடி வழங்கப்பட்ட விபச்சாரம் செய்த ஒருவன், தன்னைப்போன்ற ஒருவரைத் தவிர வேறு எவரையும் திருமணம் செய்யக்கூடாது.)\n\r\n\n\r\nஇதே போன்றதொரு செய்தி அபூதாவூத் அவர்களால் தமது சுனன் நூலில் பதிவு செய்யப்பட்டுள்ளது."},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=5\" class=\"link\">24:5</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:5 ஐ பார்க்கவும்"},"5":{"html":"<strong>கற்புள்ள பெண்கள் மீது அவதூறு சுமத்துவதற்கான தண்டனை</strong><br />\r\n<br />\r\nஇந்த வசனம், சுதந்திரமான, பருவமடைந்த மற்றும் கற்புள்ள பெண்கள் மீது பொய்யான குற்றச்சாட்டுகளை (அவதூறு) சுமத்துபவர்களுக்கான மார்க்கம் விதித்துள்ள தண்டனையை விளக்குகிறது. பொய்யாகக் குற்றம் சாட்டப்பட்டவர் ஒரு ஆணாக இருந்தாலும், இதே கசையடித் தண்டனை அவருக்கும் பொருந்தும். குற்றம் சாட்டுபவர் தான் கூறுவது உண்மை என்பதற்குத் தேவையான ஆதாரங்களைச் சமர்ப்பித்தால், அந்தத் தண்டனை அவருக்குப் பொருந்தாது. அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتُوا</span> <span class=\"quran-arabic-font text-success\">بِأَرْبَعَةِ</span> <span class=\"quran-arabic-font text-success\">شُهَدَاءَ</span> <span class=\"quran-arabic-font text-success\">فَاجْلِدُوهُمْ</span> <span class=\"quran-arabic-font text-success\">ثَمَانِينَ</span> <span class=\"quran-arabic-font text-success\">جَلْدَةً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَقْبَلُوا</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">شَهَادَةً</span> <span class=\"quran-arabic-font text-success\">أَبَداً</span> <span class=\"quran-arabic-font text-success\">وَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَاسِقُونَ﴿</span><br />\r\n<br />\r\n(மேலும், அவர்கள் நான்கு சாட்சிகளைக் கொண்டு வராவிட்டால், அவர்களுக்கு எண்பது கசையடிகள் கொடுங்கள். அவர்களின் சாட்சியத்தை எக்காலத்திலும் ஏற்றுக்கொள்ளாதீர்கள். நிச்சயமாக அவர்களே பெரும் பாவிகளாவர்.) குற்றம் சாட்டுபவர் தான் கூறுவது உண்மை என்பதை நிரூபிக்கத் தவறினால், அவருக்கு மூன்று சட்டங்கள் பொருந்தும்: (முதலாவதாக) அவருக்கு எண்பது கசையடிகள் கொடுக்கப்பட வேண்டும்; (இரண்டாவதாக) அவருடைய சாட்சியம் எப்போதும் நிராகரிக்கப்பட வேண்டும்; (மூன்றாவதாக) அல்லாஹ்வின் பார்வையிலும் மனிதர்களின் பார்வையிலும் அவர் நற்பண்பு இல்லாத ஒரு பெரும் பாவி (ஃபாஸிக்) என்று முத்திரை குத்தப்படுவார்.<br />\r\n<br />\r\n<strong>அவதூறு சுமத்தியவர் மன்னிப்புக் கோருவது குறித்த விளக்கம்</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">تَابُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَأَصْلَحُواْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதற்குப் பிறகு மன்னிப்புக் கேட்டு, தங்களைத் திருத்திக் கொள்பவர்களைத் தவிர; (அத்தகையவர்களுக்கு) நிச்சயமாக அல்லாஹ் மன்னிப்பவனும் மகா கருணையாளனும் ஆவான்.) இந்த விதிவிலக்கானது மேலே குறிப்பிடப்பட்ட இரண்டாவது மற்றும் மூன்றாவது சட்டங்களைக் குறிக்கிறது. அவர் மன்னிப்புக் கேட்டாலும் அல்லது தன் நிலையில் பிடிவாதமாக இருந்தாலும் சரி, கசையடித் தண்டனை நிறைவேற்றப்படும். அவர் தவ்பாச் செய்வதன் மூலம் 'ஃபாஸிக்' (பாவி) என்ற பெயர் நீங்கிவிடும் என்பதில் அறிஞர்களிடையே ஒருமித்த கருத்து உள்ளது. ஆனால் அவரது சாட்சியம் ஏற்கப்படுமா என்பதில் கருத்து வேறுபாடு உள்ளது. அவர் உண்மையாகவே வருந்தி மன்னிப்புக் கேட்டால், அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படலாம்; மேலும் அவர் ஒரு பெரும் பாவியாகக் கருதப்பட மாட்டார். இதுவே தாபியீன்களின் (Tabi`in) தலைவரான ஸயீத் பின் அல்-முஸய்யிப் அவர்களது மற்றும் ஸலஃப்களில் ஒரு குழுவினரின் கருத்தாகும். மேலும் இமாம் மாலிக், இமாம் அஹ்மத் மற்றும் இமாம் ஷாஃபிஈ ஆகியோரும் இக்கருத்தையே கொண்டுள்ளனர். ஆனால் இமாம் அபூ ஹனீஃபா(ரஹ்) அவர்கள், \"அவர் மன்னிப்புக் கேட்டாலும் அவரது சாட்சியம் எக்காலத்திலும் ஏற்றுக்கொள்ளப்படாது\" என்று கூறினார்கள். அஷ்-ஷஅபி மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"அவர் மன்னிப்புக் கேட்டாலும் அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படாது; எனினும் அவர் தானாக முன்வந்து தான் பொய் சொன்னதாக ஒப்புக்கொண்டால் மட்டுமே அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படும்\" என்று கூறினார்கள். மேலும் அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />","text":"கற்புள்ள பெண்கள் மீது அவதூறு சுமத்துவதற்கான தண்டனை\n\r\n\n\r\nஇந்த வசனம், சுதந்திரமான, பருவமடைந்த மற்றும் கற்புள்ள பெண்கள் மீது பொய்யான குற்றச்சாட்டுகளை (அவதூறு) சுமத்துபவர்களுக்கான மார்க்கம் விதித்துள்ள தண்டனையை விளக்குகிறது. பொய்யாகக் குற்றம் சாட்டப்பட்டவர் ஒரு ஆணாக இருந்தாலும், இதே கசையடித் தண்டனை அவருக்கும் பொருந்தும். குற்றம் சாட்டுபவர் தான் கூறுவது உண்மை என்பதற்குத் தேவையான ஆதாரங்களைச் சமர்ப்பித்தால், அந்தத் தண்டனை அவருக்குப் பொருந்தாது. அல்லாஹ் கூறினான்: ﴾ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلاَ تَقْبَلُوا لَهُمْ شَهَادَةً أَبَداً وَأُولَئِكَ هُمُ الْفَاسِقُونَ﴿\n\r\n\n\r\n(மேலும், அவர்கள் நான்கு சாட்சிகளைக் கொண்டு வராவிட்டால், அவர்களுக்கு எண்பது கசையடிகள் கொடுங்கள். அவர்களின் சாட்சியத்தை எக்காலத்திலும் ஏற்றுக்கொள்ளாதீர்கள். நிச்சயமாக அவர்களே பெரும் பாவிகளாவர்.) குற்றம் சாட்டுபவர் தான் கூறுவது உண்மை என்பதை நிரூபிக்கத் தவறினால், அவருக்கு மூன்று சட்டங்கள் பொருந்தும்: (முதலாவதாக) அவருக்கு எண்பது கசையடிகள் கொடுக்கப்பட வேண்டும்; (இரண்டாவதாக) அவருடைய சாட்சியம் எப்போதும் நிராகரிக்கப்பட வேண்டும்; (மூன்றாவதாக) அல்லாஹ்வின் பார்வையிலும் மனிதர்களின் பார்வையிலும் அவர் நற்பண்பு இல்லாத ஒரு பெரும் பாவி (ஃபாஸிக்) என்று முத்திரை குத்தப்படுவார்.\n\r\n\n\r\nஅவதூறு சுமத்தியவர் மன்னிப்புக் கோருவது குறித்த விளக்கம்\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾إِلاَّ الَّذِينَ تَابُواْ مِن بَعْدِ ذَلِكَ وَأَصْلَحُواْ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ ﴿\n\r\n\n\r\n(அதற்குப் பிறகு மன்னிப்புக் கேட்டு, தங்களைத் திருத்திக் கொள்பவர்களைத் தவிர; (அத்தகையவர்களுக்கு) நிச்சயமாக அல்லாஹ் மன்னிப்பவனும் மகா கருணையாளனும் ஆவான்.) இந்த விதிவிலக்கானது மேலே குறிப்பிடப்பட்ட இரண்டாவது மற்றும் மூன்றாவது சட்டங்களைக் குறிக்கிறது. அவர் மன்னிப்புக் கேட்டாலும் அல்லது தன் நிலையில் பிடிவாதமாக இருந்தாலும் சரி, கசையடித் தண்டனை நிறைவேற்றப்படும். அவர் தவ்பாச் செய்வதன் மூலம் 'ஃபாஸிக்' (பாவி) என்ற பெயர் நீங்கிவிடும் என்பதில் அறிஞர்களிடையே ஒருமித்த கருத்து உள்ளது. ஆனால் அவரது சாட்சியம் ஏற்கப்படுமா என்பதில் கருத்து வேறுபாடு உள்ளது. அவர் உண்மையாகவே வருந்தி மன்னிப்புக் கேட்டால், அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படலாம்; மேலும் அவர் ஒரு பெரும் பாவியாகக் கருதப்பட மாட்டார். இதுவே தாபியீன்களின் (Tabi`in) தலைவரான ஸயீத் பின் அல்-முஸய்யிப் அவர்களது மற்றும் ஸலஃப்களில் ஒரு குழுவினரின் கருத்தாகும். மேலும் இமாம் மாலிக், இமாம் அஹ்மத் மற்றும் இமாம் ஷாஃபிஈ ஆகியோரும் இக்கருத்தையே கொண்டுள்ளனர். ஆனால் இமாம் அபூ ஹனீஃபா(ரஹ்) அவர்கள், \"அவர் மன்னிப்புக் கேட்டாலும் அவரது சாட்சியம் எக்காலத்திலும் ஏற்றுக்கொள்ளப்படாது\" என்று கூறினார்கள். அஷ்-ஷஅபி மற்றும் அத்-தஹ்ஹாக் ஆகியோர், \"அவர் மன்னிப்புக் கேட்டாலும் அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படாது; எனினும் அவர் தானாக முன்வந்து தான் பொய் சொன்னதாக ஒப்புக்கொண்டால் மட்டுமே அவரது சாட்சியம் ஏற்றுக்கொள்ளப்படும்\" என்று கூறினார்கள். மேலும் அல்லாஹ்வே மிக அறிந்தவன்."},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=10\" class=\"link\">24:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:10 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=10\" class=\"link\">24:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:10 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=10\" class=\"link\">24:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:10 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=10\" class=\"link\">24:10</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:10 ஐ பார்க்கவும்"},"10":{"html":"<strong>லிஆனின் விபரங்கள்</strong><br />\r\n<br />\r\nஇந்த வசனம் கணவன்மார்களுக்கு ஒரு தீர்வை வழங்குகிறது. ஒரு கணவன் தன் மனைவியைக் குற்றம் சாட்டி, அதற்குரிய ஆதாரத்தைக் கொண்டு வர முடியாவிட்டால், அல்லாஹ் கட்டளையிட்டபடி அவர் 'லிஆன்' (சபதமேற்றுப் பிரிதல்) செய்யலாம். அதாவது, அவர் தனது மனைவியை ஆட்சியாளர் (இமாம்) முன் கொண்டு வந்து, தான் சுமத்தும் குற்றச்சாட்டைத் தெரிவிக்க வேண்டும். பின்னர் ஆட்சியாளர், நான்கு சாட்சிகள் முன்னிலையில் அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்யுமாறு அவரிடம் கோருவார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَمِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர் உண்மையே கூறுகிறார் என்று) தன் மனைவியின் மீதான விபச்சாரக் குற்றச்சாட்டில் அவர் சத்தியம் செய்ய வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْخَامِسَةُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">لَعْنَةَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَاذِبِينَ</span><br />\r\n<br />\r\n(ஐந்தாவது முறை; அவர் பொய்யராக இருந்தால் அல்லாஹ்வின் சாபம் அவர் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) அவர் அவ்வாறு கூறிவிட்டால், அந்த லிஆன் மூலமாகவே அவள் அவரிடமிருந்து விவாகரத்து செய்யப்படுகிறாள். அவள் அவருக்கு நிரந்தரமாகத் தடை செய்யப்பட்டவளாகிறாள்; மேலும் அவர் அவளுக்குரிய மஹரைக் கொடுத்துவிட வேண்டும். அவள் மீது விபச்சாரத்திற்கான (ஸினா) தண்டனை நிறைவேற்றப்பட வேண்டும். எனினும், அவளும் லிஆன் செய்து, தன் கணவன் பொய்யுரைப்பதாக அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்தால் தவிர, அந்தத் தண்டனையிலிருந்து அவள் தப்ப முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْخَامِسَةَ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">غَضَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span><br />\r\n<br />\r\n(ஐந்தாவது முறை; அவர் கூறுவது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَدْرَؤُاْ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span><br />\r\n<br />\r\n(ஆனால் அவள் தண்டனையைத் தடுத்துக் கொள்வாள்) அதாவது, அவளுக்கு விதிக்கப்பட்ட தண்டனையை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَدْرَؤُاْ</span> <span class=\"quran-arabic-font text-success\">عَنْهَا</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَشْهَدَ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَ</span> <span class=\"quran-arabic-font text-success\">شَهَادَاتٍ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَاذِبِينَ</span> - <span class=\"quran-arabic-font text-success\">وَالْخَامِسَةَ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">غَضَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span><br />\r\n<br />\r\n(அவர் பொய் சொல்கிறார் என்று அவள் நான்கு முறை அல்லாஹ்வின் மீது சாட்சியம் கூறினால். ஐந்தாவது முறையாக, அவர் உண்மையைப் பேசினால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) ஒரு பெண் விபச்சாரம் செய்ததாகத் தன் மனைவியை அம்பலப்படுத்த ஒரு ஆண் முன்வருகிறான் என்றால், பொதுவாக அவன் உண்மையைப் பேசினாலன்றி அந்த அளவிற்குச் செல்ல மாட்டான் என்பதை அனைவரும் அறிவர். எனவேதான், பெண்ணின் விஷயத்தில் ஐந்தாவது சத்தியத்தில் 'அல்லாஹ்வின் கோபம்' (கதப்) எனக் குறிப்பிடப்பட்டுள்ளது. ஏனெனில், உண்மையை அறிந்திருந்தும் அதிலிருந்து விலகிச் செல்பவர் மீதே அல்லாஹ்வின் கோபம் உண்டாகும். பின்னர் அல்லாஹ் தனது படைப்புகளுக்கு வழங்கிய அருளையும் கருணையையும் குறிப்பிடுகிறான்; அவர்கள் இக்கட்டான சூழலில் இருக்கும்போது அதிலிருந்து வெளியேற ஒரு வழியை அவன் ஏற்படுத்திக் கொடுத்துள்ளான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتُهُ</span><br />\r\n<br />\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால்!) அதாவது, உங்கள் விவகாரங்கள் பல உங்களுக்கு மிகவும் சிரமமாக இருந்திருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">تَوَّابٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் பாவமன்னிப்பை ஏற்றுக்கொள்பவன்,) அதாவது, உறுதிமொழி எடுத்து சத்தியம் செய்த பின்னரும் தனது அடியார்களிடம் இருந்து மன்னிப்பை ஏற்றுக்கொள்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَكِيمٌ</span><br />\r\n<br />\r\n(அவன் ஞானமிக்கவன்.) அவன் விதிக்கும் சட்டங்களிலும், கட்டளைகளிலும், விலக்கல்களிலும் அளப்பரிய ஞானம் உடையவன். இந்த வசனத்தை எவ்வாறு நடைமுறைப்படுத்த வேண்டும், இது ஏன் அருளப்பட்டது, எந்த நபித்தோழர்களைப் (ரழி) பற்றி இது அருளப்பட்டது என்பதை விளக்கும் ஹதீஸ்கள் பல உள்ளன.<br />\r\n<br />\r\n<strong>லிஆன் வசனம் அருளப்பட்டதற்கான காரணம்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"எப்போது இந்த வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَرْمُونَ</span> <span class=\"quran-arabic-font text-success\">الْمُحْصَنَاتِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتُواْ</span> <span class=\"quran-arabic-font text-success\">بِأَرْبَعَةِ</span> <span class=\"quran-arabic-font text-success\">شُهَدَآءَ</span> <span class=\"quran-arabic-font text-success\">فَاجْلِدُوهُمْ</span> <span class=\"quran-arabic-font text-success\">ثَمَانِينَ</span> <span class=\"quran-arabic-font text-success\">جَلْدَةً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَقْبَلُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">شَهَادَةً</span> <span class=\"quran-arabic-font text-success\">أَبَداً</span><br />\r\n<br />\r\n(கற்புள்ள பெண்கள் மீது பழி சுமத்தி, பின்னர் நான்கு சாட்சிகளைக் கொண்டு வராதவர்களுக்கு எண்பது கசையடிகள் கொடுங்கள்; மேலும் அவர்களின் சாட்சியத்தை ஒருபோதும் ஏற்றுக்கொள்ளாதீர்கள் - <a href=\"qurandisp.php?sura=24&ayah=4\" class=\"link\">24:4</a>) அருளப்பட்டதோ, அப்போது அன்சாரிகளின் தலைவரான ஸஃத் பின் உபாதா (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! இது இப்படியா அருளப்பட்டது?' என்று கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الْأَنْصَارِ</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">سَيِّدُكُمْ؟</span>»<br />\r\n<br />\r\n(அன்சாரிகளே! உங்கள் தலைவர் என்ன கூறுகிறார் என்று கேட்டீர்களா?) என்று கேட்டார்கள்.<br />\r\n<br />\r\nஅதற்கு அவர்கள், 'அல்லாஹ்வின் தூதரே! அவரைக் குறை சொல்லாதீர்கள், அவர் மிகவும் ரோஷமுள்ள மனிதர். அல்லாஹ்வின் மீது ஆணையாக, அவர் கன்னிப் பெண்ணைத் தவிர வேறு யாரையும் மணந்ததில்லை. அவர் ஒரு பெண்ணை விவாகரத்து செய்துவிட்டால், அவரது ரோஷத்திற்கு அஞ்சி எங்களில் யாரும் அவளை மணக்கத் துணிய மாட்டோம்' என்று கூறினார்கள். அப்போது ஸஃத் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக, அல்லாஹ்வின் தூதரே! இந்த வசனம் உண்மை என்றும் அது அல்லாஹ்விடமிருந்தே வந்தது என்றும் எனக்குத் தெரியும். ஆனால் நான் வியப்படைகிறேன்; என் மனைவியுடன் ஒரு அந்நிய மனிதன் இருப்பதைக் கண்டால், நான் நான்கு சாட்சிகளை அழைத்து வரும் வரை அவனை ஒன்றும் செய்யாமல் இருக்க வேண்டுமா? அல்லாஹ்வின் மீது ஆணையாக, நான் சாட்சிகளைத் திரட்டுவதற்குள் அவன் தன் காரியத்தை முடித்திருப்பானே!' என்று கூறினார்கள். சிறிது காலம் கழித்து, ஹிலால் பின் உமைய்யா (ரழி) அவர்கள் - யாருடைய பாவமன்னிப்பு ஏற்றுக்கொள்ளப்பட்டதோ அந்த மூவரில் ஒருவர் - ஒரு இரவு வேளையில் தனது தோட்டத்திலிருந்து வீடு திரும்பியபோது, தன் மனைவியுடன் ஒரு மனிதன் இருப்பதைக் கண்டார்கள். அவர் தனது கண்களால் பார்த்தார்கள், காதுகளால் கேட்டார்கள்; எனினும் காலை வரை அந்த மனிதனைத் தொந்தரவு செய்யவில்லை. காலையில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் சென்று, 'அல்லாஹ்வின் தூதரே! நான் இரவில் என் வீட்டிற்குச் சென்றபோது, என் மனைவியுடன் ஒரு மனிதனைக் கண்டேன். என் கண்களால் பார்த்தேன், காதுகளால் கேட்டேன்' என்று கூறினார்கள். ஹிலால் (ரழி) அவர்கள் சொன்னதைக் கேட்டு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிகவும் வருத்தமடைந்தார்கள். அப்போது அன்சாரிகள் ஒன்று கூடி, 'ஏற்கனவே ஸஃத் பின் உபாதா (ரழி) கூறிய கருத்தால் நாம் சோதிக்கப்பட்டோம். இப்போது ஹிலால் பின் உமைய்யாவுக்கு (ரழி) தண்டனை வழங்கப்பட்டு, மக்கள் முன் அவரது சாட்சியம் செல்லாததாக அறிவிக்கப்படுமே' என்று கவலைப்பட்டார்கள். அப்போது ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! இந்தப் பிரச்சினையில் இருந்து அல்லாஹ் எனக்கு ஒரு வழியை ஏற்படுத்துவான் என்று நம்புகிறேன்' என்று கூறினார்கள். மேலும் ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! நான் சொன்ன செய்தியால் நீங்கள் வருத்தமடைந்திருப்பதை நான் காண்கிறேன். ஆனால், நான் உண்மையையே கூறுகிறேன் என்பதை அல்லாஹ் அறிவான்' என்றார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவருக்குக் கசையடி தண்டனை கொடுக்க எண்ணியபோது, அல்லாஹ் தனது தூதருக்கு வஹீ (இறைச்செய்தி) அருளினான். வஹீ (இறைச்செய்தி) அருளப்படும்போது ஏற்படும் முக மாற்றத்தைக் கண்டு நபித்தோழர்கள் அதை உணர்ந்துகொண்டார்கள்; வஹீ (இறைச்செய்தி) முடியும் வரை அவர்களைத் தொந்தரவு செய்யாமல் அமைதியாக இருந்தார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَرْمُونَ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">شُهَدَآءُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَنفُسُهُمْ</span> <span class=\"quran-arabic-font text-success\">فَشَهَادَةُ</span> <span class=\"quran-arabic-font text-success\">أَحَدِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعُ</span> <span class=\"quran-arabic-font text-success\">شَهَادَاتٍ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span><br />\r\n<br />\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்தி, தங்களைத் தவிர வேறு சாட்சிகள் இல்லாதவர்களுக்கு, அவர்களில் ஒவ்வொருவரின் சாட்சியமும் அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்வதாகும்...) வஹீ (இறைச்செய்தி) முடிவடைந்ததும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَبْشِرْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">هِلَالُ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">فَرَجًا</span> <span class=\"quran-arabic-font text-success\">وَمَخْرَجًا</span>»<br />\r\n<br />\r\n(ஹிலாலே! நற்செய்தி பெறுவீராக, நிச்சயமாக அல்லாஹ் உமக்கு ஒரு தீர்வையும் வழியையும் ஏற்படுத்திவிட்டான்) என்று கூறினார்கள்.<br />\r\n<br />\r\nஹிலால் (ரழி) அவர்கள், 'இதைத்தான் என் இறைவனிடம் எதிர்பார்த்துக் கொண்டிருந்தேன்; அவன் போற்றுதலுக்குரியவன்' என்று கூறினார்கள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَرْسِلُوا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهَا</span>»<br />\r\n<br />\r\n(அவளை அழைத்து வாருங்கள்) என்று கூறினார்கள். அவள் வந்ததும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருவரிடமும் இந்த வசனத்தை ஓதிக் காட்டி, இவ்வுலகத் தண்டனையை விட மறுமையின் தண்டனை மிகவும் கடுமையானது என்பதை அவர்களுக்கு நினைவூட்டினார்கள். ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ்வின் தூதரே, நான் அவளைப் பற்றி உண்மையையே கூறியிருக்கிறேன்' என்றார். ஆனால் அவளோ, 'அவர் பொய் சொல்கிறார்' என்று கூறினாள். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَاعِنُوا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span>»<br />\r\n<br />\r\n(இருவருக்கும் இடையில் லிஆன் செய்யச் சொல்லுங்கள்) என்று கட்டளையிட்டார்கள். அதன்படி ஹிலாலிடம் (ரழி) சாட்சியம் அளிக்கச் சொல்லப்பட்டது. அவர் தான் உண்மையாளர்களில் ஒருவர் என்று அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்தார். அவர் ஐந்தாவது முறை சத்தியம் செய்ய வந்தபோது, அவரிடம், 'ஹிலாலே! அல்லாஹ்வை அஞ்சிக் கொள்ளுங்கள். இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது. இந்த ஐந்தாவது சத்தியம் உங்களுக்குத் தண்டனையை உறுதிப்படுத்திவிடும்' என்று எச்சரிக்கப்பட்டது. அதற்கு அவர், 'அல்லாஹ்வின் மீது ஆணையாக! இதற்காக அல்லாஹ் என்னைத் தண்டிக்க மாட்டான். இதற்காக அவன் எனக்குக் கசையடி கொடுக்காமல் பாதுகாத்தது போலவே' என்று கூறி, தான் பொய் சொல்லியிருந்தால் அல்லாஹ்வின் சாபம் தன் மீது உண்டாகட்டும் என்று ஐந்தாவது முறையாகச் சத்தியம் செய்தார். பின்னர் அந்தப் பெண்ணிடம் நான்கு முறை அல்லாஹ்வின் மீது சத்தியம் செய்து, தன் கணவர் பொய் சொல்வதாகச் சாட்சியம் அளிக்கச் சொல்லப்பட்டது. அவள் ஐந்தாவது முறைக்கு வந்தபோது, அவளிடமும், 'அல்லாஹ்வை அஞ்சிக் கொள்; இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது. இந்த ஐந்தாவது சத்தியம் உனக்குத் தண்டனையை உறுதிப்படுத்திவிடும்' என்று கூறப்பட்டது. அவள் சிறிது நேரம் தயங்கி மௌனமாக நின்றாள். தன் குற்றத்தை ஒப்புக்கொள்ளப் போவது போல் தோன்றியது; ஆனால் உடனே, 'அல்லாஹ்வின் மீது ஆணையாக! என் கூட்டத்தாருக்கு நான் அவப்பெயரைத் தேடித்தர மாட்டேன்' என்று கூறி, தன் கணவர் சொல்வது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் தன் மீது உண்டாகட்டும் என்று ஐந்தாவது சத்தியத்தை முடித்தாள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவ்விருவரையும் பிரித்து வைத்தார்கள். பிறக்கப்போகும் குழந்தைக்குத் தந்தையின் பெயரைச் சூட்டக்கூடாது என்றும், அக்குழந்தையை யாரும் குறைகூறக் கூடாது என்றும், அவ்வாறு குறைகூறுபவர்கள் தண்டிக்கப்படுவார்கள் என்றும் தீர்ப்பளித்தார்கள். மேலும், ஹிலால் (ரழி) அவளுக்கு வீடோ உணவோ அளிக்க வேண்டிய அவசியமில்லை என்றும் தீர்ப்பளித்தார்கள். ஏனெனில் அவர்கள் விவாகரத்து மூலமாகவோ அல்லது கணவன் இறந்ததாலோ பிரியவில்லை. பின்னர் நபியவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">جَاءَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أُصَيْهِبَ</span> (<span class=\"quran-arabic-font text-success\">أُرَيْسِحَ</span>) <span class=\"quran-arabic-font text-success\">حَمْشَ</span> <span class=\"quran-arabic-font text-success\">السَّاقَيْنِ،</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لِهِلَالٍ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">جَاءَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَوْرَقَ</span> <span class=\"quran-arabic-font text-success\">جَعَدًا</span> <span class=\"quran-arabic-font text-success\">جُمَالِيًّا</span> <span class=\"quran-arabic-font text-success\">خَدَلَّجَ</span> <span class=\"quran-arabic-font text-success\">السَّاقَيْنِ</span> <span class=\"quran-arabic-font text-success\">سَابِغَ</span> <span class=\"quran-arabic-font text-success\">الْأَلْيَتَيْنِ،</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لِلَّذِي</span> <span class=\"quran-arabic-font text-success\">رُمِيَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span>»<br />\r\n<br />\r\n(அவள் பிறக்கும் குழந்தை செந்நிறமாகவும், மெலிந்த தொடைகளையும் கால்களையும் கொண்டிருந்தால், அது ஹிலாலின் குழந்தை. அவ்வாறன்றி, அக்குழந்தை கருமை நிறமாகவும், சுருள் முடியுடனும், தடித்த கால்களுடனும், பருத்த பிட்டங்களுடனும் இருந்தால், அவள் மீது சுமத்தப்பட்ட குற்றச்சாட்டு உண்மை என்று அர்த்தம்.) பின்னர் அவள், சுருள் முடி, தடித்த கால்கள் மற்றும் பருத்த பிட்டங்கள் கொண்ட குழந்தையைப் பெற்றெடுத்தாள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْلَا</span> <span class=\"quran-arabic-font text-success\">الْأَيْمَانُ</span> <span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">وَلَهَا</span> <span class=\"quran-arabic-font text-success\">شَأْنٌ</span>»<br />\r\n<br />\r\n(அவள் செய்த சத்தியங்கள் மட்டும் இல்லையென்றால், அவளுடைய விவகாரத்தில் நான் ஒரு முடிவெடுத்திருப்பேன்) என்று கூறினார்கள்.\" இக்ரிமா (ரழி) அவர்கள் கூறுகையில், \"அந்தக் குழந்தை வளர்ந்து எகிப்தின் ஆளுநராகப் பதவி வகித்தது; அவன் தன் தாயின் பெயரைக் கொண்டே அழைக்கப்பட்டான், எந்தத் தந்தையுடனும் அவன் தொடர்புபடுத்தப்படவில்லை\" என்று குறிப்பிட்டார்கள். அபூ தாவூத் இதே போன்ற ஒரு சுருக்கமான செய்தியைப் பதிவு செய்துள்ளார். இந்த ஹதீஸிற்கு ஆதாரமான செய்திகள் புகாரி மற்றும் முஸ்லிம் போன்ற ஸஹீஹ் நூல்களில் பல அறிவிப்பாளர் தொடர்களுடன் காணப்படுகின்றன. புகாரியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஹிலால் பின் உமைய்யா (ரழி) அவர்கள் தனது மனைவியை ஷரீக் பின் ஸஹ்மாவுடன் சேர்த்துத் தவறு செய்ததாக நபி (ஸல்) அவர்களிடம் குற்றம் சாட்டினார்கள். அப்போது நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْبَيِّنَةَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">حَدٌّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظَهْرِكَ</span>»<br />\r\n<br />\r\n(ஆதாரம் கொண்டு வா, இல்லையேல் உன் முதுகில் தண்டனை நிறைவேற்றப்படும்) என்று கூறினார்கள். அவர், \"அல்லாஹ்வின் தூதரே! எங்களில் ஒருவர் தன் மனைவியுடன் ஒரு அந்நிய மனிதனைக் கண்டால், அவர் ஆதாரம் தேடியா ஓடுவார்?\" என்று கேட்டார். நபி (ஸல்) அவர்கள் மீண்டும்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْبَيِّنَةَ</span> <span class=\"quran-arabic-font text-success\">وَإِلَّا</span> <span class=\"quran-arabic-font text-success\">حَدٌّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظَهْرِكَ</span>»<br />\r\n<br />\r\n(ஆதாரம் கொண்டு வா, இல்லையேல் உன் முதுகில் தண்டனை தான்) என்று கூறினார்கள். அப்போது ஹிலால் (ரழி), \"உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! நான் உண்மையைத்தான் கூறுகிறேன். நிச்சயமாக அல்லாஹ் எனது முதுகில் கசையடி விழுவதைத் தடுக்கும் ஒரு செய்தியை இறக்கி வைப்பான்\" என்று கூறினார்கள். அதன் பின்னரே ஜிப்ரீல் (அலை) அவர்கள் வஹீ (இறைச்செய்தி) கொண்டு வந்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَرْمُونَ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجَهُمْ</span><br />\r\n<br />\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்துபவர்கள்...) என்ற வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக அவர் உண்மையாளர்களில் ஒருவர்) - <a href=\"qurandisp.php?sura=24&ayah=6\" class=\"link\">24:6</a> என்பது வரை அருளப்பட்டது. வஹீ (இறைச்செய்தி) முடிந்ததும் நபி (ஸல்) அவர்கள் அவ்விருவரையும் அழைத்து வரச் செய்தார்கள். ஹிலால் (ரழி) தனது சாட்சியத்தைக் கூறியபோது, நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمَا</span> <span class=\"quran-arabic-font text-success\">كَاذِبٌ،</span> <span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمَا</span> <span class=\"quran-arabic-font text-success\">تَائِبٌ؟</span>»<br />\r\n<br />\r\n(நிச்சயமாக உங்களில் ஒருவர் பொய்யுரைக்கிறார் என்பதை அல்லாஹ் அறிவான். உங்களில் யாராவது பாவமன்னிப்புத் தேடித் திரும்புவார்களா?) என்று கேட்டார்கள். பின்னர் அந்தப் பெண் எழுந்து நின்று தனது சாட்சியத்தைக் கூறினாள். அவள் ஐந்தாவது சத்தியத்திற்கு வந்தபோது மக்கள் அவளைத் தடுத்து, \"நீ ஐந்தாவது முறை சத்தியம் செய்து, நீ பொய்யாக இருந்தால் அல்லாஹ்வின் சாபம் நிச்சயம் உன் மீது உண்டாகும்\" என்று எச்சரித்தார்கள். இப்னு அப்பாஸ் (ரழி) கூறுகிறார்கள்: \"அவள் தயங்கி நின்றதைக் கண்டு அவள் தன் மனதை மாற்றிக் கொள்வாள் என்று நாங்கள் நினைத்தோம். ஆனால் அவளோ, 'இன்று நான் என் கூட்டத்தாருக்கு அவமானத்தைத் தேடித் தரமாட்டேன்' என்று கூறி ஐந்தாவது சத்தியத்தையும் செய்தாள்.\" பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَبْصِرُوهَا،</span> <span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">جَاءَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَكْحَلَ</span> <span class=\"quran-arabic-font text-success\">الْعَيْنَيْنِ</span> <span class=\"quran-arabic-font text-success\">سَابِغَ</span> <span class=\"quran-arabic-font text-success\">الْأَلْيَتَيْنِ</span> <span class=\"quran-arabic-font text-success\">خَدَلَّجَ</span> <span class=\"quran-arabic-font text-success\">السَّاقَيْنِ،</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">لِشَرِيكِ</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">سَحْمَاءَ</span>»<br />\r\n<br />\r\n(அவள் பிரசவிக்கும் வரை காத்திருங்கள்; அந்தக் குழந்தையின் கண்கள் சுர்மா தீட்டியது போலவும், பிட்டங்கள் பருத்தும், கால்கள் தடித்தும் இருந்தால் அது ஷரீக் பின் ஸஹ்மாவின் குழந்தையாகும்) என்று கூறினார்கள். அவள் அவ்வாறே ஒரு குழந்தையைப் பெற்றெடுத்தாள். அப்போது நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْلَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَضَى</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">كِتَابِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">لَكَانَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">وَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">شَأْنٌ</span>»<br />\r\n<br />\r\n(அல்லாஹ்வின் வேதத்தில் ஏற்கனவே சட்டம் வந்திருக்காவிட்டால், அவளுடைய விஷயத்தில் நான் ஒரு முடிவெடுத்திருப்பேன்) என்று கூறினார்கள். இந்த அறிவிப்பு புகாரியில் மட்டுமே உள்ளது; எனினும் இது தொடர்பான செய்திகள் இப்னு அப்பாஸ் (ரழி) மற்றும் பிறரிடமிருந்தும் வந்துள்ளன. இமாம் அஹ்மத் அவர்கள், ஸஈத் பின் ஜுபைர் (ரழி) அவர்கள் கூறியதாவது: இப்னு அஸ்-ஸுபைரின் (ரழி) ஆட்சிக்காலத்தில், லிஆன் செய்த தம்பதியர் பிரிக்கப்பட வேண்டுமா என்று என்னிடம் கேட்கப்பட்டது. எனக்கு விடை தெரியாததால், இப்னு உமர் (ரழி) அவர்களின் வீட்டிற்குச் சென்று கேட்டேன். அவர், \"சுப்ஹானல்லாஹ்! முதன்முதலில் இதைப் பற்றி இன்னாரின் மகன் இன்னார்தான் கேட்டார். அவர், 'அல்லாஹ்வின் தூதரே! ஒரு மனிதன் தன் மனைவியுடன் அந்நியன் இருப்பதை நேரில் கண்டால் என்ன செய்வது? அவன் அதைப் பற்றிப் பேசினால் மிகவும் பாரதூரமான விஷயமாகிவிடும்; அமைதியாக இருந்தாலும் மிகப்பெரிய பாவத்தை மறைத்ததாகிவிடும்' என்று கேட்டார்.\" நபி (ஸல்) அவர்கள் முதலில் பதிலளிக்கவில்லை. பின்னர் அவர் மீண்டும் வந்து, 'நான் கேட்ட கேள்வி இப்போது எனக்கே சோதனையாக வந்துவிட்டது' என்று கூறினார். அப்போதுதான் அல்லாஹ் இந்த வசனங்களை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَرْمُونَ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجَهُمْ</span><br />\r\n<br />\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்துபவர்கள்...) என்பது முதல்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">غَضَبَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span><br />\r\n<br />\r\n(அவர் உண்மையைப் பேசினால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்பது வரை.) பின்னர் நபி (ஸல்) அவர்கள் அந்த மனிதருக்கு அறிவுரை கூறி, அல்லாஹ்வை நினைவூட்டினார்கள்; இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது என்று கூறினார்கள். அவர், 'உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! நான் பொய் சொல்லவில்லை' என்றார். பின்னர் நபியவர்கள் அந்தப் பெண்ணிடமும் அவ்வாறே அறிவுரை கூறினார்கள். அவள், 'உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! அவர் பொய் சொல்கிறார்' என்றாள். பின்னர் நபி (ஸல்) அவர்கள் அந்த மனிதரை நான்கு முறை சத்தியம் செய்யச் சொன்னார்கள், ஐந்தாவது முறை அவர் பொய்யராக இருந்தால் அல்லாஹ்வின் சாபம் அவர் மீது உண்டாகட்டும் என்று சத்தியம் செய்யச் சொன்னார்கள். பின்னர் அந்தப் பெண்ணையும் நான்கு முறை சத்தியம் செய்யச் சொன்னார்கள்; ஐந்தாவது முறை தன் கணவன் சொல்வது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் தன் மீது உண்டாகட்டும் என்று சத்தியம் செய்யச் சொன்னார்கள். அதன் பின்னரே நபி (ஸல்) அவர்கள் அவ்விருவரையும் பிரித்து வைத்தார்கள்.\" இது நஸாயி, புகாரி மற்றும் முஸ்லிம் ஆகிய நூல்களில் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />","text":"லிஆனின் விபரங்கள்\n\r\n\n\r\nஇந்த வசனம் கணவன்மார்களுக்கு ஒரு தீர்வை வழங்குகிறது. ஒரு கணவன் தன் மனைவியைக் குற்றம் சாட்டி, அதற்குரிய ஆதாரத்தைக் கொண்டு வர முடியாவிட்டால், அல்லாஹ் கட்டளையிட்டபடி அவர் 'லிஆன்' (சபதமேற்றுப் பிரிதல்) செய்யலாம். அதாவது, அவர் தனது மனைவியை ஆட்சியாளர் (இமாம்) முன் கொண்டு வந்து, தான் சுமத்தும் குற்றச்சாட்டைத் தெரிவிக்க வேண்டும். பின்னர் ஆட்சியாளர், நான்கு சாட்சிகள் முன்னிலையில் அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்யுமாறு அவரிடம் கோருவார்.\n\r\n\n\r\nإِنَّهُ لَمِنَ الصَّادِقِينَ\n\r\n\n\r\n(நிச்சயமாக அவர் உண்மையே கூறுகிறார் என்று) தன் மனைவியின் மீதான விபச்சாரக் குற்றச்சாட்டில் அவர் சத்தியம் செய்ய வேண்டும்.\n\r\n\n\r\nوَالْخَامِسَةُ أَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِن كَانَ مِنَ الْكَاذِبِينَ\n\r\n\n\r\n(ஐந்தாவது முறை; அவர் பொய்யராக இருந்தால் அல்லாஹ்வின் சாபம் அவர் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) அவர் அவ்வாறு கூறிவிட்டால், அந்த லிஆன் மூலமாகவே அவள் அவரிடமிருந்து விவாகரத்து செய்யப்படுகிறாள். அவள் அவருக்கு நிரந்தரமாகத் தடை செய்யப்பட்டவளாகிறாள்; மேலும் அவர் அவளுக்குரிய மஹரைக் கொடுத்துவிட வேண்டும். அவள் மீது விபச்சாரத்திற்கான (ஸினா) தண்டனை நிறைவேற்றப்பட வேண்டும். எனினும், அவளும் லிஆன் செய்து, தன் கணவன் பொய்யுரைப்பதாக அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்தால் தவிர, அந்தத் தண்டனையிலிருந்து அவள் தப்ப முடியாது.\n\r\n\n\r\nوَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَآ إِن كَانَ مِنَ الصَّادِقِينَ\n\r\n\n\r\n(ஐந்தாவது முறை; அவர் கூறுவது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَيَدْرَؤُاْ عَنْهَا الْعَذَابَ\n\r\n\n\r\n(ஆனால் அவள் தண்டனையைத் தடுத்துக் கொள்வாள்) அதாவது, அவளுக்கு விதிக்கப்பட்ட தண்டனையை.\n\r\n\n\r\nوَيَدْرَؤُاْ عَنْهَا الْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ - وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَآ إِن كَانَ مِنَ الصَّادِقِينَ\n\r\n\n\r\n(அவர் பொய் சொல்கிறார் என்று அவள் நான்கு முறை அல்லாஹ்வின் மீது சாட்சியம் கூறினால். ஐந்தாவது முறையாக, அவர் உண்மையைப் பேசினால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்று கூற வேண்டும்.) ஒரு பெண் விபச்சாரம் செய்ததாகத் தன் மனைவியை அம்பலப்படுத்த ஒரு ஆண் முன்வருகிறான் என்றால், பொதுவாக அவன் உண்மையைப் பேசினாலன்றி அந்த அளவிற்குச் செல்ல மாட்டான் என்பதை அனைவரும் அறிவர். எனவேதான், பெண்ணின் விஷயத்தில் ஐந்தாவது சத்தியத்தில் 'அல்லாஹ்வின் கோபம்' (கதப்) எனக் குறிப்பிடப்பட்டுள்ளது. ஏனெனில், உண்மையை அறிந்திருந்தும் அதிலிருந்து விலகிச் செல்பவர் மீதே அல்லாஹ்வின் கோபம் உண்டாகும். பின்னர் அல்லாஹ் தனது படைப்புகளுக்கு வழங்கிய அருளையும் கருணையையும் குறிப்பிடுகிறான்; அவர்கள் இக்கட்டான சூழலில் இருக்கும்போது அதிலிருந்து வெளியேற ஒரு வழியை அவன் ஏற்படுத்திக் கொடுத்துள்ளான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ\n\r\n\n\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால்!) அதாவது, உங்கள் விவகாரங்கள் பல உங்களுக்கு மிகவும் சிரமமாக இருந்திருக்கும்.\n\r\n\n\r\nوَأَنَّ اللَّهَ تَوَّابٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் பாவமன்னிப்பை ஏற்றுக்கொள்பவன்,) அதாவது, உறுதிமொழி எடுத்து சத்தியம் செய்த பின்னரும் தனது அடியார்களிடம் இருந்து மன்னிப்பை ஏற்றுக்கொள்கிறான்.\n\r\n\n\r\nحَكِيمٌ\n\r\n\n\r\n(அவன் ஞானமிக்கவன்.) அவன் விதிக்கும் சட்டங்களிலும், கட்டளைகளிலும், விலக்கல்களிலும் அளப்பரிய ஞானம் உடையவன். இந்த வசனத்தை எவ்வாறு நடைமுறைப்படுத்த வேண்டும், இது ஏன் அருளப்பட்டது, எந்த நபித்தோழர்களைப் (ரழி) பற்றி இது அருளப்பட்டது என்பதை விளக்கும் ஹதீஸ்கள் பல உள்ளன.\n\r\n\n\r\nலிஆன் வசனம் அருளப்பட்டதற்கான காரணம்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"எப்போது இந்த வசனம்,\n\r\n\n\r\nوَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُواْ بِأَرْبَعَةِ شُهَدَآءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلاَ تَقْبَلُواْ لَهُمْ شَهَادَةً أَبَداً\n\r\n\n\r\n(கற்புள்ள பெண்கள் மீது பழி சுமத்தி, பின்னர் நான்கு சாட்சிகளைக் கொண்டு வராதவர்களுக்கு எண்பது கசையடிகள் கொடுங்கள்; மேலும் அவர்களின் சாட்சியத்தை ஒருபோதும் ஏற்றுக்கொள்ளாதீர்கள் - 24:4) அருளப்பட்டதோ, அப்போது அன்சாரிகளின் தலைவரான ஸஃத் பின் உபாதா (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! இது இப்படியா அருளப்பட்டது?' என்று கேட்டார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«يَا مَعْشَرَ الْأَنْصَارِ أَلَا تَسْمَعُونَ مَا يَقُولُ سَيِّدُكُمْ؟»\n\r\n\n\r\n(அன்சாரிகளே! உங்கள் தலைவர் என்ன கூறுகிறார் என்று கேட்டீர்களா?) என்று கேட்டார்கள்.\n\r\n\n\r\nஅதற்கு அவர்கள், 'அல்லாஹ்வின் தூதரே! அவரைக் குறை சொல்லாதீர்கள், அவர் மிகவும் ரோஷமுள்ள மனிதர். அல்லாஹ்வின் மீது ஆணையாக, அவர் கன்னிப் பெண்ணைத் தவிர வேறு யாரையும் மணந்ததில்லை. அவர் ஒரு பெண்ணை விவாகரத்து செய்துவிட்டால், அவரது ரோஷத்திற்கு அஞ்சி எங்களில் யாரும் அவளை மணக்கத் துணிய மாட்டோம்' என்று கூறினார்கள். அப்போது ஸஃத் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக, அல்லாஹ்வின் தூதரே! இந்த வசனம் உண்மை என்றும் அது அல்லாஹ்விடமிருந்தே வந்தது என்றும் எனக்குத் தெரியும். ஆனால் நான் வியப்படைகிறேன்; என் மனைவியுடன் ஒரு அந்நிய மனிதன் இருப்பதைக் கண்டால், நான் நான்கு சாட்சிகளை அழைத்து வரும் வரை அவனை ஒன்றும் செய்யாமல் இருக்க வேண்டுமா? அல்லாஹ்வின் மீது ஆணையாக, நான் சாட்சிகளைத் திரட்டுவதற்குள் அவன் தன் காரியத்தை முடித்திருப்பானே!' என்று கூறினார்கள். சிறிது காலம் கழித்து, ஹிலால் பின் உமைய்யா (ரழி) அவர்கள் - யாருடைய பாவமன்னிப்பு ஏற்றுக்கொள்ளப்பட்டதோ அந்த மூவரில் ஒருவர் - ஒரு இரவு வேளையில் தனது தோட்டத்திலிருந்து வீடு திரும்பியபோது, தன் மனைவியுடன் ஒரு மனிதன் இருப்பதைக் கண்டார்கள். அவர் தனது கண்களால் பார்த்தார்கள், காதுகளால் கேட்டார்கள்; எனினும் காலை வரை அந்த மனிதனைத் தொந்தரவு செய்யவில்லை. காலையில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் சென்று, 'அல்லாஹ்வின் தூதரே! நான் இரவில் என் வீட்டிற்குச் சென்றபோது, என் மனைவியுடன் ஒரு மனிதனைக் கண்டேன். என் கண்களால் பார்த்தேன், காதுகளால் கேட்டேன்' என்று கூறினார்கள். ஹிலால் (ரழி) அவர்கள் சொன்னதைக் கேட்டு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிகவும் வருத்தமடைந்தார்கள். அப்போது அன்சாரிகள் ஒன்று கூடி, 'ஏற்கனவே ஸஃத் பின் உபாதா (ரழி) கூறிய கருத்தால் நாம் சோதிக்கப்பட்டோம். இப்போது ஹிலால் பின் உமைய்யாவுக்கு (ரழி) தண்டனை வழங்கப்பட்டு, மக்கள் முன் அவரது சாட்சியம் செல்லாததாக அறிவிக்கப்படுமே' என்று கவலைப்பட்டார்கள். அப்போது ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! இந்தப் பிரச்சினையில் இருந்து அல்லாஹ் எனக்கு ஒரு வழியை ஏற்படுத்துவான் என்று நம்புகிறேன்' என்று கூறினார்கள். மேலும் ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! நான் சொன்ன செய்தியால் நீங்கள் வருத்தமடைந்திருப்பதை நான் காண்கிறேன். ஆனால், நான் உண்மையையே கூறுகிறேன் என்பதை அல்லாஹ் அறிவான்' என்றார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவருக்குக் கசையடி தண்டனை கொடுக்க எண்ணியபோது, அல்லாஹ் தனது தூதருக்கு வஹீ (இறைச்செய்தி) அருளினான். வஹீ (இறைச்செய்தி) அருளப்படும்போது ஏற்படும் முக மாற்றத்தைக் கண்டு நபித்தோழர்கள் அதை உணர்ந்துகொண்டார்கள்; வஹீ (இறைச்செய்தி) முடியும் வரை அவர்களைத் தொந்தரவு செய்யாமல் அமைதியாக இருந்தார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَّهُمْ شُهَدَآءُ إِلاَّ أَنفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ\n\r\n\n\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்தி, தங்களைத் தவிர வேறு சாட்சிகள் இல்லாதவர்களுக்கு, அவர்களில் ஒவ்வொருவரின் சாட்சியமும் அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்வதாகும்...) வஹீ (இறைச்செய்தி) முடிவடைந்ததும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«أَبْشِرْ يَا هِلَالُ فَقَدْ جَعَلَ اللهُ لَكَ فَرَجًا وَمَخْرَجًا»\n\r\n\n\r\n(ஹிலாலே! நற்செய்தி பெறுவீராக, நிச்சயமாக அல்லாஹ் உமக்கு ஒரு தீர்வையும் வழியையும் ஏற்படுத்திவிட்டான்) என்று கூறினார்கள்.\n\r\n\n\r\nஹிலால் (ரழி) அவர்கள், 'இதைத்தான் என் இறைவனிடம் எதிர்பார்த்துக் கொண்டிருந்தேன்; அவன் போற்றுதலுக்குரியவன்' என்று கூறினார்கள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«أَرْسِلُوا إِلَيْهَا»\n\r\n\n\r\n(அவளை அழைத்து வாருங்கள்) என்று கூறினார்கள். அவள் வந்ததும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருவரிடமும் இந்த வசனத்தை ஓதிக் காட்டி, இவ்வுலகத் தண்டனையை விட மறுமையின் தண்டனை மிகவும் கடுமையானது என்பதை அவர்களுக்கு நினைவூட்டினார்கள். ஹிலால் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ்வின் தூதரே, நான் அவளைப் பற்றி உண்மையையே கூறியிருக்கிறேன்' என்றார். ஆனால் அவளோ, 'அவர் பொய் சொல்கிறார்' என்று கூறினாள். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«لَاعِنُوا بَيْنَهُمَا»\n\r\n\n\r\n(இருவருக்கும் இடையில் லிஆன் செய்யச் சொல்லுங்கள்) என்று கட்டளையிட்டார்கள். அதன்படி ஹிலாலிடம் (ரழி) சாட்சியம் அளிக்கச் சொல்லப்பட்டது. அவர் தான் உண்மையாளர்களில் ஒருவர் என்று அல்லாஹ்வின் மீது நான்கு முறை சத்தியம் செய்தார். அவர் ஐந்தாவது முறை சத்தியம் செய்ய வந்தபோது, அவரிடம், 'ஹிலாலே! அல்லாஹ்வை அஞ்சிக் கொள்ளுங்கள். இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது. இந்த ஐந்தாவது சத்தியம் உங்களுக்குத் தண்டனையை உறுதிப்படுத்திவிடும்' என்று எச்சரிக்கப்பட்டது. அதற்கு அவர், 'அல்லாஹ்வின் மீது ஆணையாக! இதற்காக அல்லாஹ் என்னைத் தண்டிக்க மாட்டான். இதற்காக அவன் எனக்குக் கசையடி கொடுக்காமல் பாதுகாத்தது போலவே' என்று கூறி, தான் பொய் சொல்லியிருந்தால் அல்லாஹ்வின் சாபம் தன் மீது உண்டாகட்டும் என்று ஐந்தாவது முறையாகச் சத்தியம் செய்தார். பின்னர் அந்தப் பெண்ணிடம் நான்கு முறை அல்லாஹ்வின் மீது சத்தியம் செய்து, தன் கணவர் பொய் சொல்வதாகச் சாட்சியம் அளிக்கச் சொல்லப்பட்டது. அவள் ஐந்தாவது முறைக்கு வந்தபோது, அவளிடமும், 'அல்லாஹ்வை அஞ்சிக் கொள்; இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது. இந்த ஐந்தாவது சத்தியம் உனக்குத் தண்டனையை உறுதிப்படுத்திவிடும்' என்று கூறப்பட்டது. அவள் சிறிது நேரம் தயங்கி மௌனமாக நின்றாள். தன் குற்றத்தை ஒப்புக்கொள்ளப் போவது போல் தோன்றியது; ஆனால் உடனே, 'அல்லாஹ்வின் மீது ஆணையாக! என் கூட்டத்தாருக்கு நான் அவப்பெயரைத் தேடித்தர மாட்டேன்' என்று கூறி, தன் கணவர் சொல்வது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் தன் மீது உண்டாகட்டும் என்று ஐந்தாவது சத்தியத்தை முடித்தாள். பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அவ்விருவரையும் பிரித்து வைத்தார்கள். பிறக்கப்போகும் குழந்தைக்குத் தந்தையின் பெயரைச் சூட்டக்கூடாது என்றும், அக்குழந்தையை யாரும் குறைகூறக் கூடாது என்றும், அவ்வாறு குறைகூறுபவர்கள் தண்டிக்கப்படுவார்கள் என்றும் தீர்ப்பளித்தார்கள். மேலும், ஹிலால் (ரழி) அவளுக்கு வீடோ உணவோ அளிக்க வேண்டிய அவசியமில்லை என்றும் தீர்ப்பளித்தார்கள். ஏனெனில் அவர்கள் விவாகரத்து மூலமாகவோ அல்லது கணவன் இறந்ததாலோ பிரியவில்லை. பின்னர் நபியவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنْ جَاءَتْ بِهِ أُصَيْهِبَ (أُرَيْسِحَ) حَمْشَ السَّاقَيْنِ، فَهُوَ لِهِلَالٍ، وَإِنْ جَاءَتْ بِهِ أَوْرَقَ جَعَدًا جُمَالِيًّا خَدَلَّجَ السَّاقَيْنِ سَابِغَ الْأَلْيَتَيْنِ، فَهُوَ لِلَّذِي رُمِيَتْ بِهِ»\n\r\n\n\r\n(அவள் பிறக்கும் குழந்தை செந்நிறமாகவும், மெலிந்த தொடைகளையும் கால்களையும் கொண்டிருந்தால், அது ஹிலாலின் குழந்தை. அவ்வாறன்றி, அக்குழந்தை கருமை நிறமாகவும், சுருள் முடியுடனும், தடித்த கால்களுடனும், பருத்த பிட்டங்களுடனும் இருந்தால், அவள் மீது சுமத்தப்பட்ட குற்றச்சாட்டு உண்மை என்று அர்த்தம்.) பின்னர் அவள், சுருள் முடி, தடித்த கால்கள் மற்றும் பருத்த பிட்டங்கள் கொண்ட குழந்தையைப் பெற்றெடுத்தாள். அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«لَوْلَا الْأَيْمَانُ لَكَانَ لِي وَلَهَا شَأْنٌ»\n\r\n\n\r\n(அவள் செய்த சத்தியங்கள் மட்டும் இல்லையென்றால், அவளுடைய விவகாரத்தில் நான் ஒரு முடிவெடுத்திருப்பேன்) என்று கூறினார்கள்.\" இக்ரிமா (ரழி) அவர்கள் கூறுகையில், \"அந்தக் குழந்தை வளர்ந்து எகிப்தின் ஆளுநராகப் பதவி வகித்தது; அவன் தன் தாயின் பெயரைக் கொண்டே அழைக்கப்பட்டான், எந்தத் தந்தையுடனும் அவன் தொடர்புபடுத்தப்படவில்லை\" என்று குறிப்பிட்டார்கள். அபூ தாவூத் இதே போன்ற ஒரு சுருக்கமான செய்தியைப் பதிவு செய்துள்ளார். இந்த ஹதீஸிற்கு ஆதாரமான செய்திகள் புகாரி மற்றும் முஸ்லிம் போன்ற ஸஹீஹ் நூல்களில் பல அறிவிப்பாளர் தொடர்களுடன் காணப்படுகின்றன. புகாரியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஹிலால் பின் உமைய்யா (ரழி) அவர்கள் தனது மனைவியை ஷரீக் பின் ஸஹ்மாவுடன் சேர்த்துத் தவறு செய்ததாக நபி (ஸல்) அவர்களிடம் குற்றம் சாட்டினார்கள். அப்போது நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«الْبَيِّنَةَ أَوْ حَدٌّ فِي ظَهْرِكَ»\n\r\n\n\r\n(ஆதாரம் கொண்டு வா, இல்லையேல் உன் முதுகில் தண்டனை நிறைவேற்றப்படும்) என்று கூறினார்கள். அவர், \"அல்லாஹ்வின் தூதரே! எங்களில் ஒருவர் தன் மனைவியுடன் ஒரு அந்நிய மனிதனைக் கண்டால், அவர் ஆதாரம் தேடியா ஓடுவார்?\" என்று கேட்டார். நபி (ஸல்) அவர்கள் மீண்டும்,\n\r\n\n\r\n«الْبَيِّنَةَ وَإِلَّا حَدٌّ فِي ظَهْرِكَ»\n\r\n\n\r\n(ஆதாரம் கொண்டு வா, இல்லையேல் உன் முதுகில் தண்டனை தான்) என்று கூறினார்கள். அப்போது ஹிலால் (ரழி), \"உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! நான் உண்மையைத்தான் கூறுகிறேன். நிச்சயமாக அல்லாஹ் எனது முதுகில் கசையடி விழுவதைத் தடுக்கும் ஒரு செய்தியை இறக்கி வைப்பான்\" என்று கூறினார்கள். அதன் பின்னரே ஜிப்ரீல் (அலை) அவர்கள் வஹீ (இறைச்செய்தி) கொண்டு வந்தார்கள்:\n\r\n\n\r\nوَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ\n\r\n\n\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்துபவர்கள்...) என்ற வசனம்,\n\r\n\n\r\nإِن كَانَ مِنَ الصَّادِقِينَ\n\r\n\n\r\n(நிச்சயமாக அவர் உண்மையாளர்களில் ஒருவர்) - 24:6 என்பது வரை அருளப்பட்டது. வஹீ (இறைச்செய்தி) முடிந்ததும் நபி (ஸல்) அவர்கள் அவ்விருவரையும் அழைத்து வரச் செய்தார்கள். ஹிலால் (ரழி) தனது சாட்சியத்தைக் கூறியபோது, நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«إِنَّ اللهَ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ، فَهَلْ مِنْكُمَا تَائِبٌ؟»\n\r\n\n\r\n(நிச்சயமாக உங்களில் ஒருவர் பொய்யுரைக்கிறார் என்பதை அல்லாஹ் அறிவான். உங்களில் யாராவது பாவமன்னிப்புத் தேடித் திரும்புவார்களா?) என்று கேட்டார்கள். பின்னர் அந்தப் பெண் எழுந்து நின்று தனது சாட்சியத்தைக் கூறினாள். அவள் ஐந்தாவது சத்தியத்திற்கு வந்தபோது மக்கள் அவளைத் தடுத்து, \"நீ ஐந்தாவது முறை சத்தியம் செய்து, நீ பொய்யாக இருந்தால் அல்லாஹ்வின் சாபம் நிச்சயம் உன் மீது உண்டாகும்\" என்று எச்சரித்தார்கள். இப்னு அப்பாஸ் (ரழி) கூறுகிறார்கள்: \"அவள் தயங்கி நின்றதைக் கண்டு அவள் தன் மனதை மாற்றிக் கொள்வாள் என்று நாங்கள் நினைத்தோம். ஆனால் அவளோ, 'இன்று நான் என் கூட்டத்தாருக்கு அவமானத்தைத் தேடித் தரமாட்டேன்' என்று கூறி ஐந்தாவது சத்தியத்தையும் செய்தாள்.\" பின்னர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«أَبْصِرُوهَا، فَإِنْ جَاءَتْ بِهِ أَكْحَلَ الْعَيْنَيْنِ سَابِغَ الْأَلْيَتَيْنِ خَدَلَّجَ السَّاقَيْنِ، فَهُوَ لِشَرِيكِ ابْنِ سَحْمَاءَ»\n\r\n\n\r\n(அவள் பிரசவிக்கும் வரை காத்திருங்கள்; அந்தக் குழந்தையின் கண்கள் சுர்மா தீட்டியது போலவும், பிட்டங்கள் பருத்தும், கால்கள் தடித்தும் இருந்தால் அது ஷரீக் பின் ஸஹ்மாவின் குழந்தையாகும்) என்று கூறினார்கள். அவள் அவ்வாறே ஒரு குழந்தையைப் பெற்றெடுத்தாள். அப்போது நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«لَوْلَا مَا مَضَى مِنْ كِتَابِ اللهِ لَكَانَ لِي وَ لَهَا شَأْنٌ»\n\r\n\n\r\n(அல்லாஹ்வின் வேதத்தில் ஏற்கனவே சட்டம் வந்திருக்காவிட்டால், அவளுடைய விஷயத்தில் நான் ஒரு முடிவெடுத்திருப்பேன்) என்று கூறினார்கள். இந்த அறிவிப்பு புகாரியில் மட்டுமே உள்ளது; எனினும் இது தொடர்பான செய்திகள் இப்னு அப்பாஸ் (ரழி) மற்றும் பிறரிடமிருந்தும் வந்துள்ளன. இமாம் அஹ்மத் அவர்கள், ஸஈத் பின் ஜுபைர் (ரழி) அவர்கள் கூறியதாவது: இப்னு அஸ்-ஸுபைரின் (ரழி) ஆட்சிக்காலத்தில், லிஆன் செய்த தம்பதியர் பிரிக்கப்பட வேண்டுமா என்று என்னிடம் கேட்கப்பட்டது. எனக்கு விடை தெரியாததால், இப்னு உமர் (ரழி) அவர்களின் வீட்டிற்குச் சென்று கேட்டேன். அவர், \"சுப்ஹானல்லாஹ்! முதன்முதலில் இதைப் பற்றி இன்னாரின் மகன் இன்னார்தான் கேட்டார். அவர், 'அல்லாஹ்வின் தூதரே! ஒரு மனிதன் தன் மனைவியுடன் அந்நியன் இருப்பதை நேரில் கண்டால் என்ன செய்வது? அவன் அதைப் பற்றிப் பேசினால் மிகவும் பாரதூரமான விஷயமாகிவிடும்; அமைதியாக இருந்தாலும் மிகப்பெரிய பாவத்தை மறைத்ததாகிவிடும்' என்று கேட்டார்.\" நபி (ஸல்) அவர்கள் முதலில் பதிலளிக்கவில்லை. பின்னர் அவர் மீண்டும் வந்து, 'நான் கேட்ட கேள்வி இப்போது எனக்கே சோதனையாக வந்துவிட்டது' என்று கூறினார். அப்போதுதான் அல்லாஹ் இந்த வசனங்களை அருளினான்:\n\r\n\n\r\nوَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ\n\r\n\n\r\n(தங்கள் மனைவிகள் மீது பழி சுமத்துபவர்கள்...) என்பது முதல்,\n\r\n\n\r\nأَنَّ غَضَبَ اللَّهِ عَلَيْهَآ إِن كَانَ مِنَ الصَّادِقِينَ\n\r\n\n\r\n(அவர் உண்மையைப் பேசினால் அல்லாஹ்வின் கோபம் அவள் மீது உண்டாகட்டும் என்பது வரை.) பின்னர் நபி (ஸல்) அவர்கள் அந்த மனிதருக்கு அறிவுரை கூறி, அல்லாஹ்வை நினைவூட்டினார்கள்; இவ்வுலகத் தண்டனை மறுமையின் தண்டனையை விட எளிதானது என்று கூறினார்கள். அவர், 'உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! நான் பொய் சொல்லவில்லை' என்றார். பின்னர் நபியவர்கள் அந்தப் பெண்ணிடமும் அவ்வாறே அறிவுரை கூறினார்கள். அவள், 'உங்களை உண்மையைக் கொண்டு அனுப்பியவன் மீது ஆணையாக! அவர் பொய் சொல்கிறார்' என்றாள். பின்னர் நபி (ஸல்) அவர்கள் அந்த மனிதரை நான்கு முறை சத்தியம் செய்யச் சொன்னார்கள், ஐந்தாவது முறை அவர் பொய்யராக இருந்தால் அல்லாஹ்வின் சாபம் அவர் மீது உண்டாகட்டும் என்று சத்தியம் செய்யச் சொன்னார்கள். பின்னர் அந்தப் பெண்ணையும் நான்கு முறை சத்தியம் செய்யச் சொன்னார்கள்; ஐந்தாவது முறை தன் கணவன் சொல்வது உண்மையாக இருந்தால் அல்லாஹ்வின் கோபம் தன் மீது உண்டாகட்டும் என்று சத்தியம் செய்யச் சொன்னார்கள். அதன் பின்னரே நபி (ஸல்) அவர்கள் அவ்விருவரையும் பிரித்து வைத்தார்கள்.\" இது நஸாயி, புகாரி மற்றும் முஸ்லிம் ஆகிய நூல்களில் பதிவு செய்யப்பட்டுள்ளது."},"11":{"html":"<strong>Al-Ifk (அவதூறு)</strong><br />\r\n<br />\r\n<br />\r\nஅடுத்த பத்து வசனங்களும் நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களைப் பற்றியே அருளப்பட்டன. நயவஞ்சகர்களில் அவதூறு மற்றும் பொய்யைப் பரப்பிய ஒரு கூட்டத்தினர், ஆயிஷா (ரழி) அவர்களின் மீது அபாண்டமாகப் பழி சுமத்தி, அவர்களைப் பற்றிப் பொய்களைப் பரப்பியபோது இது நிகழ்ந்தது. அல்லாஹ் ஆயிஷா (ரழி) அவர்களுக்காகவும், தனது தூதருக்காகவும் ரோஷம் கொண்டு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கண்ணியத்தைப் பாதுகாக்க ஆயிஷா (ரழி) அவர்களின் நிரபராதித்துவத்தை வஹீ (இறைச்செய்தி) மூலம் வெளிப்படுத்தினான். அவன் கூறினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">بِالإِفْكِ</span> <span class=\"quran-arabic-font text-success\">عُصْبَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, அந்த அவதூறைக் கொண்டு வந்தவர்கள் உங்களில் ஒரு குழுவினரே.) அதாவது அவர்கள் ஒன்று அல்லது இரண்டு பேர் அல்ல, ஒரு கூட்டத்தினர். இந்தக் குழுவில் முதன்மையானவன் நயவஞ்சகர்களின் தலைவனான அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். அவனே இந்தப் பொய்யைப் புனைந்து மற்றவர்களிடம் பரப்பினான். இறுதியில் சில முஸ்லிம்கள் அதனை நம்பத் தொடங்கினார்கள், மற்றவர்கள் அது உண்மையாக இருக்கலாமோ என்று எண்ணி அதைப் பற்றிப் பேச ஆரம்பித்தார்கள். குர்ஆன் வசனங்கள் அருளப்படும் வரை கிட்டத்தட்ட ஒரு மாத காலத்திற்கு இந்நிலை நீடித்தது. இது ஸஹீஹான ஹதீஸ்களில் பதிவாகியுள்ளது. இமாம் அஹ்மத் அவர்கள் அஸ்-ஸுஹ்ரி கூறியதாகப் பதிவு செய்துள்ளார்கள்: ஸயீத் இப்னுல் முஸய்யிப், உர்வா இப்னு அஸ்-ஸுபைர், அல்கமா இப்னு வக்காஸ் மற்றும் உபைதுல்லாஹ் இப்னு அப்துல்லாஹ் இப்னு உத்பா இப்னு மஸ்ஊத் ஆகியோர் நபி (ஸல்) அவர்களின் மனைவியான ஆயிஷா (ரழி) அவர்களைப் பற்றி அவதூறு பேசுபவர்கள் பேசியது குறித்தும், அல்லாஹ் அவர்களின் நிரபராதித்துவத்தை அறிவித்தது குறித்தும் என்னிடம் கூறினார்கள். அவர்கள் ஒவ்வொருவரும் இந்தச் சம்பவத்தின் ஒரு பகுதியை விவரித்தார்கள். அவர்களில் சிலருக்கு மற்றவர்களை விடக் கூடுதல் விவரங்கள் தெரிந்திருந்தன அல்லது மற்றவர்களை விடச் சிறப்பாக மனனம் செய்திருந்தார்கள். ஆயிஷா (ரழி) அவர்களிடமிருந்து நேரடியாகக் கேட்ட அந்த நால்வரிடமிருந்தும் நான் இந்த வரலாற்றைத் தெரிந்துகொண்டேன். ஒருவர் கூறிய செய்தியை மற்றவர்கள் கூறியது உறுதிப்படுத்தியது. அவர்கள் குறிப்பிட்டதாவது, நபி (ஸல்) அவர்களின் மனைவியான ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு பயணம் மேற்கொள்ள விரும்பினால், தம் மனைவியரிடையே சீட்டுக் குலுக்குவார்கள். அதில் யாருடைய பெயர் வருகிறதோ அவரைத் தம்மோடு அழைத்துச் செல்வார்கள்.\" ஆயிஷா (ரழி) அவர்கள் கூறினார்கள், \"அவ்வாறே ஒரு போர்ப் பயணத்தின்போது எங்களிடையே சீட்டுக் குலுக்கினார்கள், அதில் என் பெயர் வந்தது. எனவே நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் புறப்பட்டேன். இது ஹிஜாப் (மறைப்பு) பற்றிய கட்டளை அருளப்பட்ட பிறகு நிகழ்ந்தது. எனவே நான் ஒரு சிவிகையில் (ஒட்டகக் கட்டில்) அமர்ந்து பயணம் செய்தேன், தங்கும் இடங்களிலும் அதிலேயே தங்கியிருந்தேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அந்தப் போரை முடித்துவிட்டுத் திரும்பும் வரை நாங்கள் பயணத்தைத் தொடர்ந்தோம். நாங்கள் மதீனாவை நெருங்கிக் கொண்டிருந்தபோது ஒரு இடத்தில் தங்கி ஓய்வெடுத்தோம். பிறகு பயணம் தொடரப் போவதாக அறிவிக்கப்பட்டது. இதைக் கேட்ட நான், இயற்கை உபாதையைக் கழிப்பதற்காகப் படையிலிருந்து சற்றுத் தொலைவிற்கு வேகமாக நடந்து சென்றேன். பிறகு என் சிவிகையை நோக்கித் திரும்பி வந்தேன். அப்போது என் மார்பைத் தொட்டுப் பார்த்தபோது, கோமேதகம் மற்றும் பவளத்தினால் ஆன என் கழுத்து மாலை அறுந்து விழுந்திருப்பதை உணர்ந்தேன். எனவே நான் அதைக் கண்டெடுக்கத் திரும்பிச் சென்றேன். அங்கே தேடிக் கொண்டிருந்ததால் நான் திரும்ப வருவது தாமதமானது. இதற்கிடையில், என் சிவிகையை ஒட்டகத்தின் மீது தூக்கி வைக்கும் ஆட்கள் வந்து, நான் உள்ளே இருப்பதாகவே நினைத்து அதை அப்படியே ஒட்டகத்தின் மீது ஏற்றிவிட்டார்கள். அக்காலப் பெண்கள் மிகக் குறைவான உணவையே உட்கொண்டதால் மிகவும் மெலிந்தவர்களாக இருந்தனர். எனவே சிவிகை இலகுவாக இருந்ததைக் கண்டு அந்தப் பணியாளர்கள் சந்தேகப்படவில்லை. அவர்கள் அப்படியே புறப்பட்டுச் சென்றுவிட்டனர். படை நகர்ந்த பிறகுதான் என் மாலையைக் கண்டெடுத்தேன். பிறகு நான் தங்கியிருந்த இடத்திற்குத் திரும்பினேன். அங்கே அழைப்பதற்கோ பதில் சொல்வதற்கோ ஒருவரும் இல்லை. எனவே மக்கள் என்னைக் காணாமல் தேடித் திரும்புவார்கள் என்று எண்ணி நான் இருந்த இடத்திலேயே அமர்ந்துவிட்டேன். அவ்வாறு அமர்ந்திருந்தபோது எனக்கு உறக்கம் வந்துவிட, அப்படியே தூங்கிவிட்டேன். ஸஃப்வான் இப்னுல் முஅத்தல் அஸ்-ஸுலமி அத்-தக்வானி (ரழி) என்பவர் இரவில் படைக்குப் பின்னால் தங்கி ஓய்வெடுத்துவிட்டு, விடியற்காலை நேரத்தில் நான் இருந்த இடத்திற்கு வந்து சேர்ந்தார். அங்கே ஒருவர் தூங்கிக் கொண்டிருப்பதை அவர் கண்டார். ஹிஜாப் கட்டளை வருவதற்கு முன்பு அவர் என்னைப் பார்த்திருந்ததால், என்னைக் கண்டதும் அடையாளம் கண்டுகொண்டார். அவர் என்னைப் பார்த்து 'இன்னா லில்லாஹி வ இன்னா இலைஹி ராஜிஊன் (நிச்சயமாக நாம் அல்லாஹ்வுக்கே உரியவர்கள்; அவனிடமே நாம் திரும்புவோம்)' என்று கூறிய சத்தத்தைக் கேட்டு நான் விழித்தேன். உடனே என் மேலாடையால் (ஜில்பாப்) முகத்தை மறைத்துக் கொண்டேன். அல்லாஹ்வின் மீது ஆணையாக, அவர் என்னிடம் ஒரு வார்த்தைகூடப் பேசவில்லை. அவர் 'இன்னா லில்லாஹி வ இன்னா இலைஹி ராஜிஊன்' என்று சொன்னதைத் தவிர வேறெதுவும் என் காதில் விழவில்லை. அவர் தமது ஒட்டகத்தைக் கொண்டு வந்து, நான் ஏறுவதற்காக அதைக் கீழே மண்டியிடச் செய்தார். பிறகு அவர் ஒட்டகத்தை முன் நடத்திச் சென்றார். நண்பகல் (ளுஹர்) நேரத்தில் நாங்கள் படையைச் சென்றடைந்தோம்.<br />\r\n<br />\r\n<br />\r\nஎனக்கு நேர்ந்த இந்தச் சம்பவத்தால் சிலர் அழிவை நோக்கிச் சென்றனர். அவர்களில் முதன்மையானவன் அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். நாங்கள் மதீனா வந்து சேர்ந்ததும் நான் ஒரு மாதம் நோய்வாய்ப்பட்டிருந்தேன். அப்போதும் மக்கள் அவதூறு பேசுபவர்களின் பேச்சைப் பரப்பிக் கொண்டிருந்தார்கள், ஆனால் எனக்கு அது பற்றி எதுவும் தெரியாது. நான் உடல்நலமில்லாமல் இருந்தபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் என்னிடம் காட்டும் கனிவை நான் காணாததுதான் எனக்கு வருத்தத்தை அளித்தது. அவர்கள் வீட்டிற்குள் வந்து,<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">تِيكُمْ؟</span>»<br />\r\n<br />\r\n<br />\r\n(அந்தப் பெண் எப்படி இருக்கிறார்?) என்று மட்டும் கேட்டுவிட்டுச் சென்றுவிடுவார்கள். அதுதான் எனக்கு வேதனையாக இருந்தது. நான் உடல்நலம் தேறி வெளியே செல்லும் வரை ஏதோ தவறாக நடப்பதை நான் உணரவில்லை. ஒருமுறை நானும் உம்மு மிஸ்தஹ் அவர்களும் எங்களின் இயற்கை உபாதைகளைக் கழிக்க அல்-மனாஸிஃ என்ற இடத்திற்குச் சென்றோம். அக்காலத்தில் வீடுகளுக்கு அருகில் கழிப்பறைகள் இல்லாததால், இரவு நேரத்தில்தான் நாங்கள் வெளியே செல்வோம். இது பழைய அரேபியர்களின் பழக்கத்தைப் போன்றது. வீடுகளுக்குள் கழிப்பறை இருப்பதை நாங்கள் ஒரு தொந்தரவாகவும் அருவருப்பாகவும் கருதினோம். உம்மு மிஸ்தஹ் என்பவர் அபூ ருஹ்ம் இப்னுல் முத்தலிப் இப்னு அப்து மனாஃபின் மகளாவார். அவரின் தாயார் அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களின் அத்தை ஆவார். உம்மு மிஸ்தஹ் அவர்களின் மகன் மிஸ்தஹ் இப்னு உஸாஸா (ரழி) ஆவார். நாங்கள் எங்களது வேலையை முடித்துவிட்டுத் திரும்பும்போது, உம்மு மிஸ்தஹ் தனது ஆடையின் ஓரத்தில் தடுக்கி விழுந்து, 'மிஸ்தஹ் அழிந்து போகட்டும்!' என்று சாபமிட்டார். நான் அவரிடம், 'நீர் எவ்வளவு தவறான வார்த்தையைச் சொன்னீர்! பத்ருப் போரில் கலந்துகொண்ட ஒரு மனிதரையா திட்டுகிறீர்?' என்று கேட்டேன். அதற்கு அவர், 'பெண்ணே, அவர் உங்களைப் பற்றி என்ன சொன்னார் என்று உங்களுக்குத் தெரியாதா?' என்று கேட்டார். 'அவர் என்ன சொன்னார்?' என்று நான் கேட்டபோது, அவதூறு பேசுபவர்கள் சொல்லி வந்த செய்திகளை அவர் எனக்கு விளக்கினார். அதைக் கேட்டதும் எனது நோய் இன்னும் அதிகரித்தது. நான் வீடு திரும்பியதும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் என்னிடம் வந்து ஸலாம் கூறிவிட்டு,<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">تِيكُمْ؟</span>»<br />\r\n<br />\r\n<br />\r\n(அந்தப் பெண் எப்படி இருக்கிறார்?) என்று கேட்டார்கள். நான் அவர்களிடம், 'நான் என் பெற்றோரிடம் செல்ல எனக்கு அனுமதி அளிப்பீர்களா?' என்று கேட்டேன். அவர்களிடமிருந்து உண்மையை அறிந்து உறுதிப்படுத்திக் கொள்ளவே நான் விரும்பினேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதி வழங்க, நான் என் தாயிடம் சென்று, 'தாயே, மக்கள் என்ன பேசிக் கொள்கிறார்கள்?' என்று கேட்டேன். அதற்கு என் தாய், 'மகளே, வருத்தப்படாதே. அல்லாஹ்வின் மீது ஆணையாக, அழகிய ஒரு பெண்ணைத் தனது கணவன் நேசிக்கும்போது, அவருக்குச் சக மனைவிகள் இருந்தால், அவர்கள் அந்தப் பெண் மீது ஏதாவது குறைகளைச் சொல்லத்தான் செய்வார்கள்' என்று தேறுதல் கூறினார். நான், 'ஸுப்ஹானல்லாஹ்! மக்கள் உண்மையிலேயேவா இதைப் பேசுகிறார்கள்?' என்று கேட்டேன். அன்று இரவு முழுவதும் அழுது கொண்டே இருந்தேன், என் கண்ணீர் நிற்கவில்லை, நான் உறங்கவும் இல்லை. காலை நேரத்திலும் அழுது கொண்டே இருந்தேன். வஹீ (இறைச்செய்தி) வருவது நின்றிருந்ததால், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அலீ இப்னு அபீ தாலிப் (ரழி) மற்றும் உஸாமா இப்னு ஸைத் (ரழி) ஆகியோரை அழைத்து, என்னைப் பிரிவது குறித்து ஆலோசனை செய்தார்கள். உஸாமா (ரழி) அவர்கள் என்னைப் பற்றித் தமக்குத் தெரிந்த நல்ல குணங்களைக் கூறி, 'அல்லாஹ்வின் தூதரே, அவர்கள் உங்கள் மனைவி, அவர்களைப் பற்றி நல்லதைத் தவிர வேறெதுவும் எங்களுக்குத் தெரியாது' என்றார். ஆனால் அலீ (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே, அல்லாஹ் உங்களுக்கு எந்த நெருக்கடியையும் தரவில்லை, அவர்களைத் தவிர வேறு பல பெண்களும் இருக்கிறார்கள். அவர்களின் பணிப்பெண்ணிடம் கேட்டால் அவள் உண்மையைச் சொல்வாள்' என்றார். எனவே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பரீராவை (ரழி) அழைத்து,<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَيْ</span> <span class=\"quran-arabic-font text-success\">بَرِيرَةُ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">يَرِيبُكِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَائِشَةَ؟</span>»<br />\r\n<br />\r\n<br />\r\n(பரீராவே, ஆயிஷாவிடம் உனக்குச் சந்தேகம் ஏற்படுத்தும் எதையாவது நீ கண்டதுண்டா?) என்று கேட்டார்கள். அதற்குப் பரீரா (ரழி), 'உங்களைச் சத்தியத்துடன் அனுப்பியவன் மீது சத்தியமாக, அவர் ஒரு இளம் பெண்ணாக இருப்பதால் மாவைப் பிசைந்து வைத்துவிட்டுத் தூங்கி விடுவார், வீட்டு ஆடுகள் வந்து அதைத் தின்றுவிடும். இதைத் தவிர அவரிடம் வேறு எந்தக் குறையையும் நான் கண்டதில்லை' என்றார். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து (மக்களிடையே உரையாற்றி), அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூலைத் தமக்கு சார்பாகக் கவனிப்பவர் யார் என்று கேட்டார்கள். மிம்பரில் நின்றபடி அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَامَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِينَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْذِرُنِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">بَلَغَنِي</span> <span class=\"quran-arabic-font text-success\">أَذَاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">بَيْتِي،</span> <span class=\"quran-arabic-font text-success\">فَوَاللهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِي</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">خَيْرًا،</span> <span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">ذَكَرُوا</span> <span class=\"quran-arabic-font text-success\">رَجُلًا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">خَيْرًا،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَدْخُلُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِي</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مَعِي</span>»<br />\r\n<br />\r\n<br />\r\n(முஸ்லிம் சமூகமே! என் குடும்பத்தாரைப் பற்றி அவதூறு கூறி என்னைத் துன்புறுத்தும் அந்த மனிதனிடமிருந்து எனக்கு யார் நீதி பெற்றுத் தருவார்? அல்லாஹ்வின் மீது ஆணையாக, என் குடும்பத்தாரைப் பற்றி நல்லதைத் தவிர வேறெதுவும் எனக்குத் தெரியாது. அவர்கள் ஒரு மனிதரைக் குறிப்பிடுகிறார்கள், அவரைக் குறித்தும் நல்லதைத் தவிர நான் எதையும் அறியவில்லை. அவர் என்னோடு தவிர என் வீட்டிற்குள் நுழைந்ததே இல்லை.) உடனே ஸஃத் இப்னு முஆத் அல்-அன்சாரி (ரழி) எழுந்து, 'அல்லாஹ்வின் தூதரே, அல்லாஹ்வின் மீது சத்தியமாக, நான் அவனைக் கவனித்துக் கொள்கிறேன். அவன் அவ்ஸ் கோத்திரத்தைச் சேர்ந்தவனாக இருந்தால் அவன் தலையைத் துண்டிப்பேன், அவன் எங்கள் சகோதரர்களான கஸ்ரஜ் கோத்திரத்தைச் சேர்ந்தவனாக இருந்தால் உங்கள் கட்டளைப்படி செயல்படுவோம்' என்றார். அப்போது கஸ்ரஜ் கோத்திரத்தின் தலைவரான ஸஃத் இப்னு உபாதா (ரழி) எழுந்தார். அவர் ஒரு நல்ல மனிதர்தான், ஆனால் கோத்திரப் பற்றினால் உந்தப்பட்டு ஸஃத் இப்னு முஆத்திடம், 'அல்லாஹ்வின் மீது சத்தியமாக, நீ அவனைக் கொல்ல மாட்டாய், உன்னால் அவனைக் கொல்லவும் முடியாது' என்றார். பிறகு ஸஃத் இப்னு முஆத்தின் உறவினரான உஸைத் இப்னு ஹுளைர் (ரழி) எழுந்து, 'நீ பொய் சொல்கிறாய்! அல்லாஹ்வின் மீது சத்தியமாக, நாங்கள் அவனைக் கொல்வோம். நீ ஒரு நயவஞ்சகன், அதனால்தான் நயவஞ்சகர்களுக்காக வாதிடுகிறாய்' என்றார். இதனால் அவ்ஸ் மற்றும் கஸ்ரஜ் கோத்திரத்தினரிடையே வாக்குவாதம் முற்றி சண்டையிடும் நிலை ஏற்பட்டது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிம்பரிலிருந்தே அவர்களை அமைதிப்படுத்தினார்கள். அவர்கள் அமைதியானதும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் மௌனமானார்கள். அன்று நான் தொடர்ந்து அழுது கொண்டிருந்தேன், என் கண்ணீர் துளிகூட நிற்கவில்லை. என் பெற்றோர் நான் அழுது அழுது என் கல்லீரலே வெடித்துவிடும் என்று அஞ்சினார்கள். ஒரு அன்சாரிப் பெண் என்னைக் காண அனுமதி கேட்டு என்னுடன் அமர்ந்து அழுதார். அந்தச் சமயத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் வந்து அமர்ந்தார்கள். வதந்திகள் பரவிய இந்த ஒரு மாத காலமாக அவர்கள் என் அருகில் அமர்ந்ததே இல்லை. அமர்ந்தவுடன் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தஷஹ்ஹுத் ஓதிவிட்டுப் பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">بَعْدُ،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عَائِشَةُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">بَلَغَنِي</span> <span class=\"quran-arabic-font text-success\">عَنْكِ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،فَإِنْ</span> <span class=\"quran-arabic-font text-success\">كُنْتِ</span> <span class=\"quran-arabic-font text-success\">بَرِيئَةً</span> <span class=\"quran-arabic-font text-success\">فَسَيُبَرِّئُكِ</span> <span class=\"quran-arabic-font text-success\">اللهُ،</span> <span class=\"quran-arabic-font text-success\">وَإِنْ</span> <span class=\"quran-arabic-font text-success\">كُنْتِ</span> <span class=\"quran-arabic-font text-success\">أَلْمَمْتِ</span> <span class=\"quran-arabic-font text-success\">بِذَنْبٍ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَغْفِرِي</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تُوبِي</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اعْتَرَفَ</span> <span class=\"quran-arabic-font text-success\">بِذَنْبِهِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">تَابَ،</span> <span class=\"quran-arabic-font text-success\">تَابَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span>»<br />\r\n<br />\r\n<br />\r\n(இதற்குப் பிறகு, ஆயிஷாவே! உன்னைப் பற்றி எனக்கு இன்னின்ன செய்திகள் கிடைத்துள்ளன. நீ நிரபராதியாக இருந்தால் அல்லாஹ் உன்னைத் தூய்மைப்படுத்துவான். ஒருவேளை நீ ஏதேனும் தவறு செய்திருந்தால் அல்லாஹ்விடம் மன்னிப்புக் கேட்டு அவன் பக்கம் திரும்பு. ஏனெனில் ஒரு அடியான் தனது பாவத்தை ஒப்புக்கொண்டு தவ்பா (மன்னிப்பு) கோரினால், அல்லாஹ் அதனை ஏற்றுக்கொள்கிறான்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறி முடித்ததும், என் கண்ணீர் முற்றிலுமாக நின்றது. ஒரு சொட்டு கண்ணீர்கூட வரவில்லை. நான் என் தந்தையிடம், 'அல்லாஹ்வின் தூதருக்கு என் சார்பாகப் பதிலளியுங்கள்' என்றேன். அவர், 'நான் அவரிடம் என்ன சொல்வதென்று தெரியவில்லை' என்றார். பிறகு என் தாயிடம் கேட்டேன், அவரும் அதே பதிலையே சொன்னார். நான் குர்ஆனை அதிகம் மனனம் செய்யாத ஒரு சிறுமியாக இருந்த போதிலும், நான் கூறினேன்: 'அல்லாஹ்வின் மீது சத்தியமாக! இந்தச் செய்தியை நீங்கள் அதிகம் கேள்விப்பட்டதால் இது உங்கள் மனங்களில் பதிந்துவிட்டது, இதனை நீங்கள் நம்பியும் விட்டீர்கள். நான் இப்போது நிரபராதி என்று கூறினால் - நான் நிரபராதி என்று அல்லாஹ்வுக்குத் தெரியும் - நீங்கள் என்னை நம்ப மாட்டீர்கள். ஆனால் நான் தவறு செய்ததாக ஒப்புக்கொண்டால் - நான் நிரபராதி என்று அல்லாஹ்வுக்குத் தெரிந்தும் - நீங்கள் என்னை நம்புவீர்கள். அல்லாஹ்வின் மீது சத்தியமாக! யூசுஃப் (அலை) அவர்களின் தந்தை கூறியதையே நானும் கூறுகிறேன்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَصَبْرٌ</span> <span class=\"quran-arabic-font text-success\">جَمِيلٌ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَعَانُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَصِفُونَ</span><br />\r\n<br />\r\n<br />\r\n((எனவே, எனக்கு) அழகிய பொறுமையே மிகச் சிறந்தது. நீங்கள் விவரிக்கும் (இந்தப் பொய்க்கு) எதிராக உதவி தேடப்படுபவன் அல்லாஹ்வே) <a href=\"qurandisp.php?sura=12&ayah=18\" class=\"link\">12:18</a>. பிறகு நான் என் முகத்தைத் திருப்பிக் கொண்டு படுக்கையில் சாய்ந்தேன்.<br />\r\n<br />\r\n<br />\r\nஅல்லாஹ்வின் மீது சத்தியமாக! நான் நிரபராதி என்பதால் அல்லாஹ் என் நிரபராதித்துவத்தை நிரூபிப்பான் என்று எனக்குத் தெரியும். ஆனால், என்னைப் பற்றி என்றென்றும் ஓதப்படும் குர்ஆன் வசனங்கள் அருளப்படும் என்று நான் கனவிலும் நினைக்கவில்லை. என்னை அற்பமானவளாகவே நான் கருதினேன். மாறாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கனவின் மூலம் அல்லாஹ் என் நிரபராதித்துவத்தை வெளிப்படுத்துவான் என்றே நான் நம்பினேன். அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அந்த இடத்தை விட்டு நகர்வதற்கு முன்பாகவும், வீட்டிலிருந்தவர்கள் வெளியேறுவதற்கு முன்பாகவும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வஹீ (இறைச்செய்தி) வரத் தொடங்கியது. வஹீ அருளப்படும்போது அவர்களுக்கு ஏற்படும் கடும் சிரமம் அப்போதும் ஏற்பட்டது. குளிர்காலமாக இருந்தும் அவர்களின் நெற்றியிலிருந்து முத்துக்களைப் போன்ற வியர்வைத் துளிகள் வழிந்தோடின. அந்த நிலை நீங்கியதும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் புன்னகைத்தபடி முதலில் சொன்னது:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَبْشِرِي</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عَائِشَةُ،</span> <span class=\"quran-arabic-font text-success\">أَمَّا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">بَرَّأَكِ</span>»<br />\r\n<br />\r\n<br />\r\n(ஆயிஷாவே! நற்செய்தி பெறுவாயாக! அல்லாஹ் உன்னைத் தூய்மையானவள் என அறிவித்துவிட்டான்.) என் தாய் என்னிடம், 'எழுந்து அவரிடம் செல்' என்றார். நான், 'அல்லாஹ்வின் மீது சத்தியமாக! நான் அவரிடம் செல்ல மாட்டேன், என் நிரபராதித்துவத்தை நிரூபித்த அல்லாஹ்வைத் தவிர வேறு எவருக்கும் நான் நன்றி கூற மாட்டேன்' என்றேன். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">بِالإِفْكِ</span> <span class=\"quran-arabic-font text-success\">عُصْبَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, அவதூறைக் கொண்டு வந்தவர்கள் உங்களில் ஒரு குழுவினரே.) என்ற தொடக்கத்தைக் கொண்ட அந்தப் பத்து வசனங்களை அல்லாஹ் என் நிரபராதித்துவத்திற்காக அருளினான். அபூபக்ர் (ரழி) அவர்கள் தமது ஏழை உறவினரான மிஸ்தஹ் இப்னு உஸாஸாவிற்குச் செலவு செய்து வந்தார்கள். ஆயிஷா (ரழி) அவர்களைப் பற்றி மிஸ்தஹ் பேசிய பிறகு, 'இனி ஒருபோதும் அவருக்குச் செலவு செய்ய மாட்டேன்' என்று சத்தியம் செய்தார்கள். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَأْتَلِ</span> <span class=\"quran-arabic-font text-success\">أُوْلُواْ</span> <span class=\"quran-arabic-font text-success\">الْفَضْلِ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالسَّعَةِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُؤْتُواْ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">الْقُرْبَى</span><br />\r\n<br />\r\n<br />\r\n(உங்களில் சிறப்பும் வசதியும் உடையவர்கள் தம் உறவினர்களுக்குக் கொடுக்க மாட்டேன் என்று சத்தியம் செய்ய வேண்டாம்.) என்பது முதல்<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">تُحِبُّونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(அல்லாஹ் உங்களை மன்னிக்க வேண்டும் என்று நீங்கள் விரும்ப மாட்டீர்களா? அல்லாஹ் மிகவும் மன்னிப்பவன், மிக்க கருணையாளன்) <a href=\"qurandisp.php?sura=24&ayah=22\" class=\"link\">24:22</a> என்ற வசனம் வரை அருளப்பட்டது. உடனே அபூபக்ர் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ் என்னை மன்னிக்க வேண்டும் என்றே நான் விரும்புகிறேன்' என்று கூறி, மிஸ்தஹிற்கு முன்பை விட அதிகமாகவே செலவு செய்யத் தொடங்கினார்கள். 'நான் அவருக்குச் செய்வதை ஒருபோதும் நிறுத்த மாட்டேன்' என்றும் கூறினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸைனப் பின்த் ஜஹ்ஷிடம் (ரழி) என்னைப் பற்றிக் கேட்டபோது,<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">زَيْنَبُ</span> <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">عَلِمْتِ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتِ؟</span>»<br />\r\n<br />\r\n<br />\r\n(ஸைனபே! நீ என்ன அறிந்திருக்கிறாய் அல்லது என்ன பார்த்திருக்கிறாய்?) என்று கேட்டார்கள். அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! என் செவியையும் பார்வையையும் நான் பாதுகாத்துக் கொள்கிறேன். அல்லாஹ்வின் மீது சத்தியமாக! ஆயிஷாவிடம் நல்லதைத் தவிர வேறெதுவும் எனக்குத் தெரியாது' என்றார். அவர் நபி (ஸல்) அவர்களின் மனைவியரிடையே என்னுடன் போட்டியிடுபவராக இருந்தும், அவரது இறையச்சத்தின் காரணமாக அல்லாஹ் அவரைப் பாதுகாத்தான். ஆனால் அவரது சகோதரி ஹம்னா பின்த் ஜஹ்ஷ் அவருக்காக வாதிட்டு அழிந்து போனவர்களுடன் அவரும் அழிந்து போனார்.\" இப்னு ஷிஹாப் கூறினார், \"இந்தக் குழுவினரைப் பற்றி எங்களுக்குத் தெரிந்த தகவல்கள் இவ்வளவுதான்.\" இது புகாரி மற்றும் முஸ்லிம் ஆகியோரின் ஸஹீஹ்களிலும், இப்னு இஸ்ஹாக் மூலமும் அஸ்-ஸுஹ்ரியின் அறிவிப்பாகப் பதிவாகியுள்ளது. அவர் மேலும் கூறினார்: யஹ்யா இப்னு அப்பாத் இப்னு அப்துல்லாஹ் இப்னு அஸ்-ஸுபைர் தனது தந்தை வழியாக ஆயிஷா (ரழி) அவர்களிடமிருந்தும், அப்துல்லாஹ் இப்னு அபீபக்ர் இப்னு முஹம்மது இப்னு அம்ரு இப்னு ஹஸ்ம் அல்-அன்சாரி, அம்ரா வழியாக ஆயிஷா (ரழி) அவர்களிடமிருந்தும் இதே போன்ற செய்தியை அறிவித்துள்ளனர். அல்லாஹ்வே நன்கறிந்தவன். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">بِالإِفْكِ</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக, அவதூறைக் கொண்டு வந்தவர்கள்) அதாவது பொய்களையும் புனைவுகளையும் கொண்டு வந்தவர்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عُصْبَةٌ</span><br />\r\n<br />\r\n<br />\r\n(ஒரு குழுவினர்) அதாவது உங்களில் உள்ள ஒரு கூட்டம்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَحْسَبُوهُ</span> <span class=\"quran-arabic-font text-success\">شَرّاً</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n<br />\r\n(அதனை உங்களுக்குக் கெடுதி என்று எண்ணாதீர்கள்.) அபூபக்ரின் குடும்பத்தாரே!<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n<br />\r\n(மாறாக அது உங்களுக்கு நன்மையே.) அதாவது இவ்வுலகிலும் மறுமையிலும் புகழ்மிக்க நினைவுகூரலும், உயர்ந்த அந்தஸ்தும் உங்களுக்குக் கிடைக்கும். நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களின் நிரபராதித்துவத்தைக் குர்ஆனில் வெளிப்படுத்தியதன் மூலம் அபூபக்ர் (ரழி) அவர்களின் குடும்பத்தின் மீது தான் கொண்டுள்ள மதிப்பினை அல்லாஹ் வெளிப்படுத்தினான்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ</span><br />\r\n<br />\r\n<br />\r\n(அதற்கு முன்னிருந்தோ அல்லது பின்னிருந்தோ அசத்தியம் நெருங்காது...) <a href=\"qurandisp.php?sura=41&ayah=42\" class=\"link\">41:42</a>. இப்னு அப்பாஸ் (ரழி) அவர்கள் ஆயிஷா (ரழி) அவர்களின் மரணத் தறுவாயில் அவர்களிடம் வந்து, \"மகிழ்ச்சியடையுங்கள்! நீங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவி, அவர்கள் உங்களை மிகவும் நேசித்தார்கள். உங்களைத் தவிர வேறெந்தக் கன்னியையும் அவர்கள் மணம் புரியவில்லை. உங்கள் நிரபராதித்துவம் வானத்திலிருந்து அருளப்பட்டது\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">امْرِىءٍ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">اكْتَسَبَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الإِثْمِ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் ஒவ்வொரு மனிதனுக்கும் அவன் சம்பாதித்த பாவத்தின் பங்கு வழங்கப்படும்.) அதாவது நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களைப் பற்றி அவதூறு பேசிய ஒவ்வொருவருக்கும் அச்செயலுக்கேற்ப தண்டனை வழங்கப்படும்.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِى</span> <span class=\"quran-arabic-font text-success\">تَوَلَّى</span> <span class=\"quran-arabic-font text-success\">كِبْرَهُ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களில் எவன் இதில் பெரும்பங்கை ஏற்றானோ,) இச்செயலைத் தொடங்கி வைத்தவன் அல்லது வதந்திகளைச் சேகரித்துப் பரப்பியவனைக் குறிப்பதாகக் கூறப்படுகிறது.<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span><br />\r\n<br />\r\n<br />\r\n(அவனுக்குப் பெரும் வேதனை உண்டு.) அச்செயலுக்காக அவனுக்குக் கடும் தண்டனை உண்டு. அவன் அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். அல்லாஹ் அவனை இழிவுபடுத்திச் சபிப்பானாக.<br />\r\n<br />\r\n<br />\r\n<br />","text":"Al-Ifk (அவதூறு)\n\r\n\n\r\n\n\r\nஅடுத்த பத்து வசனங்களும் நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களைப் பற்றியே அருளப்பட்டன. நயவஞ்சகர்களில் அவதூறு மற்றும் பொய்யைப் பரப்பிய ஒரு கூட்டத்தினர், ஆயிஷா (ரழி) அவர்களின் மீது அபாண்டமாகப் பழி சுமத்தி, அவர்களைப் பற்றிப் பொய்களைப் பரப்பியபோது இது நிகழ்ந்தது. அல்லாஹ் ஆயிஷா (ரழி) அவர்களுக்காகவும், தனது தூதருக்காகவும் ரோஷம் கொண்டு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கண்ணியத்தைப் பாதுகாக்க ஆயிஷா (ரழி) அவர்களின் நிரபராதித்துவத்தை வஹீ (இறைச்செய்தி) மூலம் வெளிப்படுத்தினான். அவன் கூறினான்:\n\r\n\n\r\n\n\r\nإِنَّ الَّذِينَ جَآءُوا بِالإِفْكِ عُصْبَةٌ مِّنْكُمْ\n\r\n\n\r\n\n\r\n(நிச்சயமாக, அந்த அவதூறைக் கொண்டு வந்தவர்கள் உங்களில் ஒரு குழுவினரே.) அதாவது அவர்கள் ஒன்று அல்லது இரண்டு பேர் அல்ல, ஒரு கூட்டத்தினர். இந்தக் குழுவில் முதன்மையானவன் நயவஞ்சகர்களின் தலைவனான அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். அவனே இந்தப் பொய்யைப் புனைந்து மற்றவர்களிடம் பரப்பினான். இறுதியில் சில முஸ்லிம்கள் அதனை நம்பத் தொடங்கினார்கள், மற்றவர்கள் அது உண்மையாக இருக்கலாமோ என்று எண்ணி அதைப் பற்றிப் பேச ஆரம்பித்தார்கள். குர்ஆன் வசனங்கள் அருளப்படும் வரை கிட்டத்தட்ட ஒரு மாத காலத்திற்கு இந்நிலை நீடித்தது. இது ஸஹீஹான ஹதீஸ்களில் பதிவாகியுள்ளது. இமாம் அஹ்மத் அவர்கள் அஸ்-ஸுஹ்ரி கூறியதாகப் பதிவு செய்துள்ளார்கள்: ஸயீத் இப்னுல் முஸய்யிப், உர்வா இப்னு அஸ்-ஸுபைர், அல்கமா இப்னு வக்காஸ் மற்றும் உபைதுல்லாஹ் இப்னு அப்துல்லாஹ் இப்னு உத்பா இப்னு மஸ்ஊத் ஆகியோர் நபி (ஸல்) அவர்களின் மனைவியான ஆயிஷா (ரழி) அவர்களைப் பற்றி அவதூறு பேசுபவர்கள் பேசியது குறித்தும், அல்லாஹ் அவர்களின் நிரபராதித்துவத்தை அறிவித்தது குறித்தும் என்னிடம் கூறினார்கள். அவர்கள் ஒவ்வொருவரும் இந்தச் சம்பவத்தின் ஒரு பகுதியை விவரித்தார்கள். அவர்களில் சிலருக்கு மற்றவர்களை விடக் கூடுதல் விவரங்கள் தெரிந்திருந்தன அல்லது மற்றவர்களை விடச் சிறப்பாக மனனம் செய்திருந்தார்கள். ஆயிஷா (ரழி) அவர்களிடமிருந்து நேரடியாகக் கேட்ட அந்த நால்வரிடமிருந்தும் நான் இந்த வரலாற்றைத் தெரிந்துகொண்டேன். ஒருவர் கூறிய செய்தியை மற்றவர்கள் கூறியது உறுதிப்படுத்தியது. அவர்கள் குறிப்பிட்டதாவது, நபி (ஸல்) அவர்களின் மனைவியான ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு பயணம் மேற்கொள்ள விரும்பினால், தம் மனைவியரிடையே சீட்டுக் குலுக்குவார்கள். அதில் யாருடைய பெயர் வருகிறதோ அவரைத் தம்மோடு அழைத்துச் செல்வார்கள்.\" ஆயிஷா (ரழி) அவர்கள் கூறினார்கள், \"அவ்வாறே ஒரு போர்ப் பயணத்தின்போது எங்களிடையே சீட்டுக் குலுக்கினார்கள், அதில் என் பெயர் வந்தது. எனவே நான் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் புறப்பட்டேன். இது ஹிஜாப் (மறைப்பு) பற்றிய கட்டளை அருளப்பட்ட பிறகு நிகழ்ந்தது. எனவே நான் ஒரு சிவிகையில் (ஒட்டகக் கட்டில்) அமர்ந்து பயணம் செய்தேன், தங்கும் இடங்களிலும் அதிலேயே தங்கியிருந்தேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அந்தப் போரை முடித்துவிட்டுத் திரும்பும் வரை நாங்கள் பயணத்தைத் தொடர்ந்தோம். நாங்கள் மதீனாவை நெருங்கிக் கொண்டிருந்தபோது ஒரு இடத்தில் தங்கி ஓய்வெடுத்தோம். பிறகு பயணம் தொடரப் போவதாக அறிவிக்கப்பட்டது. இதைக் கேட்ட நான், இயற்கை உபாதையைக் கழிப்பதற்காகப் படையிலிருந்து சற்றுத் தொலைவிற்கு வேகமாக நடந்து சென்றேன். பிறகு என் சிவிகையை நோக்கித் திரும்பி வந்தேன். அப்போது என் மார்பைத் தொட்டுப் பார்த்தபோது, கோமேதகம் மற்றும் பவளத்தினால் ஆன என் கழுத்து மாலை அறுந்து விழுந்திருப்பதை உணர்ந்தேன். எனவே நான் அதைக் கண்டெடுக்கத் திரும்பிச் சென்றேன். அங்கே தேடிக் கொண்டிருந்ததால் நான் திரும்ப வருவது தாமதமானது. இதற்கிடையில், என் சிவிகையை ஒட்டகத்தின் மீது தூக்கி வைக்கும் ஆட்கள் வந்து, நான் உள்ளே இருப்பதாகவே நினைத்து அதை அப்படியே ஒட்டகத்தின் மீது ஏற்றிவிட்டார்கள். அக்காலப் பெண்கள் மிகக் குறைவான உணவையே உட்கொண்டதால் மிகவும் மெலிந்தவர்களாக இருந்தனர். எனவே சிவிகை இலகுவாக இருந்ததைக் கண்டு அந்தப் பணியாளர்கள் சந்தேகப்படவில்லை. அவர்கள் அப்படியே புறப்பட்டுச் சென்றுவிட்டனர். படை நகர்ந்த பிறகுதான் என் மாலையைக் கண்டெடுத்தேன். பிறகு நான் தங்கியிருந்த இடத்திற்குத் திரும்பினேன். அங்கே அழைப்பதற்கோ பதில் சொல்வதற்கோ ஒருவரும் இல்லை. எனவே மக்கள் என்னைக் காணாமல் தேடித் திரும்புவார்கள் என்று எண்ணி நான் இருந்த இடத்திலேயே அமர்ந்துவிட்டேன். அவ்வாறு அமர்ந்திருந்தபோது எனக்கு உறக்கம் வந்துவிட, அப்படியே தூங்கிவிட்டேன். ஸஃப்வான் இப்னுல் முஅத்தல் அஸ்-ஸுலமி அத்-தக்வானி (ரழி) என்பவர் இரவில் படைக்குப் பின்னால் தங்கி ஓய்வெடுத்துவிட்டு, விடியற்காலை நேரத்தில் நான் இருந்த இடத்திற்கு வந்து சேர்ந்தார். அங்கே ஒருவர் தூங்கிக் கொண்டிருப்பதை அவர் கண்டார். ஹிஜாப் கட்டளை வருவதற்கு முன்பு அவர் என்னைப் பார்த்திருந்ததால், என்னைக் கண்டதும் அடையாளம் கண்டுகொண்டார். அவர் என்னைப் பார்த்து 'இன்னா லில்லாஹி வ இன்னா இலைஹி ராஜிஊன் (நிச்சயமாக நாம் அல்லாஹ்வுக்கே உரியவர்கள்; அவனிடமே நாம் திரும்புவோம்)' என்று கூறிய சத்தத்தைக் கேட்டு நான் விழித்தேன். உடனே என் மேலாடையால் (ஜில்பாப்) முகத்தை மறைத்துக் கொண்டேன். அல்லாஹ்வின் மீது ஆணையாக, அவர் என்னிடம் ஒரு வார்த்தைகூடப் பேசவில்லை. அவர் 'இன்னா லில்லாஹி வ இன்னா இலைஹி ராஜிஊன்' என்று சொன்னதைத் தவிர வேறெதுவும் என் காதில் விழவில்லை. அவர் தமது ஒட்டகத்தைக் கொண்டு வந்து, நான் ஏறுவதற்காக அதைக் கீழே மண்டியிடச் செய்தார். பிறகு அவர் ஒட்டகத்தை முன் நடத்திச் சென்றார். நண்பகல் (ளுஹர்) நேரத்தில் நாங்கள் படையைச் சென்றடைந்தோம்.\n\r\n\n\r\n\n\r\nஎனக்கு நேர்ந்த இந்தச் சம்பவத்தால் சிலர் அழிவை நோக்கிச் சென்றனர். அவர்களில் முதன்மையானவன் அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். நாங்கள் மதீனா வந்து சேர்ந்ததும் நான் ஒரு மாதம் நோய்வாய்ப்பட்டிருந்தேன். அப்போதும் மக்கள் அவதூறு பேசுபவர்களின் பேச்சைப் பரப்பிக் கொண்டிருந்தார்கள், ஆனால் எனக்கு அது பற்றி எதுவும் தெரியாது. நான் உடல்நலமில்லாமல் இருந்தபோது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் என்னிடம் காட்டும் கனிவை நான் காணாததுதான் எனக்கு வருத்தத்தை அளித்தது. அவர்கள் வீட்டிற்குள் வந்து,\n\r\n\n\r\n\n\r\n«كَيْفَ تِيكُمْ؟»\n\r\n\n\r\n\n\r\n(அந்தப் பெண் எப்படி இருக்கிறார்?) என்று மட்டும் கேட்டுவிட்டுச் சென்றுவிடுவார்கள். அதுதான் எனக்கு வேதனையாக இருந்தது. நான் உடல்நலம் தேறி வெளியே செல்லும் வரை ஏதோ தவறாக நடப்பதை நான் உணரவில்லை. ஒருமுறை நானும் உம்மு மிஸ்தஹ் அவர்களும் எங்களின் இயற்கை உபாதைகளைக் கழிக்க அல்-மனாஸிஃ என்ற இடத்திற்குச் சென்றோம். அக்காலத்தில் வீடுகளுக்கு அருகில் கழிப்பறைகள் இல்லாததால், இரவு நேரத்தில்தான் நாங்கள் வெளியே செல்வோம். இது பழைய அரேபியர்களின் பழக்கத்தைப் போன்றது. வீடுகளுக்குள் கழிப்பறை இருப்பதை நாங்கள் ஒரு தொந்தரவாகவும் அருவருப்பாகவும் கருதினோம். உம்மு மிஸ்தஹ் என்பவர் அபூ ருஹ்ம் இப்னுல் முத்தலிப் இப்னு அப்து மனாஃபின் மகளாவார். அவரின் தாயார் அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்களின் அத்தை ஆவார். உம்மு மிஸ்தஹ் அவர்களின் மகன் மிஸ்தஹ் இப்னு உஸாஸா (ரழி) ஆவார். நாங்கள் எங்களது வேலையை முடித்துவிட்டுத் திரும்பும்போது, உம்மு மிஸ்தஹ் தனது ஆடையின் ஓரத்தில் தடுக்கி விழுந்து, 'மிஸ்தஹ் அழிந்து போகட்டும்!' என்று சாபமிட்டார். நான் அவரிடம், 'நீர் எவ்வளவு தவறான வார்த்தையைச் சொன்னீர்! பத்ருப் போரில் கலந்துகொண்ட ஒரு மனிதரையா திட்டுகிறீர்?' என்று கேட்டேன். அதற்கு அவர், 'பெண்ணே, அவர் உங்களைப் பற்றி என்ன சொன்னார் என்று உங்களுக்குத் தெரியாதா?' என்று கேட்டார். 'அவர் என்ன சொன்னார்?' என்று நான் கேட்டபோது, அவதூறு பேசுபவர்கள் சொல்லி வந்த செய்திகளை அவர் எனக்கு விளக்கினார். அதைக் கேட்டதும் எனது நோய் இன்னும் அதிகரித்தது. நான் வீடு திரும்பியதும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் என்னிடம் வந்து ஸலாம் கூறிவிட்டு,\n\r\n\n\r\n\n\r\n«كَيْفَ تِيكُمْ؟»\n\r\n\n\r\n\n\r\n(அந்தப் பெண் எப்படி இருக்கிறார்?) என்று கேட்டார்கள். நான் அவர்களிடம், 'நான் என் பெற்றோரிடம் செல்ல எனக்கு அனுமதி அளிப்பீர்களா?' என்று கேட்டேன். அவர்களிடமிருந்து உண்மையை அறிந்து உறுதிப்படுத்திக் கொள்ளவே நான் விரும்பினேன். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதி வழங்க, நான் என் தாயிடம் சென்று, 'தாயே, மக்கள் என்ன பேசிக் கொள்கிறார்கள்?' என்று கேட்டேன். அதற்கு என் தாய், 'மகளே, வருத்தப்படாதே. அல்லாஹ்வின் மீது ஆணையாக, அழகிய ஒரு பெண்ணைத் தனது கணவன் நேசிக்கும்போது, அவருக்குச் சக மனைவிகள் இருந்தால், அவர்கள் அந்தப் பெண் மீது ஏதாவது குறைகளைச் சொல்லத்தான் செய்வார்கள்' என்று தேறுதல் கூறினார். நான், 'ஸுப்ஹானல்லாஹ்! மக்கள் உண்மையிலேயேவா இதைப் பேசுகிறார்கள்?' என்று கேட்டேன். அன்று இரவு முழுவதும் அழுது கொண்டே இருந்தேன், என் கண்ணீர் நிற்கவில்லை, நான் உறங்கவும் இல்லை. காலை நேரத்திலும் அழுது கொண்டே இருந்தேன். வஹீ (இறைச்செய்தி) வருவது நின்றிருந்ததால், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அலீ இப்னு அபீ தாலிப் (ரழி) மற்றும் உஸாமா இப்னு ஸைத் (ரழி) ஆகியோரை அழைத்து, என்னைப் பிரிவது குறித்து ஆலோசனை செய்தார்கள். உஸாமா (ரழி) அவர்கள் என்னைப் பற்றித் தமக்குத் தெரிந்த நல்ல குணங்களைக் கூறி, 'அல்லாஹ்வின் தூதரே, அவர்கள் உங்கள் மனைவி, அவர்களைப் பற்றி நல்லதைத் தவிர வேறெதுவும் எங்களுக்குத் தெரியாது' என்றார். ஆனால் அலீ (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே, அல்லாஹ் உங்களுக்கு எந்த நெருக்கடியையும் தரவில்லை, அவர்களைத் தவிர வேறு பல பெண்களும் இருக்கிறார்கள். அவர்களின் பணிப்பெண்ணிடம் கேட்டால் அவள் உண்மையைச் சொல்வாள்' என்றார். எனவே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பரீராவை (ரழி) அழைத்து,\n\r\n\n\r\n\n\r\n«أَيْ بَرِيرَةُ هَلْ رَأَيْتِ مِنْ شَيْءٍ يَرِيبُكِ مِنْ عَائِشَةَ؟»\n\r\n\n\r\n\n\r\n(பரீராவே, ஆயிஷாவிடம் உனக்குச் சந்தேகம் ஏற்படுத்தும் எதையாவது நீ கண்டதுண்டா?) என்று கேட்டார்கள். அதற்குப் பரீரா (ரழி), 'உங்களைச் சத்தியத்துடன் அனுப்பியவன் மீது சத்தியமாக, அவர் ஒரு இளம் பெண்ணாக இருப்பதால் மாவைப் பிசைந்து வைத்துவிட்டுத் தூங்கி விடுவார், வீட்டு ஆடுகள் வந்து அதைத் தின்றுவிடும். இதைத் தவிர அவரிடம் வேறு எந்தக் குறையையும் நான் கண்டதில்லை' என்றார். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து (மக்களிடையே உரையாற்றி), அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூலைத் தமக்கு சார்பாகக் கவனிப்பவர் யார் என்று கேட்டார்கள். மிம்பரில் நின்றபடி அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«يَامَعْشَرَ الْمُسْلِمِينَ مَنْ يَعْذِرُنِي مِنْ رَجُلٍ قَدْ بَلَغَنِي أَذَاهُ فِي أَهْلِ بَيْتِي، فَوَاللهِ مَا عَلِمْتُ عَلَى أَهْلِي إِلَّا خَيْرًا، وَلَقَدْ ذَكَرُوا رَجُلًا مَا عَلِمْتُ عَلَيْهِ إِلَّا خَيْرًا، وَمَا كَانَ يَدْخُلُ عَلَى أَهْلِي إِلَّا مَعِي»\n\r\n\n\r\n\n\r\n(முஸ்லிம் சமூகமே! என் குடும்பத்தாரைப் பற்றி அவதூறு கூறி என்னைத் துன்புறுத்தும் அந்த மனிதனிடமிருந்து எனக்கு யார் நீதி பெற்றுத் தருவார்? அல்லாஹ்வின் மீது ஆணையாக, என் குடும்பத்தாரைப் பற்றி நல்லதைத் தவிர வேறெதுவும் எனக்குத் தெரியாது. அவர்கள் ஒரு மனிதரைக் குறிப்பிடுகிறார்கள், அவரைக் குறித்தும் நல்லதைத் தவிர நான் எதையும் அறியவில்லை. அவர் என்னோடு தவிர என் வீட்டிற்குள் நுழைந்ததே இல்லை.) உடனே ஸஃத் இப்னு முஆத் அல்-அன்சாரி (ரழி) எழுந்து, 'அல்லாஹ்வின் தூதரே, அல்லாஹ்வின் மீது சத்தியமாக, நான் அவனைக் கவனித்துக் கொள்கிறேன். அவன் அவ்ஸ் கோத்திரத்தைச் சேர்ந்தவனாக இருந்தால் அவன் தலையைத் துண்டிப்பேன், அவன் எங்கள் சகோதரர்களான கஸ்ரஜ் கோத்திரத்தைச் சேர்ந்தவனாக இருந்தால் உங்கள் கட்டளைப்படி செயல்படுவோம்' என்றார். அப்போது கஸ்ரஜ் கோத்திரத்தின் தலைவரான ஸஃத் இப்னு உபாதா (ரழி) எழுந்தார். அவர் ஒரு நல்ல மனிதர்தான், ஆனால் கோத்திரப் பற்றினால் உந்தப்பட்டு ஸஃத் இப்னு முஆத்திடம், 'அல்லாஹ்வின் மீது சத்தியமாக, நீ அவனைக் கொல்ல மாட்டாய், உன்னால் அவனைக் கொல்லவும் முடியாது' என்றார். பிறகு ஸஃத் இப்னு முஆத்தின் உறவினரான உஸைத் இப்னு ஹுளைர் (ரழி) எழுந்து, 'நீ பொய் சொல்கிறாய்! அல்லாஹ்வின் மீது சத்தியமாக, நாங்கள் அவனைக் கொல்வோம். நீ ஒரு நயவஞ்சகன், அதனால்தான் நயவஞ்சகர்களுக்காக வாதிடுகிறாய்' என்றார். இதனால் அவ்ஸ் மற்றும் கஸ்ரஜ் கோத்திரத்தினரிடையே வாக்குவாதம் முற்றி சண்டையிடும் நிலை ஏற்பட்டது. அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மிம்பரிலிருந்தே அவர்களை அமைதிப்படுத்தினார்கள். அவர்கள் அமைதியானதும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் மௌனமானார்கள். அன்று நான் தொடர்ந்து அழுது கொண்டிருந்தேன், என் கண்ணீர் துளிகூட நிற்கவில்லை. என் பெற்றோர் நான் அழுது அழுது என் கல்லீரலே வெடித்துவிடும் என்று அஞ்சினார்கள். ஒரு அன்சாரிப் பெண் என்னைக் காண அனுமதி கேட்டு என்னுடன் அமர்ந்து அழுதார். அந்தச் சமயத்தில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களிடம் வந்து அமர்ந்தார்கள். வதந்திகள் பரவிய இந்த ஒரு மாத காலமாக அவர்கள் என் அருகில் அமர்ந்ததே இல்லை. அமர்ந்தவுடன் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தஷஹ்ஹுத் ஓதிவிட்டுப் பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\n\n\r\n«أَمَّا بَعْدُ، يَا عَائِشَةُ فَإِنَّهُ قَدْ بَلَغَنِي عَنْكِ كَذَا وَكَذَا،فَإِنْ كُنْتِ بَرِيئَةً فَسَيُبَرِّئُكِ اللهُ، وَإِنْ كُنْتِ أَلْمَمْتِ بِذَنْبٍ فَاسْتَغْفِرِي اللهَ ثُمَّ تُوبِي إِلَيْهِ، فَإِنَّ الْعَبْدَ إِذَا اعْتَرَفَ بِذَنْبِهِ ثُمَّ تَابَ، تَابَ اللهُ عَلَيْهِ»\n\r\n\n\r\n\n\r\n(இதற்குப் பிறகு, ஆயிஷாவே! உன்னைப் பற்றி எனக்கு இன்னின்ன செய்திகள் கிடைத்துள்ளன. நீ நிரபராதியாக இருந்தால் அல்லாஹ் உன்னைத் தூய்மைப்படுத்துவான். ஒருவேளை நீ ஏதேனும் தவறு செய்திருந்தால் அல்லாஹ்விடம் மன்னிப்புக் கேட்டு அவன் பக்கம் திரும்பு. ஏனெனில் ஒரு அடியான் தனது பாவத்தை ஒப்புக்கொண்டு தவ்பா (மன்னிப்பு) கோரினால், அல்லாஹ் அதனை ஏற்றுக்கொள்கிறான்.) அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறி முடித்ததும், என் கண்ணீர் முற்றிலுமாக நின்றது. ஒரு சொட்டு கண்ணீர்கூட வரவில்லை. நான் என் தந்தையிடம், 'அல்லாஹ்வின் தூதருக்கு என் சார்பாகப் பதிலளியுங்கள்' என்றேன். அவர், 'நான் அவரிடம் என்ன சொல்வதென்று தெரியவில்லை' என்றார். பிறகு என் தாயிடம் கேட்டேன், அவரும் அதே பதிலையே சொன்னார். நான் குர்ஆனை அதிகம் மனனம் செய்யாத ஒரு சிறுமியாக இருந்த போதிலும், நான் கூறினேன்: 'அல்லாஹ்வின் மீது சத்தியமாக! இந்தச் செய்தியை நீங்கள் அதிகம் கேள்விப்பட்டதால் இது உங்கள் மனங்களில் பதிந்துவிட்டது, இதனை நீங்கள் நம்பியும் விட்டீர்கள். நான் இப்போது நிரபராதி என்று கூறினால் - நான் நிரபராதி என்று அல்லாஹ்வுக்குத் தெரியும் - நீங்கள் என்னை நம்ப மாட்டீர்கள். ஆனால் நான் தவறு செய்ததாக ஒப்புக்கொண்டால் - நான் நிரபராதி என்று அல்லாஹ்வுக்குத் தெரிந்தும் - நீங்கள் என்னை நம்புவீர்கள். அல்லாஹ்வின் மீது சத்தியமாக! யூசுஃப் (அலை) அவர்களின் தந்தை கூறியதையே நானும் கூறுகிறேன்:\n\r\n\n\r\n\n\r\nفَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ عَلَى مَا تَصِفُونَ\n\r\n\n\r\n\n\r\n((எனவே, எனக்கு) அழகிய பொறுமையே மிகச் சிறந்தது. நீங்கள் விவரிக்கும் (இந்தப் பொய்க்கு) எதிராக உதவி தேடப்படுபவன் அல்லாஹ்வே) 12:18. பிறகு நான் என் முகத்தைத் திருப்பிக் கொண்டு படுக்கையில் சாய்ந்தேன்.\n\r\n\n\r\n\n\r\nஅல்லாஹ்வின் மீது சத்தியமாக! நான் நிரபராதி என்பதால் அல்லாஹ் என் நிரபராதித்துவத்தை நிரூபிப்பான் என்று எனக்குத் தெரியும். ஆனால், என்னைப் பற்றி என்றென்றும் ஓதப்படும் குர்ஆன் வசனங்கள் அருளப்படும் என்று நான் கனவிலும் நினைக்கவில்லை. என்னை அற்பமானவளாகவே நான் கருதினேன். மாறாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் கனவின் மூலம் அல்லாஹ் என் நிரபராதித்துவத்தை வெளிப்படுத்துவான் என்றே நான் நம்பினேன். அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அந்த இடத்தை விட்டு நகர்வதற்கு முன்பாகவும், வீட்டிலிருந்தவர்கள் வெளியேறுவதற்கு முன்பாகவும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்கு வஹீ (இறைச்செய்தி) வரத் தொடங்கியது. வஹீ அருளப்படும்போது அவர்களுக்கு ஏற்படும் கடும் சிரமம் அப்போதும் ஏற்பட்டது. குளிர்காலமாக இருந்தும் அவர்களின் நெற்றியிலிருந்து முத்துக்களைப் போன்ற வியர்வைத் துளிகள் வழிந்தோடின. அந்த நிலை நீங்கியதும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் புன்னகைத்தபடி முதலில் சொன்னது:\n\r\n\n\r\n\n\r\n«أَبْشِرِي يَا عَائِشَةُ، أَمَّا اللهُ عَزَّ وَجَلَّ فَقَدْ بَرَّأَكِ»\n\r\n\n\r\n\n\r\n(ஆயிஷாவே! நற்செய்தி பெறுவாயாக! அல்லாஹ் உன்னைத் தூய்மையானவள் என அறிவித்துவிட்டான்.) என் தாய் என்னிடம், 'எழுந்து அவரிடம் செல்' என்றார். நான், 'அல்லாஹ்வின் மீது சத்தியமாக! நான் அவரிடம் செல்ல மாட்டேன், என் நிரபராதித்துவத்தை நிரூபித்த அல்லாஹ்வைத் தவிர வேறு எவருக்கும் நான் நன்றி கூற மாட்டேன்' என்றேன். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\n\n\r\nإِنَّ الَّذِينَ جَآءُوا بِالإِفْكِ عُصْبَةٌ مِّنْكُمْ\n\r\n\n\r\n\n\r\n(நிச்சயமாக, அவதூறைக் கொண்டு வந்தவர்கள் உங்களில் ஒரு குழுவினரே.) என்ற தொடக்கத்தைக் கொண்ட அந்தப் பத்து வசனங்களை அல்லாஹ் என் நிரபராதித்துவத்திற்காக அருளினான். அபூபக்ர் (ரழி) அவர்கள் தமது ஏழை உறவினரான மிஸ்தஹ் இப்னு உஸாஸாவிற்குச் செலவு செய்து வந்தார்கள். ஆயிஷா (ரழி) அவர்களைப் பற்றி மிஸ்தஹ் பேசிய பிறகு, 'இனி ஒருபோதும் அவருக்குச் செலவு செய்ய மாட்டேன்' என்று சத்தியம் செய்தார்கள். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\n\n\r\nوَلاَ يَأْتَلِ أُوْلُواْ الْفَضْلِ مِنكُمْ وَالسَّعَةِ أَن يُؤْتُواْ أُوْلِى الْقُرْبَى\n\r\n\n\r\n\n\r\n(உங்களில் சிறப்பும் வசதியும் உடையவர்கள் தம் உறவினர்களுக்குக் கொடுக்க மாட்டேன் என்று சத்தியம் செய்ய வேண்டாம்.) என்பது முதல்\n\r\n\n\r\n\n\r\nأَلاَ تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n\n\r\n(அல்லாஹ் உங்களை மன்னிக்க வேண்டும் என்று நீங்கள் விரும்ப மாட்டீர்களா? அல்லாஹ் மிகவும் மன்னிப்பவன், மிக்க கருணையாளன்) 24:22 என்ற வசனம் வரை அருளப்பட்டது. உடனே அபூபக்ர் (ரழி) அவர்கள், 'அல்லாஹ்வின் மீது சத்தியமாக! அல்லாஹ் என்னை மன்னிக்க வேண்டும் என்றே நான் விரும்புகிறேன்' என்று கூறி, மிஸ்தஹிற்கு முன்பை விட அதிகமாகவே செலவு செய்யத் தொடங்கினார்கள். 'நான் அவருக்குச் செய்வதை ஒருபோதும் நிறுத்த மாட்டேன்' என்றும் கூறினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸைனப் பின்த் ஜஹ்ஷிடம் (ரழி) என்னைப் பற்றிக் கேட்டபோது,\n\r\n\n\r\n\n\r\n«يَا زَيْنَبُ مَاذَا عَلِمْتِ أَوْ رَأَيْتِ؟»\n\r\n\n\r\n\n\r\n(ஸைனபே! நீ என்ன அறிந்திருக்கிறாய் அல்லது என்ன பார்த்திருக்கிறாய்?) என்று கேட்டார்கள். அதற்கு அவர், 'அல்லாஹ்வின் தூதரே! என் செவியையும் பார்வையையும் நான் பாதுகாத்துக் கொள்கிறேன். அல்லாஹ்வின் மீது சத்தியமாக! ஆயிஷாவிடம் நல்லதைத் தவிர வேறெதுவும் எனக்குத் தெரியாது' என்றார். அவர் நபி (ஸல்) அவர்களின் மனைவியரிடையே என்னுடன் போட்டியிடுபவராக இருந்தும், அவரது இறையச்சத்தின் காரணமாக அல்லாஹ் அவரைப் பாதுகாத்தான். ஆனால் அவரது சகோதரி ஹம்னா பின்த் ஜஹ்ஷ் அவருக்காக வாதிட்டு அழிந்து போனவர்களுடன் அவரும் அழிந்து போனார்.\" இப்னு ஷிஹாப் கூறினார், \"இந்தக் குழுவினரைப் பற்றி எங்களுக்குத் தெரிந்த தகவல்கள் இவ்வளவுதான்.\" இது புகாரி மற்றும் முஸ்லிம் ஆகியோரின் ஸஹீஹ்களிலும், இப்னு இஸ்ஹாக் மூலமும் அஸ்-ஸுஹ்ரியின் அறிவிப்பாகப் பதிவாகியுள்ளது. அவர் மேலும் கூறினார்: யஹ்யா இப்னு அப்பாத் இப்னு அப்துல்லாஹ் இப்னு அஸ்-ஸுபைர் தனது தந்தை வழியாக ஆயிஷா (ரழி) அவர்களிடமிருந்தும், அப்துல்லாஹ் இப்னு அபீபக்ர் இப்னு முஹம்மது இப்னு அம்ரு இப்னு ஹஸ்ம் அல்-அன்சாரி, அம்ரா வழியாக ஆயிஷா (ரழி) அவர்களிடமிருந்தும் இதே போன்ற செய்தியை அறிவித்துள்ளனர். அல்லாஹ்வே நன்கறிந்தவன். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nإِنَّ الَّذِينَ جَآءُوا بِالإِفْكِ\n\r\n\n\r\n\n\r\n(நிச்சயமாக, அவதூறைக் கொண்டு வந்தவர்கள்) அதாவது பொய்களையும் புனைவுகளையும் கொண்டு வந்தவர்கள்.\n\r\n\n\r\n\n\r\nعُصْبَةٌ\n\r\n\n\r\n\n\r\n(ஒரு குழுவினர்) அதாவது உங்களில் உள்ள ஒரு கூட்டம்.\n\r\n\n\r\n\n\r\nلاَ تَحْسَبُوهُ شَرّاً لَّكُمْ\n\r\n\n\r\n\n\r\n(அதனை உங்களுக்குக் கெடுதி என்று எண்ணாதீர்கள்.) அபூபக்ரின் குடும்பத்தாரே!\n\r\n\n\r\n\n\r\nبَلْ هُوَ خَيْرٌ لَّكُمْ\n\r\n\n\r\n\n\r\n(மாறாக அது உங்களுக்கு நன்மையே.) அதாவது இவ்வுலகிலும் மறுமையிலும் புகழ்மிக்க நினைவுகூரலும், உயர்ந்த அந்தஸ்தும் உங்களுக்குக் கிடைக்கும். நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களின் நிரபராதித்துவத்தைக் குர்ஆனில் வெளிப்படுத்தியதன் மூலம் அபூபக்ர் (ரழி) அவர்களின் குடும்பத்தின் மீது தான் கொண்டுள்ள மதிப்பினை அல்லாஹ் வெளிப்படுத்தினான்.\n\r\n\n\r\n\n\r\nلاَّ يَأْتِيهِ الْبَاطِلُ مِن بَيْنِ يَدَيْهِ وَلاَ مِنْ خَلْفِهِ\n\r\n\n\r\n\n\r\n(அதற்கு முன்னிருந்தோ அல்லது பின்னிருந்தோ அசத்தியம் நெருங்காது...) 41:42. இப்னு அப்பாஸ் (ரழி) அவர்கள் ஆயிஷா (ரழி) அவர்களின் மரணத் தறுவாயில் அவர்களிடம் வந்து, \"மகிழ்ச்சியடையுங்கள்! நீங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவி, அவர்கள் உங்களை மிகவும் நேசித்தார்கள். உங்களைத் தவிர வேறெந்தக் கன்னியையும் அவர்கள் மணம் புரியவில்லை. உங்கள் நிரபராதித்துவம் வானத்திலிருந்து அருளப்பட்டது\" என்று கூறினார்கள்.\n\r\n\n\r\n\n\r\nلِكُلِّ امْرِىءٍ مِّنْهُمْ مَّا اكْتَسَبَ مِنَ الإِثْمِ\n\r\n\n\r\n\n\r\n(அவர்களில் ஒவ்வொரு மனிதனுக்கும் அவன் சம்பாதித்த பாவத்தின் பங்கு வழங்கப்படும்.) அதாவது நம்பிக்கையாளர்களின் தாயான ஆயிஷா (ரழி) அவர்களைப் பற்றி அவதூறு பேசிய ஒவ்வொருவருக்கும் அச்செயலுக்கேற்ப தண்டனை வழங்கப்படும்.\n\r\n\n\r\n\n\r\nوَالَّذِى تَوَلَّى كِبْرَهُ مِنْهُمْ\n\r\n\n\r\n\n\r\n(அவர்களில் எவன் இதில் பெரும்பங்கை ஏற்றானோ,) இச்செயலைத் தொடங்கி வைத்தவன் அல்லது வதந்திகளைச் சேகரித்துப் பரப்பியவனைக் குறிப்பதாகக் கூறப்படுகிறது.\n\r\n\n\r\n\n\r\nلَهُ عَذَابٌ عَظِيمٌ\n\r\n\n\r\n\n\r\n(அவனுக்குப் பெரும் வேதனை உண்டு.) அச்செயலுக்காக அவனுக்குக் கடும் தண்டனை உண்டு. அவன் அப்துல்லாஹ் இப்னு உபை இப்னு ஸலூல் ஆவான். அல்லாஹ் அவனை இழிவுபடுத்திச் சபிப்பானாக."},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=13\" class=\"link\">24:13</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:13 ஐ பார்க்கவும்"},"13":{"html":"<strong>அவதூறைப் பரப்பியதற்காக இறைநம்பிக்கையாளர்களைக் கண்டித்தல்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ், அன்னை ஆயிஷா (ரழி) அவர்களின் விஷயம் தொடர்பாக இறைநம்பிக்கையாளர்களைக் கண்டிக்கிறான். ஏனெனில், அவர்களில் சிலர் இந்தப் பொல்லாத பேச்சையும் பரப்பப்பட்ட அந்த அவதூறையும் பேசிக் கொண்டிருந்தனர். எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّوْلا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْتُمُوهُ</span><br />\r\n<br />\r\n(அதை நீங்கள் செவியுற்றபோது...) அதாவது, இறைநம்பிக்கையாளர்களின் அன்னை (ரழி) அவர்கள் மீது சுமத்தப்பட்ட அந்த அவதூறான பேச்சைக் கேட்டபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ظَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَاتُ</span> <span class=\"quran-arabic-font text-success\">بِأَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span><br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களான ஆண்களும் பெண்களும் தங்களைப் பற்றி நல்லதையே எண்ணியிருக்க வேண்டாமா?) அதாவது, அந்தப் பேச்சை ஏன் அவர்கள் தங்களோடு ஒப்பிட்டுப் பார்க்கவில்லை? அத்தகைய செயல் தங்களுக்குத் தகுதியற்றது எனும் போது, இறைநம்பிக்கையாளர்களின் அன்னைக்கு அது எவ்வகையிலும் பொருந்தாதது அல்லவா? அவர் குற்றமற்றவர் என்று எண்ணுவதே பொருத்தமாக இருந்திருக்கும். அல்லது, இது அபூ அய்யூப் காலித் பின் ஸைத் அல்-அன்சாரி (ரழி) மற்றும் அவரது மனைவியைப் பற்றி அருளப்பட்டது என்றும் கூறப்படுகிறது. இமாம் முஹம்மது பின் இஸ்ஹாக் பின் யஸார் அறிவிக்கிறார்கள்: \"அபூ அய்யூப் காலித் பின் ஸைத் அல்-அன்சாரி (ரழி) அவர்களின் மனைவியான உம்மு அய்யூப் (ரழி), அவரிடம், 'அபூ அய்யூபே! மக்கள் ஆயிஷா (ரழி) அவர்களைப் பற்றிப் பேசுவதை நீங்கள் கேட்டீர்களா?' என்று கேட்டார். அதற்கு அவர், 'ஆம், அது முற்றிலும் பொய்யாகும். உம்மு அய்யூபே! நீங்கள் அப்படிச் செய்வீர்களா?' என்று கேட்டார். அதற்கு அவர், 'இல்லை, அல்லாஹ்வின் மீது ஆணையாக! நான் அப்படிச் செய்ய மாட்டேன்' என்றார். அதற்கு அபூ அய்யூப் (ரழி), 'அல்லாஹ்வின் மீது ஆணையாக! ஆயிஷா (ரழி) உங்களை விடச் சிறந்தவர்' என்றார்.\" குர்ஆன் அருளப்பட்டபோது, அவதூறு பரப்பியவர்களில் அந்தத் தீய செயலைப் பற்றிப் பேசியவர்களை அல்லாஹ் குறிப்பிட்டான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">بِالإِفْكِ</span> <span class=\"quran-arabic-font text-success\">عُصْبَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக அந்த அவதூறைக் கொண்டு வந்தவர்கள் உங்களிலுள்ள ஒரு குழுவினரே.) <a href=\"qurandisp.php?sura=24&ayah=11\" class=\"link\">24:11</a> இது ஹஸான் (ரழி) மற்றும் அவர் சொன்னதைச் சொன்ன அவரது தோழர்களைக் குறிக்கிறது. பிறகு அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّوْلا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْتُمُوهُ</span> <span class=\"quran-arabic-font text-success\">ظَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span><br />\r\n<br />\r\n(அதை நீங்கள் செவியுற்றபோது, இறைநம்பிக்கையாளர்களான ஆண்கள் ஏன்... எண்ணவில்லை?) அதாவது, அபூ அய்யூப் (ரழி) அவர்களும் அவருடைய மனைவியும் எண்ணியது போல ஏன் எண்ணவில்லை? அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ظَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span><br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களான ஆண்கள் எண்ணுகிறார்கள்...) அதாவது, 'இறைநம்பிக்கையாளர்களின் அன்னை நபியவர்களின் மனைவியாகவும், அவர்களுக்கு மிகவும் நெருக்கமானவராகவும் இருக்கும்போது, ஏன் அவர்கள் நல்லவிதமாக எண்ணவில்லை?' இது உள்ளத்தின் உணர்வுகள் தொடர்பானது;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறினார்கள்:) அதாவது, வாய்மொழியாகத் தங்கள் நாவுகளால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">إِفْكٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n(\"இது ஒரு தெளிவான அவதூறாகும்\") அதாவது, இறைநம்பிக்கையாளர்களின் அன்னை (ரழி) அவர்கள் மீது கூறப்பட்ட அப்பட்டமான பொய். நடந்த சம்பவங்கள் சந்தேகத்திற்கு இடமளித்திருக்கக் கூடாது. அன்னை ஆயிஷா (ரழி) அவர்கள், ஸஃப்வான் பின் முஅத்தல் (ரழி) அவர்களின் ஒட்டகத்தின் மீது அமர்ந்து, நண்பகல் வேளையில், ஒட்டுமொத்தப் படையும் பார்த்துக் கொண்டிருக்க, அவர்களிடையே அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் இருக்கும் நிலையில் வெளிப்படையாக வந்தார்கள். இதுவே அந்த விஷயத்தில் சந்தேகம் கொள்வதற்கு எதுவுமில்லை என்பதைத் தெளிவுபடுத்தியிருக்க வேண்டும். அந்த விஷயத்தில் ஏதேனும் சந்தேகத்திற்குரியது இருந்திருந்தால், அவர்கள் இத்தனை சாட்சிகளுக்கு முன்னால் இப்படி வெளிப்படையாக வந்திருக்க மாட்டார்கள்; ரகசியமாகவே வந்திருப்பார்கள். இதன் அடிப்படையில், அவதூறு பரப்பியவர்கள் அன்னை (ரழி) அவர்கள் மீது சுமத்தியது ஒரு அப்பட்டமான பொய், தவறான பேச்சு மற்றும் தீய மூடத்தனமான பேச்சாகும். இதில் ஈடுபட்டவர்கள் நஷ்டமடைந்தார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّوْلاَ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">بِأَرْبَعَةِ</span> <span class=\"quran-arabic-font text-success\">شُهَدَآءَ</span><br />\r\n<br />\r\n(அதற்காக அவர்கள் ஏன் நான்கு சாட்சிகளைக் கொண்டு வரவில்லை?) அதாவது, அவர்கள் சொல்வது உண்மை என்பதை நிரூபிப்பதற்கு.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَأْتُواْ</span> <span class=\"quran-arabic-font text-success\">بِالشُّهَدَآءِ</span> <span class=\"quran-arabic-font text-success\">فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْكَاذِبُونَ</span><br />\r\n<br />\r\n(அவர்கள் சாட்சிகளைக் கொண்டு வராததால், அல்லாஹ்விடம் அவர்களே பொய்யர்கள்.) அவர்கள் நிச்சயமாகப் பொல்லாத பொய்யர்கள் என்று அல்லாஹ் தீர்ப்பளித்துள்ளான்.<br />\r\n<br />","text":"அவதூறைப் பரப்பியதற்காக இறைநம்பிக்கையாளர்களைக் கண்டித்தல்\n\r\n\n\r\nஇங்கே அல்லாஹ், அன்னை ஆயிஷா (ரழி) அவர்களின் விஷயம் தொடர்பாக இறைநம்பிக்கையாளர்களைக் கண்டிக்கிறான். ஏனெனில், அவர்களில் சிலர் இந்தப் பொல்லாத பேச்சையும் பரப்பப்பட்ட அந்த அவதூறையும் பேசிக் கொண்டிருந்தனர். எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلَّوْلا إِذْ سَمِعْتُمُوهُ\n\r\n\n\r\n(அதை நீங்கள் செவியுற்றபோது...) அதாவது, இறைநம்பிக்கையாளர்களின் அன்னை (ரழி) அவர்கள் மீது சுமத்தப்பட்ட அந்த அவதூறான பேச்சைக் கேட்டபோது,\n\r\n\n\r\nظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنفُسِهِمْ خَيْراً\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களான ஆண்களும் பெண்களும் தங்களைப் பற்றி நல்லதையே எண்ணியிருக்க வேண்டாமா?) அதாவது, அந்தப் பேச்சை ஏன் அவர்கள் தங்களோடு ஒப்பிட்டுப் பார்க்கவில்லை? அத்தகைய செயல் தங்களுக்குத் தகுதியற்றது எனும் போது, இறைநம்பிக்கையாளர்களின் அன்னைக்கு அது எவ்வகையிலும் பொருந்தாதது அல்லவா? அவர் குற்றமற்றவர் என்று எண்ணுவதே பொருத்தமாக இருந்திருக்கும். அல்லது, இது அபூ அய்யூப் காலித் பின் ஸைத் அல்-அன்சாரி (ரழி) மற்றும் அவரது மனைவியைப் பற்றி அருளப்பட்டது என்றும் கூறப்படுகிறது. இமாம் முஹம்மது பின் இஸ்ஹாக் பின் யஸார் அறிவிக்கிறார்கள்: \"அபூ அய்யூப் காலித் பின் ஸைத் அல்-அன்சாரி (ரழி) அவர்களின் மனைவியான உம்மு அய்யூப் (ரழி), அவரிடம், 'அபூ அய்யூபே! மக்கள் ஆயிஷா (ரழி) அவர்களைப் பற்றிப் பேசுவதை நீங்கள் கேட்டீர்களா?' என்று கேட்டார். அதற்கு அவர், 'ஆம், அது முற்றிலும் பொய்யாகும். உம்மு அய்யூபே! நீங்கள் அப்படிச் செய்வீர்களா?' என்று கேட்டார். அதற்கு அவர், 'இல்லை, அல்லாஹ்வின் மீது ஆணையாக! நான் அப்படிச் செய்ய மாட்டேன்' என்றார். அதற்கு அபூ அய்யூப் (ரழி), 'அல்லாஹ்வின் மீது ஆணையாக! ஆயிஷா (ரழி) உங்களை விடச் சிறந்தவர்' என்றார்.\" குர்ஆன் அருளப்பட்டபோது, அவதூறு பரப்பியவர்களில் அந்தத் தீய செயலைப் பற்றிப் பேசியவர்களை அல்லாஹ் குறிப்பிட்டான்:\n\r\n\n\r\nإِنَّ الَّذِينَ جَآءُوا بِالإِفْكِ عُصْبَةٌ مِّنْكُمْ\n\r\n\n\r\n(நிச்சயமாக அந்த அவதூறைக் கொண்டு வந்தவர்கள் உங்களிலுள்ள ஒரு குழுவினரே.) 24:11 இது ஹஸான் (ரழி) மற்றும் அவர் சொன்னதைச் சொன்ன அவரது தோழர்களைக் குறிக்கிறது. பிறகு அல்லாஹ் கூறினான்:\n\r\n\n\r\nلَّوْلا إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ\n\r\n\n\r\n(அதை நீங்கள் செவியுற்றபோது, இறைநம்பிக்கையாளர்களான ஆண்கள் ஏன்... எண்ணவில்லை?) அதாவது, அபூ அய்யூப் (ரழி) அவர்களும் அவருடைய மனைவியும் எண்ணியது போல ஏன் எண்ணவில்லை? அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nظَنَّ الْمُؤْمِنُونَ\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களான ஆண்கள் எண்ணுகிறார்கள்...) அதாவது, 'இறைநம்பிக்கையாளர்களின் அன்னை நபியவர்களின் மனைவியாகவும், அவர்களுக்கு மிகவும் நெருக்கமானவராகவும் இருக்கும்போது, ஏன் அவர்கள் நல்லவிதமாக எண்ணவில்லை?' இது உள்ளத்தின் உணர்வுகள் தொடர்பானது;\n\r\n\n\r\nوَقَالُواْ\n\r\n\n\r\n(மேலும் அவர்கள் கூறினார்கள்:) அதாவது, வாய்மொழியாகத் தங்கள் நாவுகளால்,\n\r\n\n\r\nهَذَا إِفْكٌ مُّبِينٌ\n\r\n\n\r\n(\"இது ஒரு தெளிவான அவதூறாகும்\") அதாவது, இறைநம்பிக்கையாளர்களின் அன்னை (ரழி) அவர்கள் மீது கூறப்பட்ட அப்பட்டமான பொய். நடந்த சம்பவங்கள் சந்தேகத்திற்கு இடமளித்திருக்கக் கூடாது. அன்னை ஆயிஷா (ரழி) அவர்கள், ஸஃப்வான் பின் முஅத்தல் (ரழி) அவர்களின் ஒட்டகத்தின் மீது அமர்ந்து, நண்பகல் வேளையில், ஒட்டுமொத்தப் படையும் பார்த்துக் கொண்டிருக்க, அவர்களிடையே அல்லாஹ்வின் தூதர் (ஸல்) அவர்களும் இருக்கும் நிலையில் வெளிப்படையாக வந்தார்கள். இதுவே அந்த விஷயத்தில் சந்தேகம் கொள்வதற்கு எதுவுமில்லை என்பதைத் தெளிவுபடுத்தியிருக்க வேண்டும். அந்த விஷயத்தில் ஏதேனும் சந்தேகத்திற்குரியது இருந்திருந்தால், அவர்கள் இத்தனை சாட்சிகளுக்கு முன்னால் இப்படி வெளிப்படையாக வந்திருக்க மாட்டார்கள்; ரகசியமாகவே வந்திருப்பார்கள். இதன் அடிப்படையில், அவதூறு பரப்பியவர்கள் அன்னை (ரழி) அவர்கள் மீது சுமத்தியது ஒரு அப்பட்டமான பொய், தவறான பேச்சு மற்றும் தீய மூடத்தனமான பேச்சாகும். இதில் ஈடுபட்டவர்கள் நஷ்டமடைந்தார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nلَّوْلاَ جَآءُوا عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ\n\r\n\n\r\n(அதற்காக அவர்கள் ஏன் நான்கு சாட்சிகளைக் கொண்டு வரவில்லை?) அதாவது, அவர்கள் சொல்வது உண்மை என்பதை நிரூபிப்பதற்கு.\n\r\n\n\r\nفَإِذْ لَمْ يَأْتُواْ بِالشُّهَدَآءِ فَأُولَئِكَ عِندَ اللَّهِ هُمُ الْكَاذِبُونَ\n\r\n\n\r\n(அவர்கள் சாட்சிகளைக் கொண்டு வராததால், அல்லாஹ்விடம் அவர்களே பொய்யர்கள்.) அவர்கள் நிச்சயமாகப் பொல்லாத பொய்யர்கள் என்று அல்லாஹ் தீர்ப்பளித்துள்ளான்."},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=15\" class=\"link\">24:15</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:15 ஐ பார்க்கவும்"},"15":{"html":"<strong>அவதூறு பரப்பியவர்கள் தவ்பா செய்து மீளுவதற்கு வாய்ப்பளித்ததன் மூலம் அவர்கள் மீது அல்லாஹ் பொழிந்த அருட்கொடை</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتُهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَالْآخِرَةِ﴿</span><br />\r\n(இவ்வுலகிலும் மறுமையிலும் உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லையெனில்,) இது ஆயிஷா (ரழி) அவர்களைப் பற்றிய அவதூறு பேச்சுகளில் ஈடுபட்டவர்களை நோக்கிச் சொல்லப்படுகிறது. அல்லாஹ் இவ்வுலகில் அவர்களின் தவ்பாவை (பாவமன்னிப்பை) ஏற்றுக்கொண்டான் என்பதையும், அவர்களின் ஈமான் (நம்பிக்கை) காரணமாக மறுமையில் அவர்களை மன்னித்தான் என்பதையும் இது அவர்களுக்குத் தெரிவிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾لَمَسَّكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَفَضْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ﴿</span><br />\r\n(நீங்கள் பேசிய அந்த அவதூறின் காரணமாக உங்களை நிச்சயமாகத் தீண்டியிருக்கும்,) <span class=\"quran-arabic-font text-success\">﴾عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ﴿</span><br />\r\n(கடுமையான வேதனை.) இது தவ்பா செய்ததன் மூலம் அல்லாஹ்வின் மீது நம்பிக்கை கொண்டிருந்தவர்களான மிஸ்தஹ் (ரழி), ஹஸ்ஸான் (ரழி) மற்றும் ஸைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் சகோதரி ஹம்னா பின்த் ஜஹ்ஷ் (ரழி) போன்றோரைக் குறிக்கிறது. அப்துல்லாஹ் இப்னு உபய் இப்னு ஸலூல் மற்றும் அவனைப் போன்ற இந்த அவதூறில் ஈடுபட்ட நயவஞ்சகர்களை (முனாஃபிக்கீன்களை) இந்த வசனம் குறிக்கவில்லை. ஏனெனில், அவர்கள் செய்த பாவத்தைச் சமன் செய்யவோ அல்லது துடைத்தெறியவோ போதுமான ஈமானும் நற்செயல்களும் அவர்களிடம் இருக்கவில்லை. அதேபோன்று, ஒரு குறிப்பிட்ட செயலுக்காக எச்சரிக்கப்பட்ட தண்டனைகள், தவ்பா செய்யாவிட்டாலோ அல்லது அந்தப் பாவத்தைச் சமன் செய்யக்கூடிய அளவுக்கு நற்செயல்கள் இல்லாவிட்டாலோ நிச்சயமாக நிறைவேற்றப்படும். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِذْ</span> <span class=\"quran-arabic-font text-success\">تَلَقَّوْنَهُ</span> <span class=\"quran-arabic-font text-success\">بِأَلْسِنَتِكُمْ﴿</span><br />\r\n(உங்கள் நாவுகளால் அதனை நீங்கள் ஒருவரிடமிருந்து ஒருவராகப் பரப்பிக் கொண்டிருந்தபோது,) முஜாஹித் மற்றும் ஸயீத் இப்னு ஜுபைர் ஆகியோர், \"உங்களில் சிலர் இதனை மற்றவர்களுக்கு எடுத்துரைத்துக் கொண்டிருந்தீர்கள்\" என்று கூறினார்கள். அதாவது, 'இன்னாரிடமிருந்து நான் இதனைக் கேட்டேன், இன்னார் இப்படிச் சொன்னார், அவர்களில் சிலர் இப்படிச் சொன்னார்கள்' என்று ஒருவருக்கு ஒருவர் கூறுவதைக் குறிக்கும். மற்றவர்கள் இவ்வசனத்தை (<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تَلِقُونَهُ</span> <span class=\"quran-arabic-font text-success\">بِأَلْسِنَتِكُمْ</span>) (\"உங்கள் நாவுகளால் ஒரு பொய்யை நீங்கள் உருவாக்கிக் கொண்டிருந்தபோது...\") என்று ஓதினார்கள். ஸஹீஹ் அல்-புகாரியில் ஆயிஷா (ரழி) அவர்கள் இவ்வாறு ஓதியதாகப் பதிவு செய்யப்பட்டுள்ளது. அவர்களைப் பொறுத்தவரை, ஒருவர் விடாப்பிடியாகக் கூறிக்கொண்டிருக்கும் பொய்களை இது குறிக்கிறது. முதல் ஓதல் முறையே சிறந்ததாகவும் மிகவும் பிரபலமானதாகவும் உள்ளது; பெரும்பாலானோர் அவ்வாறே ஓதுகின்றனர். இருப்பினும், இரண்டாவது ஓதல் முறை இறைநம்பிக்கையாளர்களின் தாயாரான ஆயிஷா (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. <span class=\"quran-arabic-font text-success\">﴾وَتَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">بِأَفْوَاهِكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">عِلْمٌ﴿</span><br />\r\n(மேலும் உங்களுக்கு எதைப் பற்றி அறிவு இல்லையோ அதனை உங்கள் வாய்களால் கூறினீர்கள்,) அதாவது உங்களுக்கு துளியும் தெரியாத ஒரு விஷயத்தைப் பற்றி நீங்கள் பேசிக் கொண்டிருந்தீர்கள். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَتَحْسَبُونَهُ</span> <span class=\"quran-arabic-font text-success\">هَيِّناً</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ﴿</span><br />\r\n(அதனை நீங்கள் ஒரு சாதாரண விஷயமாகக் கருதினீர்கள்; ஆனால் அல்லாஹ்விடமோ அது மிகப் பெரியதாக இருந்தது.) அதாவது, \"இறைநம்பிக்கையாளர்களின் தாயாரைப் பற்றி நீங்கள் அவ்வாறு பேசிவிட்டு, அது ஒரு சிறிய, முக்கியமற்ற விஷயம் என்று எண்ணினீர்கள். அவர் நபியின் (ஸல்) மனைவியாக இல்லாவிட்டாலும் கூட அது ஒரு சாதாரணமான விஷயம் அல்ல. அப்படியிருக்க, அவர் எழுதப்படிக்கத் தெரியாத நபியும், இறுதி நபியும், தூதர்களின் தலைவருமானவரின் (ஸல்) மனைவியாக இருக்கும்போது அது எவ்வளவு பாரதூரமானது!\" தனது தூதருடைய மனைவியைப் பற்றி இத்தகைய பேச்சுக்கள் பேசப்படுவது அல்லாஹ்விடம் மிகப் பெரும் குற்றமாகும்! ஏனெனில், மாண்பும் உயர்வும் மிக்கவனான அல்லாஹ் இத்தகைய விஷயங்களில் மிகுந்த கோபமும் சீற்றமும் கொள்கிறான். மேலும் தனது நபிமார்களில் எவருடைய மனைவிக்கும் இத்தகைய இழிவை அவன் ஒருபோதும் ஏற்படுத்த மாட்டான். நிலைமை இப்படியிருக்க, நபிமார்களின் மனைவிகளிலேயே சிறந்தவரும், இம்மையிலும் மறுமையிலும் ஆதமின் மக்களில் சிறந்தவருமானவரின் மனைவியைப் பற்றிப் பேசுவது எவ்வளவு பெரிய கொடுமை! அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَتَحْسَبُونَهُ</span> <span class=\"quran-arabic-font text-success\">هَيِّناً</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ﴿</span><br />\r\n(அதனை நீங்கள் ஒரு சாதாரண விஷயமாகக் கருதினீர்கள்; ஆனால் அல்லாஹ்விடமோ அது மிகப் பெரியதாக இருந்தது.) புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் பின்வருமாறு அறிவிக்கப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلَ</span> <span class=\"quran-arabic-font text-success\">لَيَتَكَلَّمُ</span> <span class=\"quran-arabic-font text-success\">بِالْكَلِمَةِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">سَخَطِ</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَدْرِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَبْلُغُ،</span> <span class=\"quran-arabic-font text-success\">يَهْوِي</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">أَبْعَدَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(நிச்சயமாக ஒரு மனிதன் அல்லாஹ்வின் கோபத்தைத் தூண்டக்கூடிய ஒரு வார்த்தையைப் பேசுகிறான். அதன் விளைவு எவ்வளவு தூரம் செல்லும் என்பதை அவன் உணர்வதில்லை. அதன் காரணமாக அவன் வானத்திற்கும் பூமிக்கும் இடைப்பட்ட தூரத்தை விட அதிகத் தொலைவில் நரகத்தில் தூக்கி எறியப்படுவான்.) மற்றொரு அறிவிப்பில்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُلْقِي</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">بَالًا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அதற்கு அவன் எத்தகைய முக்கியத்துவமும் கொடுக்காமல் இருக்கலாம்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"அவதூறு பரப்பியவர்கள் தவ்பா செய்து மீளுவதற்கு வாய்ப்பளித்ததன் மூலம் அவர்கள் மீது அல்லாஹ் பொழிந்த அருட்கொடை\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾وَلَوْلاَ فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ فِى الدُّنْيَا وَالْآخِرَةِ﴿\n\r\n(இவ்வுலகிலும் மறுமையிலும் உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லையெனில்,) இது ஆயிஷா (ரழி) அவர்களைப் பற்றிய அவதூறு பேச்சுகளில் ஈடுபட்டவர்களை நோக்கிச் சொல்லப்படுகிறது. அல்லாஹ் இவ்வுலகில் அவர்களின் தவ்பாவை (பாவமன்னிப்பை) ஏற்றுக்கொண்டான் என்பதையும், அவர்களின் ஈமான் (நம்பிக்கை) காரணமாக மறுமையில் அவர்களை மன்னித்தான் என்பதையும் இது அவர்களுக்குத் தெரிவிக்கிறது. ﴾لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ﴿\n\r\n(நீங்கள் பேசிய அந்த அவதூறின் காரணமாக உங்களை நிச்சயமாகத் தீண்டியிருக்கும்,) ﴾عَذَابٌ عَظِيمٌ﴿\n\r\n(கடுமையான வேதனை.) இது தவ்பா செய்ததன் மூலம் அல்லாஹ்வின் மீது நம்பிக்கை கொண்டிருந்தவர்களான மிஸ்தஹ் (ரழி), ஹஸ்ஸான் (ரழி) மற்றும் ஸைனப் பின்த் ஜஹ்ஷ் (ரழி) அவர்களின் சகோதரி ஹம்னா பின்த் ஜஹ்ஷ் (ரழி) போன்றோரைக் குறிக்கிறது. அப்துல்லாஹ் இப்னு உபய் இப்னு ஸலூல் மற்றும் அவனைப் போன்ற இந்த அவதூறில் ஈடுபட்ட நயவஞ்சகர்களை (முனாஃபிக்கீன்களை) இந்த வசனம் குறிக்கவில்லை. ஏனெனில், அவர்கள் செய்த பாவத்தைச் சமன் செய்யவோ அல்லது துடைத்தெறியவோ போதுமான ஈமானும் நற்செயல்களும் அவர்களிடம் இருக்கவில்லை. அதேபோன்று, ஒரு குறிப்பிட்ட செயலுக்காக எச்சரிக்கப்பட்ட தண்டனைகள், தவ்பா செய்யாவிட்டாலோ அல்லது அந்தப் பாவத்தைச் சமன் செய்யக்கூடிய அளவுக்கு நற்செயல்கள் இல்லாவிட்டாலோ நிச்சயமாக நிறைவேற்றப்படும். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِذْ تَلَقَّوْنَهُ بِأَلْسِنَتِكُمْ﴿\n\r\n(உங்கள் நாவுகளால் அதனை நீங்கள் ஒருவரிடமிருந்து ஒருவராகப் பரப்பிக் கொண்டிருந்தபோது,) முஜாஹித் மற்றும் ஸயீத் இப்னு ஜுபைர் ஆகியோர், \"உங்களில் சிலர் இதனை மற்றவர்களுக்கு எடுத்துரைத்துக் கொண்டிருந்தீர்கள்\" என்று கூறினார்கள். அதாவது, 'இன்னாரிடமிருந்து நான் இதனைக் கேட்டேன், இன்னார் இப்படிச் சொன்னார், அவர்களில் சிலர் இப்படிச் சொன்னார்கள்' என்று ஒருவருக்கு ஒருவர் கூறுவதைக் குறிக்கும். மற்றவர்கள் இவ்வசனத்தை (إِذْ تَلِقُونَهُ بِأَلْسِنَتِكُمْ) (\"உங்கள் நாவுகளால் ஒரு பொய்யை நீங்கள் உருவாக்கிக் கொண்டிருந்தபோது...\") என்று ஓதினார்கள். ஸஹீஹ் அல்-புகாரியில் ஆயிஷா (ரழி) அவர்கள் இவ்வாறு ஓதியதாகப் பதிவு செய்யப்பட்டுள்ளது. அவர்களைப் பொறுத்தவரை, ஒருவர் விடாப்பிடியாகக் கூறிக்கொண்டிருக்கும் பொய்களை இது குறிக்கிறது. முதல் ஓதல் முறையே சிறந்ததாகவும் மிகவும் பிரபலமானதாகவும் உள்ளது; பெரும்பாலானோர் அவ்வாறே ஓதுகின்றனர். இருப்பினும், இரண்டாவது ஓதல் முறை இறைநம்பிக்கையாளர்களின் தாயாரான ஆயிஷா (ரழி) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. ﴾وَتَقُولُونَ بِأَفْوَاهِكُمْ مَّا لَّيْسَ لَكُمْ بِهِ عِلْمٌ﴿\n\r\n(மேலும் உங்களுக்கு எதைப் பற்றி அறிவு இல்லையோ அதனை உங்கள் வாய்களால் கூறினீர்கள்,) அதாவது உங்களுக்கு துளியும் தெரியாத ஒரு விஷயத்தைப் பற்றி நீங்கள் பேசிக் கொண்டிருந்தீர்கள். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَتَحْسَبُونَهُ هَيِّناً وَهُوَ عِندَ اللَّهِ عَظِيمٌ﴿\n\r\n(அதனை நீங்கள் ஒரு சாதாரண விஷயமாகக் கருதினீர்கள்; ஆனால் அல்லாஹ்விடமோ அது மிகப் பெரியதாக இருந்தது.) அதாவது, \"இறைநம்பிக்கையாளர்களின் தாயாரைப் பற்றி நீங்கள் அவ்வாறு பேசிவிட்டு, அது ஒரு சிறிய, முக்கியமற்ற விஷயம் என்று எண்ணினீர்கள். அவர் நபியின் (ஸல்) மனைவியாக இல்லாவிட்டாலும் கூட அது ஒரு சாதாரணமான விஷயம் அல்ல. அப்படியிருக்க, அவர் எழுதப்படிக்கத் தெரியாத நபியும், இறுதி நபியும், தூதர்களின் தலைவருமானவரின் (ஸல்) மனைவியாக இருக்கும்போது அது எவ்வளவு பாரதூரமானது!\" தனது தூதருடைய மனைவியைப் பற்றி இத்தகைய பேச்சுக்கள் பேசப்படுவது அல்லாஹ்விடம் மிகப் பெரும் குற்றமாகும்! ஏனெனில், மாண்பும் உயர்வும் மிக்கவனான அல்லாஹ் இத்தகைய விஷயங்களில் மிகுந்த கோபமும் சீற்றமும் கொள்கிறான். மேலும் தனது நபிமார்களில் எவருடைய மனைவிக்கும் இத்தகைய இழிவை அவன் ஒருபோதும் ஏற்படுத்த மாட்டான். நிலைமை இப்படியிருக்க, நபிமார்களின் மனைவிகளிலேயே சிறந்தவரும், இம்மையிலும் மறுமையிலும் ஆதமின் மக்களில் சிறந்தவருமானவரின் மனைவியைப் பற்றிப் பேசுவது எவ்வளவு பெரிய கொடுமை! அல்லாஹ் கூறுகிறான்: ﴾وَتَحْسَبُونَهُ هَيِّناً وَهُوَ عِندَ اللَّهِ عَظِيمٌ﴿\n\r\n(அதனை நீங்கள் ஒரு சாதாரண விஷயமாகக் கருதினீர்கள்; ஆனால் அல்லாஹ்விடமோ அது மிகப் பெரியதாக இருந்தது.) புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் பின்வருமாறு அறிவிக்கப்பட்டுள்ளது: ﴾«إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللهِ، لَا يَدْرِي مَا تَبْلُغُ، يَهْوِي بِهَا فِي النَّارِ أَبْعَدَ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ»﴿\n\r\n(நிச்சயமாக ஒரு மனிதன் அல்லாஹ்வின் கோபத்தைத் தூண்டக்கூடிய ஒரு வார்த்தையைப் பேசுகிறான். அதன் விளைவு எவ்வளவு தூரம் செல்லும் என்பதை அவன் உணர்வதில்லை. அதன் காரணமாக அவன் வானத்திற்கும் பூமிக்கும் இடைப்பட்ட தூரத்தை விட அதிகத் தொலைவில் நரகத்தில் தூக்கி எறியப்படுவான்.) மற்றொரு அறிவிப்பில்: ﴾«لَا يُلْقِي لَهَا بَالًا»﴿\n\r\n(அதற்கு அவன் எத்தகைய முக்கியத்துவமும் கொடுக்காமல் இருக்கலாம்.)"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=18\" class=\"link\">24:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:18 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=18\" class=\"link\">24:18</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:18 ஐ பார்க்கவும்"},"18":{"html":"<strong>கூடுதல் ஒழுக்க நெறிமுறை</strong><br />\r\nமக்களைப் பற்றி நல்லவிதமாக எண்ண வேண்டும் என்ற கட்டளைக்கு மேலதிகமாக வழங்கப்படும் மற்றுமொரு ஒழுக்க நெறிமுறை இதுவாகும். அதாவது, நல்லவர்களைப் பற்றித் தகுதியற்ற ஏதேனும் கூறப்பட்டால், அவர்களைப் பற்றி நல்லதையே எண்ண வேண்டும்; அவர்களைப் பற்றி நன்மையைத் தவிர வேறெதையும் நினைக்கக் கூடாது. ஷைத்தான் ஒருவருடைய உள்ளத்திலும் கற்பனையிலும் அவர்களைப் பற்றித் தகுதியற்ற எண்ணங்களை ஊடுருவச் செய்தால், அவர் அதைப் பற்றிப் பேசக் கூடாது. ஏனெனில், நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">تَجَاوَزَ</span> <span class=\"quran-arabic-font text-success\">لِأُمَّتِي</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">حَدَّثَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">أَنْفُسُهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَقُلْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلْ</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(என் சமுதாயத்தினர் (உம்மத்) தங்கள் உள்ளங்களில் நினைப்பவற்றைப் பேசாமலோ அல்லது அதன்படி செயல்படாமலோ இருக்கும் வரை, அல்லாஹ் அவற்றை மன்னித்து விடுகிறான்.) இது புகாரீ, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. அல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾وَلَوْلَا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْتُمُوهُ</span> <span class=\"quran-arabic-font text-success\">قُلْتُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّتَكَلَّمَ</span> <span class=\"quran-arabic-font text-success\">بِهَذَا﴿</span><br />\r\n<br />\r\n(\"நீங்கள் அதைக் கேட்டபோது, இதைப் பற்றிப் பேசுவது நமக்குத் தகுதியற்றது என்று ஏன் சொல்லவில்லை?\") அதாவது, நாம் இதைப் பற்றி யாரிடமும் பேசவோ அல்லது குறிப்பிடவோ கூடாது. <span class=\"quran-arabic-font text-success\">﴾سُبْحَانَكَ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">بُهْتَانٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ﴿</span><br />\r\n<br />\r\n(\"(யா அல்லாஹ்!) நீ தூயவன்! இது ஒரு பெரும் அவதூறாகும்!\") அதாவது, தனது நபியும் உற்றத் தோழருமானவரின் (ஸல்) மனைவியைப் (ரழி) பற்றி இத்தகையப் பேச்சுகள் கூறப்படுவதிலிருந்து அல்லாஹ் மிகவும் தூய்மையானவன். பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَعِظُكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَعُودُواْ</span> <span class=\"quran-arabic-font text-success\">لِمِثْلِهِ</span> <span class=\"quran-arabic-font text-success\">أَبَداً﴿</span><br />\r\n<br />\r\n(\"இது போன்ற செயலை நீங்கள் ஒருபோதும் மீண்டும் செய்யக் கூடாது என்று அல்லாஹ் உங்களுக்கு அறிவுறுத்துகிறான்.\") அதாவது, எதிர்காலத்தில் இது போன்ற எதையும் நீங்கள் மீண்டும் செய்யக் கூடாது என அல்லாஹ் உங்களைத் தடுத்து எச்சரிக்கிறான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் நம்பிக்கையாளர்களாக (முஃமின்களாக) இருந்தால்.\") அதாவது, நீங்கள் அல்லாஹ்வையும் அவனது சட்டங்களையும் நம்பி, அவனது தூதரையும் (ஸல்) கண்ணியப்படுத்துபவர்களாக இருந்தால் (இவ்வாறு நடக்க மாட்டீர்கள்). நிராகரிப்பாளர்கள் (காஃபிர்கள்) என்று குறிப்பிடப்படுபவர்களைப் பொறுத்தவரை, அவர்களுக்கு வேறு விதமான தீர்ப்புகள் பொருந்தும். பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَيُبَيِّنُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْآيَاتِ﴿</span><br />\r\n<br />\r\n(\"மேலும், அல்லாஹ் உங்களுக்குத் தனது வசனங்களைத் (ஆயத்களைத்) தெளிவுபடுத்துகிறான்.\") அதாவது, அவன் உங்களுக்கு ஷரீஆவின் சட்டங்களையும் தனது இறை விதிகளையும் தெளிவுபடுத்துகிறான். <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٌ﴿</span><br />\r\n<br />\r\n(\"மேலும் அல்லாஹ் எல்லாம் அறிந்தவன்; மகா ஞானமிக்கவன்.\") அதாவது, தனது அடியார்களுக்கு எது சிறந்தது என்பதை அவன் நன்கு அறிவான்; அவன் தனது சட்டங்களிலும் விதிகளிலும் மகா ஞானம் மிக்கவன்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"கூடுதல் ஒழுக்க நெறிமுறை\n\r\nமக்களைப் பற்றி நல்லவிதமாக எண்ண வேண்டும் என்ற கட்டளைக்கு மேலதிகமாக வழங்கப்படும் மற்றுமொரு ஒழுக்க நெறிமுறை இதுவாகும். அதாவது, நல்லவர்களைப் பற்றித் தகுதியற்ற ஏதேனும் கூறப்பட்டால், அவர்களைப் பற்றி நல்லதையே எண்ண வேண்டும்; அவர்களைப் பற்றி நன்மையைத் தவிர வேறெதையும் நினைக்கக் கூடாது. ஷைத்தான் ஒருவருடைய உள்ளத்திலும் கற்பனையிலும் அவர்களைப் பற்றித் தகுதியற்ற எண்ணங்களை ஊடுருவச் செய்தால், அவர் அதைப் பற்றிப் பேசக் கூடாது. ஏனெனில், நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِنَّ اللهَ تَعَالَى تَجَاوَزَ لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسُهَا مَا لَمْ تَقُلْ أَوْ تَعْمَلْ»﴿\n\r\n\n\r\n(என் சமுதாயத்தினர் (உம்மத்) தங்கள் உள்ளங்களில் நினைப்பவற்றைப் பேசாமலோ அல்லது அதன்படி செயல்படாமலோ இருக்கும் வரை, அல்லாஹ் அவற்றை மன்னித்து விடுகிறான்.) இது புகாரீ, முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. அல்லாஹ்வின் கூற்று: ﴾وَلَوْلَا إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَا أَن نَّتَكَلَّمَ بِهَذَا﴿\n\r\n\n\r\n(\"நீங்கள் அதைக் கேட்டபோது, இதைப் பற்றிப் பேசுவது நமக்குத் தகுதியற்றது என்று ஏன் சொல்லவில்லை?\") அதாவது, நாம் இதைப் பற்றி யாரிடமும் பேசவோ அல்லது குறிப்பிடவோ கூடாது. ﴾سُبْحَانَكَ هَذَا بُهْتَانٌ عَظِيمٌ﴿\n\r\n\n\r\n(\"(யா அல்லாஹ்!) நீ தூயவன்! இது ஒரு பெரும் அவதூறாகும்!\") அதாவது, தனது நபியும் உற்றத் தோழருமானவரின் (ஸல்) மனைவியைப் (ரழி) பற்றி இத்தகையப் பேச்சுகள் கூறப்படுவதிலிருந்து அல்லாஹ் மிகவும் தூய்மையானவன். பிறகு அல்லாஹ் கூறுகிறான்: ﴾يَعِظُكُمُ اللَّهُ أَن تَعُودُواْ لِمِثْلِهِ أَبَداً﴿\n\r\n\n\r\n(\"இது போன்ற செயலை நீங்கள் ஒருபோதும் மீண்டும் செய்யக் கூடாது என்று அல்லாஹ் உங்களுக்கு அறிவுறுத்துகிறான்.\") அதாவது, எதிர்காலத்தில் இது போன்ற எதையும் நீங்கள் மீண்டும் செய்யக் கூடாது என அல்லாஹ் உங்களைத் தடுத்து எச்சரிக்கிறான். அல்லாஹ் கூறுகிறான்: ﴾إِن كُنتُم مُّؤْمِنِينَ﴿\n\r\n\n\r\n(\"நீங்கள் நம்பிக்கையாளர்களாக (முஃமின்களாக) இருந்தால்.\") அதாவது, நீங்கள் அல்லாஹ்வையும் அவனது சட்டங்களையும் நம்பி, அவனது தூதரையும் (ஸல்) கண்ணியப்படுத்துபவர்களாக இருந்தால் (இவ்வாறு நடக்க மாட்டீர்கள்). நிராகரிப்பாளர்கள் (காஃபிர்கள்) என்று குறிப்பிடப்படுபவர்களைப் பொறுத்தவரை, அவர்களுக்கு வேறு விதமான தீர்ப்புகள் பொருந்தும். பிறகு அல்லாஹ் கூறுகிறான்: ﴾وَيُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ﴿\n\r\n\n\r\n(\"மேலும், அல்லாஹ் உங்களுக்குத் தனது வசனங்களைத் (ஆயத்களைத்) தெளிவுபடுத்துகிறான்.\") அதாவது, அவன் உங்களுக்கு ஷரீஆவின் சட்டங்களையும் தனது இறை விதிகளையும் தெளிவுபடுத்துகிறான். ﴾وَاللَّهُ عَلِيمٌ حَكِيمٌ﴿\n\r\n\n\r\n(\"மேலும் அல்லாஹ் எல்லாம் அறிந்தவன்; மகா ஞானமிக்கவன்.\") அதாவது, தனது அடியார்களுக்கு எது சிறந்தது என்பதை அவன் நன்கு அறிவான்; அவன் தனது சட்டங்களிலும் விதிகளிலும் மகா ஞானம் மிக்கவன்."},"19":{"html":"<strong>நம்பிக்கை கொண்டவர்களிடையே மானக்கேடான விஷயங்கள் பரவுவதை விரும்புவோரை ஒழுங்குபடுத்துதல்</strong><br />\r\n<br />\r\nதீய பேச்சைக் கேட்டு, அதை ஓரளவுக்கு நம்பி, அதனைப் பரப்பத் தொடங்குபவர்களுக்கு வழங்கப்படும் மூன்றாவது ஒழுங்குமுறை இதுவாகும்; அவர்கள் அத்தகைய பேச்சுகளைப் பரப்பவோ அல்லது மற்றவர்களுக்குக் கொண்டு செல்லவோ கூடாது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُحِبُّونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَشِيعَ</span> <span class=\"quran-arabic-font text-success\">الْفَاحِشَةُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, ஈமான் கொண்டவர்களிடையே மானக்கேடான விஷயங்கள் பரவ வேண்டும் என்று விரும்புவோருக்கு, நோவினை தரும் வேதனை உண்டு.) அதாவது, நம்பிக்கை கொண்டவர்களைப் பற்றிய தீய செய்திகள் வெளிப்படுவதை விரும்புபவர்களை இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَالآخِرَةِ﴿</span><br />\r\n<br />\r\n(இவ்வுலகிலும், மறுமையிலும்.) இதன் பொருள், (இவ்வுலகில்) சட்டம் விதித்துள்ள தண்டனையினாலும், மறுமையில் நரகத்தின் வேதனையினாலும் அவர்களுக்குத் தண்டனை உண்டு என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">وَأَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வே அறிகிறான், நீங்கள் அறிய மாட்டீர்கள்.) அதாவது, காரியங்களை அவனிடமே ஒப்படைத்து விடுங்கள், நீங்கள் நேர்வழி பெறுவீர்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் ஸவ்பான் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளனர்: நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُؤْذُوا</span> <span class=\"quran-arabic-font text-success\">عِبَادَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تُعَيِّرُوهُمْ،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَطْلُبُوا</span> <span class=\"quran-arabic-font text-success\">عَوْرَاتِهِمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">طَلَبَ</span> <span class=\"quran-arabic-font text-success\">عَوْرَةَ</span> <span class=\"quran-arabic-font text-success\">أَخِيهِ</span> <span class=\"quran-arabic-font text-success\">الْمُسْلِمِ</span> <span class=\"quran-arabic-font text-success\">طَلَبَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَوْرَتَهُ،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَفْضَحَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بَيْتِهِ</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அடியார்களுக்குத் தொந்தரவு கொடுக்காதீர்கள், அவர்களைப் பழிக்காதீர்கள், அவர்களின் மறைவான குறைகளைத் தேடாதீர்கள். ஏனெனில், எவர் தனது முஸ்லிம் சகோதரரின் குறைகளைத் தேடுகிறாரோ, அல்லாஹ் அவரது குறையைத் தேடுவான்; எவனது குறையை அல்லாஹ் தேடுகிறானோ, அவர் தனது வீட்டிற்குள் மறைந்திருந்தாலும் கூட அல்லாஹ் அவரை இழிவுபடுத்துவான்.)<br />\r\n<br />","text":"நம்பிக்கை கொண்டவர்களிடையே மானக்கேடான விஷயங்கள் பரவுவதை விரும்புவோரை ஒழுங்குபடுத்துதல்\n\r\n\n\r\nதீய பேச்சைக் கேட்டு, அதை ஓரளவுக்கு நம்பி, அதனைப் பரப்பத் தொடங்குபவர்களுக்கு வழங்கப்படும் மூன்றாவது ஒழுங்குமுறை இதுவாகும்; அவர்கள் அத்தகைய பேச்சுகளைப் பரப்பவோ அல்லது மற்றவர்களுக்குக் கொண்டு செல்லவோ கூடாது. அல்லாஹ் கூறுகிறான்: ﴾إِنَّ الَّذِينَ يُحِبُّونَ أَن تَشِيعَ الْفَاحِشَةُ فِى الَّذِينَ ءَامَنُواْ لَهُمْ عَذَابٌ أَلِيمٌ﴿\n\r\n\n\r\n(நிச்சயமாக, ஈமான் கொண்டவர்களிடையே மானக்கேடான விஷயங்கள் பரவ வேண்டும் என்று விரும்புவோருக்கு, நோவினை தரும் வேதனை உண்டு.) அதாவது, நம்பிக்கை கொண்டவர்களைப் பற்றிய தீய செய்திகள் வெளிப்படுவதை விரும்புபவர்களை இது குறிக்கிறது.\n\r\n\n\r\n﴾فِى الدُّنْيَا وَالآخِرَةِ﴿\n\r\n\n\r\n(இவ்வுலகிலும், மறுமையிலும்.) இதன் பொருள், (இவ்வுலகில்) சட்டம் விதித்துள்ள தண்டனையினாலும், மறுமையில் நரகத்தின் வேதனையினாலும் அவர்களுக்குத் தண்டனை உண்டு என்பதாகும்.\n\r\n\n\r\n﴾وَاللَّهُ يَعْلَمُ وَأَنتُمْ لاَ تَعْلَمُونَ﴿\n\r\n\n\r\n(அல்லாஹ்வே அறிகிறான், நீங்கள் அறிய மாட்டீர்கள்.) அதாவது, காரியங்களை அவனிடமே ஒப்படைத்து விடுங்கள், நீங்கள் நேர்வழி பெறுவீர்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் ஸவ்பான் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளனர்: நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«لَا تُؤْذُوا عِبَادَ اللهِ وَلَا تُعَيِّرُوهُمْ، وَلَا تَطْلُبُوا عَوْرَاتِهِمْ، فَإِنَّهُ مَنْ طَلَبَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ طَلَبَ اللهُ عَوْرَتَهُ، حَتَّى يَفْضَحَهُ فِي بَيْتِهِ»﴿\n\r\n\n\r\n(அல்லாஹ்வின் அடியார்களுக்குத் தொந்தரவு கொடுக்காதீர்கள், அவர்களைப் பழிக்காதீர்கள், அவர்களின் மறைவான குறைகளைத் தேடாதீர்கள். ஏனெனில், எவர் தனது முஸ்லிம் சகோதரரின் குறைகளைத் தேடுகிறாரோ, அல்லாஹ் அவரது குறையைத் தேடுவான்; எவனது குறையை அல்லாஹ் தேடுகிறானோ, அவர் தனது வீட்டிற்குள் மறைந்திருந்தாலும் கூட அல்லாஹ் அவரை இழிவுபடுத்துவான்.)"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=21\" class=\"link\">24:21</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:21 ஐ பார்க்கவும்"},"21":{"html":"<strong>அல்லாஹ்வின் அருளை நினைவூட்டுவதும் ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றுவது குறித்து எச்சரிப்பதும்</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَلَوْلَا</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتُهُ</span> <span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">رَءُوفٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால், மேலும் நிச்சயமாக அல்லாஹ் மிக்க இரக்கமுள்ளவனாகவும், நிகரற்ற அன்புடையவனாகவும் இல்லாதிருந்தால் நிலைமை மிக மோசமாகியிருக்கும்.) அதாவது, இது இல்லாதிருந்தால், நிலைமையே முற்றிலும் வேறாக இருந்திருக்கும். ஆனால் உயர்ந்தோனாகிய அவன், தன் அடியார்கள் மீது மிக்க இரக்கமும் பெருங்கருணையும் கொண்டவனாக இருக்கிறான். இந்தப் பாவத்தைச் செய்தவர்களில் தன்னிடம் தவ்பா (பாவமன்னிப்பு) கோருபவர்களின் மன்னிப்பை அவன் ஏற்றுக்கொள்கிறான். மேலும், அவர்கள் மீது விதிக்கப்பட்ட தண்டனை நிறைவேற்றப்பட்டதன் மூலம் அவர்களை அவன் தூய்மைப்படுத்துகிறான். பிறகு அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعُوا</span> <span class=\"quran-arabic-font text-success\">خُطُوَاتِ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஈமான் கொண்டவர்களே! ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றாதீர்கள்.) அதாவது, அவனது வழிகளையும், பாதைகளையும் அவன் ஏவுகின்ற காரியங்களையும் பின்பற்றாதீர்கள்.<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعْ</span> <span class=\"quran-arabic-font text-success\">خُطُوَاتِ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَأْمُرُ</span> <span class=\"quran-arabic-font text-success\">بِالْفَحْشَاءِ</span> <span class=\"quran-arabic-font text-success\">وَالْمُنكَرِ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும், எவர் ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றுகிறாரோ, நிச்சயமாக அவன் மானக்கேடான காரியங்களையும் தீமைகளையுமே ஏவுகிறான்.) இது மிகவும் சுருக்கமாகவும் அதேசமயம் மிகத் தெளிவான முறையிலும் விடுக்கப்பட்ட ஓர் எச்சரிக்கையாகும். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலி பின் அபீ தல்ஹா அறிவிக்கிறார்கள்:<span class=\"quran-arabic-font text-success\">﴾خُطُوَاتِ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஷைத்தானின் அடிச்சுவடுகள்) என்பது அவனது செயல்களைக் குறிக்கும். இக்ரிமா அவர்கள் இது அவனது தீய ஊசலாட்டங்களைக் குறிப்பதாகக் கூறினார்கள். கதாதா அவர்கள் கூறினார்கள்: \"ஒவ்வொரு பாவமும் ஷைத்தானின் அடிச்சுவடுகளில் ஒன்றாகும்.\" மஸ்ரூக் (ரஹ்) அவர்கள் கூறினார்கள்: \"ஒருவர் பாவம் செய்வதாகச் சத்தியம் செய்வது ஷைத்தானின் அடிச்சுவடுகளில் உள்ளதாகும்.\" அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"பாவம் செய்ய நேர்ச்சை செய்வது ஷைத்தானின் அடிச்சுவடுகளில் ஒன்றாகும்.\" பிறகு அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾وَلَوْلَا</span> <span class=\"quran-arabic-font text-success\">فَضْلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتُهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">زَكَى</span> <span class=\"quran-arabic-font text-success\">مِنكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ</span> <span class=\"quran-arabic-font text-success\">أَبَدًا﴿</span><br />\r\n<br />\r\n<br />\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால், உங்களில் எவருமே ஒருபோதும் பாவங்களிலிருந்து தூய்மை அடைந்திருக்க முடியாது.) அதாவது, தான் நாடியவர்கள் தவ்பா செய்து தன்னிடம் திரும்பி வரவும், ஷிர்க் (இணைவைப்பு), தீமை, பாவம் மற்றும் ஒவ்வொரு மனிதரிடமும் இயல்பாகக் காணப்படும் தீய குணங்களிலிருந்தும் தூய்மை பெறவும் அல்லாஹ் உதவவில்லை என்றால், எவருமே ஒருபோதும் தூய்மையையும் நன்மையையும் அடைந்திருக்க முடியாது.<span class=\"quran-arabic-font text-success\">﴾وَلَكِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُزَكِّي</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَاءُ﴿</span><br />\r\n<br />\r\n<br />\r\n(ஆனால், அல்லாஹ் தான் நாடியவர்களைத் தூய்மைப்படுத்துகிறான்) அதாவது, தனது படைப்புகளில் தான் நாடியவர்களை அவன் தூய்மைப்படுத்துகிறான். மேலும், தான் நாடியவர்களை வழிகேட்டில் விட்டுவிடுகிறான்; அவர்கள் தங்களது வழிகேட்டிலும் பாவத்திலும் அழிந்துபோக விட்டுவிடுகிறான்.<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَمِيعٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(மேலும் அல்லாஹ் யாவற்றையும் செவியேற்பவன்,) அதாவது, தனது அடியார்கள் கூறுவதை அவன் செவியேற்கிறான்,<span class=\"quran-arabic-font text-success\">﴾عَلِيمٌ﴿</span><br />\r\n<br />\r\n<br />\r\n(யாவற்றையும் அறிந்தவன்.) யார் நேர்வழிக்குத் தகுதியானவர், யார் வழிகேட்டிற்குத் தகுதியானவர் என்பதை அவன் நன்கு அறிந்தவன்.<br />\r\n<br />","text":"அல்லாஹ்வின் அருளை நினைவூட்டுவதும் ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றுவது குறித்து எச்சரிப்பதும்\n\r\n\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:﴾وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ رَءُوفٌ رَّحِيمٌ﴿\n\r\n\n\r\n\n\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால், மேலும் நிச்சயமாக அல்லாஹ் மிக்க இரக்கமுள்ளவனாகவும், நிகரற்ற அன்புடையவனாகவும் இல்லாதிருந்தால் நிலைமை மிக மோசமாகியிருக்கும்.) அதாவது, இது இல்லாதிருந்தால், நிலைமையே முற்றிலும் வேறாக இருந்திருக்கும். ஆனால் உயர்ந்தோனாகிய அவன், தன் அடியார்கள் மீது மிக்க இரக்கமும் பெருங்கருணையும் கொண்டவனாக இருக்கிறான். இந்தப் பாவத்தைச் செய்தவர்களில் தன்னிடம் தவ்பா (பாவமன்னிப்பு) கோருபவர்களின் மன்னிப்பை அவன் ஏற்றுக்கொள்கிறான். மேலும், அவர்கள் மீது விதிக்கப்பட்ட தண்டனை நிறைவேற்றப்பட்டதன் மூலம் அவர்களை அவன் தூய்மைப்படுத்துகிறான். பிறகு அல்லாஹ் கூறுகிறான்:﴾يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ﴿\n\r\n\n\r\n\n\r\n(ஈமான் கொண்டவர்களே! ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றாதீர்கள்.) அதாவது, அவனது வழிகளையும், பாதைகளையும் அவன் ஏவுகின்ற காரியங்களையும் பின்பற்றாதீர்கள்.﴾وَمَن يَتَّبِعْ خُطُوَاتِ الشَّيْطَانِ فَإِنَّهُ يَأْمُرُ بِالْفَحْشَاءِ وَالْمُنكَرِ﴿\n\r\n\n\r\n\n\r\n(மேலும், எவர் ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்றுகிறாரோ, நிச்சயமாக அவன் மானக்கேடான காரியங்களையும் தீமைகளையுமே ஏவுகிறான்.) இது மிகவும் சுருக்கமாகவும் அதேசமயம் மிகத் தெளிவான முறையிலும் விடுக்கப்பட்ட ஓர் எச்சரிக்கையாகும். இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலி பின் அபீ தல்ஹா அறிவிக்கிறார்கள்:﴾خُطُوَاتِ الشَّيْطَانِ﴿\n\r\n\n\r\n\n\r\n(ஷைத்தானின் அடிச்சுவடுகள்) என்பது அவனது செயல்களைக் குறிக்கும். இக்ரிமா அவர்கள் இது அவனது தீய ஊசலாட்டங்களைக் குறிப்பதாகக் கூறினார்கள். கதாதா அவர்கள் கூறினார்கள்: \"ஒவ்வொரு பாவமும் ஷைத்தானின் அடிச்சுவடுகளில் ஒன்றாகும்.\" மஸ்ரூக் (ரஹ்) அவர்கள் கூறினார்கள்: \"ஒருவர் பாவம் செய்வதாகச் சத்தியம் செய்வது ஷைத்தானின் அடிச்சுவடுகளில் உள்ளதாகும்.\" அபூ மிஜ்லஸ் அவர்கள் கூறினார்கள்: \"பாவம் செய்ய நேர்ச்சை செய்வது ஷைத்தானின் அடிச்சுவடுகளில் ஒன்றாகும்.\" பிறகு அல்லாஹ் கூறுகிறான்:﴾وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَى مِنكُم مِّنْ أَحَدٍ أَبَدًا﴿\n\r\n\n\r\n\n\r\n(உங்கள் மீது அல்லாஹ்வின் அருளும் அவனது கருணையும் இல்லாதிருந்தால், உங்களில் எவருமே ஒருபோதும் பாவங்களிலிருந்து தூய்மை அடைந்திருக்க முடியாது.) அதாவது, தான் நாடியவர்கள் தவ்பா செய்து தன்னிடம் திரும்பி வரவும், ஷிர்க் (இணைவைப்பு), தீமை, பாவம் மற்றும் ஒவ்வொரு மனிதரிடமும் இயல்பாகக் காணப்படும் தீய குணங்களிலிருந்தும் தூய்மை பெறவும் அல்லாஹ் உதவவில்லை என்றால், எவருமே ஒருபோதும் தூய்மையையும் நன்மையையும் அடைந்திருக்க முடியாது.﴾وَلَكِنَّ اللَّهَ يُزَكِّي مَن يَشَاءُ﴿\n\r\n\n\r\n\n\r\n(ஆனால், அல்லாஹ் தான் நாடியவர்களைத் தூய்மைப்படுத்துகிறான்) அதாவது, தனது படைப்புகளில் தான் நாடியவர்களை அவன் தூய்மைப்படுத்துகிறான். மேலும், தான் நாடியவர்களை வழிகேட்டில் விட்டுவிடுகிறான்; அவர்கள் தங்களது வழிகேட்டிலும் பாவத்திலும் அழிந்துபோக விட்டுவிடுகிறான்.﴾وَاللَّهُ سَمِيعٌ﴿\n\r\n\n\r\n\n\r\n(மேலும் அல்லாஹ் யாவற்றையும் செவியேற்பவன்,) அதாவது, தனது அடியார்கள் கூறுவதை அவன் செவியேற்கிறான்,﴾عَلِيمٌ﴿\n\r\n\n\r\n\n\r\n(யாவற்றையும் அறிந்தவன்.) யார் நேர்வழிக்குத் தகுதியானவர், யார் வழிகேட்டிற்குத் தகுதியானவர் என்பதை அவன் நன்கு அறிந்தவன்."},"22":{"html":"<strong>செல்வம் வழங்கப்பட்டவர்கள் தர்மம் செய்யவும், சகிப்புத்தன்மையுடன் இருக்கவும் தூண்டுதல்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَأْتَلِ﴿</span><br />\r\n<br />\r\n(இன்னும் சத்தியம் செய்ய வேண்டாம்) அதாவது, ஒரு சபதம் எடுக்க வேண்டாம்,<span class=\"quran-arabic-font text-success\">﴾أُوْلُواْ</span> <span class=\"quran-arabic-font text-success\">الْفَضْلِ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ﴿</span><br />\r\n<br />\r\n(உங்களில் அருட்கொடைகள் வழங்கப்பட்டவர்கள்) இதன் பொருள், தர்மம் செய்வதற்கும் நன்மைகள் புரிவதற்கும் வசதி வாய்ப்புகள் உள்ளவர்கள்,<span class=\"quran-arabic-font text-success\">﴾وَالسَّعَةِ﴿</span><br />\r\n<br />\r\n(மற்றும் செல்வம் உடையவர்கள்) இதன் பொருள், நல்ல பொருளாதார வசதி கொண்டவர்கள்,<span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">يُؤْتُواْ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">الْقُرْبَى</span> <span class=\"quran-arabic-font text-success\">وَالْمَسَاكِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُهَاجِرِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(தங்கள் உறவினர்களுக்கும், ஏழைகளுக்கும், அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்தவர்களுக்கும் உதவிகள் வழங்குவதற்கு.) இதன் பொருள், தேவையுடையவர்களாக இருக்கும் அல்லது அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்த உங்கள் உறவினர்களுடன் இரத்த பந்த உறவுகளைப் பேண மாட்டேன் என்று சத்தியம் செய்யாதீர்கள். ஏனெனில், இரத்த பந்த உறவுகளைப் பேணுவதில் இதுவே மிகச்சிறந்த கருணைச் செயலாகும். அல்லாஹ் கூறுகிறான்,<span class=\"quran-arabic-font text-success\">﴾وَلْيَعْفُواْ</span> <span class=\"quran-arabic-font text-success\">وَلْيَصْفَحُواْ﴿</span><br />\r\n<br />\r\n(அவர்கள் மன்னித்து, பொறுத்துக்கொள்ளட்டும்.) கடந்த கால அவமதிப்புகளையும், மோசமான நடத்தைகளையும் மன்னிக்கட்டும். படைப்பினங்கள் தங்களுக்குத் தாங்களே அநீதி இழைத்துக் கொண்ட போதிலும், அவர்கள் மீது அல்லாஹ் காட்டும் பொறுமை, தாராள குணம் மற்றும் கருணையின் ஒரு பகுதியே இதுவாகும்.<br />\r\n<br />\r\nஇந்த ஆயத் அஸ்-ஸித்தீக் (ரழி) அவர்களைப் பற்றி அருளப்பட்டது. நாம் ஏற்கனவே ஹதீஸில் பார்த்தது போல, ஆயிஷா (ரழி) அவர்களைப் பற்றி மிஸ்தஹ் பின் உஸாஸா (ரழி) அவர்கள் அவதூறு பேசிய பிறகு, அவருக்கு இனி உதவ மாட்டேன் என்று அஸ்-ஸித்தீக் (ரழி) அவர்கள் சத்தியம் செய்தார்கள். முஃமின்களின் தாயாரான ஆயிஷா (ரழி) அவர்களின் தூய்மையை அல்லாஹ் வெளிப்படுத்தியபோது, இந்த நிகழ்வின் முடிவில் முஃமின்கள் மகிழ்ச்சியும் மனநிறைவும் அடைந்தனர். மேலும், இந்த விஷயத்தைப் பேசிய முஃமின்கள் வருந்தி மன்னிப்புத் தேடினர் (தவ்பா செய்தனர்); தண்டனைக்குரியவர்களுக்கு தண்டனையும் நிறைவேற்றப்பட்டது. <br />\r\n<br />\r\nஅப்போது அல்லாஹ், அஸ்-ஸித்தீக் (ரழி) அவர்களின் உள்ளத்தை அவரது உறவினரான மிஸ்தஹ் பின் உஸாஸா (ரழி) அவர்கள் மீது மென்மையாக்கத் தொடங்கினான். மிஸ்தஹ் (ரழி) அவர்கள் அஸ்-ஸித்தீக் (ரழி) அவர்களின் தாயாரின் சகோதரி மகனாக இருந்தார். மேலும், அபூபக்கர் (ரழி) அவர்கள் வழங்கியதைத் தவிர வேறு எந்தச் செல்வமும் இல்லாத ஒரு ஏழையாக அவர் இருந்தார். அவர் அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்தவர்களில் ஒருவராகவும் இருந்தார். அவர் அந்தப் பொய்களையும் அவதூறுகளையும் பரப்பியிருந்தாலும், பின்னர் அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொண்டான், மேலும் அவருக்குரிய தண்டனையும் நிறைவேற்றப்பட்டது. அஸ்-ஸித்தீக் (ரழி) அவர்கள் தனது தாராள குணத்திற்காக அறியப்பட்டவர்; அவர் உறவினர்களுக்கும் அந்நியர்களுக்கும் ஒருசேர உதவிகளைச் செய்தவர்.<br />\r\n<br />\r\nஇந்த ஆயத் அருளப்பட்டபோது:<span class=\"quran-arabic-font text-success\">﴾أَلاَ</span> <span class=\"quran-arabic-font text-success\">تُحِبُّونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களை மன்னிப்பதை நீங்கள் விரும்பமாட்டீர்களா? மேலும், அல்லாஹ் மிகவும் மன்னிப்பவன்; மிக்க கிருபையுடையவன்.), இது செயலுக்கு ஏற்ற கூலி வழங்கப்படுவதையும், 'நீங்கள் மற்றவர்களை மன்னித்தால், நீங்களும் மன்னிக்கப்படுவீர்கள்' என்பதையும் காட்டுகிறது. அப்போது அஸ்-ஸித்தீக் (ரழி) அவர்கள், \"நிச்சயமாக, அல்லாஹ்வின் மீது ஆணையாக, எங்கள் இறைவா! நீ எங்களை மன்னிப்பதையே நாங்கள் விரும்புகிறோம்\" என்று கூறினார்கள். <br />\r\n<br />\r\nபின்னர் அவர் மிஸ்தஹ் (ரழி) அவர்களுக்காக மீண்டும் செலவிடத் தொடங்கினார்; \"அல்லாஹ்வின் மீது ஆணையாக, அவருக்குச் செலவிடுவதை நான் ஒருபோதும் நிறுத்த மாட்டேன்\" என்றும் கூறினார். இது, \"அல்லாஹ்வின் மீது ஆணையாக, அவருக்கு நான் ஒருபோதும் செலவு செய்ய மாட்டேன்\" என்று அவர் முன்பு கூறியதற்குப் பரிகாரமாக அமைந்தது. அவர் 'அஸ்-ஸித்தீக்' (உண்மையாளர்) என்று அழைக்கப்படுவதற்கு முற்றிலும் தகுதியானவர் என்பதை இது நிரூபிக்கிறது. அல்லாஹ் அவரையும் அவருடைய மகளையும் (ரழி) பொருந்திக்கொள்வானாக.<br />\r\n<br />","text":"செல்வம் வழங்கப்பட்டவர்கள் தர்மம் செய்யவும், சகிப்புத்தன்மையுடன் இருக்கவும் தூண்டுதல்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்,﴾وَلاَ يَأْتَلِ﴿\n\r\n\n\r\n(இன்னும் சத்தியம் செய்ய வேண்டாம்) அதாவது, ஒரு சபதம் எடுக்க வேண்டாம்,﴾أُوْلُواْ الْفَضْلِ مِنكُمْ﴿\n\r\n\n\r\n(உங்களில் அருட்கொடைகள் வழங்கப்பட்டவர்கள்) இதன் பொருள், தர்மம் செய்வதற்கும் நன்மைகள் புரிவதற்கும் வசதி வாய்ப்புகள் உள்ளவர்கள்,﴾وَالسَّعَةِ﴿\n\r\n\n\r\n(மற்றும் செல்வம் உடையவர்கள்) இதன் பொருள், நல்ல பொருளாதார வசதி கொண்டவர்கள்,﴾أَن يُؤْتُواْ أُوْلِى الْقُرْبَى وَالْمَسَاكِينَ وَالْمُهَاجِرِينَ فِى سَبِيلِ اللَّهِ﴿\n\r\n\n\r\n(தங்கள் உறவினர்களுக்கும், ஏழைகளுக்கும், அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்தவர்களுக்கும் உதவிகள் வழங்குவதற்கு.) இதன் பொருள், தேவையுடையவர்களாக இருக்கும் அல்லது அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்த உங்கள் உறவினர்களுடன் இரத்த பந்த உறவுகளைப் பேண மாட்டேன் என்று சத்தியம் செய்யாதீர்கள். ஏனெனில், இரத்த பந்த உறவுகளைப் பேணுவதில் இதுவே மிகச்சிறந்த கருணைச் செயலாகும். அல்லாஹ் கூறுகிறான்,﴾وَلْيَعْفُواْ وَلْيَصْفَحُواْ﴿\n\r\n\n\r\n(அவர்கள் மன்னித்து, பொறுத்துக்கொள்ளட்டும்.) கடந்த கால அவமதிப்புகளையும், மோசமான நடத்தைகளையும் மன்னிக்கட்டும். படைப்பினங்கள் தங்களுக்குத் தாங்களே அநீதி இழைத்துக் கொண்ட போதிலும், அவர்கள் மீது அல்லாஹ் காட்டும் பொறுமை, தாராள குணம் மற்றும் கருணையின் ஒரு பகுதியே இதுவாகும்.\n\r\n\n\r\nஇந்த ஆயத் அஸ்-ஸித்தீக் (ரழி) அவர்களைப் பற்றி அருளப்பட்டது. நாம் ஏற்கனவே ஹதீஸில் பார்த்தது போல, ஆயிஷா (ரழி) அவர்களைப் பற்றி மிஸ்தஹ் பின் உஸாஸா (ரழி) அவர்கள் அவதூறு பேசிய பிறகு, அவருக்கு இனி உதவ மாட்டேன் என்று அஸ்-ஸித்தீக் (ரழி) அவர்கள் சத்தியம் செய்தார்கள். முஃமின்களின் தாயாரான ஆயிஷா (ரழி) அவர்களின் தூய்மையை அல்லாஹ் வெளிப்படுத்தியபோது, இந்த நிகழ்வின் முடிவில் முஃமின்கள் மகிழ்ச்சியும் மனநிறைவும் அடைந்தனர். மேலும், இந்த விஷயத்தைப் பேசிய முஃமின்கள் வருந்தி மன்னிப்புத் தேடினர் (தவ்பா செய்தனர்); தண்டனைக்குரியவர்களுக்கு தண்டனையும் நிறைவேற்றப்பட்டது.\n\r\n\n\r\nஅப்போது அல்லாஹ், அஸ்-ஸித்தீக் (ரழி) அவர்களின் உள்ளத்தை அவரது உறவினரான மிஸ்தஹ் பின் உஸாஸா (ரழி) அவர்கள் மீது மென்மையாக்கத் தொடங்கினான். மிஸ்தஹ் (ரழி) அவர்கள் அஸ்-ஸித்தீக் (ரழி) அவர்களின் தாயாரின் சகோதரி மகனாக இருந்தார். மேலும், அபூபக்கர் (ரழி) அவர்கள் வழங்கியதைத் தவிர வேறு எந்தச் செல்வமும் இல்லாத ஒரு ஏழையாக அவர் இருந்தார். அவர் அல்லாஹ்வின் பாதையில் ஹிஜ்ரத் செய்தவர்களில் ஒருவராகவும் இருந்தார். அவர் அந்தப் பொய்களையும் அவதூறுகளையும் பரப்பியிருந்தாலும், பின்னர் அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொண்டான், மேலும் அவருக்குரிய தண்டனையும் நிறைவேற்றப்பட்டது. அஸ்-ஸித்தீக் (ரழி) அவர்கள் தனது தாராள குணத்திற்காக அறியப்பட்டவர்; அவர் உறவினர்களுக்கும் அந்நியர்களுக்கும் ஒருசேர உதவிகளைச் செய்தவர்.\n\r\n\n\r\nஇந்த ஆயத் அருளப்பட்டபோது:﴾أَلاَ تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ﴿\n\r\n\n\r\n(அல்லாஹ் உங்களை மன்னிப்பதை நீங்கள் விரும்பமாட்டீர்களா? மேலும், அல்லாஹ் மிகவும் மன்னிப்பவன்; மிக்க கிருபையுடையவன்.), இது செயலுக்கு ஏற்ற கூலி வழங்கப்படுவதையும், 'நீங்கள் மற்றவர்களை மன்னித்தால், நீங்களும் மன்னிக்கப்படுவீர்கள்' என்பதையும் காட்டுகிறது. அப்போது அஸ்-ஸித்தீக் (ரழி) அவர்கள், \"நிச்சயமாக, அல்லாஹ்வின் மீது ஆணையாக, எங்கள் இறைவா! நீ எங்களை மன்னிப்பதையே நாங்கள் விரும்புகிறோம்\" என்று கூறினார்கள்.\n\r\n\n\r\nபின்னர் அவர் மிஸ்தஹ் (ரழி) அவர்களுக்காக மீண்டும் செலவிடத் தொடங்கினார்; \"அல்லாஹ்வின் மீது ஆணையாக, அவருக்குச் செலவிடுவதை நான் ஒருபோதும் நிறுத்த மாட்டேன்\" என்றும் கூறினார். இது, \"அல்லாஹ்வின் மீது ஆணையாக, அவருக்கு நான் ஒருபோதும் செலவு செய்ய மாட்டேன்\" என்று அவர் முன்பு கூறியதற்குப் பரிகாரமாக அமைந்தது. அவர் 'அஸ்-ஸித்தீக்' (உண்மையாளர்) என்று அழைக்கப்படுவதற்கு முற்றிலும் தகுதியானவர் என்பதை இது நிரூபிக்கிறது. அல்லாஹ் அவரையும் அவருடைய மகளையும் (ரழி) பொருந்திக்கொள்வானாக."},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=25\" class=\"link\">24:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:25 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=25\" class=\"link\">24:25</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:25 ஐ பார்க்கவும்"},"25":{"html":"<strong>கற்புள்ள, முஃமினான, தீயச் செயல்களைப் பற்றி நினைத்துக்கூடப் பார்க்காத பெண்கள் மீது அவதூறு கூறுவோருக்கு விடுக்கப்படும் எச்சரிக்கை</strong><br />\r\n<br />\r\nநல்ல முஃமின்களாக இருப்பதால், தங்கள் கற்பைத் தீண்டும் எதையும் நினைத்துக்கூடப் பார்க்காத கற்புள்ள பெண்கள் மீது அவதூறு கூறுபவர்களுக்கு, இது அல்லாஹ்வின் கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும். மற்ற எந்தப் பெண்ணையும் விட இப்பிரிவில் இடம்பெற இறைநம்பிக்கையாளர்களின் அன்னையர்களே (உம்முஹாதுல் முஃமினீன்) அதிகத் தகுதியுடையவர்கள். குறிப்பாக, இந்த வசனம் அருளப்படக் காரணமாக இருந்த ஆயிஷா பின்த் அஸ்-ஸித்தீக் (ரழி) அவர்கள் இதில் முதன்மையானவர்கள். இந்த வசனம் அருளப்பட்ட பிறகும், அவர்களைப் பற்றி அவதூறு பரப்புபவர் அல்லது பழி சுமத்துபவர் குர்ஆனைப் பிடிவாதமாக மறுப்பதன் காரணமாக ஒரு காஃபிர் (நிராகரிப்பாளர்) ஆகிவிடுகிறார் என்று அனைத்து அறிஞர்களும் ஏகோபித்து முடிவு செய்துள்ளனர். இதே சட்டம் மற்ற அனைத்து இறைநம்பிக்கையாளர்களின் அன்னையர்களுக்கும் பொருந்தும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لُعِنُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَالْآخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span><br />\r\n<br />\r\n(அவர்கள் இம்மையிலும் மறுமையிலும் சபிக்கப்பட்டவர்கள்; மேலும் அவர்களுக்குக் கடுமையான வேதனை உண்டு.) இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُؤْذُونَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ</span><br />\r\n<br />\r\n(நிச்சயமாக, யார் அல்லாஹ்வையும் அவனுடைய தூதரையும் துன்புறுத்துகிறார்களோ,) <a href=\"qurandisp.php?sura=33&ayah=57\" class=\"link\">33:57</a>. அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"இது ஆயிஷா (ரழி) அவர்களைக் குறித்ததாகும். இக்காலத்தில் முஸ்லிம் பெண்களுக்கு எதிராக இது போன்ற செயல்களில் ஈடுபடுபவர்களுக்கும் இதே சட்டம் பொருந்தும்; எனினும் ஆயிஷா (ரழி) அவர்களே இங்கு முதன்மையாகக் குறிப்பிடப்படுகிறார்கள்.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اجْتَنِبُوا</span> <span class=\"quran-arabic-font text-success\">السَّبْعَ</span> <span class=\"quran-arabic-font text-success\">الْمُوبِقَاتِ</span>»<br />\r\n<br />\r\n(அழிவை ஏற்படுத்தும் ஏழு பெரும் பாவங்களைத் தவிர்ந்து கொள்ளுங்கள்.) \"அல்லாஹ்வின் தூதரே! அவை யாவை?\" என்று அவர்களிடம் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الشِّرْكُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ،</span> <span class=\"quran-arabic-font text-success\">وَالسِّحْرُ،</span> <span class=\"quran-arabic-font text-success\">وَقَتْلُ</span> <span class=\"quran-arabic-font text-success\">النَّفْسِ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">حَرَّمَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ،</span> <span class=\"quran-arabic-font text-success\">وَأَكْلُ</span> <span class=\"quran-arabic-font text-success\">الرِّبَا،</span> <span class=\"quran-arabic-font text-success\">وَأَكْلُ</span> <span class=\"quran-arabic-font text-success\">مَالِ</span> <span class=\"quran-arabic-font text-success\">الْيَتِيمِ،</span> <span class=\"quran-arabic-font text-success\">وَالتَّوَلِّي</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الزَّحْفِ،</span> <span class=\"quran-arabic-font text-success\">وَقَذْفُ</span> <span class=\"quran-arabic-font text-success\">الْمُحْصَنَاتِ</span> <span class=\"quran-arabic-font text-success\">الْغَافِلَاتِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنَاتِ</span>»<br />\r\n<br />\r\n(அல்லாஹ்வுக்கு இணை வைப்பது; சூனியம்; நியாயமான காரணமின்றிக் கொலை செய்யக் கூடாது என்று அல்லாஹ் தடுத்துள்ள உயிரைக் கொல்வது; வட்டி (ரிபா) உண்பது; அனாதைகளின் சொத்தை உண்பது; போர்க்களத்தில் இருந்து புறமுதுகிட்டு ஓடுவது; மேலும், தீயச் செயல்களைப் பற்றி நினைத்துக்கூடப் பார்க்காத, முஃமினான, கற்புள்ள பெண்கள் மீது அவதூறு சுமத்துவது.) இதனை புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களும் பதிவு செய்துள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">أَلْسِنَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَيْدِيهِمْ</span> <span class=\"quran-arabic-font text-success\">وَأَرْجُلُهُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span><br />\r\n<br />\r\n(அந்நாளில், அவர்கள் செய்து கொண்டிருந்தவை குறித்து அவர்களுடைய நாவுகளும், கைகளும், கால்களும் அவர்களுக்கு எதிராகச் சாட்சி கூறும்.) இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"தொழுகையை (ஸலாத்) நிலைநாட்டியவர்களைத் தவிர வேறு யாரும் சொர்க்கத்தில் நுழைய முடியாது என்பதை இணைவைப்பாளர்கள் உணரும்போது இது நடக்கும். அவர்கள், 'வாருங்கள், நாம் (அனைத்தையும்) மறுப்போம்' என்று கூறுவார்கள். அவர்கள் (அனைத்தையும்) மறுக்கும்போது, அவர்களின் வாய்கள் முத்திரையிடப்படும். அவர்களின் கைகளும் கால்களும் அவர்களுக்கு எதிராகச் சாட்சியம் அளிக்கும். அவர்களால் அல்லாஹ்விடமிருந்து எதையும் மறைக்க முடியாது.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் நபியவர்கள் (ஸல்) அவர்களுடன் இருந்தோம். அப்போது அவர்கள் தமது கடைவாய்ப் பற்கள் தெரியும் அளவிற்குப் புன்னகைத்தார்கள். பின்னர் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَتَدْرُونَ</span> <span class=\"quran-arabic-font text-success\">مِمَّ</span> <span class=\"quran-arabic-font text-success\">أَضْحَكُ؟</span>»<br />\r\n<br />\r\n(நான் ஏன் புன்னகைக்கிறேன் என்று உங்களுக்குத் தெரியுமா?) நாங்கள், 'அல்லாஹ்வும் அவனது தூதருமே மிக அறிந்தவர்கள்' என்றோம். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مُجَادَلَةِ</span> <span class=\"quran-arabic-font text-success\">الْعَبْدِ</span> <span class=\"quran-arabic-font text-success\">لِرَبِّهِ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تُجِرْنِي</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمِ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">بَلَى،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أُجِيزُ</span> <span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">شَاهِدًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نَفْسِي،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">كَفَى</span> <span class=\"quran-arabic-font text-success\">بِنَفْسِكَ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">شَهِيدًا</span> <span class=\"quran-arabic-font text-success\">وَبِالْكِرَامِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">شُهُودًا،</span> <span class=\"quran-arabic-font text-success\">فَيُخْتَمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَيُقَالُ</span> <span class=\"quran-arabic-font text-success\">لِأَرْكَانِهِ</span>: <span class=\"quran-arabic-font text-success\">انْطِقِي</span> <span class=\"quran-arabic-font text-success\">فَتَنْطِقَ</span> <span class=\"quran-arabic-font text-success\">بِعَمَلِهِ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُخَلَّى</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُ</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْكَلَامِ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">بُعْدًا</span> <span class=\"quran-arabic-font text-success\">لَكُنَّ</span> <span class=\"quran-arabic-font text-success\">وَسُحْقًا</span> <span class=\"quran-arabic-font text-success\">فَعَنْكُنَّ</span> <span class=\"quran-arabic-font text-success\">كُنْتُ</span> <span class=\"quran-arabic-font text-success\">أُنَاضِلُ</span>»<br />\r\n<br />\r\n(ஓர் அடியான் தன் இறைவனிடம் தர்க்கம் செய்வதைக் குறித்துத்தான் (புன்னகைத்தேன்). அவன் கூறுவான்: 'என் இறைவனே! அநீதியிலிருந்து நீ எனக்குப் பாதுகாப்பு அளிக்கவில்லையா?' அல்லாஹ், 'ஆம்' என்று கூறுவான். அந்த அடியான், 'எனக்கு எதிராக என்னைத் தவிர வேறு யாரையும் சாட்சியாக நான் ஏற்க மாட்டேன்' என்பான். அதற்கு அல்லாஹ், 'இன்று உனக்கு எதிராக நீயே சாட்சியாகப் போதுமானவன்; மேலும் கண்ணியமான (வானவர்கள்) சாட்சிகளாக இருப்பார்கள்' என்று கூறுவான். பின்னர் அவனது வாய் முத்திரையிடப்பட்டு, அவனது உடல் உறுப்புகளிடம் 'பேசு' என்று சொல்லப்படும். அந்த உறுப்புகள் அவன் செய்த செயல்களைப் பற்றிப் பேசும். பிறகு அவன் பேசுவதற்கு அனுமதிக்கப்படுவான். அப்போது அவன் (தன் உறுப்புகளிடம்), 'உங்களுக்கு நாசம் உண்டாகட்டும்! உங்களுக்காகத்தானே நான் வாதாடிக் கொண்டிருந்தேன்!' என்பான்.)\" இதனை முஸ்லிம் மற்றும் அன்-நஸாயீ பதிவு செய்துள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يُوَفِّيهِمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">دِينَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span><br />\r\n<br />\r\n(அந்நாளில் அல்லாஹ் அவர்களின் 'தீனஹும்' (பிரதிபலனை) முழுமையாகக் கொடுப்பான்,) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">دِينَهُمُ</span><br />\r\n<br />\r\n('தீனஹும்') என்பதற்கு 'அவர்களின் கணக்கு' என்று பொருள். குர்ஆனில் 'தீனஹும்' என்ற வார்த்தை வரும்போதெல்லாம், அதன் பொருள் 'அவர்களின் கணக்கு' என்பதாகும்.\" இது பிற அறிஞர்களின் கருத்தும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينُ</span><br />\r\n<br />\r\n(மேலும், அல்லாஹ்வே தெளிவான உண்மையானவன் என்பதை அவர்கள் அறிந்து கொள்வார்கள்.) அதாவது, அவனது வாக்குறுதி, அவனது எச்சரிக்கை மற்றும் அவனது விசாரணை ஆகியவை நீதியானவை; அவற்றில் எந்த அநீதியும் இல்லை என்பதாகும்.<br />\r\n<br />","text":"கற்புள்ள, முஃமினான, தீயச் செயல்களைப் பற்றி நினைத்துக்கூடப் பார்க்காத பெண்கள் மீது அவதூறு கூறுவோருக்கு விடுக்கப்படும் எச்சரிக்கை\n\r\n\n\r\nநல்ல முஃமின்களாக இருப்பதால், தங்கள் கற்பைத் தீண்டும் எதையும் நினைத்துக்கூடப் பார்க்காத கற்புள்ள பெண்கள் மீது அவதூறு கூறுபவர்களுக்கு, இது அல்லாஹ்வின் கடுமையான எச்சரிக்கையும் அச்சுறுத்தலுமாகும். மற்ற எந்தப் பெண்ணையும் விட இப்பிரிவில் இடம்பெற இறைநம்பிக்கையாளர்களின் அன்னையர்களே (உம்முஹாதுல் முஃமினீன்) அதிகத் தகுதியுடையவர்கள். குறிப்பாக, இந்த வசனம் அருளப்படக் காரணமாக இருந்த ஆயிஷா பின்த் அஸ்-ஸித்தீக் (ரழி) அவர்கள் இதில் முதன்மையானவர்கள். இந்த வசனம் அருளப்பட்ட பிறகும், அவர்களைப் பற்றி அவதூறு பரப்புபவர் அல்லது பழி சுமத்துபவர் குர்ஆனைப் பிடிவாதமாக மறுப்பதன் காரணமாக ஒரு காஃபிர் (நிராகரிப்பாளர்) ஆகிவிடுகிறார் என்று அனைத்து அறிஞர்களும் ஏகோபித்து முடிவு செய்துள்ளனர். இதே சட்டம் மற்ற அனைத்து இறைநம்பிக்கையாளர்களின் அன்னையர்களுக்கும் பொருந்தும்.\n\r\n\n\r\nلُعِنُوا فِي الدُّنْيَا وَالْآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ\n\r\n\n\r\n(அவர்கள் இம்மையிலும் மறுமையிலும் சபிக்கப்பட்டவர்கள்; மேலும் அவர்களுக்குக் கடுமையான வேதனை உண்டு.) இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nإِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ وَرَسُولَهُ\n\r\n\n\r\n(நிச்சயமாக, யார் அல்லாஹ்வையும் அவனுடைய தூதரையும் துன்புறுத்துகிறார்களோ,) 33:57. அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"இது ஆயிஷா (ரழி) அவர்களைக் குறித்ததாகும். இக்காலத்தில் முஸ்லிம் பெண்களுக்கு எதிராக இது போன்ற செயல்களில் ஈடுபடுபவர்களுக்கும் இதே சட்டம் பொருந்தும்; எனினும் ஆயிஷா (ரழி) அவர்களே இங்கு முதன்மையாகக் குறிப்பிடப்படுகிறார்கள்.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ»\n\r\n\n\r\n(அழிவை ஏற்படுத்தும் ஏழு பெரும் பாவங்களைத் தவிர்ந்து கொள்ளுங்கள்.) \"அல்லாஹ்வின் தூதரே! அவை யாவை?\" என்று அவர்களிடம் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الشِّرْكُ بِاللهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ»\n\r\n\n\r\n(அல்லாஹ்வுக்கு இணை வைப்பது; சூனியம்; நியாயமான காரணமின்றிக் கொலை செய்யக் கூடாது என்று அல்லாஹ் தடுத்துள்ள உயிரைக் கொல்வது; வட்டி (ரிபா) உண்பது; அனாதைகளின் சொத்தை உண்பது; போர்க்களத்தில் இருந்து புறமுதுகிட்டு ஓடுவது; மேலும், தீயச் செயல்களைப் பற்றி நினைத்துக்கூடப் பார்க்காத, முஃமினான, கற்புள்ள பெண்கள் மீது அவதூறு சுமத்துவது.) இதனை புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களும் பதிவு செய்துள்ளன.\n\r\n\n\r\nيَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُواْ يَعْمَلُونَ\n\r\n\n\r\n(அந்நாளில், அவர்கள் செய்து கொண்டிருந்தவை குறித்து அவர்களுடைய நாவுகளும், கைகளும், கால்களும் அவர்களுக்கு எதிராகச் சாட்சி கூறும்.) இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"தொழுகையை (ஸலாத்) நிலைநாட்டியவர்களைத் தவிர வேறு யாரும் சொர்க்கத்தில் நுழைய முடியாது என்பதை இணைவைப்பாளர்கள் உணரும்போது இது நடக்கும். அவர்கள், 'வாருங்கள், நாம் (அனைத்தையும்) மறுப்போம்' என்று கூறுவார்கள். அவர்கள் (அனைத்தையும்) மறுக்கும்போது, அவர்களின் வாய்கள் முத்திரையிடப்படும். அவர்களின் கைகளும் கால்களும் அவர்களுக்கு எதிராகச் சாட்சியம் அளிக்கும். அவர்களால் அல்லாஹ்விடமிருந்து எதையும் மறைக்க முடியாது.\" இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார்கள்: அனஸ் பின் மாலிக் (ரழி) அவர்கள் கூறினார்கள்: \"நாங்கள் நபியவர்கள் (ஸல்) அவர்களுடன் இருந்தோம். அப்போது அவர்கள் தமது கடைவாய்ப் பற்கள் தெரியும் அளவிற்குப் புன்னகைத்தார்கள். பின்னர் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَتَدْرُونَ مِمَّ أَضْحَكُ؟»\n\r\n\n\r\n(நான் ஏன் புன்னகைக்கிறேன் என்று உங்களுக்குத் தெரியுமா?) நாங்கள், 'அல்லாஹ்வும் அவனது தூதருமே மிக அறிந்தவர்கள்' என்றோம். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مِنْ مُجَادَلَةِ الْعَبْدِ لِرَبِّهِ يَقُولُ: يَا رَبِّ أَلَمْ تُجِرْنِي مِنَ الظُّلْمِ؟ فَيَقُولُ: بَلَى، فَيَقُولُ: لَا أُجِيزُ عَلَيَّ شَاهِدًا إِلَّا مِنْ نَفْسِي، فَيَقُولُ: كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ شَهِيدًا وَبِالْكِرَامِ عَلَيْكَ شُهُودًا، فَيُخْتَمُ عَلَى فِيهِ وَيُقَالُ لِأَرْكَانِهِ: انْطِقِي فَتَنْطِقَ بِعَمَلِهِ، ثُمَّ يُخَلَّى بَيْنَهُ وَبَيْنَ الْكَلَامِ فَيَقُولُ: بُعْدًا لَكُنَّ وَسُحْقًا فَعَنْكُنَّ كُنْتُ أُنَاضِلُ»\n\r\n\n\r\n(ஓர் அடியான் தன் இறைவனிடம் தர்க்கம் செய்வதைக் குறித்துத்தான் (புன்னகைத்தேன்). அவன் கூறுவான்: 'என் இறைவனே! அநீதியிலிருந்து நீ எனக்குப் பாதுகாப்பு அளிக்கவில்லையா?' அல்லாஹ், 'ஆம்' என்று கூறுவான். அந்த அடியான், 'எனக்கு எதிராக என்னைத் தவிர வேறு யாரையும் சாட்சியாக நான் ஏற்க மாட்டேன்' என்பான். அதற்கு அல்லாஹ், 'இன்று உனக்கு எதிராக நீயே சாட்சியாகப் போதுமானவன்; மேலும் கண்ணியமான (வானவர்கள்) சாட்சிகளாக இருப்பார்கள்' என்று கூறுவான். பின்னர் அவனது வாய் முத்திரையிடப்பட்டு, அவனது உடல் உறுப்புகளிடம் 'பேசு' என்று சொல்லப்படும். அந்த உறுப்புகள் அவன் செய்த செயல்களைப் பற்றிப் பேசும். பிறகு அவன் பேசுவதற்கு அனுமதிக்கப்படுவான். அப்போது அவன் (தன் உறுப்புகளிடம்), 'உங்களுக்கு நாசம் உண்டாகட்டும்! உங்களுக்காகத்தானே நான் வாதாடிக் கொண்டிருந்தேன்!' என்பான்.)\" இதனை முஸ்லிம் மற்றும் அன்-நஸாயீ பதிவு செய்துள்ளன.\n\r\n\n\r\nيَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ\n\r\n\n\r\n(அந்நாளில் அல்லாஹ் அவர்களின் 'தீனஹும்' (பிரதிபலனை) முழுமையாகக் கொடுப்பான்,) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nدِينَهُمُ\n\r\n\n\r\n('தீனஹும்') என்பதற்கு 'அவர்களின் கணக்கு' என்று பொருள். குர்ஆனில் 'தீனஹும்' என்ற வார்த்தை வரும்போதெல்லாம், அதன் பொருள் 'அவர்களின் கணக்கு' என்பதாகும்.\" இது பிற அறிஞர்களின் கருத்தும் ஆகும்.\n\r\n\n\r\nوَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ\n\r\n\n\r\n(மேலும், அல்லாஹ்வே தெளிவான உண்மையானவன் என்பதை அவர்கள் அறிந்து கொள்வார்கள்.) அதாவது, அவனது வாக்குறுதி, அவனது எச்சரிக்கை மற்றும் அவனது விசாரணை ஆகியவை நீதியானவை; அவற்றில் எந்த அநீதியும் இல்லை என்பதாகும்."},"26":{"html":"<strong>மனிதகுலத்தின் சிறந்தவரை மணமுடித்ததால் ஆயிஷா (ரழி) அவர்களின் கண்ணியம்</strong><br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"தீய சொற்கள் தீய ஆண்களுக்கும், தீய ஆண்கள் தீய சொற்களுக்கும் உரியவர்கள்; நல்ல சொற்கள் நல்ல ஆண்களுக்கும், நல்ல ஆண்கள் நல்ல சொற்களுக்கும் உரியவர்கள். இது ஆயிஷா (ரழி) அவர்களையும், அவர்கள் மீது அவதூறு சுமத்தியவர்களையும் குறித்தே அருளப்பட்டது.\" இது போன்றே முஜாஹித், அதா, ஸயீத் பின் ஜுபைர், அஷ்-ஷஅபி, அல்-ஹஸன் பின் அபுல் ஹஸன் அல்-பஸரி, ஹபீப் பின் அபீ தாபித் மற்றும் அத்-தஹ்ஹாக் ஆகியோராலும் அறிவிக்கப்பட்டுள்ளது. மேலும், இதுவே இப்னு ஜரீர் அவர்களால் பெரிதும் விரும்பப்பட்ட கருத்தாகும். தீய பேச்சு தீயவர்களுக்கே மிகவும் பொருத்தமானது என்றும், நற்பேச்சு நல்லவர்களுக்கே மிகவும் பொருத்தமானது என்றும் இதற்கு அவர்கள் விளக்கம் அளித்தார்கள். நயவஞ்சகர்கள் ஆயிஷா (ரழி) அவர்கள் மீது சுமத்திய பழிச்சொற்கள் அவர்களுக்கே (நயவஞ்சகர்களுக்கே) மிகவும் பொருத்தமானதாகும். மேலும், அத்தகைய பழிச்சொற்களிலிருந்து விலகி இருப்பதற்கும், நிரபராதியாக இருப்பதற்கும் ஆயிஷா (ரழி) அவர்களே மிகவும் தகுதியானவர்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">مُبَرَّءُونَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span><br />\r\n<br />\r\n(அத்தகைய (நல்ல)வர்கள் அவர்கள் கூறும் (ஒவ்வொரு) தீய சொல்லிலிருந்தும் நீங்கியவர்கள்;)<br />\r\n<br />\r\nஅப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"தீய பெண்கள் தீய ஆண்களுக்கும், தீய ஆண்கள் தீய பெண்களுக்கும் உரியவர்கள்; நல்ல பெண்கள் நல்ல ஆண்களுக்கும், நல்ல ஆண்கள் நல்ல பெண்களுக்கும் உரியவர்கள்.\" இதுவும் அவர்கள் கூறியதையே (நிரபராதித்தன்மையையே) உறுதிப்படுத்துகிறது. அதாவது, ஆயிஷா (ரழி) அவர்கள் மிகச் சிறந்தவராக இருந்த காரணத்தினாலேயே, அல்லாஹ் அவர்களைத் தனது தூதரின் மனைவியாக்கினான். ஏனெனில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மனிதகுலத்திலேயே மிகச் சிறந்தவர்களில் சிறந்தவர் ஆவார்கள். ஆயிஷா (ரழி) அவர்கள் தீயவராக இருந்திருந்தால், அல்லாஹ்வின் சட்டப்படியோ அல்லது அவனது விதியின்படியோ அவர்கள் தூதருக்குப் பொருத்தமான துணையாக இருந்திருக்க மாட்டார்கள். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">مُبَرَّءُونَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span><br />\r\n<br />\r\n(அத்தகையவர்கள் அவர்கள் கூறும் (ஒவ்வொரு) தீய சொல்லிலிருந்தும் நீங்கியவர்கள்;) அதாவது, அவதூறு பரப்புபவர்களும் பகைமை கொண்டவர்களும் கூறுகின்ற பழிச்சொற்களிலிருந்து இவர்கள் வெகு தொலைவில் இருக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَهُم</span> <span class=\"quran-arabic-font text-success\">مَّغْفِرَةٌ</span><br />\r\n<br />\r\n(அவர்களுக்கு மன்னிப்பு உண்டு,) அதாவது, அவர்கள் மீது சுமத்தப்பட்ட பொய்களின் காரணமாக (அவர்களுக்கு அல்லாஹ்விடம் மன்னிப்பு உண்டு),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرِزْقٌ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٌ</span><br />\r\n<br />\r\n(இன்னும் கண்ணியமான வாழ்வாதாரமும் உண்டு.) அதாவது, பேரின்பச் சோலைகளில் அல்லாஹ்விடம் அவர்களுக்கு நற்கூலி உண்டு. இது ஆயிஷா (ரழி) அவர்கள் சுவர்க்கத்திலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவியாகவே இருப்பார்கள் என்பதற்கான வாக்குறுதியாகும். இப்னு அபீ ஹாதீம் (ரஹ்) அவர்கள் கூறினார்கள்: ஆயிஷா (ரழி) அவர்கள் மரணத் தருவாயில் இருந்தபோது இப்னு அப்பாஸ் (ரழி) அவர்கள் அவர்களிடம் (செல்ல அனுமதி கேட்டு) வந்தார்கள். அவர், \"முஃமின்களின் அன்னையே! மகிழ்ச்சியடைவீராக! நீங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவியாவீர். உங்களைத் தவிர வேறு கன்னிப் பெண்ணை அவர்கள் மணக்கவில்லை. உங்களின் நிரபராதித் தன்மை வானிலிருந்து இறங்கியது\" என்று கூறினார்கள். அதற்கு ஆயிஷா (ரழி), \"இப்னு அப்பாஸே! என்னை (புகழ்வதை) விட்டுவிடுவீராக! அல்லாஹ்வின் மீதாணையாக! நான் மறக்கடிக்கப்பட்டவளாக இருந்திருக்க வேண்டும் என்றே விரும்புகிறேன்\" என்று கூறினார்கள்.<br />\r\n<br />","text":"மனிதகுலத்தின் சிறந்தவரை மணமுடித்ததால் ஆயிஷா (ரழி) அவர்களின் கண்ணியம்\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"தீய சொற்கள் தீய ஆண்களுக்கும், தீய ஆண்கள் தீய சொற்களுக்கும் உரியவர்கள்; நல்ல சொற்கள் நல்ல ஆண்களுக்கும், நல்ல ஆண்கள் நல்ல சொற்களுக்கும் உரியவர்கள். இது ஆயிஷா (ரழி) அவர்களையும், அவர்கள் மீது அவதூறு சுமத்தியவர்களையும் குறித்தே அருளப்பட்டது.\" இது போன்றே முஜாஹித், அதா, ஸயீத் பின் ஜுபைர், அஷ்-ஷஅபி, அல்-ஹஸன் பின் அபுல் ஹஸன் அல்-பஸரி, ஹபீப் பின் அபீ தாபித் மற்றும் அத்-தஹ்ஹாக் ஆகியோராலும் அறிவிக்கப்பட்டுள்ளது. மேலும், இதுவே இப்னு ஜரீர் அவர்களால் பெரிதும் விரும்பப்பட்ட கருத்தாகும். தீய பேச்சு தீயவர்களுக்கே மிகவும் பொருத்தமானது என்றும், நற்பேச்சு நல்லவர்களுக்கே மிகவும் பொருத்தமானது என்றும் இதற்கு அவர்கள் விளக்கம் அளித்தார்கள். நயவஞ்சகர்கள் ஆயிஷா (ரழி) அவர்கள் மீது சுமத்திய பழிச்சொற்கள் அவர்களுக்கே (நயவஞ்சகர்களுக்கே) மிகவும் பொருத்தமானதாகும். மேலும், அத்தகைய பழிச்சொற்களிலிருந்து விலகி இருப்பதற்கும், நிரபராதியாக இருப்பதற்கும் ஆயிஷா (ரழி) அவர்களே மிகவும் தகுதியானவர்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nأُولَئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ\n\r\n\n\r\n(அத்தகைய (நல்ல)வர்கள் அவர்கள் கூறும் (ஒவ்வொரு) தீய சொல்லிலிருந்தும் நீங்கியவர்கள்;)\n\r\n\n\r\nஅப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள் கூறினார்கள்: \"தீய பெண்கள் தீய ஆண்களுக்கும், தீய ஆண்கள் தீய பெண்களுக்கும் உரியவர்கள்; நல்ல பெண்கள் நல்ல ஆண்களுக்கும், நல்ல ஆண்கள் நல்ல பெண்களுக்கும் உரியவர்கள்.\" இதுவும் அவர்கள் கூறியதையே (நிரபராதித்தன்மையையே) உறுதிப்படுத்துகிறது. அதாவது, ஆயிஷா (ரழி) அவர்கள் மிகச் சிறந்தவராக இருந்த காரணத்தினாலேயே, அல்லாஹ் அவர்களைத் தனது தூதரின் மனைவியாக்கினான். ஏனெனில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மனிதகுலத்திலேயே மிகச் சிறந்தவர்களில் சிறந்தவர் ஆவார்கள். ஆயிஷா (ரழி) அவர்கள் தீயவராக இருந்திருந்தால், அல்லாஹ்வின் சட்டப்படியோ அல்லது அவனது விதியின்படியோ அவர்கள் தூதருக்குப் பொருத்தமான துணையாக இருந்திருக்க மாட்டார்கள். அல்லாஹ் கூறினான்:\n\r\n\n\r\nأُولَئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ\n\r\n\n\r\n(அத்தகையவர்கள் அவர்கள் கூறும் (ஒவ்வொரு) தீய சொல்லிலிருந்தும் நீங்கியவர்கள்;) அதாவது, அவதூறு பரப்புபவர்களும் பகைமை கொண்டவர்களும் கூறுகின்ற பழிச்சொற்களிலிருந்து இவர்கள் வெகு தொலைவில் இருக்கிறார்கள்.\n\r\n\n\r\nلَهُم مَّغْفِرَةٌ\n\r\n\n\r\n(அவர்களுக்கு மன்னிப்பு உண்டு,) அதாவது, அவர்கள் மீது சுமத்தப்பட்ட பொய்களின் காரணமாக (அவர்களுக்கு அல்லாஹ்விடம் மன்னிப்பு உண்டு),\n\r\n\n\r\nوَرِزْقٌ كَرِيمٌ\n\r\n\n\r\n(இன்னும் கண்ணியமான வாழ்வாதாரமும் உண்டு.) அதாவது, பேரின்பச் சோலைகளில் அல்லாஹ்விடம் அவர்களுக்கு நற்கூலி உண்டு. இது ஆயிஷா (ரழி) அவர்கள் சுவர்க்கத்திலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவியாகவே இருப்பார்கள் என்பதற்கான வாக்குறுதியாகும். இப்னு அபீ ஹாதீம் (ரஹ்) அவர்கள் கூறினார்கள்: ஆயிஷா (ரழி) அவர்கள் மரணத் தருவாயில் இருந்தபோது இப்னு அப்பாஸ் (ரழி) அவர்கள் அவர்களிடம் (செல்ல அனுமதி கேட்டு) வந்தார்கள். அவர், \"முஃமின்களின் அன்னையே! மகிழ்ச்சியடைவீராக! நீங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் மனைவியாவீர். உங்களைத் தவிர வேறு கன்னிப் பெண்ணை அவர்கள் மணக்கவில்லை. உங்களின் நிரபராதித் தன்மை வானிலிருந்து இறங்கியது\" என்று கூறினார்கள். அதற்கு ஆயிஷா (ரழி), \"இப்னு அப்பாஸே! என்னை (புகழ்வதை) விட்டுவிடுவீராக! அல்லாஹ்வின் மீதாணையாக! நான் மறக்கடிக்கப்பட்டவளாக இருந்திருக்க வேண்டும் என்றே விரும்புகிறேன்\" என்று கூறினார்கள்."},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=29\" class=\"link\">24:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:29 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=29\" class=\"link\">24:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:29 ஐ பார்க்கவும்"},"29":{"html":"<strong>அனுமதி கோருதலும் வீடுகளுக்குள் நுழையும் ஒழுக்கங்களும்</strong><br />\r\n<br />\r\nஇது இஸ்லாமிய ஒழுக்கமாகும். அல்லாஹ் தனது முஃமின்களான (நம்பிக்கையாளர்களான) அடியார்களுக்கு இந்த ஒழுக்கங்களைக் (அனுமதி கோருவதை) கற்றுக்கொடுத்தான். மேலும், அவர்கள் தங்களுடைய வீடுகள் அல்லாத பிற வீடுகளுக்குள் நுழைவதற்கு முன்னால் அனுமதி கேட்கும் வரையிலும், அனுமதி பெற்ற பின் அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரையிலும் நுழைய வேண்டாம் என்று கட்டளையிட்டான். ஒருவர் மூன்று முறை அனுமதி கேட்க வேண்டும்; அனுமதி வழங்கப்பட்டால் (அவர் நுழையலாம்), இல்லையெனில் அவர் திரும்பிச் சென்றுவிட வேண்டும்.<br />\r\n<br />\r\nஅபூ மூஸா (ரழி) அவர்கள் உமர் (ரழி) அவர்களிடம் வர மூன்று முறை அனுமதி கேட்டபோது, உமர் (ரழி) அவர்கள் அனுமதி வழங்காததால் அவர் திரும்பிச் சென்றுவிட்டார் என்று ஸஹீஹ் ஹதீஸில் பதிவாகியுள்ளது. பின்னர் உமர் (ரழி) அவர்கள், \"அப்துல்லாஹ் பின் கைஸ் அனுமதி கேட்பதைக் கேட்கவில்லையா? அவரை உள்ளே வரச் சொல்லுங்கள்\" என்று கூறினார்கள். அவரைத் தேடிப் பார்த்தபோது அவர் சென்றுவிட்டதைக் கண்டார்கள். பின்னர் அவர் வந்தபோது, உமர் (ரழி) அவர்கள், \"நீங்கள் ஏன் திரும்பிச் சென்றுவிட்டீர்கள்?\" என்று கேட்டார்கள். அதற்கு அவர், \"நான் மூன்று முறை அனுமதி கேட்டேன், எனக்கு அனுமதி வழங்கப்படவில்லை. 'உங்களில் எவராவது மூன்று முறை அனுமதி கேட்டும் அவருக்கு அனுமதி வழங்கப்படாவிட்டால், அவர் திரும்பிச் செல்லட்டும்' என்று நபி (ஸல்) அவர்கள் கூற நான் கேட்டிருக்கிறேன்\" என்று பதிலளித்தார்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَأْذَنَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثًا</span> <span class=\"quran-arabic-font text-success\">فَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْذَنْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">فَلْيَنْصَرِفْ</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் மூன்று முறை அனுமதி கேட்டும் அவருக்கு அனுமதி வழங்கப்படவில்லை என்றால், அவர் திரும்பிச் சென்றுவிடட்டும்.) இதைக் கேட்ட உமர் (ரழி) அவர்கள், \"இதற்கு நீர் நிச்சயமாக ஆதாரத்தைக் கொண்டு வர வேண்டும், இல்லையெனில் உம்மை தண்டிப்பேன்!\" என்று கூறினார்கள். எனவே, அபூ மூஸா (ரழி) அவர்கள் அன்ஸாரிகளின் ஒரு குழுவிடம் சென்று உமர் (ரழி) அவர்கள் கூறியதைத் தெரிவித்தார். அதற்கு அவர்கள், \"எங்களில் இளையவரைத் தவிர வேறு யாரும் இதற்காக சாட்சி சொல்ல வரமாட்டார்கள்\" என்று கூறினார்கள். அதன்படி அபூ ஸஈத் அல்-குத்ரீ (ரழி) அவர்கள் அவருடன் சென்று உமர் (ரழி) அவர்களிடம் அந்த ஹதீஸைக் கூறினார்கள். அப்போது உமர் (ரழி) அவர்கள், \"சந்தையில் நான் வியாபாரத்தில் மும்முரமாக இருந்ததே இதை நான் தெரிந்து கொள்வதற்குத் தடையாக இருந்தது\" என்று கூறினார்கள்.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் ஒரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள். அதில் அனஸ் (ரழி) அவர்கள் அல்லது வேறு யாரோ ஒருவர், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸஃத் பின் உபாதா (ரழி) அவர்களிடம் அனுமதி கேட்டதாகக் குறிப்பிட்டுள்ளனர். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">السَّلَامُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَةُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span>»<br />\r\n<br />\r\n(அஸ்ஸலாமு அலைக்க வ ரஹ்மத்துல்லாஹ்) அதற்கு ஸஃத் (ரழி) அவர்கள், \"வ அலைக்கஸ்ஸலாம் வ ரஹ்மத்துல்லாஹ்\" என்று பதிலளித்தார்கள். ஆனால் நபி (ஸல்) அவர்கள் மூன்று முறை ஸலாம் கூறும் வரை பதிலைக் கேட்கவில்லை. ஸஃத் (ரழி) அவர்களும் மூன்று முறை பதில் கூறினார்கள், ஆனால் நபி (ஸல்) அவர்களுக்குக் கேட்காதவாறு மெல்லிய குரலிலேயே பதில் கூறினார்கள். நபி (ஸல்) அவர்கள் திரும்பிச் சென்றபோது, ஸஃத் (ரழி) அவர்கள் அவர்களைப் பின்தொடர்ந்து ஓடிவந்து, \"அல்லாஹ்வின் தூதரே! என் தந்தையும் தாயும் உங்களுக்கு அர்ப்பணமாகட்டும்! நீங்கள் ஸலாம் கூறிய போதெல்லாம் நான் பதில் கூறினேன், ஆனால் உங்களுக்குக் கேட்காதவாறு மெதுவாகக் கூறினேன். உங்களுடைய ஸலாமையும் பரக்கத்தையும் அதிகமாகப் பெறவே நான் அப்படிச் செய்தேன்\" என்று கூறினார்கள். பின்னர் அவர் நபி (ஸல்) அவர்களைத் தன் வீட்டிற்குள் அழைத்துச் சென்று, உலர்ந்த திராட்சைகளை வழங்கினார்கள். நபி (ஸல்) அவர்கள் அதை உண்ட பின் இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَكَلَ</span> <span class=\"quran-arabic-font text-success\">طَعَامَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَبْرَارُ،</span> <span class=\"quran-arabic-font text-success\">وَصَلَّتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ،</span> <span class=\"quran-arabic-font text-success\">وَأَفْطَرَ</span> <span class=\"quran-arabic-font text-success\">عِنْدَكُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّائِمُونَ</span>»<br />\r\n<br />\r\n(நல்லோர்கள் உங்கள் உணவை உண்ணட்டும், மலக்குகள் உங்கள் மீது அருள்பொழியட்டும், நோன்பாளிகள் உங்களிடம் நோன்பு திறக்கட்டும்.)<br />\r\n<br />\r\nமேலும், அனுமதி கேட்பவர் வாசலுக்கு நேராக நிற்கக் கூடாது என்பதையும் ஒருவர் அறிந்திருக்க வேண்டும். அவர் வாசலுக்கு வலதுபுறத்திலோ அல்லது இடதுபுறத்திலோ தள்ளி நிற்க வேண்டும். அபூ தாவூத் பதிவு செய்துள்ள ஹதீஸில் அப்துல்லாஹ் பின் புஸ்ர் (ரழி) அவர்கள் கூறுகிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒருவரது வாசலுக்கு வரும்போது, அதற்கு நேராக நிற்க மாட்டார்கள். மாறாக, வலது அல்லது இடது பக்கமாகத் தள்ளி நின்று:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">السَّلَامُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ،</span> <span class=\"quran-arabic-font text-success\">السَّلَامُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span>»<br />\r\n<br />\r\n(அஸ்ஸலாமு அலைக்கும், அஸ்ஸலாமு அலைக்கும்) என்று கூறுவார்கள். ஏனெனில், அக்காலத்தில் வீடுகளின் வாசலில் திரைகளோ மறைப்புகளோ இருக்கவில்லை.\" இந்தச் செய்தியை அபூ தாவூத் மட்டுமே பதிவு செய்துள்ளார். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">امْرَءًا</span> <span class=\"quran-arabic-font text-success\">اطَّلَعَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">إِذْنٍ</span> <span class=\"quran-arabic-font text-success\">فَخَذَفْتَهُ</span> <span class=\"quran-arabic-font text-success\">بِحَصَاةٍ</span> <span class=\"quran-arabic-font text-success\">فَفَقَأْتَ</span> <span class=\"quran-arabic-font text-success\">عَيْنَهُ،</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٍ</span>»<br />\r\n<br />\r\n(ஒருவர் உங்கள் அனுமதியின்றி உங்கள் வீட்டிற்குள் எட்டிப் பார்த்தால், நீங்கள் ஒரு சிறு கல்லை அவர் மீது எறிந்து அதனால் அவரது கண் பாதிக்கப்பட்டுவிட்டாலும், உங்கள் மீது எந்தக் குற்றமும் இல்லை.) மேலும் நபி (ஸல்) அவர்கள் கூறினார்கள்: \"பார்வையின் (பாதுகாப்பின்) காரணமாகவே அனுமதி கோருவது கடமையாக்கப்பட்டுள்ளது.\"<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">جُعِلَ</span> <span class=\"quran-arabic-font text-success\">الِاسْتِئْذَانُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْلِ</span> <span class=\"quran-arabic-font text-success\">الْبَصَرِ</span>»<br />\r\n<br />\r\nஜாபிர் (ரழி) அவர்கள் கூறியதாக 'அல்-ஜமாஆ' (முக்கிய ஹதீஸ் தொகுப்பாளர்கள்) பதிவு செய்துள்ளதாவது: \"என் தந்தை வாங்கியிருந்த கடன் சம்பந்தமாக நான் நபி (ஸல்) அவர்களிடம் வந்து கதவைத் தட்டினேன். அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">ذَا؟</span>»<br />\r\n<br />\r\n(யார் அது?) என்று கேட்டார்கள். அதற்கு நான், \"நான் தான்!\" என்று கூறினேன். அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">أَنَا</span>»<br />\r\n<br />\r\n(நான் நான்) என அதை அவர்கள் வெறுப்பதைப் போன்ற தொனியில் கூறினார்கள்.\" அவர்கள் அதை விரும்பவில்லை, ஏனெனில் \"நான்\" என்ற வார்த்தை யார் பேசுகிறார் என்பதைத் தெளிவாகக் காட்டாது. தனது பெயரையோ அல்லது தான் அறியப்பட்ட புனைப்பெயரையோ கூறினால் ஒழிய, யார் வேண்டுமானாலும் தன்னை \"நான்\" என்று சொல்லிக் கொள்ளலாம். இது அனுமதி கோருவதன் நோக்கத்தையே சிதைத்துவிடும். அனுமதி கோருவதன் நோக்கமே, குர்ஆன் வசனத்தில் கூறப்பட்டுள்ளபடி, வீட்டிற்குள் இருப்பவர்களை நிம்மதியாக உணரச் செய்வதுதான். அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"மக்களை நிம்மதியாக இருக்கச் செய்வது என்பது உள்ளே நுழைய அனுமதி கேட்பதேயாகும்.\" இதுவே மற்ற அறிஞர்களின் கருத்தாகவும் உள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் கலதா பின் அல்-ஹன்பல் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: மக்கா வெற்றியின் போது, நபி (ஸல்) அவர்கள் பள்ளத்தாக்கின் ஒரு பகுதியில் இருந்தபோது, ஸஃப்வான் பின் உமய்யா (ரழி) அவர்கள் பால், ஒரு சிறிய மான்குட்டி மற்றும் சில வெள்ளரிக்காய்களை நபி (ஸல்) அவர்களிடம் கொடுத்து அனுப்பினார்கள். அவர் கூறுகிறார், \"நான் நபி (ஸல்) அவர்களிடம் சென்றபோது ஸலாம் கூறவுமில்லை, அனுமதி கேட்கவுமில்லை. அப்போது நபி (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ارْجِعْ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span>: <span class=\"quran-arabic-font text-success\">السَّلَامُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">أَأَدْخُلُ؟</span>»<br />\r\n<br />\r\n(திரும்பிச் சென்று, \"அஸ்ஸலாமு அலைக்கும், நான் உள்ளே வரலாமா?\" என்று சொல்) எனக் கூறினார்கள். இது ஸஃப்வான் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்ற பிறகு நடந்த நிகழ்வாகும்.\" இது அபூ தாவூத், அத்-திர்மிதீ மற்றும் அந்-நஸாஈ ஆகிய நூல்களிலும் பதிவாகியுள்ளது. அத்-திர்மிதீ இதை \"ஹஸன் ஃகரீப்\" என்று குறிப்பிட்டுள்ளார்.<br />\r\n<br />\r\nஇப்னு ஜுரைஜ் அவர்கள் அதாஃ பின் அபீ ரபாஹ் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"மூன்று வசனங்கள் உள்ளன, அவற்றின் சட்டங்களை மக்கள் புறக்கணிக்கிறார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْرَمَكُمْ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">أَتْقَاكُمْ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ்விடம் உங்களில் மிக கண்ணியமானவர், உங்களில் அதிக தக்வா (இறையச்சம்) உடையவரே ஆவார்) <a href=\"qurandisp.php?sura=49&ayah=13\" class=\"link\">49:13</a>. ஆனால் மக்களோ இப்போது, அல்லாஹ்விடம் மிகக் கண்ணியமானவர் பெரிய வீடு வைத்திருப்பவர்தான் என்று கூறுகிறார்கள். அனுமதி பெறுவதைப் பொறுத்தவரையில், மக்கள் அதை முற்றிலுமாக மறந்துவிட்டார்கள்.\" நான் அவரிடம் கேட்டேன், \"என்னுடன் ஒரே வீட்டில் தங்கியிருக்கும் எனது அனாதை சகோதரிகளிடம் நுழையவும் நான் அனுமதி கேட்க வேண்டுமா?\" என்று. அதற்கு அவர், \"ஆம்\" என்றார். நான் அவரிடம் சலுகை கோரியபோது, அவர் அதை மறுத்து, \"அவர்களை நீ ஆடையின்றிப் பார்க்க விரும்புகிறாயா?\" என்று கேட்டார். நான் \"இல்லை\" என்றேன். அவர், \"அப்படியானால் அனுமதி கேள்\" என்றார். நான் மீண்டும் கேட்க, அவர், \"நீ அல்லாஹ்வுக்குக் கீழ்ப்படிய விரும்புகிறாயா?\" என்று கேட்டார். நான் \"ஆம்\" என்றேன். அவர், \"அப்படியானால் அனுமதி கேள்\" என்றார்.<br />\r\n<br />\r\nஇப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்கள்: இப்னு தாவூஸ் அவர்கள் என்னிடம் கூறினார்கள், அவரது தந்தை, \"எனது மஹ்ரம்களை (திருமணம் செய்யத் தகாத நெருங்கிய பெண் உறவினர்களை) ஆடையின்றிப் பார்ப்பதை விட நான் வெறுக்கும் விஷயம் வேறில்லை\" என்று கூறுவார்கள். அவர் இந்த விஷயத்தில் மிகக் கண்டிப்பானவராக இருந்தார். இப்னு ஜுரைஜ் மேலும் கூறுகையில், அஸ்-ஸுஹ்ரீ அவர்கள் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறியதாக, \"உங்கள் தாய்மார்களிடம் செல்லும்போது கூட நீங்கள் அனுமதி கேட்க வேண்டும்\" என்று ஹுதைல் பின் ஷுரஹ்பீல் அவர்கள் சொல்லக் கேட்டதாக அறிவிக்கிறார்கள். இப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்: நான் அதாஃவிடம், \"ஒருவர் தன் மனைவியிடம் செல்லவும் அனுமதி கேட்க வேண்டுமா?\" என்று கேட்டேன். அவர், \"இல்லை, அது கட்டாயமில்லை. இருப்பினும் அவர் வருவதை அவளுக்குத் தெரியப்படுத்துவது சிறந்தது. அவள் தன்னை அவர் பார்ப்பதை விரும்பாத ஒரு நிலையில் இருக்கலாம் என்பதால், அவளைத் திடுக்கிடச் செய்யாமல் இருப்பது நல்லது\" என்றார்.<br />\r\n<br />\r\nஅபூ ஜஃபர் பின் ஜரீர் அவர்கள், இப்னு மஸ்ஊத் (ரழி) அவர்களின் மனைவியான ஸைனப் (ரழி) அவர்களின் சகோதரி மகனிடமிருந்து அறிவிக்கிறார்கள்: ஸைனப் (ரழி) அவர்கள் கூறினார்கள், \"அப்துல்லாஹ் (ரழி) அவர்கள் ஏதேனும் வேலையை முடித்துவிட்டு வீடு திரும்பினால், வாசலை அடைந்ததும் கனைப்பார்கள் அல்லது துப்புவார்கள். நாங்கள் ஏதேனும் ஒரு நிலையில் இருப்பதை அவர் திடீரெனப் பார்த்துவிடக் கூடாது என்பதற்காகவே அப்படிச் செய்வார்கள்.\" இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِكُمْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَسْتَأْنِسُواْ</span> <span class=\"quran-arabic-font text-success\">وَتُسَلِّمُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِهَا</span><br />\r\n<br />\r\n(முஃமின்களே! உங்கள் வீடுகள் அல்லாத பிற வீடுகளில், நீங்கள் அனுமதி கேட்டு அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரை நுழையாதீர்கள்.)<br />\r\n<br />\r\nமுகாதில் பின் ஹய்யான் கூறுகிறார்: \"ஜாஹிலிய்யா (அறியாமைக் காலம்) காலத்தில் ஒருவன் தன் நண்பனைச் சந்தித்தால் ஸலாம் கூற மாட்டான். மாறாக 'ஹுய்யித ஸபாஹன்' (காலை வணக்கம்) அல்லது 'ஹுய்யித மஸாஅன்' (மாலை வணக்கம்) என்றே கூறுவான். அதுதான் அன்றைய மக்களின் வாழ்த்தாக இருந்தது. மேலும் அவர்கள் பிறர் வீடுகளுக்குள் நுழைய அனுமதி கேட்க மாட்டார்கள். ஒருவன் நேராக உள்ளே நுழைந்து 'நான் வந்துவிட்டேன்' என்று கூறிவிடுவான். இது ஒரு மனிதருக்கு மிகுந்த சங்கடத்தை அளிக்கும், ஏனெனில் அவர் தன் மனைவியுடன் இருக்கலாம். எனவே அல்லாஹ் திரையிடுதல் மற்றும் கற்புநெறியைப் பேணுவதை வலியுறுத்தி, இச்செயல்களைத் தூய்மையானதாக ஆக்கி, ஜாஹிலிய்யா முறையை மாற்றினான். எனவேதான் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِكُمْ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَسْتَأْنِسُواْ</span> <span class=\"quran-arabic-font text-success\">وَتُسَلِّمُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَهْلِهَا</span><br />\r\n<br />\r\n(முஃமின்களே! உங்கள் வீடுகள் அல்லாத பிற வீடுகளில், நீங்கள் அனுமதி கேட்டு அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரை நுழையாதீர்கள்...) முகாதில் அவர்களின் இந்தக் கருத்து மிகச் சிறந்தது. அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذَلِكُمْ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n(அதுவே உங்களுக்கு மிகச் சிறந்தது,) அதாவது, அனுமதி பெற்று நுழைவது இரு தரப்பினருக்கும், அதாவது அனுமதி கேட்பவருக்கும், வீட்டிற்குள் இருப்பவர்களுக்கும் சிறந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span><br />\r\n<br />\r\n(இதைக் கொண்டு நீங்கள் படிப்பினை பெறுவதற்காக.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَجِدُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">أَحَداً</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُوهَا</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُؤْذَنَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span><br />\r\n<br />\r\n(அங்கே நீங்கள் எவரையும் காணாவிட்டால், உங்களுக்கு அனுமதி வழங்கப்படும் வரை அங்கு நுழையாதீர்கள்.) இது பிறருடைய உடமைகளை அவர்களின் அனுமதியின்றிப் பயன்படுத்துவது தொடர்பான சட்டமாகும். வீட்டின் உரிமையாளர் விரும்பினால் அனுமதி அளிக்கலாம், இல்லையெனில் மறுக்கலாம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">ارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">فَارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَزْكَى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span><br />\r\n<br />\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது.) அதாவது, அனுமதி கேட்கும் முன்போ அல்லது பின்போ நீங்கள் வாசலிலிருந்து திருப்பி அனுப்பப்பட்டால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَزْكَى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span><br />\r\n<br />\r\n(திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது.) அதாவது, அடம் பிடிக்காமல் திரும்பிச் செல்வது உங்களுக்குத் தூய்மையானதும் சிறந்ததும் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.) கத்தாதா அவர்கள் கூறுகிறார்கள், முஹாஜிர்களில் ஒருவர் கூறினார்: \"எனது வாழ்நாள் முழுவதும் இந்த வசனத்தின்படி நடக்க நான் முயற்சி செய்தேன். ஆனால், எனது சகோதரர் ஒருவரிடம் நான் அனுமதி கேட்டபோது அவர் என்னை 'திரும்பிப் போ' என்று சொல்லவில்லை. அப்படி அவர் சொல்லியிருந்தால் நான் மகிழ்ச்சியோடு திரும்பியிருப்பேன். ஏனெனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">ارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">فَارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَزْكَى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது. மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.)\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">ارْجِعُواْ</span> <span class=\"quran-arabic-font text-success\">فَارْجِعُواْ</span><br />\r\n<br />\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்...) இது குறித்து ஸஈத் பின் ஜுபைர் கூறும்போது, \"இதன் பொருள், மற்றவர்களின் கதவு வாசல்களில் (அனுமதி மறுக்கப்பட்ட பிறகும்) காத்து நிற்காதீர்கள் என்பதாகும்\" என்கிறார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَسْكُونَةٍ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَتَاعٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n(யாரும் குடியிருக்காத, (ஆனால்) உங்களுக்குப் பயன் அளிக்கக்கூடிய வீடுகளில் நீங்கள் நுழைவது உங்கள் மீது குற்றமில்லை.) இந்த வசனம் முந்தைய வசனத்தை விட சற்று விரிவானது. ஏனெனில், ஒரு குறிப்பிட்ட தேவைக்காக ஆள் இல்லாத வீடுகளுக்குள் நுழைவது அனுமதிக்கப்பட்டுள்ளது என்று இது கூறுகிறது. விருந்தினர்களுக்காக ஒதுக்கப்பட்ட வீடுகள் போன்றவை இதற்கு உதாரணம்; அங்கு தங்குவதற்கு ஒருமுறை அனுமதி பெற்றாலே போதுமானது.<br />\r\n<br />\r\nஇப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِكُمْ</span><br />\r\n<br />\r\n(உங்கள் வீடுகள் அல்லாத மற்ற வீடுகளில் நுழையாதீர்கள்,) என்ற வசனம் பொதுவானது. பின்னர் இதில் ஒரு விதிவிலக்கு அளிக்கப்பட்டு பின்வரும் வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَدْخُلُواْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مَسْكُونَةٍ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَتَاعٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تُبْدُونَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَكْتُمُونَ</span><br />\r\n<br />\r\n(எந்த வீடுகளில் யாரும் குடியிருக்கவில்லையோ, அங்கு உங்களுக்கு ஏதேனும் தேவை இருக்குமானால், அத்தகைய வீடுகளில் நீங்கள் நுழைவது உங்கள் மீது குற்றமில்லை. மேலும், நீங்கள் வெளிப்படுத்துவதையும் நீங்கள் மறைப்பதையும் அல்லாஹ் அறிவான்.) இதே போன்ற கருத்து இக்ரிமா மற்றும் அல்-ஹஸன் அல்-பஸரீ ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது.<br />\r\n<br />\r\n<br />\r\n<br />","text":"அனுமதி கோருதலும் வீடுகளுக்குள் நுழையும் ஒழுக்கங்களும்\n\r\n\n\r\nஇது இஸ்லாமிய ஒழுக்கமாகும். அல்லாஹ் தனது முஃமின்களான (நம்பிக்கையாளர்களான) அடியார்களுக்கு இந்த ஒழுக்கங்களைக் (அனுமதி கோருவதை) கற்றுக்கொடுத்தான். மேலும், அவர்கள் தங்களுடைய வீடுகள் அல்லாத பிற வீடுகளுக்குள் நுழைவதற்கு முன்னால் அனுமதி கேட்கும் வரையிலும், அனுமதி பெற்ற பின் அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரையிலும் நுழைய வேண்டாம் என்று கட்டளையிட்டான். ஒருவர் மூன்று முறை அனுமதி கேட்க வேண்டும்; அனுமதி வழங்கப்பட்டால் (அவர் நுழையலாம்), இல்லையெனில் அவர் திரும்பிச் சென்றுவிட வேண்டும்.\n\r\n\n\r\nஅபூ மூஸா (ரழி) அவர்கள் உமர் (ரழி) அவர்களிடம் வர மூன்று முறை அனுமதி கேட்டபோது, உமர் (ரழி) அவர்கள் அனுமதி வழங்காததால் அவர் திரும்பிச் சென்றுவிட்டார் என்று ஸஹீஹ் ஹதீஸில் பதிவாகியுள்ளது. பின்னர் உமர் (ரழி) அவர்கள், \"அப்துல்லாஹ் பின் கைஸ் அனுமதி கேட்பதைக் கேட்கவில்லையா? அவரை உள்ளே வரச் சொல்லுங்கள்\" என்று கூறினார்கள். அவரைத் தேடிப் பார்த்தபோது அவர் சென்றுவிட்டதைக் கண்டார்கள். பின்னர் அவர் வந்தபோது, உமர் (ரழி) அவர்கள், \"நீங்கள் ஏன் திரும்பிச் சென்றுவிட்டீர்கள்?\" என்று கேட்டார்கள். அதற்கு அவர், \"நான் மூன்று முறை அனுமதி கேட்டேன், எனக்கு அனுமதி வழங்கப்படவில்லை. 'உங்களில் எவராவது மூன்று முறை அனுமதி கேட்டும் அவருக்கு அனுமதி வழங்கப்படாவிட்டால், அவர் திரும்பிச் செல்லட்டும்' என்று நபி (ஸல்) அவர்கள் கூற நான் கேட்டிருக்கிறேன்\" என்று பதிலளித்தார்:\n\r\n\n\r\n«إِذَا اسْتَأْذَنَ أَحَدُكُمْ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَنْصَرِفْ»\n\r\n\n\r\n(உங்களில் ஒருவர் மூன்று முறை அனுமதி கேட்டும் அவருக்கு அனுமதி வழங்கப்படவில்லை என்றால், அவர் திரும்பிச் சென்றுவிடட்டும்.) இதைக் கேட்ட உமர் (ரழி) அவர்கள், \"இதற்கு நீர் நிச்சயமாக ஆதாரத்தைக் கொண்டு வர வேண்டும், இல்லையெனில் உம்மை தண்டிப்பேன்!\" என்று கூறினார்கள். எனவே, அபூ மூஸா (ரழி) அவர்கள் அன்ஸாரிகளின் ஒரு குழுவிடம் சென்று உமர் (ரழி) அவர்கள் கூறியதைத் தெரிவித்தார். அதற்கு அவர்கள், \"எங்களில் இளையவரைத் தவிர வேறு யாரும் இதற்காக சாட்சி சொல்ல வரமாட்டார்கள்\" என்று கூறினார்கள். அதன்படி அபூ ஸஈத் அல்-குத்ரீ (ரழி) அவர்கள் அவருடன் சென்று உமர் (ரழி) அவர்களிடம் அந்த ஹதீஸைக் கூறினார்கள். அப்போது உமர் (ரழி) அவர்கள், \"சந்தையில் நான் வியாபாரத்தில் மும்முரமாக இருந்ததே இதை நான் தெரிந்து கொள்வதற்குத் தடையாக இருந்தது\" என்று கூறினார்கள்.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் ஒரு அறிவிப்பைப் பதிவு செய்துள்ளார்கள். அதில் அனஸ் (ரழி) அவர்கள் அல்லது வேறு யாரோ ஒருவர், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஸஃத் பின் உபாதா (ரழி) அவர்களிடம் அனுமதி கேட்டதாகக் குறிப்பிட்டுள்ளனர். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«السَّلَامُ عَلَيْكَ وَرَحْمَةُ اللهِ»\n\r\n\n\r\n(அஸ்ஸலாமு அலைக்க வ ரஹ்மத்துல்லாஹ்) அதற்கு ஸஃத் (ரழி) அவர்கள், \"வ அலைக்கஸ்ஸலாம் வ ரஹ்மத்துல்லாஹ்\" என்று பதிலளித்தார்கள். ஆனால் நபி (ஸல்) அவர்கள் மூன்று முறை ஸலாம் கூறும் வரை பதிலைக் கேட்கவில்லை. ஸஃத் (ரழி) அவர்களும் மூன்று முறை பதில் கூறினார்கள், ஆனால் நபி (ஸல்) அவர்களுக்குக் கேட்காதவாறு மெல்லிய குரலிலேயே பதில் கூறினார்கள். நபி (ஸல்) அவர்கள் திரும்பிச் சென்றபோது, ஸஃத் (ரழி) அவர்கள் அவர்களைப் பின்தொடர்ந்து ஓடிவந்து, \"அல்லாஹ்வின் தூதரே! என் தந்தையும் தாயும் உங்களுக்கு அர்ப்பணமாகட்டும்! நீங்கள் ஸலாம் கூறிய போதெல்லாம் நான் பதில் கூறினேன், ஆனால் உங்களுக்குக் கேட்காதவாறு மெதுவாகக் கூறினேன். உங்களுடைய ஸலாமையும் பரக்கத்தையும் அதிகமாகப் பெறவே நான் அப்படிச் செய்தேன்\" என்று கூறினார்கள். பின்னர் அவர் நபி (ஸல்) அவர்களைத் தன் வீட்டிற்குள் அழைத்துச் சென்று, உலர்ந்த திராட்சைகளை வழங்கினார்கள். நபி (ஸல்) அவர்கள் அதை உண்ட பின் இவ்வாறு கூறினார்கள்:\n\r\n\n\r\n«أَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ، وَأَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ»\n\r\n\n\r\n(நல்லோர்கள் உங்கள் உணவை உண்ணட்டும், மலக்குகள் உங்கள் மீது அருள்பொழியட்டும், நோன்பாளிகள் உங்களிடம் நோன்பு திறக்கட்டும்.)\n\r\n\n\r\nமேலும், அனுமதி கேட்பவர் வாசலுக்கு நேராக நிற்கக் கூடாது என்பதையும் ஒருவர் அறிந்திருக்க வேண்டும். அவர் வாசலுக்கு வலதுபுறத்திலோ அல்லது இடதுபுறத்திலோ தள்ளி நிற்க வேண்டும். அபூ தாவூத் பதிவு செய்துள்ள ஹதீஸில் அப்துல்லாஹ் பின் புஸ்ர் (ரழி) அவர்கள் கூறுகிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒருவரது வாசலுக்கு வரும்போது, அதற்கு நேராக நிற்க மாட்டார்கள். மாறாக, வலது அல்லது இடது பக்கமாகத் தள்ளி நின்று:\n\r\n\n\r\n«السَّلَامُ عَلَيْكُمْ، السَّلَامُ عَلَيْكُمْ»\n\r\n\n\r\n(அஸ்ஸலாமு அலைக்கும், அஸ்ஸலாமு அலைக்கும்) என்று கூறுவார்கள். ஏனெனில், அக்காலத்தில் வீடுகளின் வாசலில் திரைகளோ மறைப்புகளோ இருக்கவில்லை.\" இந்தச் செய்தியை அபூ தாவூத் மட்டுமே பதிவு செய்துள்ளார். புகாரி மற்றும் முஸ்லிம் ஆகிய இரு ஸஹீஹ் நூல்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவாகியுள்ளது:\n\r\n\n\r\n«لَوْ أَنَّ امْرَءًا اطَّلَعَ عَلَيْكَ بِغَيْرِ إِذْنٍ فَخَذَفْتَهُ بِحَصَاةٍ فَفَقَأْتَ عَيْنَهُ، مَا كَانَ عَلَيْكَ مِنْ جُنَاحٍ»\n\r\n\n\r\n(ஒருவர் உங்கள் அனுமதியின்றி உங்கள் வீட்டிற்குள் எட்டிப் பார்த்தால், நீங்கள் ஒரு சிறு கல்லை அவர் மீது எறிந்து அதனால் அவரது கண் பாதிக்கப்பட்டுவிட்டாலும், உங்கள் மீது எந்தக் குற்றமும் இல்லை.) மேலும் நபி (ஸல்) அவர்கள் கூறினார்கள்: \"பார்வையின் (பாதுகாப்பின்) காரணமாகவே அனுமதி கோருவது கடமையாக்கப்பட்டுள்ளது.\"\n\r\n\n\r\n«إِنَّمَا جُعِلَ الِاسْتِئْذَانُ مِنْ أَجْلِ الْبَصَرِ»\n\r\n\n\r\nஜாபிர் (ரழி) அவர்கள் கூறியதாக 'அல்-ஜமாஆ' (முக்கிய ஹதீஸ் தொகுப்பாளர்கள்) பதிவு செய்துள்ளதாவது: \"என் தந்தை வாங்கியிருந்த கடன் சம்பந்தமாக நான் நபி (ஸல்) அவர்களிடம் வந்து கதவைத் தட்டினேன். அவர்கள்:\n\r\n\n\r\n«مَنْ ذَا؟»\n\r\n\n\r\n(யார் அது?) என்று கேட்டார்கள். அதற்கு நான், \"நான் தான்!\" என்று கூறினேன். அவர்கள்:\n\r\n\n\r\n«أَنَا أَنَا»\n\r\n\n\r\n(நான் நான்) என அதை அவர்கள் வெறுப்பதைப் போன்ற தொனியில் கூறினார்கள்.\" அவர்கள் அதை விரும்பவில்லை, ஏனெனில் \"நான்\" என்ற வார்த்தை யார் பேசுகிறார் என்பதைத் தெளிவாகக் காட்டாது. தனது பெயரையோ அல்லது தான் அறியப்பட்ட புனைப்பெயரையோ கூறினால் ஒழிய, யார் வேண்டுமானாலும் தன்னை \"நான்\" என்று சொல்லிக் கொள்ளலாம். இது அனுமதி கோருவதன் நோக்கத்தையே சிதைத்துவிடும். அனுமதி கோருவதன் நோக்கமே, குர்ஆன் வசனத்தில் கூறப்பட்டுள்ளபடி, வீட்டிற்குள் இருப்பவர்களை நிம்மதியாக உணரச் செய்வதுதான். அல்-அவ்ஃபீ அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"மக்களை நிம்மதியாக இருக்கச் செய்வது என்பது உள்ளே நுழைய அனுமதி கேட்பதேயாகும்.\" இதுவே மற்ற அறிஞர்களின் கருத்தாகவும் உள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் கலதா பின் அல்-ஹன்பல் (ரழி) அவர்களிடமிருந்து பதிவு செய்துள்ளார்கள்: மக்கா வெற்றியின் போது, நபி (ஸல்) அவர்கள் பள்ளத்தாக்கின் ஒரு பகுதியில் இருந்தபோது, ஸஃப்வான் பின் உமய்யா (ரழி) அவர்கள் பால், ஒரு சிறிய மான்குட்டி மற்றும் சில வெள்ளரிக்காய்களை நபி (ஸல்) அவர்களிடம் கொடுத்து அனுப்பினார்கள். அவர் கூறுகிறார், \"நான் நபி (ஸல்) அவர்களிடம் சென்றபோது ஸலாம் கூறவுமில்லை, அனுமதி கேட்கவுமில்லை. அப்போது நபி (ஸல்) அவர்கள்:\n\r\n\n\r\n«ارْجِعْ فَقُلْ: السَّلَامُ عَلَيْكُمْ أَأَدْخُلُ؟»\n\r\n\n\r\n(திரும்பிச் சென்று, \"அஸ்ஸலாமு அலைக்கும், நான் உள்ளே வரலாமா?\" என்று சொல்) எனக் கூறினார்கள். இது ஸஃப்வான் (ரழி) அவர்கள் இஸ்லாத்தை ஏற்ற பிறகு நடந்த நிகழ்வாகும்.\" இது அபூ தாவூத், அத்-திர்மிதீ மற்றும் அந்-நஸாஈ ஆகிய நூல்களிலும் பதிவாகியுள்ளது. அத்-திர்மிதீ இதை \"ஹஸன் ஃகரீப்\" என்று குறிப்பிட்டுள்ளார்.\n\r\n\n\r\nஇப்னு ஜுரைஜ் அவர்கள் அதாஃ பின் அபீ ரபாஹ் வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: \"மூன்று வசனங்கள் உள்ளன, அவற்றின் சட்டங்களை மக்கள் புறக்கணிக்கிறார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ்விடம் உங்களில் மிக கண்ணியமானவர், உங்களில் அதிக தக்வா (இறையச்சம்) உடையவரே ஆவார்) 49:13. ஆனால் மக்களோ இப்போது, அல்லாஹ்விடம் மிகக் கண்ணியமானவர் பெரிய வீடு வைத்திருப்பவர்தான் என்று கூறுகிறார்கள். அனுமதி பெறுவதைப் பொறுத்தவரையில், மக்கள் அதை முற்றிலுமாக மறந்துவிட்டார்கள்.\" நான் அவரிடம் கேட்டேன், \"என்னுடன் ஒரே வீட்டில் தங்கியிருக்கும் எனது அனாதை சகோதரிகளிடம் நுழையவும் நான் அனுமதி கேட்க வேண்டுமா?\" என்று. அதற்கு அவர், \"ஆம்\" என்றார். நான் அவரிடம் சலுகை கோரியபோது, அவர் அதை மறுத்து, \"அவர்களை நீ ஆடையின்றிப் பார்க்க விரும்புகிறாயா?\" என்று கேட்டார். நான் \"இல்லை\" என்றேன். அவர், \"அப்படியானால் அனுமதி கேள்\" என்றார். நான் மீண்டும் கேட்க, அவர், \"நீ அல்லாஹ்வுக்குக் கீழ்ப்படிய விரும்புகிறாயா?\" என்று கேட்டார். நான் \"ஆம்\" என்றேன். அவர், \"அப்படியானால் அனுமதி கேள்\" என்றார்.\n\r\n\n\r\nஇப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்கள்: இப்னு தாவூஸ் அவர்கள் என்னிடம் கூறினார்கள், அவரது தந்தை, \"எனது மஹ்ரம்களை (திருமணம் செய்யத் தகாத நெருங்கிய பெண் உறவினர்களை) ஆடையின்றிப் பார்ப்பதை விட நான் வெறுக்கும் விஷயம் வேறில்லை\" என்று கூறுவார்கள். அவர் இந்த விஷயத்தில் மிகக் கண்டிப்பானவராக இருந்தார். இப்னு ஜுரைஜ் மேலும் கூறுகையில், அஸ்-ஸுஹ்ரீ அவர்கள் இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறியதாக, \"உங்கள் தாய்மார்களிடம் செல்லும்போது கூட நீங்கள் அனுமதி கேட்க வேண்டும்\" என்று ஹுதைல் பின் ஷுரஹ்பீல் அவர்கள் சொல்லக் கேட்டதாக அறிவிக்கிறார்கள். இப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்: நான் அதாஃவிடம், \"ஒருவர் தன் மனைவியிடம் செல்லவும் அனுமதி கேட்க வேண்டுமா?\" என்று கேட்டேன். அவர், \"இல்லை, அது கட்டாயமில்லை. இருப்பினும் அவர் வருவதை அவளுக்குத் தெரியப்படுத்துவது சிறந்தது. அவள் தன்னை அவர் பார்ப்பதை விரும்பாத ஒரு நிலையில் இருக்கலாம் என்பதால், அவளைத் திடுக்கிடச் செய்யாமல் இருப்பது நல்லது\" என்றார்.\n\r\n\n\r\nஅபூ ஜஃபர் பின் ஜரீர் அவர்கள், இப்னு மஸ்ஊத் (ரழி) அவர்களின் மனைவியான ஸைனப் (ரழி) அவர்களின் சகோதரி மகனிடமிருந்து அறிவிக்கிறார்கள்: ஸைனப் (ரழி) அவர்கள் கூறினார்கள், \"அப்துல்லாஹ் (ரழி) அவர்கள் ஏதேனும் வேலையை முடித்துவிட்டு வீடு திரும்பினால், வாசலை அடைந்ததும் கனைப்பார்கள் அல்லது துப்புவார்கள். நாங்கள் ஏதேனும் ஒரு நிலையில் இருப்பதை அவர் திடீரெனப் பார்த்துவிடக் கூடாது என்பதற்காகவே அப்படிச் செய்வார்கள்.\" இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும்.\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تَدْخُلُواْ بُيُوتاً غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُواْ وَتُسَلِّمُواْ عَلَى أَهْلِهَا\n\r\n\n\r\n(முஃமின்களே! உங்கள் வீடுகள் அல்லாத பிற வீடுகளில், நீங்கள் அனுமதி கேட்டு அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரை நுழையாதீர்கள்.)\n\r\n\n\r\nமுகாதில் பின் ஹய்யான் கூறுகிறார்: \"ஜாஹிலிய்யா (அறியாமைக் காலம்) காலத்தில் ஒருவன் தன் நண்பனைச் சந்தித்தால் ஸலாம் கூற மாட்டான். மாறாக 'ஹுய்யித ஸபாஹன்' (காலை வணக்கம்) அல்லது 'ஹுய்யித மஸாஅன்' (மாலை வணக்கம்) என்றே கூறுவான். அதுதான் அன்றைய மக்களின் வாழ்த்தாக இருந்தது. மேலும் அவர்கள் பிறர் வீடுகளுக்குள் நுழைய அனுமதி கேட்க மாட்டார்கள். ஒருவன் நேராக உள்ளே நுழைந்து 'நான் வந்துவிட்டேன்' என்று கூறிவிடுவான். இது ஒரு மனிதருக்கு மிகுந்த சங்கடத்தை அளிக்கும், ஏனெனில் அவர் தன் மனைவியுடன் இருக்கலாம். எனவே அல்லாஹ் திரையிடுதல் மற்றும் கற்புநெறியைப் பேணுவதை வலியுறுத்தி, இச்செயல்களைத் தூய்மையானதாக ஆக்கி, ஜாஹிலிய்யா முறையை மாற்றினான். எனவேதான் அல்லாஹ் கூறினான்:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تَدْخُلُواْ بُيُوتاً غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُواْ وَتُسَلِّمُواْ عَلَى أَهْلِهَا\n\r\n\n\r\n(முஃமின்களே! உங்கள் வீடுகள் அல்லாத பிற வீடுகளில், நீங்கள் அனுமதி கேட்டு அங்குள்ளவர்களுக்கு ஸலாம் கூறும் வரை நுழையாதீர்கள்...) முகாதில் அவர்களின் இந்தக் கருத்து மிகச் சிறந்தது. அல்லாஹ் கூறினான்:\n\r\n\n\r\nذَلِكُمْ خَيْرٌ لَّكُمْ\n\r\n\n\r\n(அதுவே உங்களுக்கு மிகச் சிறந்தது,) அதாவது, அனுமதி பெற்று நுழைவது இரு தரப்பினருக்கும், அதாவது அனுமதி கேட்பவருக்கும், வீட்டிற்குள் இருப்பவர்களுக்கும் சிறந்தது.\n\r\n\n\r\nلَعَلَّكُمْ تَذَكَّرُونَ\n\r\n\n\r\n(இதைக் கொண்டு நீங்கள் படிப்பினை பெறுவதற்காக.)\n\r\n\n\r\nفَإِن لَّمْ تَجِدُواْ فِيهَا أَحَداً فَلاَ تَدْخُلُوهَا حَتَّى يُؤْذَنَ لَكُمُ\n\r\n\n\r\n(அங்கே நீங்கள் எவரையும் காணாவிட்டால், உங்களுக்கு அனுமதி வழங்கப்படும் வரை அங்கு நுழையாதீர்கள்.) இது பிறருடைய உடமைகளை அவர்களின் அனுமதியின்றிப் பயன்படுத்துவது தொடர்பான சட்டமாகும். வீட்டின் உரிமையாளர் விரும்பினால் அனுமதி அளிக்கலாம், இல்லையெனில் மறுக்கலாம்.\n\r\n\n\r\nوَإِن قِيلَ لَكُمْ ارْجِعُواْ فَارْجِعُواْ هُوَ أَزْكَى لَكُمْ\n\r\n\n\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது.) அதாவது, அனுமதி கேட்கும் முன்போ அல்லது பின்போ நீங்கள் வாசலிலிருந்து திருப்பி அனுப்பப்பட்டால்,\n\r\n\n\r\nفَارْجِعُواْ هُوَ أَزْكَى لَكُمْ\n\r\n\n\r\n(திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது.) அதாவது, அடம் பிடிக்காமல் திரும்பிச் செல்வது உங்களுக்குத் தூய்மையானதும் சிறந்ததும் ஆகும்.\n\r\n\n\r\nوَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ\n\r\n\n\r\n(மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.) கத்தாதா அவர்கள் கூறுகிறார்கள், முஹாஜிர்களில் ஒருவர் கூறினார்: \"எனது வாழ்நாள் முழுவதும் இந்த வசனத்தின்படி நடக்க நான் முயற்சி செய்தேன். ஆனால், எனது சகோதரர் ஒருவரிடம் நான் அனுமதி கேட்டபோது அவர் என்னை 'திரும்பிப் போ' என்று சொல்லவில்லை. அப்படி அவர் சொல்லியிருந்தால் நான் மகிழ்ச்சியோடு திரும்பியிருப்பேன். ஏனெனில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَإِن قِيلَ لَكُمْ ارْجِعُواْ فَارْجِعُواْ هُوَ أَزْكَى لَكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ\n\r\n\n\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்; அதுவே உங்களுக்கு மிகவும் தூய்மையானது. மேலும் அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.)\"\n\r\n\n\r\nوَإِن قِيلَ لَكُمْ ارْجِعُواْ فَارْجِعُواْ\n\r\n\n\r\n(திரும்பிச் செல்லுங்கள் என்று உங்களிடம் கூறப்பட்டால், நீங்கள் திரும்பி விடுங்கள்...) இது குறித்து ஸஈத் பின் ஜுபைர் கூறும்போது, \"இதன் பொருள், மற்றவர்களின் கதவு வாசல்களில் (அனுமதி மறுக்கப்பட்ட பிறகும்) காத்து நிற்காதீர்கள் என்பதாகும்\" என்கிறார்.\n\r\n\n\r\nلَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُواْ بُيُوتاً غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَّكُمْ\n\r\n\n\r\n(யாரும் குடியிருக்காத, (ஆனால்) உங்களுக்குப் பயன் அளிக்கக்கூடிய வீடுகளில் நீங்கள் நுழைவது உங்கள் மீது குற்றமில்லை.) இந்த வசனம் முந்தைய வசனத்தை விட சற்று விரிவானது. ஏனெனில், ஒரு குறிப்பிட்ட தேவைக்காக ஆள் இல்லாத வீடுகளுக்குள் நுழைவது அனுமதிக்கப்பட்டுள்ளது என்று இது கூறுகிறது. விருந்தினர்களுக்காக ஒதுக்கப்பட்ட வீடுகள் போன்றவை இதற்கு உதாரணம்; அங்கு தங்குவதற்கு ஒருமுறை அனுமதி பெற்றாலே போதுமானது.\n\r\n\n\r\nஇப்னு ஜுரைஜ் அவர்கள் கூறுகிறார்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nلاَ تَدْخُلُواْ بُيُوتاً غَيْرَ بُيُوتِكُمْ\n\r\n\n\r\n(உங்கள் வீடுகள் அல்லாத மற்ற வீடுகளில் நுழையாதீர்கள்,) என்ற வசனம் பொதுவானது. பின்னர் இதில் ஒரு விதிவிலக்கு அளிக்கப்பட்டு பின்வரும் வசனம் அருளப்பட்டது:\n\r\n\n\r\nلَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُواْ بُيُوتاً غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَّكُمْ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ\n\r\n\n\r\n(எந்த வீடுகளில் யாரும் குடியிருக்கவில்லையோ, அங்கு உங்களுக்கு ஏதேனும் தேவை இருக்குமானால், அத்தகைய வீடுகளில் நீங்கள் நுழைவது உங்கள் மீது குற்றமில்லை. மேலும், நீங்கள் வெளிப்படுத்துவதையும் நீங்கள் மறைப்பதையும் அல்லாஹ் அறிவான்.) இதே போன்ற கருத்து இக்ரிமா மற்றும் அல்-ஹஸன் அல்-பஸரீ ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது."},"30":{"html":"«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالْجُلُوسَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الطُّرُقَاتِ</span>»<br />\r\n(வீதிகளில் அமர்வதைத் தவிர்த்துக் கொள்ளுங்கள்.) அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! நாங்கள் ஒருவருக்கொருவர் பேசிக்கொள்வதற்கு வீதிகளில் அமர்வதைத் தவிர வேறு வழியில்லை\" என்று கூறினார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَبَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَعْطُوا</span> <span class=\"quran-arabic-font text-success\">الطَّرِيقَ</span> <span class=\"quran-arabic-font text-success\">حَقَّهُ</span>»<br />\r\n(நீங்கள் அங்கேயே இருக்க விரும்பினால், அந்த வீதிக்குரிய உரிமைகளை அதற்கு வழங்குங்கள்.) அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! வீதியின் உரிமைகள் யாவை?\" என்று கேட்டனர். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">غَضُّ</span> <span class=\"quran-arabic-font text-success\">الْبَصَرِ،</span> <span class=\"quran-arabic-font text-success\">وَكَفُّ</span> <span class=\"quran-arabic-font text-success\">الْأَذَى،</span> <span class=\"quran-arabic-font text-success\">وَرَدُّ</span> <span class=\"quran-arabic-font text-success\">السَّلَامِ،</span> <span class=\"quran-arabic-font text-success\">وَالْأَمْرُ</span> <span class=\"quran-arabic-font text-success\">بِالْمَعْرُوفِ،</span> <span class=\"quran-arabic-font text-success\">وَالنَّهْيُ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْمُنْكَرِ</span>»<br />\r\n(பார்வையைத் தாழ்த்திக் கொள்வது, தொந்தரவு கொடுப்பதைத் தவிர்ப்பது, ஸலாமுக்குப் பதிலளிப்பது, நன்மையை ஏவி தீமையைத் தடுப்பது ஆகியவையாகும்.) அபூ அல்-காஸிம் அல்-பகவீ அவர்கள், அபூ உமாமா (ரழி) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اكْفُلُوا</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">سِتًّا</span> <span class=\"quran-arabic-font text-success\">أَكْفُلْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بِالْجَنَّةِ</span>: <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">حَدَّث</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَكْذِبْ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">ائْتُمِنَ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَخُنْ،وَإِذَا</span> <span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يُخْلِفْ،</span> <span class=\"quran-arabic-font text-success\">وَغُضُّوا</span> <span class=\"quran-arabic-font text-success\">أَبْصَارَكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَكُفُّوا</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَاحْفَظُوا</span> <span class=\"quran-arabic-font text-success\">فُرُوجَكُمْ</span>»<br />\r\n(ஆறு விஷயங்களுக்கு நீங்கள் எனக்குப் பொறுப்பேற்றுக் கொள்ளுங்கள், நான் உங்களுக்குச் சொர்க்கத்திற்குப் பொறுப்பேற்கிறேன்: உங்களில் எவராவது பேசினால் பொய் சொல்லக்கூடாது; அவரிடம் ஏதேனும் ஒப்படைக்கப்பட்டால் நம்பிக்கைத் துரோகம் செய்யக்கூடாது; வாக்குறுதி அளித்தால் அதை மீறக்கூடாது; உங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுங்கள்; உங்கள் கைகளைக் கட்டுப்படுத்திக் கொள்ளுங்கள்; உங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்ளுங்கள்.) பார்வை என்பது இதயத்தைத் தீமையின் பால் தூண்டுவதாகவும், அதற்கு வழிகோலுவதாகவும் இருப்பதால், அந்தரங்க உறுப்புகளைப் பாதுகாக்குமாறு கட்டளையிடுவதற்கு முன்பாகவே, பார்வையைத் தாழ்த்திக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டான். எனவே அவன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">يَغُضُّواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَيَحْفَظُواْ</span> <span class=\"quran-arabic-font text-success\">فُرُوجَهُمْ</span><br />\r\n(நம்பிக்கை கொண்ட ஆண்களிடம், அவர்கள் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறும், தங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்ளுமாறும் கூறுவீராக.) சில நேரங்களில் அந்தரங்க உறுப்புகளைப் பாதுகாப்பது என்பது 'ஸினா' (விபச்சாரம்) செய்வதிலிருந்து அவற்றைத் தடுத்துக் கொள்வதைக் குறிக்கும். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">لِفُرُوجِهِمْ</span> <span class=\"quran-arabic-font text-success\">حَافِظُونَ</span><br />\r\n(மேலும், அவர்கள் தங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்வார்கள்) <a href=\"qurandisp.php?sura=23&ayah=5\" class=\"link\">23:5</a>. வேறு சில நேரங்களில், (பிறர்) அதைப் பார்க்காதவாறு பாதுகாத்துக் கொள்வதையும் இது குறிக்கும். முஸ்னத் அஹ்மத் மற்றும் ஸுனன் நூல்களில் இடம்பெற்றுள்ள ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">احْفَظْ</span> <span class=\"quran-arabic-font text-success\">عَوْرَتَكَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">زَوْجَتِكَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">يَمِينُكَ</span>»<br />\r\n(உம்முடைய மனைவி மற்றும் உமது வலக்கரம் சொந்தமாக்கிக் கொண்டவர்களிடம் தவிர, மற்றவர்களிடமிருந்து உமது அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்வீராக.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">أَزْكَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n(அது அவர்களுக்கு மிகவும் தூய்மையானது.) அதாவது, இது அவர்களின் இதயங்களுக்கு மிகவும் தூய்மையானது மற்றும் அவர்களின் மார்க்கப் பற்றுக்கு மிகச் சிறந்தது. \"யார் தனது பார்வையைப் பாதுகாக்கிறாரோ, அல்லாஹ் அவரது அகப்பார்வையை அல்லது அவரது இதயத்தை ஒளிரச் செய்வான்\" என்று கூறப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">يَصْنَعُونَ</span><br />\r\n(நிச்சயமாக அல்லாஹ் அவர்கள் செய்பவற்றை நன்கு அறிந்தவன்.) இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">خَآئِنَةَ</span> <span class=\"quran-arabic-font text-success\">الاٌّعْيُنِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تُخْفِى</span> <span class=\"quran-arabic-font text-success\">الصُّدُورُ</span><br />\r\n(கண்களின் துரோகத்தையும், நெஞ்சங்கள் மறைப்பவற்றையும் அவன் அறிகிறான்.) <a href=\"qurandisp.php?sura=40&ayah=19\" class=\"link\">40:19</a> ஸஹீஹ் நூலில், அபூ ஹுரைரா (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُتِبَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ابْنِ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">حَظُّهُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الزِّنَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">مَحَالَةَ،</span> <span class=\"quran-arabic-font text-success\">فَزِنَا</span> <span class=\"quran-arabic-font text-success\">الْعَيْنَيْنِ</span> <span class=\"quran-arabic-font text-success\">النَّظَرُ،</span> <span class=\"quran-arabic-font text-success\">وَزِنَا</span> <span class=\"quran-arabic-font text-success\">اللِّسَانِ</span> <span class=\"quran-arabic-font text-success\">النُّطْقُ،</span> <span class=\"quran-arabic-font text-success\">وَزِنَا</span> <span class=\"quran-arabic-font text-success\">الْأُذُنَيْنِ</span> <span class=\"quran-arabic-font text-success\">الْاسْتِمَاعُ،</span> <span class=\"quran-arabic-font text-success\">وَزِنَا</span> <span class=\"quran-arabic-font text-success\">الْيَدَيْنِ</span> <span class=\"quran-arabic-font text-success\">الْبَطْشُ،</span> <span class=\"quran-arabic-font text-success\">وَزِنَا</span> <span class=\"quran-arabic-font text-success\">الرِّجْلَيْنِ</span> <span class=\"quran-arabic-font text-success\">الْخُطَى،</span> <span class=\"quran-arabic-font text-success\">وَالنَّفْسُ</span> <span class=\"quran-arabic-font text-success\">تَمَنَّى</span> <span class=\"quran-arabic-font text-success\">وَتَشْتَهِي،</span> <span class=\"quran-arabic-font text-success\">وَالْفَرْجُ</span> <span class=\"quran-arabic-font text-success\">يُصَدِّقُ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُهُ</span>»<br />\r\n(ஆதமின் மகனுக்கு ஸினாவில் (விபச்சாரத்தில்) அவனது பங்கு எழுதப்பட்டுள்ளது; அவன் அதைத் தப்பாமல் செய்தே தீருவான். கண்களின் ஸினா பார்ப்பதாகும்; நாவின் ஸினா பேசுவதாகும்; காதுகளின் ஸினா கேட்பதாகும்; கைகளின் ஸினா (தவறானவற்றைப்) பற்றுவதாகும்; கால்களின் ஸினா (அதற்காக) நடப்பதாகும். மனம் விரும்புகிறது, ஆசைப்படுகிறது; அந்தரங்க உறுப்பு அதனை உண்மைப்படுத்துகிறது அல்லது பொய்யாக்குகிறது.) இது அல்-புகாரி அவர்களால் முழுமையற்ற அறிவிப்பாளர் தொடருடன் பதிவு செய்யப்பட்டுள்ளது. முஸ்லிம் அவர்கள் இதே போன்ற ஒரு செய்தியை வேறுபட்ட அறிவிப்பாளர் தொடருடன் பதிவு செய்துள்ளார்கள். பல ஸலஃபுகள் (முன்னோர்கள்) கூறினார்கள்: \"தாடியில்லாத அழகான சிறுவர்களை உற்றுப் பார்ப்பதிலிருந்து அவர்கள் ஆண்களைத் தடுத்து வந்தார்கள்.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"«إِيَّاكُمْ وَالْجُلُوسَ عَلَى الطُّرُقَاتِ»\n\r\n(வீதிகளில் அமர்வதைத் தவிர்த்துக் கொள்ளுங்கள்.) அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! நாங்கள் ஒருவருக்கொருவர் பேசிக்கொள்வதற்கு வீதிகளில் அமர்வதைத் தவிர வேறு வழியில்லை\" என்று கூறினார்கள். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنْ أَبَيْتُمْ فَأَعْطُوا الطَّرِيقَ حَقَّهُ»\n\r\n(நீங்கள் அங்கேயே இருக்க விரும்பினால், அந்த வீதிக்குரிய உரிமைகளை அதற்கு வழங்குங்கள்.) அதற்கு அவர்கள், \"அல்லாஹ்வின் தூதரே! வீதியின் உரிமைகள் யாவை?\" என்று கேட்டனர். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«غَضُّ الْبَصَرِ، وَكَفُّ الْأَذَى، وَرَدُّ السَّلَامِ، وَالْأَمْرُ بِالْمَعْرُوفِ، وَالنَّهْيُ عَنِ الْمُنْكَرِ»\n\r\n(பார்வையைத் தாழ்த்திக் கொள்வது, தொந்தரவு கொடுப்பதைத் தவிர்ப்பது, ஸலாமுக்குப் பதிலளிப்பது, நன்மையை ஏவி தீமையைத் தடுப்பது ஆகியவையாகும்.) அபூ அல்-காஸிம் அல்-பகவீ அவர்கள், அபூ உமாமா (ரழி) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூற நான் கேட்டேன்:\n\r\n\n\r\n«اكْفُلُوا لِي سِتًّا أَكْفُلْ لَكُمْ بِالْجَنَّةِ: إِذَا حَدَّث أَحَدُكُمْ فَلَا يَكْذِبْ، وَإِذَا ائْتُمِنَ فَلَا يَخُنْ،وَإِذَا وَعَدَ فَلَا يُخْلِفْ، وَغُضُّوا أَبْصَارَكُمْ، وَكُفُّوا أَيْدِيَكُمْ، وَاحْفَظُوا فُرُوجَكُمْ»\n\r\n(ஆறு விஷயங்களுக்கு நீங்கள் எனக்குப் பொறுப்பேற்றுக் கொள்ளுங்கள், நான் உங்களுக்குச் சொர்க்கத்திற்குப் பொறுப்பேற்கிறேன்: உங்களில் எவராவது பேசினால் பொய் சொல்லக்கூடாது; அவரிடம் ஏதேனும் ஒப்படைக்கப்பட்டால் நம்பிக்கைத் துரோகம் செய்யக்கூடாது; வாக்குறுதி அளித்தால் அதை மீறக்கூடாது; உங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுங்கள்; உங்கள் கைகளைக் கட்டுப்படுத்திக் கொள்ளுங்கள்; உங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்ளுங்கள்.) பார்வை என்பது இதயத்தைத் தீமையின் பால் தூண்டுவதாகவும், அதற்கு வழிகோலுவதாகவும் இருப்பதால், அந்தரங்க உறுப்புகளைப் பாதுகாக்குமாறு கட்டளையிடுவதற்கு முன்பாகவே, பார்வையைத் தாழ்த்திக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டான். எனவே அவன் கூறினான்:\n\r\n\n\r\nقُلْ لِّلْمُؤْمِنِينَ يَغُضُّواْ مِنْ أَبْصَارِهِمْ وَيَحْفَظُواْ فُرُوجَهُمْ\n\r\n(நம்பிக்கை கொண்ட ஆண்களிடம், அவர்கள் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறும், தங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்ளுமாறும் கூறுவீராக.) சில நேரங்களில் அந்தரங்க உறுப்புகளைப் பாதுகாப்பது என்பது 'ஸினா' (விபச்சாரம்) செய்வதிலிருந்து அவற்றைத் தடுத்துக் கொள்வதைக் குறிக்கும். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ\n\r\n(மேலும், அவர்கள் தங்கள் அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்வார்கள்) 23:5. வேறு சில நேரங்களில், (பிறர்) அதைப் பார்க்காதவாறு பாதுகாத்துக் கொள்வதையும் இது குறிக்கும். முஸ்னத் அஹ்மத் மற்றும் ஸுனன் நூல்களில் இடம்பெற்றுள்ள ஹதீஸில் பின்வருமாறு கூறப்பட்டுள்ளது:\n\r\n\n\r\n«احْفَظْ عَوْرَتَكَ إِلَّا مِنْ زَوْجَتِكَ أَوْ مَا مَلَكَتْ يَمِينُكَ»\n\r\n(உம்முடைய மனைவி மற்றும் உமது வலக்கரம் சொந்தமாக்கிக் கொண்டவர்களிடம் தவிர, மற்றவர்களிடமிருந்து உமது அந்தரங்க உறுப்புகளைப் பாதுகாத்துக் கொள்வீராக.)\n\r\n\n\r\nذلِكَ أَزْكَى لَهُمْ\n\r\n(அது அவர்களுக்கு மிகவும் தூய்மையானது.) அதாவது, இது அவர்களின் இதயங்களுக்கு மிகவும் தூய்மையானது மற்றும் அவர்களின் மார்க்கப் பற்றுக்கு மிகச் சிறந்தது. \"யார் தனது பார்வையைப் பாதுகாக்கிறாரோ, அல்லாஹ் அவரது அகப்பார்வையை அல்லது அவரது இதயத்தை ஒளிரச் செய்வான்\" என்று கூறப்பட்டுள்ளது.\n\r\n\n\r\nإِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ\n\r\n(நிச்சயமாக அல்லாஹ் அவர்கள் செய்பவற்றை நன்கு அறிந்தவன்.) இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَعْلَمُ خَآئِنَةَ الاٌّعْيُنِ وَمَا تُخْفِى الصُّدُورُ\n\r\n(கண்களின் துரோகத்தையும், நெஞ்சங்கள் மறைப்பவற்றையும் அவன் அறிகிறான்.) 40:19 ஸஹீஹ் நூலில், அபூ ஹுரைரா (ரழி) அவர்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«كُتِبَ عَلَى ابْنِ آدَمَ حَظُّهُ مِنَ الزِّنَا أَدْرَكَ ذَلِكَ لَا مَحَالَةَ، فَزِنَا الْعَيْنَيْنِ النَّظَرُ، وَزِنَا اللِّسَانِ النُّطْقُ، وَزِنَا الْأُذُنَيْنِ الْاسْتِمَاعُ، وَزِنَا الْيَدَيْنِ الْبَطْشُ، وَزِنَا الرِّجْلَيْنِ الْخُطَى، وَالنَّفْسُ تَمَنَّى وَتَشْتَهِي، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ»\n\r\n(ஆதமின் மகனுக்கு ஸினாவில் (விபச்சாரத்தில்) அவனது பங்கு எழுதப்பட்டுள்ளது; அவன் அதைத் தப்பாமல் செய்தே தீருவான். கண்களின் ஸினா பார்ப்பதாகும்; நாவின் ஸினா பேசுவதாகும்; காதுகளின் ஸினா கேட்பதாகும்; கைகளின் ஸினா (தவறானவற்றைப்) பற்றுவதாகும்; கால்களின் ஸினா (அதற்காக) நடப்பதாகும். மனம் விரும்புகிறது, ஆசைப்படுகிறது; அந்தரங்க உறுப்பு அதனை உண்மைப்படுத்துகிறது அல்லது பொய்யாக்குகிறது.) இது அல்-புகாரி அவர்களால் முழுமையற்ற அறிவிப்பாளர் தொடருடன் பதிவு செய்யப்பட்டுள்ளது. முஸ்லிம் அவர்கள் இதே போன்ற ஒரு செய்தியை வேறுபட்ட அறிவிப்பாளர் தொடருடன் பதிவு செய்துள்ளார்கள். பல ஸலஃபுகள் (முன்னோர்கள்) கூறினார்கள்: \"தாடியில்லாத அழகான சிறுவர்களை உற்றுப் பார்ப்பதிலிருந்து அவர்கள் ஆண்களைத் தடுத்து வந்தார்கள்.\""},"31":{"html":"<strong>ஹிஜாபின் சட்டங்கள்</strong><br />\r\n<br />\r\nஇது இறைநம்பிக்கை கொண்ட பெண்களுக்கு அல்லாஹ் வழங்கிய கட்டளையாகும்; மேலும் அவனது இறைநம்பிக்கையுள்ள அடியார்களின் மனைவிகள் மீது அவன் கொண்டுள்ள கண்ணியமான ரோஷமுமாகும் (கௌரவமுமாகும்). இது இறைநம்பிக்கையுள்ள பெண்களை ஜாஹிலிய்யா (அறியாமை) காலப் பெண்களிடமிருந்தும், இணைவைப்பவளின் செயல்களிலிருந்தும் வேறுபடுத்திக் காட்டுவதற்காகவும் ஆகும். இந்த வசனம் அருளப்பட்டதற்கான காரணத்தை முகாதில் பின் ஹய்யான் குறிப்பிடுகிறார்கள்: \"நாங்கள் கேள்விப்பட்டோம் - அல்லாஹ்வே மிக அறிந்தவன் - ஜாபிர் பின் அப்துல்லாஹ் அல்-அன்சாரி (ரழி) அவர்கள் அறிவித்தார்கள்: அஸ்மா பின்த் முர்ஷிதா (ரழி) அவர்கள் பனூ ஹாரிதாவில் உள்ள தனது வீட்டில் இருந்தபோது, பெண்கள் கீழாடைகள் அணியாமல் அவரிடம் வரத் தொடங்கினார்கள். அதனால் அவர்களின் கால்களில் இருந்த கொலுசுகளும், மார்புகளும், முன்நெற்றி முடிகளும் வெளியே தெரிந்தன. இதைக் கண்ட அஸ்மா (ரழி) அவர்கள், 'இது எவ்வளவு அசிங்கமானது!' என்று கூறினார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُل</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">يَغْضُضْنَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَـرِهِنَّ</span><br />\r\n<br />\r\n(இறைநம்பிக்கை கொண்ட பெண்களுக்குத் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக...)\" மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُل</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">يَغْضُضْنَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَـرِهِنَّ</span><br />\r\n<br />\r\n(இறைநம்பிக்கை கொண்ட பெண்களுக்குத் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக) அதாவது, தங்கள் கணவர்களைத் தவிர, எதைப் பார்ப்பதற்கு அல்லாஹ் தடை விதித்துள்ளானோ அவற்றிலிருந்து (தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ள வேண்டும்). சில அறிஞர்கள், மஹ்ரம் அல்லாத ஆண்களை இச்சை (ஆசை) இல்லாமல் பார்ப்பது பெண்களுக்கு அனுமதிக்கப்பட்டுள்ளது என்று கூறியுள்ளனர். இதற்கு ஆதாரமாக ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ள செய்தியைக் குறிப்பிடுகின்றனர்: ஒரு பெருநாள் (ஈத்) அன்று மஸ்ஜிதில் எத்தியோப்பியர்கள் ஈட்டிகளுடன் விளையாடிக் கொண்டிருந்ததை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பார்த்துக் கொண்டிருந்தார்கள். அப்போது இறைநம்பிக்கையாளர்களின் தாயார் ஆயிஷா (ரழி) அவர்கள் நபி (ஸல்) அவர்களுக்குப் பின்னால் இருந்து அவர்களைப் பார்த்துக் கொண்டிருந்தார்கள். நபி (ஸல்) அவர்கள் ஆயிஷா (ரழி) அவர்களுக்குத் திரையாக இருந்து மறைத்துக் கொண்டிருந்தார்கள். இறுதியில் ஆயிஷா (ரழி) அவர்களுக்குப் போதுமென்று தோன்றிச் செல்லும் வரை அவர்கள் பார்த்துக் கொண்டிருந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَحْفَظْنَ</span> <span class=\"quran-arabic-font text-success\">فُرُوجَهُنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் மறைவிடங்களைப் பாதுகாத்துக் கொள்ளட்டும்). ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள், \"தவறான (மானக்கேடான) செயல்களிலிருந்து\" என்று கூறினார்கள். அபுல் ஆலியா அவர்கள் கூறுகையில்: \"மறைவிடங்களைப் பாதுகாப்பது பற்றி குர்ஆனில் குறிப்பிடப்பட்டுள்ள ஒவ்வொரு வசனமும் ஸினாவிலிருந்து (விபச்சாரத்திலிருந்து) பாதுகாப்பதையே குறிக்கிறது; இந்த ஒரு வசனத்தைத் தவிர --<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَحْفَظْنَ</span> <span class=\"quran-arabic-font text-success\">فُرُوجَهُنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் மறைவிடங்களைப் பாதுகாத்துக் கொள்ளட்டும்), இதற்கு மற்றவர்கள் பார்ப்பதிலிருந்து பாதுகாத்துக் கொள்ள வேண்டும் என்பதே பொருளாகும்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُبْدِينَ</span> <span class=\"quran-arabic-font text-success\">زِينَتَهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ظَهَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span><br />\r\n<br />\r\n(தங்கள் அலங்காரத்தில் வெளியிலுள்ளவற்றைத் தவிர மற்றவற்றை அவர்கள் வெளிப்படுத்த வேண்டாம்,) அதாவது, மறைக்க முடியாதவற்றைத் தவிர, மஹ்ரம் அல்லாத ஆண்களுக்குத் தங்கள் அலங்காரத்தில் எதையும் அவர்கள் வெளிப்படுத்தக் கூடாது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"உடைகள் மற்றும் மேலாடைகள் போன்றவை.\" அதாவது, அரபுப் பெண்கள் தங்கள் ஆடைகளை மறைக்கப் பயன்படுத்திய முக்காடு மற்றும் மேலாடைக்கு அடியிலிருந்து வெளியே தெரியும் பாகங்கள். இதற்காக அவர்கள் மீது குற்றமில்லை, ஏனெனில் இவற்றை மறைப்பது சாத்தியமற்றது. அதேபோல கீழாடையின் ஒரு பகுதி வெளியே தெரிவதையும் மறைக்க முடியாது. ஹஸன், இப்னு சிரீன், அபுல் ஜவ்ஸா, இப்ராஹீம் அந்-நகஈ உள்ளிட்டோரும் இப்னு மஸ்ஊத் (ரழி) அவர்களின் இதே கருத்தையே கொண்டிருந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَضْرِبْنَ</span> <span class=\"quran-arabic-font text-success\">بِخُمُرِهِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جُيُوبِهِنَّ</span><br />\r\n<br />\r\n(தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) அதாவது, அவர்கள் தங்கள் மார்புகளையும் விலாப்பகுதிகளையும் மறைக்கும் விதத்தில் மேலாடைகளை அணிய வேண்டும். இதன் மூலம் அவர்கள் ஜாஹிலிய்யா காலப் பெண்களிடமிருந்து வேறுபடுவார்கள். ஜாஹிலிய்யா காலப் பெண்கள் அவ்வாறு செய்யாமல், தங்கள் மார்புகள் முழுமையாகத் திறந்த நிலையில், கழுத்து, முன்நெற்றி முடி, கூந்தல் மற்றும் காதணிகள் வெளியே தெரியும்படி ஆண்களுக்கு முன்னால் கடந்து செல்வார்கள். எனவே, இறைநம்பிக்கையுள்ள பெண்கள் தங்களை மறைத்துக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டான். அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّبِىُّ</span> <span class=\"quran-arabic-font text-success\">قُل</span> <span class=\"quran-arabic-font text-success\">لِّأَزْوَاجِكَ</span> <span class=\"quran-arabic-font text-success\">وَبَنَـتِكَ</span> <span class=\"quran-arabic-font text-success\">وَنِسَآءِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">يُدْنِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِنَّ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">جَلَـبِيبِهِنَّ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">أَدْنَى</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُعْرَفْنَ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْذَيْنَ</span><br />\r\n<br />\r\n(நபியே! உமது மனைவிகளுக்கும், உமது புதல்விகளுக்கும், இறைநம்பிக்கை கொண்டவர்களின் பெண்களுக்கும் நீர் கூறுவீராக: அவர்கள் தங்கள் மேலாடைகளைத் தங்கள் மீது தாழ்த்திக் கொள்ளட்டும். அவர்கள் (ஒழுக்கமானவர்கள் என) அறியப்பட்டு, தொந்தரவு செய்யப்படாமல் இருக்க இதுவே மிக நெருக்கமான வழியாகும்) <a href=\"qurandisp.php?sura=33&ayah=59\" class=\"link\">33:59</a>. இந்த மேன்மையான வசனத்தில் அவன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَضْرِبْنَ</span> <span class=\"quran-arabic-font text-success\">بِخُمُرِهِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جُيُوبِهِنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் (குமுர்) முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) 'குமுர்' (Khumur) என்பது 'கிமார்' (Khimar) என்பதன் பன்மையாகும். இதற்கு 'மறைப்பது' என்று பொருள். தலையை மறைக்கப் பயன்படுவதையே மக்கள் 'முக்காடு' என்கின்றனர். ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறுகையில்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَضْرِبْنَ</span><br />\r\n<br />\r\n(போட்டுக் கொள்ளட்டும்) என்பது, அதனைச் சுற்றிக் கொண்டு உறுதியாகக் கட்டிக் கொள்வதைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِخُمُرِهِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جُيُوبِهِنَّ</span><br />\r\n<br />\r\n(தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) என்பது, தங்கள் கழுத்து மற்றும் மார்புப் பகுதிகள் தெரியாதவாறு அவற்றின் மேல் போட்டுக் கொள்ள வேண்டும் என்பதாகும். அன்னை ஆயிஷா (ரழி) அவர்கள் கூறியதாக புகாரி பதிவு செய்துள்ளார்கள்: \"ஆரம்ப காலத்தில் ஹிஜ்ரத் செய்த பெண்களுக்கு அல்லாஹ் அருள் புரியட்டும். 'வலியழ்ரிப்ன பிஹுமுரிஹின்ன அலா ஜுயூபிஹின்ன' என்ற வசனம் அருளப்பட்டபோது, அவர்கள் தங்கள் மேலாடைகளைக் கிழித்து அவற்றைக் கொண்டு முக்காடிட்டுக் கொண்டார்கள்.\" மேலும் ஸஃபிய்யா பின்த் ஷைபா (ரழி) அவர்கள் வழியாக ஆயிஷா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"இந்த வசனம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَضْرِبْنَ</span> <span class=\"quran-arabic-font text-success\">بِخُمُرِهِنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جُيُوبِهِنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) அருளப்பட்டபோது, அவர்கள் தங்கள் இஸார்களை (இடுப்புத் துணிகளை) ஓரங்களில் கிழித்து, அவற்றைக் கொண்டு முக்காடிட்டுக் கொண்டார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُبْدِينَ</span> <span class=\"quran-arabic-font text-success\">زِينَتَهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِبُعُولَتِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءِ</span> <span class=\"quran-arabic-font text-success\">بُعُولَتِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَبْنَآئِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَبْنَآءِ</span> <span class=\"quran-arabic-font text-success\">بُعُولَتِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">إِخْوَانِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِخْوَانِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">أَخَوَاتِهِنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் கணவர்கள், அல்லது தங்கள் தந்தையர்கள், அல்லது தங்கள் கணவர்களின் தந்தையர்கள், அல்லது தங்கள் புதல்வர்கள், அல்லது தங்கள் கணவர்களின் புதல்வர்கள், அல்லது தங்கள் சகோதரர்கள், அல்லது தங்கள் சகோதரர்களின் புதல்வர்கள், அல்லது தங்கள் சகோதரிகளின் புதல்வர்களைத் தவிர மற்றவர்களுக்குத் தங்கள் அலங்காரத்தை அவர்கள் வெளிப்படுத்த வேண்டாம்). இவர்கள் அனைவரும் ஒரு பெண்ணால் ஒருபோதும் திருமணம் செய்ய முடியாத நெருங்கிய உறவினர்கள் (மஹ்ரம்) ஆவர். இவர்களிடம் தன்னைத் தகாத முறையில் வெளிப்படுத்தாமல், சாதாரணமாகத் தனது அலங்காரங்களைக் காட்ட அனுமதியுண்டு. இப்னுல் முன்திர் அவர்கள் பதிவு செய்துள்ளார்கள்: இக்ரிமா (ரழி) அவர்கள் இந்த வசனத்திற்கு விளக்கமளிக்கையில்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُبْدِينَ</span> <span class=\"quran-arabic-font text-success\">زِينَتَهُنَّ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لِبُعُولَتِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِهِنَّ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءِ</span> <span class=\"quran-arabic-font text-success\">بُعُولَتِهِنَّ</span><br />\r\n<br />\r\n(மேலும் தங்கள் கணவர்கள், அல்லது தங்கள் தந்தையர்கள், அல்லது தங்கள் கணவர்களின் தந்தையர்களைத் தவிர மற்றவர்களுக்குத் தங்கள் அலங்காரத்தை அவர்கள் வெளிப்படுத்த வேண்டாம்...), \"தந்தையின் சகோதரரும், தாயின் சகோதரரும் இங்கு குறிப்பிடப்படவில்லை. ஏனெனில் அவர்கள் ஒரு பெண்ணின் அழகைத் தங்கள் மகன்களிடம் வர்ணிக்கக் கூடும். எனவே ஒரு பெண் தனது தந்தையின் சகோதரர் அல்லது தாயின் சகோதரருக்கு முன்னால் தனது முக்காடை (கிமார்) அகற்றக் கூடாது\" என்று கூறினார்கள். கணவரைப் பொறுத்தவரை, அலங்காரங்கள் அனைத்தும் அவருக்காகவே செய்யப்படுகின்றன. எனவே, மற்றவர்களுக்கு முன்னால் தோன்றுவதைப் போலல்லாமல், கணவருக்காகத் தன்னை அலங்கரிக்கும்போது அவள் மிகச் சிறந்த முறையில் இருக்க முயற்சிக்க வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نِسَآئِهِنَّ</span><br />\r\n<br />\r\n(அல்லது தங்கள் பெண்கள்), இதன் பொருள், ஒரு பெண் மற்ற முஸ்லிம் பெண்களுக்கு முன்னால் தனது அலங்காரத்துடன் இருக்கலாம். ஆனால் அஹ்லுத் திம்மா (யூத, கிறிஸ்தவ) பெண்களுக்கு முன்னால் அவ்வாறு இருக்கக் கூடாது. ஏனெனில் அவர்கள் அந்தப் பெண்ணைத் தங்கள் கணவர்களிடம் வர்ணிக்கக் கூடும். இது அனைத்துப் பெண்களுக்கும் தடை செய்யப்பட்டிருந்தாலும், அஹ்லுத் திம்மா பெண்களின் விஷயத்தில் இன்னும் கடுமையானது. ஏனெனில் அவர்களைத் தடுக்க எதுவுமில்லை. ஆனால் முஸ்லிம் பெண்களுக்கு இது ஹராம் (விலக்கப்பட்டது) என்று தெரியும் என்பதால் அவர்கள் இதனைச் செய்ய மாட்டார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُبَاشِرِ</span> <span class=\"quran-arabic-font text-success\">الْمَرْأَةُ</span> <span class=\"quran-arabic-font text-success\">الْمَرْأَةَ</span> <span class=\"quran-arabic-font text-success\">فَتَنْعَتَهَا</span> <span class=\"quran-arabic-font text-success\">لِزَوْجِهَا</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَنْظُرُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهَا</span>»<br />\r\n<br />\r\n(எந்தப் பெண்ணும் மற்றொரு பெண்ணை அவளது கணவனிடம், அவன் நேரில் பார்ப்பது போன்ற உணர்வு ஏற்படும் அளவுக்கு வர்ணிக்க வேண்டாம்). இது இப்னு மஸ்ஊத் (ரழி) அவர்கள் வழியாக புகாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَـنُهُنَّ</span><br />\r\n<br />\r\n(அல்லது அவர்களின் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்கள்.) இது இறைமறுப்பாளர்களான (முஷ்ரிக்) அடிமைப் பெண்களைக் குறிக்கும் என்று இப்னு ஜரீர் கூறுகிறார். ஒரு முஸ்லிம் பெண் இறைமறுப்பாளரான அடிமைப் பெண்ணுக்கு முன்னால் தனது அலங்காரத்தை வெளிப்படுத்துவது அனுமதிக்கப்பட்டுள்ளது. இது ஸயீத் பின் அல்-முஸய்யப் அவர்களின் கருத்தும் ஆகும். அல்லாஹ் கூறுகிறான்;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">التَّـبِعِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">أُوْلِى</span> <span class=\"quran-arabic-font text-success\">الإِرْبَةِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الرِّجَالِ</span><br />\r\n<br />\r\n(ஆண்களில் ஆசையற்ற பணியாளர்கள்,) அதாவது ஒரு பெண்ணுக்குச் சமமான நிலையில் இல்லாத, மனவளர்ச்சி குன்றிய அல்லது பெண்கள் மீது எந்த விருப்பமும் ஆசையுமற்ற பணியாளர்கள் மற்றும் ஏவலர்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இது எவ்வித ஆசையுமற்ற நபரை குறிக்கும்\" என்றார். இக்ரிமா (ரழி) அவர்கள், \"இது உணர்ச்சியற்ற அலி (திருநங்கை) போன்றோரைக் குறிக்கும்\" என்றார். இதுதான் முன்னோர்களின் (ஸலஃப்களின்) கருத்தாகும். ஸஹீஹ் நூலில் அன்னை ஆயிஷா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஒரு திருநங்கை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் இல்லத்திற்கு வருவது வழக்கம். அவரை ஆசையற்றவர்களில் ஒருவராகவே அனைவரும் கருதினர். ஆனால் ஒருமுறை அந்த நபர் ஒரு பெண்ணின் உடலமைப்பை பற்றி, \"அவள் முன்னோக்கி வரும்போது நான்கு (மடிப்புகளு)டனும், பின்னோக்கிச் செல்லும்போது எட்டு (மடிப்புகளு)டனும் தென்படுகிறாள்\" என்று வர்ணித்துக் கொண்டிருந்தபோது நபி (ஸல்) அவர்கள் அங்கு வந்தார்கள். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">أَرَى</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">هَهُنَا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَدْخُلَنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span>»<br />\r\n<br />\r\n(கவனிங்கள்! இவனுக்குப் பெண்களைப் பற்றிய விவரங்கள் தெரிந்திருக்கின்றன; இவன் இனி ஒருபோதும் உங்களிடம் நுழையக் கூடாது) என்று கூறினார்கள். அவர் அல்-பய்தா எனும் இடத்தில் தங்க வைக்கப்பட்டார். வெள்ளிக்கிழமைகளில் மட்டும் உணவு வாங்க வருவதற்கே அனுமதிக்கப்பட்டார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">الطِّفْلِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَظْهَرُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَوْرَتِ</span> <span class=\"quran-arabic-font text-success\">النِّسَآءِ</span><br />\r\n<br />\r\n(அல்லது பெண்களின் மறைவிடங்களைப் பற்றி அறியாத சிறுவர்கள்.) அவர்கள் மிகவும் சிறியவர்களாக இருப்பதால் பெண்களுக்குரிய அவ்ரா (மறைக்கப்பட வேண்டியவை), அவர்களின் மென்மையான பேச்சு அல்லது அவர்களின் கவர்ச்சியான நடை மற்றும் அசைவுகள் பற்றி எதுவும் புரியாதவர்கள். சிறு பிள்ளையாக இருந்து இவை எதனையும் புரிந்து கொள்ளவில்லை என்றால் அவர்கள் பெண்கள் பகுதிக்கு வருவதில் தவறில்லை. ஆனால் அவன் பருவ வயதை நெருங்கி இவற்றுக்கிடையிலான வேறுபாடுகளைப் புரிந்து கொள்ளும் நிலையில் இருந்தால், அவன் பெண்களிடம் நுழையக் கூடாது. புகாரி, முஸ்லிம் ஆகிய நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالدُّخُولَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النِّسَاءِ</span>»<br />\r\n<br />\r\n(பெண்கள் இருக்கும் இடத்திற்குள் நுழைவதைத் தவிர்ந்து கொள்ளுங்கள்). அப்போது, \"அல்லாஹ்வின் தூதரே! கணவனின் ஆண் உறவினர்களைப் பற்றித் தங்கள் கருத்து என்ன?\" என்று கேட்கப்பட்டது. அதற்கு அவர்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْحَمْوُ</span>: <span class=\"quran-arabic-font text-success\">الْمَوْتُ</span>»<br />\r\n<br />\r\n(கணவனின் ஆண் உறவினர் மரணத்திற்குச் சமமானவர்) என்று கூறினார்கள்.<br />\r\n<br />\r\n<strong>பெண்கள் தெருவில் நடப்பதற்கான ஒழுக்கங்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبْنَ</span> <span class=\"quran-arabic-font text-success\">بِأَرْجُلِهِنَّ</span><br />\r\n<br />\r\n(இன்னும் அவர்கள் தங்கள் மறைத்து வைத்துள்ள அலங்காரம் அறியப்பட வேண்டும் என்பதற்காகத் தங்கள் கால்களைத் தட்டி நடக்க வேண்டாம்...) அறியாமை (ஜாஹிலிய்யா) காலத்தில், பெண்கள் தாங்கள் அணிந்துள்ள கொலுசுகளின் சத்தம் கேட்க வேண்டும் என்பதற்காகத் தங்கள் கால்களைத் தட்டி நடப்பார்கள். இதனை அல்லாஹ் தடுத்தான். அதேபோல, மறைக்கப்பட்ட எந்த அலங்காரமும் வெளிப்படும் விதத்திலான அசைவுகளைச் செய்வதும் பெண்களுக்குத் தடை செய்யப்பட்டுள்ளது. ஏனெனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبْنَ</span> <span class=\"quran-arabic-font text-success\">بِأَرْجُلِهِنَّ</span><br />\r\n<br />\r\n(இன்னும் அவர்கள் தங்கள் கால்களைத் தட்டி நடக்க வேண்டாம்...) இறுதி வரை. இதிலிருந்தே, பெண்கள் வீட்டை விட்டு வெளியே செல்லும்போது நறுமணம் அல்லது வாசனைத் திரவியங்கள் பூசிச் செல்வதும் தடை செய்யப்பட்டுள்ளது. ஏனெனில் ஆண்கள் அந்த வாசனையை நுகரக்கூடும். அபு மூஸா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">عَيْنٍ</span> <span class=\"quran-arabic-font text-success\">زَانِيَةٌ،</span> <span class=\"quran-arabic-font text-success\">وَالْمَرْأَةُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">اسْتَعْطَرَتْ</span> <span class=\"quran-arabic-font text-success\">فَمَرَّتْ</span> <span class=\"quran-arabic-font text-success\">بِالْمَجْلِسِ</span> <span class=\"quran-arabic-font text-success\">فَهِيَ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا</span>»<br />\r\n<br />\r\n(ஒவ்வொரு கண்ணும் விபச்சாரம் செய்கிறது. ஒரு பெண் வாசனைத் திரவியம் பூசிக்கொண்டு ஒரு சபையைக் கடந்து சென்றால், அவள் இன்னின்னவள்) - அதாவது விபச்சாரி ஆவாள். திர்மிதி இதனை 'ஹஸன் ஸஹீஹ்' என்று குறிப்பிட்டுள்ளார். அபு தாவூத் மற்றும் நஸயீயிலும் இது பதிவு செய்யப்பட்டுள்ளது. அதேபோல, பெண்கள் தெருவின் நடுப்பகுதியில் நடப்பதும் தடுக்கப்பட்டுள்ளது. அபு உஸைத் அல்-அன்சாரி (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதிலிருந்து வெளியே வந்தபோது, தெருவில் ஆண்களும் பெண்களும் கலந்து செல்வதைக் கண்டு பெண்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اسْتَأْخِرْنَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لَكُنَّ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَحْقُقْنَ</span> <span class=\"quran-arabic-font text-success\">الطَّرِيقَ،</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُنَّ</span> <span class=\"quran-arabic-font text-success\">بِحَافَّاتِ</span> <span class=\"quran-arabic-font text-success\">الطَّرِيقِ</span>»<br />\r\n<br />\r\n(நீங்கள் பின்தங்கிச் செல்லுங்கள்; தெருவின் நடுப்பகுதியில் நடப்பதற்கு உங்களுக்கு அனுமதி இல்லை. நீங்கள் சாலையின் ஓரங்களையே பயன்படுத்த வேண்டும்). அதன் பிறகு பெண்கள் சுவரை ஒட்டியே செல்வார்கள். சில நேரங்களில் அவர்களின் மேலாடைகள் சுவரில் சிக்கிக் கொள்ளும் அளவுக்கு அவர்கள் ஒட்டிச் செல்வார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتُوبُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">أَيُّهَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تُفْلِحُونَ</span><br />\r\n<br />\r\n(இறைநம்பிக்கையாளர்களே! நீங்கள் வெற்றி பெறுவதற்காக நீங்கள் அனைவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுங்கள்.) அதாவது, இந்த அழகான ஒழுக்கங்களையும் புகழுக்குரிய பண்புகளையும் கடைபிடியுங்கள். அறியாமை காலத்துத் தீய பழக்கங்களை விட்டுவிடுங்கள். அல்லாஹ்வும் அவனது தூதரும் கட்டளையிட்டதைச் செய்வதிலும், அவர்கள் தடுத்ததைத் தவிர்ப்பதிலுமே மகத்தான வெற்றி உள்ளது. அல்லாஹ்வே அனைத்து ஆற்றல்களுக்கும் ஊற்றுக்கண்ணாவான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"ஹிஜாபின் சட்டங்கள்\n\r\n\n\r\nஇது இறைநம்பிக்கை கொண்ட பெண்களுக்கு அல்லாஹ் வழங்கிய கட்டளையாகும்; மேலும் அவனது இறைநம்பிக்கையுள்ள அடியார்களின் மனைவிகள் மீது அவன் கொண்டுள்ள கண்ணியமான ரோஷமுமாகும் (கௌரவமுமாகும்). இது இறைநம்பிக்கையுள்ள பெண்களை ஜாஹிலிய்யா (அறியாமை) காலப் பெண்களிடமிருந்தும், இணைவைப்பவளின் செயல்களிலிருந்தும் வேறுபடுத்திக் காட்டுவதற்காகவும் ஆகும். இந்த வசனம் அருளப்பட்டதற்கான காரணத்தை முகாதில் பின் ஹய்யான் குறிப்பிடுகிறார்கள்: \"நாங்கள் கேள்விப்பட்டோம் - அல்லாஹ்வே மிக அறிந்தவன் - ஜாபிர் பின் அப்துல்லாஹ் அல்-அன்சாரி (ரழி) அவர்கள் அறிவித்தார்கள்: அஸ்மா பின்த் முர்ஷிதா (ரழி) அவர்கள் பனூ ஹாரிதாவில் உள்ள தனது வீட்டில் இருந்தபோது, பெண்கள் கீழாடைகள் அணியாமல் அவரிடம் வரத் தொடங்கினார்கள். அதனால் அவர்களின் கால்களில் இருந்த கொலுசுகளும், மார்புகளும், முன்நெற்றி முடிகளும் வெளியே தெரிந்தன. இதைக் கண்ட அஸ்மா (ரழி) அவர்கள், 'இது எவ்வளவு அசிங்கமானது!' என்று கூறினார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَقُل لِّلْمُؤْمِنَـتِ يَغْضُضْنَ مِنْ أَبْصَـرِهِنَّ\n\r\n\n\r\n(இறைநம்பிக்கை கொண்ட பெண்களுக்குத் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக...)\" மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقُل لِّلْمُؤْمِنَـتِ يَغْضُضْنَ مِنْ أَبْصَـرِهِنَّ\n\r\n\n\r\n(இறைநம்பிக்கை கொண்ட பெண்களுக்குத் தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக) அதாவது, தங்கள் கணவர்களைத் தவிர, எதைப் பார்ப்பதற்கு அல்லாஹ் தடை விதித்துள்ளானோ அவற்றிலிருந்து (தங்கள் பார்வைகளைத் தாழ்த்திக் கொள்ள வேண்டும்). சில அறிஞர்கள், மஹ்ரம் அல்லாத ஆண்களை இச்சை (ஆசை) இல்லாமல் பார்ப்பது பெண்களுக்கு அனுமதிக்கப்பட்டுள்ளது என்று கூறியுள்ளனர். இதற்கு ஆதாரமாக ஸஹீஹ் நூல்களில் இடம்பெற்றுள்ள செய்தியைக் குறிப்பிடுகின்றனர்: ஒரு பெருநாள் (ஈத்) அன்று மஸ்ஜிதில் எத்தியோப்பியர்கள் ஈட்டிகளுடன் விளையாடிக் கொண்டிருந்ததை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பார்த்துக் கொண்டிருந்தார்கள். அப்போது இறைநம்பிக்கையாளர்களின் தாயார் ஆயிஷா (ரழி) அவர்கள் நபி (ஸல்) அவர்களுக்குப் பின்னால் இருந்து அவர்களைப் பார்த்துக் கொண்டிருந்தார்கள். நபி (ஸல்) அவர்கள் ஆயிஷா (ரழி) அவர்களுக்குத் திரையாக இருந்து மறைத்துக் கொண்டிருந்தார்கள். இறுதியில் ஆயிஷா (ரழி) அவர்களுக்குப் போதுமென்று தோன்றிச் செல்லும் வரை அவர்கள் பார்த்துக் கொண்டிருந்தார்கள்.\n\r\n\n\r\nوَيَحْفَظْنَ فُرُوجَهُنَّ\n\r\n\n\r\n(மேலும் தங்கள் மறைவிடங்களைப் பாதுகாத்துக் கொள்ளட்டும்). ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள், \"தவறான (மானக்கேடான) செயல்களிலிருந்து\" என்று கூறினார்கள். அபுல் ஆலியா அவர்கள் கூறுகையில்: \"மறைவிடங்களைப் பாதுகாப்பது பற்றி குர்ஆனில் குறிப்பிடப்பட்டுள்ள ஒவ்வொரு வசனமும் ஸினாவிலிருந்து (விபச்சாரத்திலிருந்து) பாதுகாப்பதையே குறிக்கிறது; இந்த ஒரு வசனத்தைத் தவிர --\n\r\n\n\r\nوَيَحْفَظْنَ فُرُوجَهُنَّ\n\r\n\n\r\n(மேலும் தங்கள் மறைவிடங்களைப் பாதுகாத்துக் கொள்ளட்டும்), இதற்கு மற்றவர்கள் பார்ப்பதிலிருந்து பாதுகாத்துக் கொள்ள வேண்டும் என்பதே பொருளாகும்\" என்று கூறினார்கள்.\n\r\n\n\r\nوَلاَ يُبْدِينَ زِينَتَهُنَّ إِلاَّ مَا ظَهَرَ مِنْهَا\n\r\n\n\r\n(தங்கள் அலங்காரத்தில் வெளியிலுள்ளவற்றைத் தவிர மற்றவற்றை அவர்கள் வெளிப்படுத்த வேண்டாம்,) அதாவது, மறைக்க முடியாதவற்றைத் தவிர, மஹ்ரம் அல்லாத ஆண்களுக்குத் தங்கள் அலங்காரத்தில் எதையும் அவர்கள் வெளிப்படுத்தக் கூடாது. இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள்: \"உடைகள் மற்றும் மேலாடைகள் போன்றவை.\" அதாவது, அரபுப் பெண்கள் தங்கள் ஆடைகளை மறைக்கப் பயன்படுத்திய முக்காடு மற்றும் மேலாடைக்கு அடியிலிருந்து வெளியே தெரியும் பாகங்கள். இதற்காக அவர்கள் மீது குற்றமில்லை, ஏனெனில் இவற்றை மறைப்பது சாத்தியமற்றது. அதேபோல கீழாடையின் ஒரு பகுதி வெளியே தெரிவதையும் மறைக்க முடியாது. ஹஸன், இப்னு சிரீன், அபுல் ஜவ்ஸா, இப்ராஹீம் அந்-நகஈ உள்ளிட்டோரும் இப்னு மஸ்ஊத் (ரழி) அவர்களின் இதே கருத்தையே கொண்டிருந்தனர்.\n\r\n\n\r\nوَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ\n\r\n\n\r\n(தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) அதாவது, அவர்கள் தங்கள் மார்புகளையும் விலாப்பகுதிகளையும் மறைக்கும் விதத்தில் மேலாடைகளை அணிய வேண்டும். இதன் மூலம் அவர்கள் ஜாஹிலிய்யா காலப் பெண்களிடமிருந்து வேறுபடுவார்கள். ஜாஹிலிய்யா காலப் பெண்கள் அவ்வாறு செய்யாமல், தங்கள் மார்புகள் முழுமையாகத் திறந்த நிலையில், கழுத்து, முன்நெற்றி முடி, கூந்தல் மற்றும் காதணிகள் வெளியே தெரியும்படி ஆண்களுக்கு முன்னால் கடந்து செல்வார்கள். எனவே, இறைநம்பிக்கையுள்ள பெண்கள் தங்களை மறைத்துக் கொள்ளுமாறு அல்லாஹ் கட்டளையிட்டான். அவன் கூறுவது போல:\n\r\n\n\r\nيأَيُّهَا النَّبِىُّ قُل لِّأَزْوَاجِكَ وَبَنَـتِكَ وَنِسَآءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَـبِيبِهِنَّ ذلِكَ أَدْنَى أَن يُعْرَفْنَ فَلاَ يُؤْذَيْنَ\n\r\n\n\r\n(நபியே! உமது மனைவிகளுக்கும், உமது புதல்விகளுக்கும், இறைநம்பிக்கை கொண்டவர்களின் பெண்களுக்கும் நீர் கூறுவீராக: அவர்கள் தங்கள் மேலாடைகளைத் தங்கள் மீது தாழ்த்திக் கொள்ளட்டும். அவர்கள் (ஒழுக்கமானவர்கள் என) அறியப்பட்டு, தொந்தரவு செய்யப்படாமல் இருக்க இதுவே மிக நெருக்கமான வழியாகும்) 33:59. இந்த மேன்மையான வசனத்தில் அவன் கூறினான்:\n\r\n\n\r\nوَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ\n\r\n\n\r\n(மேலும் தங்கள் (குமுர்) முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) 'குமுர்' (Khumur) என்பது 'கிமார்' (Khimar) என்பதன் பன்மையாகும். இதற்கு 'மறைப்பது' என்று பொருள். தலையை மறைக்கப் பயன்படுவதையே மக்கள் 'முக்காடு' என்கின்றனர். ஸயீத் பின் ஜுபைர் (ரழி) அவர்கள் கூறுகையில்:\n\r\n\n\r\nوَلْيَضْرِبْنَ\n\r\n\n\r\n(போட்டுக் கொள்ளட்டும்) என்பது, அதனைச் சுற்றிக் கொண்டு உறுதியாகக் கட்டிக் கொள்வதைக் குறிக்கும்.\n\r\n\n\r\nبِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ\n\r\n\n\r\n(தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) என்பது, தங்கள் கழுத்து மற்றும் மார்புப் பகுதிகள் தெரியாதவாறு அவற்றின் மேல் போட்டுக் கொள்ள வேண்டும் என்பதாகும். அன்னை ஆயிஷா (ரழி) அவர்கள் கூறியதாக புகாரி பதிவு செய்துள்ளார்கள்: \"ஆரம்ப காலத்தில் ஹிஜ்ரத் செய்த பெண்களுக்கு அல்லாஹ் அருள் புரியட்டும். 'வலியழ்ரிப்ன பிஹுமுரிஹின்ன அலா ஜுயூபிஹின்ன' என்ற வசனம் அருளப்பட்டபோது, அவர்கள் தங்கள் மேலாடைகளைக் கிழித்து அவற்றைக் கொண்டு முக்காடிட்டுக் கொண்டார்கள்.\" மேலும் ஸஃபிய்யா பின்த் ஷைபா (ரழி) அவர்கள் வழியாக ஆயிஷா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"இந்த வசனம்:\n\r\n\n\r\nوَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ\n\r\n\n\r\n(மேலும் தங்கள் முக்காடுகளைத் தங்கள் மார்புகளின் மேல் போட்டுக் கொள்ளட்டும்) அருளப்பட்டபோது, அவர்கள் தங்கள் இஸார்களை (இடுப்புத் துணிகளை) ஓரங்களில் கிழித்து, அவற்றைக் கொண்டு முக்காடிட்டுக் கொண்டார்கள்.\"\n\r\n\n\r\nوَلاَ يُبْدِينَ زِينَتَهُنَّ إِلاَّ لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِى إِخْوَانِهِنَّ أَوْ بَنِى أَخَوَاتِهِنَّ\n\r\n\n\r\n(மேலும் தங்கள் கணவர்கள், அல்லது தங்கள் தந்தையர்கள், அல்லது தங்கள் கணவர்களின் தந்தையர்கள், அல்லது தங்கள் புதல்வர்கள், அல்லது தங்கள் கணவர்களின் புதல்வர்கள், அல்லது தங்கள் சகோதரர்கள், அல்லது தங்கள் சகோதரர்களின் புதல்வர்கள், அல்லது தங்கள் சகோதரிகளின் புதல்வர்களைத் தவிர மற்றவர்களுக்குத் தங்கள் அலங்காரத்தை அவர்கள் வெளிப்படுத்த வேண்டாம்). இவர்கள் அனைவரும் ஒரு பெண்ணால் ஒருபோதும் திருமணம் செய்ய முடியாத நெருங்கிய உறவினர்கள் (மஹ்ரம்) ஆவர். இவர்களிடம் தன்னைத் தகாத முறையில் வெளிப்படுத்தாமல், சாதாரணமாகத் தனது அலங்காரங்களைக் காட்ட அனுமதியுண்டு. இப்னுல் முன்திர் அவர்கள் பதிவு செய்துள்ளார்கள்: இக்ரிமா (ரழி) அவர்கள் இந்த வசனத்திற்கு விளக்கமளிக்கையில்,\n\r\n\n\r\nوَلاَ يُبْدِينَ زِينَتَهُنَّ إِلاَّ لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ\n\r\n\n\r\n(மேலும் தங்கள் கணவர்கள், அல்லது தங்கள் தந்தையர்கள், அல்லது தங்கள் கணவர்களின் தந்தையர்களைத் தவிர மற்றவர்களுக்குத் தங்கள் அலங்காரத்தை அவர்கள் வெளிப்படுத்த வேண்டாம்...), \"தந்தையின் சகோதரரும், தாயின் சகோதரரும் இங்கு குறிப்பிடப்படவில்லை. ஏனெனில் அவர்கள் ஒரு பெண்ணின் அழகைத் தங்கள் மகன்களிடம் வர்ணிக்கக் கூடும். எனவே ஒரு பெண் தனது தந்தையின் சகோதரர் அல்லது தாயின் சகோதரருக்கு முன்னால் தனது முக்காடை (கிமார்) அகற்றக் கூடாது\" என்று கூறினார்கள். கணவரைப் பொறுத்தவரை, அலங்காரங்கள் அனைத்தும் அவருக்காகவே செய்யப்படுகின்றன. எனவே, மற்றவர்களுக்கு முன்னால் தோன்றுவதைப் போலல்லாமல், கணவருக்காகத் தன்னை அலங்கரிக்கும்போது அவள் மிகச் சிறந்த முறையில் இருக்க முயற்சிக்க வேண்டும்.\n\r\n\n\r\nأَوْ نِسَآئِهِنَّ\n\r\n\n\r\n(அல்லது தங்கள் பெண்கள்), இதன் பொருள், ஒரு பெண் மற்ற முஸ்லிம் பெண்களுக்கு முன்னால் தனது அலங்காரத்துடன் இருக்கலாம். ஆனால் அஹ்லுத் திம்மா (யூத, கிறிஸ்தவ) பெண்களுக்கு முன்னால் அவ்வாறு இருக்கக் கூடாது. ஏனெனில் அவர்கள் அந்தப் பெண்ணைத் தங்கள் கணவர்களிடம் வர்ணிக்கக் கூடும். இது அனைத்துப் பெண்களுக்கும் தடை செய்யப்பட்டிருந்தாலும், அஹ்லுத் திம்மா பெண்களின் விஷயத்தில் இன்னும் கடுமையானது. ஏனெனில் அவர்களைத் தடுக்க எதுவுமில்லை. ஆனால் முஸ்லிம் பெண்களுக்கு இது ஹராம் (விலக்கப்பட்டது) என்று தெரியும் என்பதால் அவர்கள் இதனைச் செய்ய மாட்டார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا تُبَاشِرِ الْمَرْأَةُ الْمَرْأَةَ فَتَنْعَتَهَا لِزَوْجِهَا كَأَنَّهُ يَنْظُرُ إِلَيْهَا»\n\r\n\n\r\n(எந்தப் பெண்ணும் மற்றொரு பெண்ணை அவளது கணவனிடம், அவன் நேரில் பார்ப்பது போன்ற உணர்வு ஏற்படும் அளவுக்கு வர்ணிக்க வேண்டாம்). இது இப்னு மஸ்ஊத் (ரழி) அவர்கள் வழியாக புகாரி, முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nأَوْ مَا مَلَكَتْ أَيْمَـنُهُنَّ\n\r\n\n\r\n(அல்லது அவர்களின் வலக்கரங்கள் சொந்தமாக்கிக் கொண்டவர்கள்.) இது இறைமறுப்பாளர்களான (முஷ்ரிக்) அடிமைப் பெண்களைக் குறிக்கும் என்று இப்னு ஜரீர் கூறுகிறார். ஒரு முஸ்லிம் பெண் இறைமறுப்பாளரான அடிமைப் பெண்ணுக்கு முன்னால் தனது அலங்காரத்தை வெளிப்படுத்துவது அனுமதிக்கப்பட்டுள்ளது. இது ஸயீத் பின் அல்-முஸய்யப் அவர்களின் கருத்தும் ஆகும். அல்லாஹ் கூறுகிறான்;\n\r\n\n\r\nأَوِ التَّـبِعِينَ غَيْرِ أُوْلِى الإِرْبَةِ مِنَ الرِّجَالِ\n\r\n\n\r\n(ஆண்களில் ஆசையற்ற பணியாளர்கள்,) அதாவது ஒரு பெண்ணுக்குச் சமமான நிலையில் இல்லாத, மனவளர்ச்சி குன்றிய அல்லது பெண்கள் மீது எந்த விருப்பமும் ஆசையுமற்ற பணியாளர்கள் மற்றும் ஏவலர்கள். இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இது எவ்வித ஆசையுமற்ற நபரை குறிக்கும்\" என்றார். இக்ரிமா (ரழி) அவர்கள், \"இது உணர்ச்சியற்ற அலி (திருநங்கை) போன்றோரைக் குறிக்கும்\" என்றார். இதுதான் முன்னோர்களின் (ஸலஃப்களின்) கருத்தாகும். ஸஹீஹ் நூலில் அன்னை ஆயிஷா (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஒரு திருநங்கை அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் இல்லத்திற்கு வருவது வழக்கம். அவரை ஆசையற்றவர்களில் ஒருவராகவே அனைவரும் கருதினர். ஆனால் ஒருமுறை அந்த நபர் ஒரு பெண்ணின் உடலமைப்பை பற்றி, \"அவள் முன்னோக்கி வரும்போது நான்கு (மடிப்புகளு)டனும், பின்னோக்கிச் செல்லும்போது எட்டு (மடிப்புகளு)டனும் தென்படுகிறாள்\" என்று வர்ணித்துக் கொண்டிருந்தபோது நபி (ஸல்) அவர்கள் அங்கு வந்தார்கள். உடனே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள்:\n\r\n\n\r\n«أَلَا أَرَى هَذَا يَعْلَمُ مَا هَهُنَا لَا يَدْخُلَنَّ عَلَيْكُمْ»\n\r\n\n\r\n(கவனிங்கள்! இவனுக்குப் பெண்களைப் பற்றிய விவரங்கள் தெரிந்திருக்கின்றன; இவன் இனி ஒருபோதும் உங்களிடம் நுழையக் கூடாது) என்று கூறினார்கள். அவர் அல்-பய்தா எனும் இடத்தில் தங்க வைக்கப்பட்டார். வெள்ளிக்கிழமைகளில் மட்டும் உணவு வாங்க வருவதற்கே அனுமதிக்கப்பட்டார்.\n\r\n\n\r\nأَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُواْ عَلَى عَوْرَتِ النِّسَآءِ\n\r\n\n\r\n(அல்லது பெண்களின் மறைவிடங்களைப் பற்றி அறியாத சிறுவர்கள்.) அவர்கள் மிகவும் சிறியவர்களாக இருப்பதால் பெண்களுக்குரிய அவ்ரா (மறைக்கப்பட வேண்டியவை), அவர்களின் மென்மையான பேச்சு அல்லது அவர்களின் கவர்ச்சியான நடை மற்றும் அசைவுகள் பற்றி எதுவும் புரியாதவர்கள். சிறு பிள்ளையாக இருந்து இவை எதனையும் புரிந்து கொள்ளவில்லை என்றால் அவர்கள் பெண்கள் பகுதிக்கு வருவதில் தவறில்லை. ஆனால் அவன் பருவ வயதை நெருங்கி இவற்றுக்கிடையிலான வேறுபாடுகளைப் புரிந்து கொள்ளும் நிலையில் இருந்தால், அவன் பெண்களிடம் நுழையக் கூடாது. புகாரி, முஸ்லிம் ஆகிய நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ»\n\r\n\n\r\n(பெண்கள் இருக்கும் இடத்திற்குள் நுழைவதைத் தவிர்ந்து கொள்ளுங்கள்). அப்போது, \"அல்லாஹ்வின் தூதரே! கணவனின் ஆண் உறவினர்களைப் பற்றித் தங்கள் கருத்து என்ன?\" என்று கேட்கப்பட்டது. அதற்கு அவர்கள்:\n\r\n\n\r\n«الْحَمْوُ: الْمَوْتُ»\n\r\n\n\r\n(கணவனின் ஆண் உறவினர் மரணத்திற்குச் சமமானவர்) என்று கூறினார்கள்.\n\r\n\n\r\nபெண்கள் தெருவில் நடப்பதற்கான ஒழுக்கங்கள்\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلاَ يَضْرِبْنَ بِأَرْجُلِهِنَّ\n\r\n\n\r\n(இன்னும் அவர்கள் தங்கள் மறைத்து வைத்துள்ள அலங்காரம் அறியப்பட வேண்டும் என்பதற்காகத் தங்கள் கால்களைத் தட்டி நடக்க வேண்டாம்...) அறியாமை (ஜாஹிலிய்யா) காலத்தில், பெண்கள் தாங்கள் அணிந்துள்ள கொலுசுகளின் சத்தம் கேட்க வேண்டும் என்பதற்காகத் தங்கள் கால்களைத் தட்டி நடப்பார்கள். இதனை அல்லாஹ் தடுத்தான். அதேபோல, மறைக்கப்பட்ட எந்த அலங்காரமும் வெளிப்படும் விதத்திலான அசைவுகளைச் செய்வதும் பெண்களுக்குத் தடை செய்யப்பட்டுள்ளது. ஏனெனில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلاَ يَضْرِبْنَ بِأَرْجُلِهِنَّ\n\r\n\n\r\n(இன்னும் அவர்கள் தங்கள் கால்களைத் தட்டி நடக்க வேண்டாம்...) இறுதி வரை. இதிலிருந்தே, பெண்கள் வீட்டை விட்டு வெளியே செல்லும்போது நறுமணம் அல்லது வாசனைத் திரவியங்கள் பூசிச் செல்வதும் தடை செய்யப்பட்டுள்ளது. ஏனெனில் ஆண்கள் அந்த வாசனையை நுகரக்கூடும். அபு மூஸா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كُلُّ عَيْنٍ زَانِيَةٌ، وَالْمَرْأَةُ إِذَا اسْتَعْطَرَتْ فَمَرَّتْ بِالْمَجْلِسِ فَهِيَ كَذَا وَكَذَا»\n\r\n\n\r\n(ஒவ்வொரு கண்ணும் விபச்சாரம் செய்கிறது. ஒரு பெண் வாசனைத் திரவியம் பூசிக்கொண்டு ஒரு சபையைக் கடந்து சென்றால், அவள் இன்னின்னவள்) - அதாவது விபச்சாரி ஆவாள். திர்மிதி இதனை 'ஹஸன் ஸஹீஹ்' என்று குறிப்பிட்டுள்ளார். அபு தாவூத் மற்றும் நஸயீயிலும் இது பதிவு செய்யப்பட்டுள்ளது. அதேபோல, பெண்கள் தெருவின் நடுப்பகுதியில் நடப்பதும் தடுக்கப்பட்டுள்ளது. அபு உஸைத் அல்-அன்சாரி (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதிலிருந்து வெளியே வந்தபோது, தெருவில் ஆண்களும் பெண்களும் கலந்து செல்வதைக் கண்டு பெண்களிடம் கூறினார்கள்:\n\r\n\n\r\n«اسْتَأْخِرْنَ فَإِنَّهُ لَيْسَ لَكُنَّ أَنْ تَحْقُقْنَ الطَّرِيقَ، عَلَيْكُنَّ بِحَافَّاتِ الطَّرِيقِ»\n\r\n\n\r\n(நீங்கள் பின்தங்கிச் செல்லுங்கள்; தெருவின் நடுப்பகுதியில் நடப்பதற்கு உங்களுக்கு அனுமதி இல்லை. நீங்கள் சாலையின் ஓரங்களையே பயன்படுத்த வேண்டும்). அதன் பிறகு பெண்கள் சுவரை ஒட்டியே செல்வார்கள். சில நேரங்களில் அவர்களின் மேலாடைகள் சுவரில் சிக்கிக் கொள்ளும் அளவுக்கு அவர்கள் ஒட்டிச் செல்வார்கள்.\n\r\n\n\r\nوَتُوبُواْ إِلَى اللَّهِ جَمِيعاً أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ\n\r\n\n\r\n(இறைநம்பிக்கையாளர்களே! நீங்கள் வெற்றி பெறுவதற்காக நீங்கள் அனைவரும் அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுங்கள்.) அதாவது, இந்த அழகான ஒழுக்கங்களையும் புகழுக்குரிய பண்புகளையும் கடைபிடியுங்கள். அறியாமை காலத்துத் தீய பழக்கங்களை விட்டுவிடுங்கள். அல்லாஹ்வும் அவனது தூதரும் கட்டளையிட்டதைச் செய்வதிலும், அவர்கள் தடுத்ததைத் தவிர்ப்பதிலுமே மகத்தான வெற்றி உள்ளது. அல்லாஹ்வே அனைத்து ஆற்றல்களுக்கும் ஊற்றுக்கண்ணாவான்."},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=34\" class=\"link\">24:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:34 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=34\" class=\"link\">24:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:34 ஐ பார்க்கவும்"},"34":{"html":"<strong>திருமணம் செய்வதற்கான கட்டளை</strong><br />\r\n<br />\r\nஇந்தத் தெளிவான வசனங்கள் (ஆயத்கள்), சந்தேகத்திற்கு இடமில்லாத சட்டங்களையும் உறுதியான கட்டளைகளையும் கொண்டுள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنْكِحُواْ</span> <span class=\"quran-arabic-font text-success\">الأَيَـمَى</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span><br />\r\n<br />\r\n(உங்களில் மணமாகாதவர்களுக்குத் திருமணம் செய்து வையுங்கள்...) இது திருமணம் செய்து கொள்வதற்கான ஒரு கட்டளையாகும். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الشَّبَابِ،</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَطَاعَ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْبَاءَةَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَتَزَوَّجْ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَغَضُّ</span> <span class=\"quran-arabic-font text-success\">لِلْبَصَرِ</span> <span class=\"quran-arabic-font text-success\">وَأَحْصَنُ</span> <span class=\"quran-arabic-font text-success\">لِلْفَرْجِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِعْ</span> <span class=\"quran-arabic-font text-success\">فَعَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">بِالصَّوْمِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وِجَاءٌ</span>»<br />\r\n<br />\r\n(வாலிபர்களே! உங்களில் எவருக்குத் திருமணம் செய்ய சக்தி இருக்கிறதோ அவர் மணம் முடித்துக் கொள்ளட்டும். ஏனெனில், அது பார்வையைக் கட்டுப்படுத்தவும், கற்பைப் பாதுகாக்கவும் மிகவும் சிறந்த வழியாகும். அதற்கு இயலாதவர் நோன்பு நோற்கட்டும்; ஏனெனில் அது அவரது இச்சையைக் கட்டுப்படுத்தும்.) இது இப்னு மஸ்ஊது (ரழி) அவர்கள் அறிவித்த ஹதீஸாக புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது. சுனன் நூல்களில், ஒன்றுக்கும் மேற்பட்டவர்களிடமிருந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تَزَوَّجُوا</span> <span class=\"quran-arabic-font text-success\">تَوَالَدُوا</span> <span class=\"quran-arabic-font text-success\">تَنَاسَلُوا</span> <span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">مُبَاهٍ</span> <span class=\"quran-arabic-font text-success\">بِكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأُمَمَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span>»<br />\r\n<br />\r\n(திருமணம் செய்து கொள்ளுங்கள், குழந்தைகளைப் பெற்று உங்கள் சந்ததிகளைப் பெருக்குங்கள்; ஏனெனில் மறுமை நாளில் மற்ற சமுதாயங்களுக்கு முன்னால் உங்களைக் கொண்டு நான் பெருமையடைவேன்.) 'அல்-அயாமா' (Al-Ayama) என்பது 'அய்யிம்' (Ayyim) என்பதன் பன்மையாகும். ஒரு ஆணுக்கு மனைவி இல்லையென்றாலோ அல்லது ஒரு பெண்ணுக்குக் கணவன் இல்லையென்றாலோ, அவர்கள் ஏற்கனவே மணம் முடித்துப் பிரிந்தவர்களாக இருந்தாலும் அல்லது இதுவரை மணம் முடிக்காதவர்களாக இருந்தாலும் அவர்களைக் குறிக்க இச்சொல் பயன்படுத்தப்படுகிறது. அல்-ஜவ்ஹரி அவர்கள் மொழி அறிஞர்களிடமிருந்து இதனை அறிவிக்கிறார்கள். இச்சொல் ஆண்களுக்கும் பெண்களுக்கும் சமமாகப் பொருந்தும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">فُقَرَآءَ</span> <span class=\"quran-arabic-font text-success\">يُغْنِهِمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ</span><br />\r\n<br />\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.) அலீ பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அல்லாஹ் அவர்களைத் திருமணம் செய்யத் தூண்டினான். சுதந்திரமானவர்களையும் அடிமைகளையும் திருமணம் செய்யக் கட்டளையிட்டதோடு, அவர்களைச் செல்வந்தர்களாக்குவதாகவும் வாக்களித்தான்.\"<br />\r\n<br />\r\nலைத் அவர்கள் அல்காஸிம் பின் முஹம்மது வழியாக அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் கூறினார்கள் என்று அறிவிக்கிறார்கள்: \"திருமணம் செய்துகொள்ளுங்கள் என்று அல்லாஹ் உங்களுக்கு இட்ட கட்டளைக்கு நீங்கள் கட்டுப்படுங்கள்; உங்களைச் செல்வந்தர்களாக்குவதாக அவன் உங்களுக்கு அளித்த வாக்குறுதியை அவன் நிறைவேற்றுவான்.\" பிறகு அவர் இவ்வசனத்தை ஓதிக் காட்டினார்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">فُقَرَآءَ</span> <span class=\"quran-arabic-font text-success\">يُغْنِهِمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ</span><br />\r\n<br />\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.) இப்னு மஸ்ஊது (ரழி) அவர்கள் கூறினார்கள்: \"திருமணத்தின் மூலம் செல்வத்தைத் தேடுங்கள்; ஏனெனில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">فُقَرَآءَ</span> <span class=\"quran-arabic-font text-success\">يُغْنِهِمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ</span><br />\r\n<br />\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.)\" இதனை இப்னு ஜரீர் பதிவு செய்துள்ளார். அல்-பஃகவி அவர்களும் உமர் (ரழி) அவர்களிடமிருந்து இது போன்ற ஒரு செய்தியைப் பதிவு செய்துள்ளார். அல்-லைத் அவர்கள் முஹம்மது பின் அஜ்லான் வழியாக, ஸயீத் அல்-மக்ஃபுரீ அவர்களிடமிருந்து, அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">ثَلَاثَةٌ</span> <span class=\"quran-arabic-font text-success\">حَقٌّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَوْنُهُمْ</span>: <span class=\"quran-arabic-font text-success\">النَّاكِحُ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">الْعَفَافَ،</span> <span class=\"quran-arabic-font text-success\">وَالْمُكَاتَبُ</span> <span class=\"quran-arabic-font text-success\">يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">الْأَدَاءَ،</span> <span class=\"quran-arabic-font text-success\">وَالْغَازِي</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span>»<br />\r\n<br />\r\n(மூன்று நபர்களுக்கு உதவி செய்வது அல்லாஹ்வின் மீது கடமையாகும்: கற்பைப் பேண விரும்பித் திருமணம் செய்பவர்; (தன் விடுதலையை விலைக்கு வாங்க) எஜமானருடன் ஒப்பந்தம் செய்து கொண்டு அதற்கான தொகையைச் செலுத்த முயற்சிக்கும் அடிமை; மற்றும் அல்லாஹ்வின் பாதையில் போர் புரிபவர்.) இதனை இமாம்கள் அஹ்மத், அத்-திர்மிதீ, அந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோர் பதிவு செய்துள்ளனர். நபி (ஸல்) அவர்கள், தன்னிடம் இடுப்புத் துணியைத் தவிர வேறொன்றும் இல்லாத, ஒரு இரும்பு மோதிரத்தைக்கூட வாங்க வசதியில்லாத ஒரு மனிதருக்குத் திருமணம் செய்து வைத்தார்கள். குர்ஆனில் அவருக்குத் தெரிந்த வசனங்களை அப்பெண்ணுக்குக் கற்பிப்பதையே மஹராக (அன்பளிப்பு) நிர்ணயித்துத் திருமணம் செய்து வைத்தார்கள். அல்லாஹ்வின் தாராளக் குணத்தாலும் கருணையாலும், அவருக்கும் அவருக்கும் போதுமான வாழ்வாதாரத்தை அல்லாஹ் வழங்கினான் என்பது யாவரும் அறிந்ததே.<br />\r\n<br />\r\n<strong>திருமணம் செய்ய இயலாதவர்கள் தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்வதற்கான கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَسْتَعْفِفِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَجِدُونَ</span> <span class=\"quran-arabic-font text-success\">نِكَاحاً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُغْنِيَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ</span><br />\r\n<br />\r\n(திருமணம் செய்ய வசதி பெறாதவர்கள், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்கும் வரை தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்ளட்டும்.) திருமணம் செய்ய வசதி இல்லாதவர்கள் தங்களைக் கற்புள்ளவர்களாக வைத்துக் கொள்ள வேண்டும் என்றும், விலக்கப்பட்ட காரியங்களைத் தவிர்க்க வேண்டும் என்றும் அல்லாஹ் கட்டளையிடுகிறான். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">الشَّبَابِ</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اسْتَطَاعَ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمُ</span> <span class=\"quran-arabic-font text-success\">الْبَاءَةَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَتَزَوَّجْ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَغَضُّ</span> <span class=\"quran-arabic-font text-success\">لِلْبَصَرِ</span> <span class=\"quran-arabic-font text-success\">وَأَحْصَنُ</span> <span class=\"quran-arabic-font text-success\">لِلْفَرْجِ،</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِعْ</span> <span class=\"quran-arabic-font text-success\">فَعَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">بِالصَّوْمِ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">وِجَاءٌ</span>»<br />\r\n<br />\r\n(வாலிபர்களே! உங்களில் எவருக்குத் திருமணம் செய்ய சக்தி இருக்கிறதோ அவர் மணம் முடித்துக் கொள்ளட்டும். ஏனெனில், அது பார்வையைக் கட்டுப்படுத்தவும், கற்பைப் பாதுகாக்கவும் மிகவும் சிறந்த வழியாகும். அதற்கு இயலாதவர் நோன்பு நோற்கட்டும்; ஏனெனில் அது அவரது இச்சையைக் கட்டுப்படுத்தும்.) இந்த வசனம் பொதுவான பொருளைக் கொண்டது. ஆனால் சூரத்து அந்-நிஸாவில் உள்ள வசனம் இன்னும் குறிப்பிட்ட பொருளைக் குறிக்கிறது. அங்கு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِعْ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">طَوْلاً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَنكِحَ</span> <span class=\"quran-arabic-font text-success\">الْمُحْصَنَـتِ</span><br />\r\n<br />\r\n(உங்களில் எவரேனும் சுதந்திரமான முஃமினான பெண்களைத் திருமணம் செய்து கொள்ள வசதி பெறவில்லையென்றால்...) என்று தொடங்கி,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَن</span> <span class=\"quran-arabic-font text-success\">تَصْبِرُواْ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span><br />\r\n<br />\r\n(ஆயினும் நீங்கள் பொறுமையாக இருப்பது உங்களுக்கு மிகச் சிறந்ததாகும்) (<a href=\"qurandisp.php?sura=4&ayah=25\" class=\"link\">4:25</a>) என்று கூறுகிறான். அதாவது, அடிமைப் பெண்களைத் திருமணம் செய்வதைத் தவிர்த்து நீங்கள் பொறுமையாக இருப்பது நல்லது; ஏனெனில் பிறக்கும் குழந்தை அடிமையாகவே இருக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்) (<a href=\"qurandisp.php?sura=4&ayah=25\" class=\"link\">4:25</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلْيَسْتَعْفِفِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَجِدُونَ</span> <span class=\"quran-arabic-font text-success\">نِكَاحاً</span><br />\r\n<br />\r\n(திருமணம் செய்ய வசதி பெறாதவர்கள் தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்ளட்டும்.) இக்ரிமா (ரழி) அவர்கள் கூறுகிறார்கள்: \"இது ஒரு பெண்ணைப் பார்த்து இச்சை கொள்ளும் மனிதரைக் குறிக்கும்; அவருக்கு மனைவி இருந்தால் அவரிடம் சென்று தனது தாம்பத்திய உறவை நிறைவேற்றிக் கொள்ளட்டும். அவருக்கு மனைவி இல்லையென்றால், அல்லாஹ் அவருக்கு வாழ்வாதாரத்தை வழங்கும் வரை வானங்கள் மற்றும் பூமியின் ஆட்சியைக் குறித்துச் சிந்திக்கட்டும்.\"<br />\r\n<br />\r\n<strong>அடிமைகளுக்கு விடுதலை ஒப்பந்தம் வழங்குவதற்கான கட்டளை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَبْتَغُونَ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَـنُكُمْ</span> <span class=\"quran-arabic-font text-success\">فَكَـتِبُوهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِمْ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span><br />\r\n<br />\r\n(உங்கள் அடிமைகளில் எவரேனும் (விடுதலைக்கான) ஒப்பந்தம் நாடினால், அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால் அதனை அவர்களுக்கு எழுதிக்கொடுங்கள்.) இது அடிமையின் எஜமானர்களுக்கு அல்லாஹ் இடும் கட்டளையாகும்: தங்கள் அடிமைகள் விடுதலை ஒப்பந்தம் (கிதாபா) கேட்டால், அவர்களுக்கு உழைக்கும் திறனும், சம்பாதித்து எஜமானருக்குரிய தொகையைச் செலுத்தும் வசதியும் இருப்பதாகத் தெரிந்தால், எஜமானர்கள் அந்த ஒப்பந்தத்தைச் செய்து கொடுக்க வேண்டும். அல்-புகாரி அவர்கள் கூறுகிறார்கள்: \"ரவ்ஹ் அவர்கள் இப்னு ஜுரைஜ் வழியாக அறிவிக்கிறார்கள்: நான் அதா அவர்களிடம், 'எனது அடிமையிடம் பணம் இருப்பது எனக்குத் தெரிந்தால், அவனுக்கு விடுதலை ஒப்பந்தம் எழுதிக் கொடுப்பது என் மீது கட்டாயமா?' என்று கேட்டேன். அதற்கு அவர், 'அது கட்டாயமாகவே இருக்கும் என்று நான் கருதுகிறேன்' என்றார்.\" அம்ர் பின் தீனார் அவர்கள் கூறுகிறார்கள்: \"நான் அதா அவர்களிடம், 'இதனை நீங்கள் யாரிடமாவது அறிவிக்கிறீர்களா?' என்று கேட்டேன். அதற்கு அவர் 'இல்லை' என்று கூறிவிட்டு, மூஸா பின் அனஸ் அறிவித்த ஒரு செய்தியைக் கூறினார்: நிறைய செல்வம் வைத்திருந்த ஸிரீன் என்பவர், அனஸ் (ரழி) அவர்களிடம் விடுதலை ஒப்பந்தம் கேட்டார். அனஸ் (ரழி) அவர்கள் மறுத்துவிட்டார்கள். உடனே அவர் உமர் (பின் அல்-கத்தாப்) (ரழி) அவர்களிடம் சென்றார். உமர் (ரழி) அவர்கள், 'அவருக்கு ஒப்பந்தம் எழுதிக் கொடுங்கள்' என்று கூறினார்கள். மீண்டும் அனஸ் (ரழி) அவர்கள் மறுத்தபோது, உமர் (ரழி) அவர்கள் சாட்டையால் அடித்து, பின்வரும் வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَكَـتِبُوهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِمْ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span><br />\r\n<br />\r\n(அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால் அதனை அவர்களுக்கு எழுதிக்கொடுங்கள்.) அதன் பிறகு அனஸ் (ரழி) அவர்கள் ஒப்பந்தம் எழுதினார்கள்.\" இது புகாரியில் துண்டிக்கப்பட்ட (முஅல்லக்) அறிவிப்பாளர் தொடருடன் கூறப்பட்டுள்ளது. அப்துர் ரஸ்ஸாக் அவர்களும் இதனை அறிவித்து, இப்னு ஜுரைஜ் வழியாக அதா அவர்கள் 'இது கட்டாயம்' என்று கூறியதைக் குறிப்பிடுகிறார்கள். இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ள செய்தியில், ஸிரீன் அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்களிடம் ஒப்பந்தம் கோரியபோது அவர் தாமதப்படுத்தினார், பின்னர் உமர் (ரழி) அவர்கள் \"நிச்சயமாக நீங்கள் அவருக்கு ஒப்பந்தம் எழுதிக் கொடுக்க வேண்டும்\" என்று வலியுறுத்தினார்கள். இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும். அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِمْ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span><br />\r\n<br />\r\n(அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால்.) இதற்கு 'நம்பகத்தன்மை' என்று சிலர் பொருள் கூறுகின்றனர். சிலர் 'நேர்மை' என்றும், மற்றவர்கள் 'சம்பாதிக்கும் திறனும் ஆற்றலும்' என்றும் கூறுகின்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَاتُوهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّالِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ءَاتَـكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுக்கு வழங்கியிருக்கும் அவனது செல்வத்திலிருந்து அவர்களுக்குக் கொடுங்கள்.) இது அல்லாஹ் அவர்களுக்கு உரிமையாக்கியுள்ள ஜகாத் நிதியைக் குறிக்கும். இது அல்-ஹஸன், அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம், அவரது தந்தை மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோரின் கருத்தாகும். இப்னு ஜரீர் அவர்களும் இக்கருத்தையே ஆதரிக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَءَاتُوهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّالِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ءَاتَـكُمْ</span><br />\r\n<br />\r\n(அல்லாஹ் உங்களுக்கு வழங்கியிருக்கும் அவனது செல்வத்திலிருந்து அவர்களுக்குக் கொடுங்கள்.) இப்ராஹீம் அந்-நகஈ அவர்கள் கூறுகிறார்கள், \"இது எஜமானர்களுக்கும் மற்ற மக்களுக்கும் அவர்களை விடுவிக்கத் தூண்டுவதாகும்.\" இது புரைதா பின் அல்-ஹுஸைப் அல்-அஸ்லமீ மற்றும் கதாதா ஆகியோரின் கருத்தாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அடிமைகளை விடுவிக்க உதவுமாறு அல்லாஹ் முஃமின்களுக்குக் கட்டளையிட்டுள்ளான்.\"<br />\r\n<br />\r\n<strong>அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு வற்புறுத்துவதற்கான தடை </strong><br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكْرِهُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَيَـتِكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبِغَآءِ</span><br />\r\n<br />\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்...) ஜாஹிலிய்யா காலத்தில் சிலர், தங்களிடம் உள்ள அடிமைப் பெண்ணை விபச்சாரம் செய்ய அனுப்பி, அதன் மூலம் கிடைக்கும் பணத்தை வாங்கிக் கொள்வார்கள். இஸ்லாம் வந்த பிறகு, அல்லாஹ் இதனை முஃமின்களுக்குத் தடை செய்தான். இந்த வசனம் அருளப்பட்டதற்கான காரணம், அப்துல்லாஹ் பின் உபை பின் சலூல் என்பவரைப் பற்றியது என்று தஃப்ஸீர் அறிஞர்கள் குறிப்பிடுகின்றனர். அவன் தன் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தி அதன் மூலம் வருமானம் ஈட்டி வந்தான். மேலும் அவர்கள் மூலம் பிறக்கும் குழந்தைகள் தனது அந்தஸ்தை உயர்த்தும் என்றும் வாதிட்டான்.<br />\r\n<br />\r\n<strong>இது குறித்து அறிவிக்கப்பட்டுள்ள செய்திகள்</strong><br />\r\n<br />\r\nஅல்-ஹாஃபிழ் அபூபக்ர் அஹ்மத் பின் அம்ர் பின் அப்தில் காலிக் அல்-பஸ்ஸார் (ரஹ்) அவர்கள் தனது முஸ்னதில் பின்வருமாறு பதிவு செய்துள்ளார்கள்: அஸ்-ஸுஹ்ரீ அவர்கள் கூறுகிறார்கள், \"அப்துல்லாஹ் பின் உபை பின் சலூலிடம் முஆதா என்ற அடிமைப் பெண் இருந்தாள். அவளை அவன் விபச்சாரம் செய்ய வற்புறுத்தினான். இஸ்லாம் வந்தபோது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكْرِهُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَيَـتِكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبِغَآءِ</span><br />\r\n<br />\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்...) என்ற வசனம் அருளப்பட்டது.\" அல்-அஃமஷ் வழியாக அபூ ஸுஃப்யான் கூறுகிறார்கள்: ஜாபிர் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி கூறுகையில், \"அப்துல்லாஹ் பின் உபை பின் சலூலின் அடிமைப் பெண்ணான முஸைக்கா என்பவரைப் பற்றி இது அருளப்பட்டது. அவளை அவன் ஒழுக்கக்கேடான செயல்களுக்கு வற்புறுத்தினான். ஆனால் அவள் தூய்மையானவளாக இருந்து அதனை மறுத்து வந்தாள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكْرِهُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَيَـتِكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبِغَآءِ</span><br />\r\n<br />\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்,)\" என்று தொடங்கி,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُكْرِههُنَّ</span> <span class=\"quran-arabic-font text-success\">فِإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">إِكْرَاهِهِنَّ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(ஆனால் எவரேனும் அவர்களைக் கட்டாயப்படுத்தினால், அத்தகைய வற்புறுத்தலுக்குப் பின் அல்லாஹ் (அப்பெண்களை) மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்.)\" அந்-நஸாயீயிலும் இது போன்ற செய்தி பதிவாகியுள்ளது. முகாத்தில் பின் ஹய்யான் கூறுகிறார்கள், \"நான் கேள்விப்பட்ட வரையில் - அல்லாஹ்வே மிக அறிந்தவன் - இந்த வசனம் இருவரைப் பற்றி அருளப்பட்டது. அவர்கள் தங்கள் அடிமைப் பெண்களை விபச்சாரத்திற்கு வற்புறுத்தினர். ஒரு அடிமைப் பெண் அன்சாரிகளுக்குச் சொந்தமான முஸைக்கா. மற்றொன்று முஸைக்காவின் தாயார் உமைமா, இவர் அப்துல்லாஹ் பின் உபை என்பவனுக்குச் சொந்தமானவர். முஆதா மற்றும் அர்வாவும் அதே நிலையில் இருந்தனர். முஸைக்காவும் அவளது தாயும் நபி (ஸல்) அவர்களிடம் வந்து இது குறித்து முறையிட்டனர். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُكْرِهُواْ</span> <span class=\"quran-arabic-font text-success\">فَتَيَـتِكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبِغَآءِ</span><br />\r\n<br />\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்), அதாவது விபச்சாரத்தில் (Zina).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَرَدْنَ</span> <span class=\"quran-arabic-font text-success\">تَحَصُّناً</span><br />\r\n<br />\r\n(அவர்கள் கற்பைப் பேண விரும்பினால்,) அதாவது, அவர்கள் ஒழுக்கமாக இருக்க விரும்பினால். பெரும்பாலான அடிமைப் பெண்களின் நிலை இதுவே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّتَبْتَغُواْ</span> <span class=\"quran-arabic-font text-success\">عَرَضَ</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span><br />\r\n<br />\r\n(இவ்வுலக வாழ்வின் சொற்ப லாபத்தைத் தேடுவதற்காக.) அதாவது, அவர்கள் சம்பாதிக்கும் பணம் மற்றும் அவர்கள் மூலம் கிடைக்கும் குழந்தைகள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரத்தம் குத்தி எடுப்பவர், விபச்சாரி மற்றும் குறி சொல்பவர் ஆகியோரின் வருமானத்தைத் தடை செய்துள்ளார்கள். மற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَهْرُ</span> <span class=\"quran-arabic-font text-success\">الْبَغِيِّ</span> <span class=\"quran-arabic-font text-success\">خَبِيثٌ</span> <span class=\"quran-arabic-font text-success\">وَكَسْبُ</span> <span class=\"quran-arabic-font text-success\">الْحَجَّامِ</span> <span class=\"quran-arabic-font text-success\">خَبِيثٌ،</span> <span class=\"quran-arabic-font text-success\">وَثَمَنُ</span> <span class=\"quran-arabic-font text-success\">الْكَلْبِ</span> <span class=\"quran-arabic-font text-success\">خَبِيثٌ</span>»<br />\r\n<br />\r\n(விபச்சாரியின் சம்பாத்தியம் தீயது, இரத்தம் குத்தி எடுப்பவரின் வருமானம் தீயது, மற்றும் நாயின் விலை தீயது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يُكْرِههُنَّ</span> <span class=\"quran-arabic-font text-success\">فِإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">إِكْرَاهِهِنَّ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(ஆனால் எவரேனும் அவர்களைக் கட்டாயப்படுத்தினால், அத்தகைய வற்புறுத்தலுக்குப் பின் அல்லாஹ் மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்.) அதாவது, ஜாபிர் (ரழி) அவர்கள் அறிவித்த ஹதீஸாக உள்ளபடி, அவர்கள் மீது அல்லாஹ் கருணை காட்டுவான். இப்னு அபீ தல்ஹா வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகிறார்கள், \"நீங்கள் அவ்வாறு வற்புறுத்தினால், அல்லாஹ் (அப்பெண்களை) மன்னிப்பவனாகவும் கருணையாளனாகவும் இருக்கிறான்; அந்தப் பாவம் அவர்களைக் கட்டாயப்படுத்தியவர் மீதே சாரும்.\" இது முஜாஹித், அதா அல்-குராஸானீ, அல்-அஃமஷ் மற்றும் கதாதா ஆகியோரின் கருத்தாகும். இந்தச் சட்டங்களை விரிவாக விளக்கிய பிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَنْزَلْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتٍ</span> <span class=\"quran-arabic-font text-success\">مُّبَيِّنَـتٍ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் உங்களுக்குத் தெளிவான வசனங்களை (ஆயத்களை) அருளியுள்ளோம்.) அதாவது, குர்ஆனில் விஷயங்களை விரிவாக விளக்கும் தெளிவான வசனங்கள் உள்ளன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَثَلاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">خَلَوْاْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكُمْ</span><br />\r\n<br />\r\n(உங்களுக்கு முன் வாழ்ந்து சென்றவர்களின் உதாரணங்களையும்,) அதாவது முந்தைய சமுதாயங்களைப் பற்றிய செய்திகள் மற்றும் அவர்கள் அல்லாஹ்வின் கட்டளைகளை மீறியபோது அவர்களுக்கு ஏற்பட்ட நிலைகள். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">سَلَفاً</span> <span class=\"quran-arabic-font text-success\">وَمَثَلاً</span> <span class=\"quran-arabic-font text-success\">لِّلاٌّخِرِينَ</span><br />\r\n<br />\r\n(எனவே நாம் அவர்களைப் பிற்காலத்தவருக்கு ஒரு முன்னோடியாகவும், உதாரணமாகவும் ஆக்கினோம்.) (<a href=\"qurandisp.php?sura=43&ayah=56\" class=\"link\">43:56</a>); நாம் அவர்களை ஒரு பாடமாக, அதாவது பாவங்களையும் விலக்கப்பட்ட செயல்களையும் செய்வதற்கான கண்டனமாக ஆக்கினோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَوْعِظَةً</span> <span class=\"quran-arabic-font text-success\">لِّلْمُتَّقِينَ</span><br />\r\n<br />\r\n(மேலும் இது தக்வா (இறையச்சம்) உடையவர்களுக்கு ஓர் உபதேசமாகும்.) அதாவது அல்லாஹ்வை நினைவு கூர்ந்து அவனுக்கு அஞ்சுபவர்களுக்கு.<br />\r\n<br />","text":"திருமணம் செய்வதற்கான கட்டளை\n\r\n\n\r\nஇந்தத் தெளிவான வசனங்கள் (ஆயத்கள்), சந்தேகத்திற்கு இடமில்லாத சட்டங்களையும் உறுதியான கட்டளைகளையும் கொண்டுள்ளன.\n\r\n\n\r\nوَأَنْكِحُواْ الأَيَـمَى مِنْكُمْ\n\r\n\n\r\n(உங்களில் மணமாகாதவர்களுக்குத் திருமணம் செய்து வையுங்கள்...) இது திருமணம் செய்து கொள்வதற்கான ஒரு கட்டளையாகும். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا مَعْشَرَ الشَّبَابِ، مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ وِجَاءٌ»\n\r\n\n\r\n(வாலிபர்களே! உங்களில் எவருக்குத் திருமணம் செய்ய சக்தி இருக்கிறதோ அவர் மணம் முடித்துக் கொள்ளட்டும். ஏனெனில், அது பார்வையைக் கட்டுப்படுத்தவும், கற்பைப் பாதுகாக்கவும் மிகவும் சிறந்த வழியாகும். அதற்கு இயலாதவர் நோன்பு நோற்கட்டும்; ஏனெனில் அது அவரது இச்சையைக் கட்டுப்படுத்தும்.) இது இப்னு மஸ்ஊது (ரழி) அவர்கள் அறிவித்த ஹதீஸாக புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹ்களிலும் இடம்பெற்றுள்ளது. சுனன் நூல்களில், ஒன்றுக்கும் மேற்பட்டவர்களிடமிருந்து அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«تَزَوَّجُوا تَوَالَدُوا تَنَاسَلُوا فَإِنِّي مُبَاهٍ بِكُمُ الْأُمَمَ يَوْمَ الْقِيَامَةِ»\n\r\n\n\r\n(திருமணம் செய்து கொள்ளுங்கள், குழந்தைகளைப் பெற்று உங்கள் சந்ததிகளைப் பெருக்குங்கள்; ஏனெனில் மறுமை நாளில் மற்ற சமுதாயங்களுக்கு முன்னால் உங்களைக் கொண்டு நான் பெருமையடைவேன்.) 'அல்-அயாமா' (Al-Ayama) என்பது 'அய்யிம்' (Ayyim) என்பதன் பன்மையாகும். ஒரு ஆணுக்கு மனைவி இல்லையென்றாலோ அல்லது ஒரு பெண்ணுக்குக் கணவன் இல்லையென்றாலோ, அவர்கள் ஏற்கனவே மணம் முடித்துப் பிரிந்தவர்களாக இருந்தாலும் அல்லது இதுவரை மணம் முடிக்காதவர்களாக இருந்தாலும் அவர்களைக் குறிக்க இச்சொல் பயன்படுத்தப்படுகிறது. அல்-ஜவ்ஹரி அவர்கள் மொழி அறிஞர்களிடமிருந்து இதனை அறிவிக்கிறார்கள். இச்சொல் ஆண்களுக்கும் பெண்களுக்கும் சமமாகப் பொருந்தும்.\n\r\n\n\r\nإِن يَكُونُواْ فُقَرَآءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ\n\r\n\n\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.) அலீ பின் அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அல்லாஹ் அவர்களைத் திருமணம் செய்யத் தூண்டினான். சுதந்திரமானவர்களையும் அடிமைகளையும் திருமணம் செய்யக் கட்டளையிட்டதோடு, அவர்களைச் செல்வந்தர்களாக்குவதாகவும் வாக்களித்தான்.\"\n\r\n\n\r\nலைத் அவர்கள் அல்காஸிம் பின் முஹம்மது வழியாக அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் கூறினார்கள் என்று அறிவிக்கிறார்கள்: \"திருமணம் செய்துகொள்ளுங்கள் என்று அல்லாஹ் உங்களுக்கு இட்ட கட்டளைக்கு நீங்கள் கட்டுப்படுங்கள்; உங்களைச் செல்வந்தர்களாக்குவதாக அவன் உங்களுக்கு அளித்த வாக்குறுதியை அவன் நிறைவேற்றுவான்.\" பிறகு அவர் இவ்வசனத்தை ஓதிக் காட்டினார்:\n\r\n\n\r\nإِن يَكُونُواْ فُقَرَآءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ\n\r\n\n\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.) இப்னு மஸ்ஊது (ரழி) அவர்கள் கூறினார்கள்: \"திருமணத்தின் மூலம் செல்வத்தைத் தேடுங்கள்; ஏனெனில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِن يَكُونُواْ فُقَرَآءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِ\n\r\n\n\r\n(அவர்கள் ஏழைகளாக இருந்தால், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்குவான்.)\" இதனை இப்னு ஜரீர் பதிவு செய்துள்ளார். அல்-பஃகவி அவர்களும் உமர் (ரழி) அவர்களிடமிருந்து இது போன்ற ஒரு செய்தியைப் பதிவு செய்துள்ளார். அல்-லைத் அவர்கள் முஹம்மது பின் அஜ்லான் வழியாக, ஸயீத் அல்-மக்ஃபுரீ அவர்களிடமிருந்து, அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«ثَلَاثَةٌ حَقٌّ عَلَى اللهِ عَوْنُهُمْ: النَّاكِحُ يُرِيدُ الْعَفَافَ، وَالْمُكَاتَبُ يُرِيدُ الْأَدَاءَ، وَالْغَازِي فِي سَبِيلِ اللهِ»\n\r\n\n\r\n(மூன்று நபர்களுக்கு உதவி செய்வது அல்லாஹ்வின் மீது கடமையாகும்: கற்பைப் பேண விரும்பித் திருமணம் செய்பவர்; (தன் விடுதலையை விலைக்கு வாங்க) எஜமானருடன் ஒப்பந்தம் செய்து கொண்டு அதற்கான தொகையைச் செலுத்த முயற்சிக்கும் அடிமை; மற்றும் அல்லாஹ்வின் பாதையில் போர் புரிபவர்.) இதனை இமாம்கள் அஹ்மத், அத்-திர்மிதீ, அந்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோர் பதிவு செய்துள்ளனர். நபி (ஸல்) அவர்கள், தன்னிடம் இடுப்புத் துணியைத் தவிர வேறொன்றும் இல்லாத, ஒரு இரும்பு மோதிரத்தைக்கூட வாங்க வசதியில்லாத ஒரு மனிதருக்குத் திருமணம் செய்து வைத்தார்கள். குர்ஆனில் அவருக்குத் தெரிந்த வசனங்களை அப்பெண்ணுக்குக் கற்பிப்பதையே மஹராக (அன்பளிப்பு) நிர்ணயித்துத் திருமணம் செய்து வைத்தார்கள். அல்லாஹ்வின் தாராளக் குணத்தாலும் கருணையாலும், அவருக்கும் அவருக்கும் போதுமான வாழ்வாதாரத்தை அல்லாஹ் வழங்கினான் என்பது யாவரும் அறிந்ததே.\n\r\n\n\r\nதிருமணம் செய்ய இயலாதவர்கள் தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்வதற்கான கட்டளை\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلْيَسْتَعْفِفِ الَّذِينَ لاَ يَجِدُونَ نِكَاحاً حَتَّى يُغْنِيَهُمُ اللَّهُ مِن فَضْلِهِ\n\r\n\n\r\n(திருமணம் செய்ய வசதி பெறாதவர்கள், அல்லாஹ் தனது அருளால் அவர்களைச் செல்வந்தர்களாக்கும் வரை தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்ளட்டும்.) திருமணம் செய்ய வசதி இல்லாதவர்கள் தங்களைக் கற்புள்ளவர்களாக வைத்துக் கொள்ள வேண்டும் என்றும், விலக்கப்பட்ட காரியங்களைத் தவிர்க்க வேண்டும் என்றும் அல்லாஹ் கட்டளையிடுகிறான். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا مَعْشَرَ الشَّبَابِ مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ، وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ وِجَاءٌ»\n\r\n\n\r\n(வாலிபர்களே! உங்களில் எவருக்குத் திருமணம் செய்ய சக்தி இருக்கிறதோ அவர் மணம் முடித்துக் கொள்ளட்டும். ஏனெனில், அது பார்வையைக் கட்டுப்படுத்தவும், கற்பைப் பாதுகாக்கவும் மிகவும் சிறந்த வழியாகும். அதற்கு இயலாதவர் நோன்பு நோற்கட்டும்; ஏனெனில் அது அவரது இச்சையைக் கட்டுப்படுத்தும்.) இந்த வசனம் பொதுவான பொருளைக் கொண்டது. ஆனால் சூரத்து அந்-நிஸாவில் உள்ள வசனம் இன்னும் குறிப்பிட்ட பொருளைக் குறிக்கிறது. அங்கு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلاً أَن يَنكِحَ الْمُحْصَنَـتِ\n\r\n\n\r\n(உங்களில் எவரேனும் சுதந்திரமான முஃமினான பெண்களைத் திருமணம் செய்து கொள்ள வசதி பெறவில்லையென்றால்...) என்று தொடங்கி,\n\r\n\n\r\nوَأَن تَصْبِرُواْ خَيْرٌ لَّكُمْ\n\r\n\n\r\n(ஆயினும் நீங்கள் பொறுமையாக இருப்பது உங்களுக்கு மிகச் சிறந்ததாகும்) (4:25) என்று கூறுகிறான். அதாவது, அடிமைப் பெண்களைத் திருமணம் செய்வதைத் தவிர்த்து நீங்கள் பொறுமையாக இருப்பது நல்லது; ஏனெனில் பிறக்கும் குழந்தை அடிமையாகவே இருக்கும்.\n\r\n\n\r\nوَاللَّهُ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்) (4:25).\n\r\n\n\r\nوَلْيَسْتَعْفِفِ الَّذِينَ لاَ يَجِدُونَ نِكَاحاً\n\r\n\n\r\n(திருமணம் செய்ய வசதி பெறாதவர்கள் தங்களைக் கற்புள்ளவர்களாகப் பேணிக் கொள்ளட்டும்.) இக்ரிமா (ரழி) அவர்கள் கூறுகிறார்கள்: \"இது ஒரு பெண்ணைப் பார்த்து இச்சை கொள்ளும் மனிதரைக் குறிக்கும்; அவருக்கு மனைவி இருந்தால் அவரிடம் சென்று தனது தாம்பத்திய உறவை நிறைவேற்றிக் கொள்ளட்டும். அவருக்கு மனைவி இல்லையென்றால், அல்லாஹ் அவருக்கு வாழ்வாதாரத்தை வழங்கும் வரை வானங்கள் மற்றும் பூமியின் ஆட்சியைக் குறித்துச் சிந்திக்கட்டும்.\"\n\r\n\n\r\nஅடிமைகளுக்கு விடுதலை ஒப்பந்தம் வழங்குவதற்கான கட்டளை\n\r\n\n\r\nوَالَّذِينَ يَبْتَغُونَ الْكِتَـبَ مِمَّا مَلَكَتْ أَيْمَـنُكُمْ فَكَـتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْراً\n\r\n\n\r\n(உங்கள் அடிமைகளில் எவரேனும் (விடுதலைக்கான) ஒப்பந்தம் நாடினால், அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால் அதனை அவர்களுக்கு எழுதிக்கொடுங்கள்.) இது அடிமையின் எஜமானர்களுக்கு அல்லாஹ் இடும் கட்டளையாகும்: தங்கள் அடிமைகள் விடுதலை ஒப்பந்தம் (கிதாபா) கேட்டால், அவர்களுக்கு உழைக்கும் திறனும், சம்பாதித்து எஜமானருக்குரிய தொகையைச் செலுத்தும் வசதியும் இருப்பதாகத் தெரிந்தால், எஜமானர்கள் அந்த ஒப்பந்தத்தைச் செய்து கொடுக்க வேண்டும். அல்-புகாரி அவர்கள் கூறுகிறார்கள்: \"ரவ்ஹ் அவர்கள் இப்னு ஜுரைஜ் வழியாக அறிவிக்கிறார்கள்: நான் அதா அவர்களிடம், 'எனது அடிமையிடம் பணம் இருப்பது எனக்குத் தெரிந்தால், அவனுக்கு விடுதலை ஒப்பந்தம் எழுதிக் கொடுப்பது என் மீது கட்டாயமா?' என்று கேட்டேன். அதற்கு அவர், 'அது கட்டாயமாகவே இருக்கும் என்று நான் கருதுகிறேன்' என்றார்.\" அம்ர் பின் தீனார் அவர்கள் கூறுகிறார்கள்: \"நான் அதா அவர்களிடம், 'இதனை நீங்கள் யாரிடமாவது அறிவிக்கிறீர்களா?' என்று கேட்டேன். அதற்கு அவர் 'இல்லை' என்று கூறிவிட்டு, மூஸா பின் அனஸ் அறிவித்த ஒரு செய்தியைக் கூறினார்: நிறைய செல்வம் வைத்திருந்த ஸிரீன் என்பவர், அனஸ் (ரழி) அவர்களிடம் விடுதலை ஒப்பந்தம் கேட்டார். அனஸ் (ரழி) அவர்கள் மறுத்துவிட்டார்கள். உடனே அவர் உமர் (பின் அல்-கத்தாப்) (ரழி) அவர்களிடம் சென்றார். உமர் (ரழி) அவர்கள், 'அவருக்கு ஒப்பந்தம் எழுதிக் கொடுங்கள்' என்று கூறினார்கள். மீண்டும் அனஸ் (ரழி) அவர்கள் மறுத்தபோது, உமர் (ரழி) அவர்கள் சாட்டையால் அடித்து, பின்வரும் வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nفَكَـتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْراً\n\r\n\n\r\n(அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால் அதனை அவர்களுக்கு எழுதிக்கொடுங்கள்.) அதன் பிறகு அனஸ் (ரழி) அவர்கள் ஒப்பந்தம் எழுதினார்கள்.\" இது புகாரியில் துண்டிக்கப்பட்ட (முஅல்லக்) அறிவிப்பாளர் தொடருடன் கூறப்பட்டுள்ளது. அப்துர் ரஸ்ஸாக் அவர்களும் இதனை அறிவித்து, இப்னு ஜுரைஜ் வழியாக அதா அவர்கள் 'இது கட்டாயம்' என்று கூறியதைக் குறிப்பிடுகிறார்கள். இப்னு ஜரீர் அவர்கள் பதிவு செய்துள்ள செய்தியில், ஸிரீன் அவர்கள் அனஸ் பின் மாலிக் (ரழி) அவர்களிடம் ஒப்பந்தம் கோரியபோது அவர் தாமதப்படுத்தினார், பின்னர் உமர் (ரழி) அவர்கள் \"நிச்சயமாக நீங்கள் அவருக்கு ஒப்பந்தம் எழுதிக் கொடுக்க வேண்டும்\" என்று வலியுறுத்தினார்கள். இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும். அல்லாஹ்வின் கூற்று:\n\r\n\n\r\nإِنْ عَلِمْتُمْ فِيهِمْ خَيْراً\n\r\n\n\r\n(அவர்களிடத்தில் நன்மையை நீங்கள் அறிந்தால்.) இதற்கு 'நம்பகத்தன்மை' என்று சிலர் பொருள் கூறுகின்றனர். சிலர் 'நேர்மை' என்றும், மற்றவர்கள் 'சம்பாதிக்கும் திறனும் ஆற்றலும்' என்றும் கூறுகின்றனர்.\n\r\n\n\r\nوَءَاتُوهُمْ مِّن مَّالِ اللَّهِ الَّذِى ءَاتَـكُمْ\n\r\n\n\r\n(அல்லாஹ் உங்களுக்கு வழங்கியிருக்கும் அவனது செல்வத்திலிருந்து அவர்களுக்குக் கொடுங்கள்.) இது அல்லாஹ் அவர்களுக்கு உரிமையாக்கியுள்ள ஜகாத் நிதியைக் குறிக்கும். இது அல்-ஹஸன், அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம், அவரது தந்தை மற்றும் முகாத்தில் பின் ஹய்யான் ஆகியோரின் கருத்தாகும். இப்னு ஜரீர் அவர்களும் இக்கருத்தையே ஆதரிக்கிறார்கள்.\n\r\n\n\r\nوَءَاتُوهُمْ مِّن مَّالِ اللَّهِ الَّذِى ءَاتَـكُمْ\n\r\n\n\r\n(அல்லாஹ் உங்களுக்கு வழங்கியிருக்கும் அவனது செல்வத்திலிருந்து அவர்களுக்குக் கொடுங்கள்.) இப்ராஹீம் அந்-நகஈ அவர்கள் கூறுகிறார்கள், \"இது எஜமானர்களுக்கும் மற்ற மக்களுக்கும் அவர்களை விடுவிக்கத் தூண்டுவதாகும்.\" இது புரைதா பின் அல்-ஹுஸைப் அல்-அஸ்லமீ மற்றும் கதாதா ஆகியோரின் கருத்தாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அடிமைகளை விடுவிக்க உதவுமாறு அல்லாஹ் முஃமின்களுக்குக் கட்டளையிட்டுள்ளான்.\"\n\r\n\n\r\nஅடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு வற்புறுத்துவதற்கான தடை\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَلاَ تُكْرِهُواْ فَتَيَـتِكُمْ عَلَى الْبِغَآءِ\n\r\n\n\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்...) ஜாஹிலிய்யா காலத்தில் சிலர், தங்களிடம் உள்ள அடிமைப் பெண்ணை விபச்சாரம் செய்ய அனுப்பி, அதன் மூலம் கிடைக்கும் பணத்தை வாங்கிக் கொள்வார்கள். இஸ்லாம் வந்த பிறகு, அல்லாஹ் இதனை முஃமின்களுக்குத் தடை செய்தான். இந்த வசனம் அருளப்பட்டதற்கான காரணம், அப்துல்லாஹ் பின் உபை பின் சலூல் என்பவரைப் பற்றியது என்று தஃப்ஸீர் அறிஞர்கள் குறிப்பிடுகின்றனர். அவன் தன் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தி அதன் மூலம் வருமானம் ஈட்டி வந்தான். மேலும் அவர்கள் மூலம் பிறக்கும் குழந்தைகள் தனது அந்தஸ்தை உயர்த்தும் என்றும் வாதிட்டான்.\n\r\n\n\r\nஇது குறித்து அறிவிக்கப்பட்டுள்ள செய்திகள்\n\r\n\n\r\nஅல்-ஹாஃபிழ் அபூபக்ர் அஹ்மத் பின் அம்ர் பின் அப்தில் காலிக் அல்-பஸ்ஸார் (ரஹ்) அவர்கள் தனது முஸ்னதில் பின்வருமாறு பதிவு செய்துள்ளார்கள்: அஸ்-ஸுஹ்ரீ அவர்கள் கூறுகிறார்கள், \"அப்துல்லாஹ் பின் உபை பின் சலூலிடம் முஆதா என்ற அடிமைப் பெண் இருந்தாள். அவளை அவன் விபச்சாரம் செய்ய வற்புறுத்தினான். இஸ்லாம் வந்தபோது,\n\r\n\n\r\nوَلاَ تُكْرِهُواْ فَتَيَـتِكُمْ عَلَى الْبِغَآءِ\n\r\n\n\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்...) என்ற வசனம் அருளப்பட்டது.\" அல்-அஃமஷ் வழியாக அபூ ஸுஃப்யான் கூறுகிறார்கள்: ஜாபிர் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி கூறுகையில், \"அப்துல்லாஹ் பின் உபை பின் சலூலின் அடிமைப் பெண்ணான முஸைக்கா என்பவரைப் பற்றி இது அருளப்பட்டது. அவளை அவன் ஒழுக்கக்கேடான செயல்களுக்கு வற்புறுத்தினான். ஆனால் அவள் தூய்மையானவளாக இருந்து அதனை மறுத்து வந்தாள். அப்போது அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَلاَ تُكْرِهُواْ فَتَيَـتِكُمْ عَلَى الْبِغَآءِ\n\r\n\n\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்,)\" என்று தொடங்கி,\n\r\n\n\r\nوَمَن يُكْرِههُنَّ فِإِنَّ اللَّهَ مِن بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n(ஆனால் எவரேனும் அவர்களைக் கட்டாயப்படுத்தினால், அத்தகைய வற்புறுத்தலுக்குப் பின் அல்லாஹ் (அப்பெண்களை) மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்.)\" அந்-நஸாயீயிலும் இது போன்ற செய்தி பதிவாகியுள்ளது. முகாத்தில் பின் ஹய்யான் கூறுகிறார்கள், \"நான் கேள்விப்பட்ட வரையில் - அல்லாஹ்வே மிக அறிந்தவன் - இந்த வசனம் இருவரைப் பற்றி அருளப்பட்டது. அவர்கள் தங்கள் அடிமைப் பெண்களை விபச்சாரத்திற்கு வற்புறுத்தினர். ஒரு அடிமைப் பெண் அன்சாரிகளுக்குச் சொந்தமான முஸைக்கா. மற்றொன்று முஸைக்காவின் தாயார் உமைமா, இவர் அப்துல்லாஹ் பின் உபை என்பவனுக்குச் சொந்தமானவர். முஆதா மற்றும் அர்வாவும் அதே நிலையில் இருந்தனர். முஸைக்காவும் அவளது தாயும் நபி (ஸல்) அவர்களிடம் வந்து இது குறித்து முறையிட்டனர். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nوَلاَ تُكْرِهُواْ فَتَيَـتِكُمْ عَلَى الْبِغَآءِ\n\r\n\n\r\n(உங்கள் அடிமைப் பெண்களை விபச்சாரத்தில் ஈடுபடுமாறு கட்டாயப்படுத்தாதீர்கள்), அதாவது விபச்சாரத்தில் (Zina).\n\r\n\n\r\nإِنْ أَرَدْنَ تَحَصُّناً\n\r\n\n\r\n(அவர்கள் கற்பைப் பேண விரும்பினால்,) அதாவது, அவர்கள் ஒழுக்கமாக இருக்க விரும்பினால். பெரும்பாலான அடிமைப் பெண்களின் நிலை இதுவே.\n\r\n\n\r\nلِّتَبْتَغُواْ عَرَضَ الْحَيَوةِ الدُّنْيَا\n\r\n\n\r\n(இவ்வுலக வாழ்வின் சொற்ப லாபத்தைத் தேடுவதற்காக.) அதாவது, அவர்கள் சம்பாதிக்கும் பணம் மற்றும் அவர்கள் மூலம் கிடைக்கும் குழந்தைகள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரத்தம் குத்தி எடுப்பவர், விபச்சாரி மற்றும் குறி சொல்பவர் ஆகியோரின் வருமானத்தைத் தடை செய்துள்ளார்கள். மற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«مَهْرُ الْبَغِيِّ خَبِيثٌ وَكَسْبُ الْحَجَّامِ خَبِيثٌ، وَثَمَنُ الْكَلْبِ خَبِيثٌ»\n\r\n\n\r\n(விபச்சாரியின் சம்பாத்தியம் தீயது, இரத்தம் குத்தி எடுப்பவரின் வருமானம் தீயது, மற்றும் நாயின் விலை தீயது.)\n\r\n\n\r\nوَمَن يُكْرِههُنَّ فِإِنَّ اللَّهَ مِن بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n(ஆனால் எவரேனும் அவர்களைக் கட்டாயப்படுத்தினால், அத்தகைய வற்புறுத்தலுக்குப் பின் அல்லாஹ் மன்னிப்பவனாகவும், மிக்க கருணையுடையவனாகவும் இருக்கிறான்.) அதாவது, ஜாபிர் (ரழி) அவர்கள் அறிவித்த ஹதீஸாக உள்ளபடி, அவர்கள் மீது அல்லாஹ் கருணை காட்டுவான். இப்னு அபீ தல்ஹா வழியாக இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகிறார்கள், \"நீங்கள் அவ்வாறு வற்புறுத்தினால், அல்லாஹ் (அப்பெண்களை) மன்னிப்பவனாகவும் கருணையாளனாகவும் இருக்கிறான்; அந்தப் பாவம் அவர்களைக் கட்டாயப்படுத்தியவர் மீதே சாரும்.\" இது முஜாஹித், அதா அல்-குராஸானீ, அல்-அஃமஷ் மற்றும் கதாதா ஆகியோரின் கருத்தாகும். இந்தச் சட்டங்களை விரிவாக விளக்கிய பிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَقَدْ أَنْزَلْنَآ إِلَيْكُمْ ءَايَـتٍ مُّبَيِّنَـتٍ\n\r\n\n\r\n(நிச்சயமாக நாம் உங்களுக்குத் தெளிவான வசனங்களை (ஆயத்களை) அருளியுள்ளோம்.) அதாவது, குர்ஆனில் விஷயங்களை விரிவாக விளக்கும் தெளிவான வசனங்கள் உள்ளன.\n\r\n\n\r\nوَمَثَلاً مِّنَ الَّذِينَ خَلَوْاْ مِن قَبْلِكُمْ\n\r\n\n\r\n(உங்களுக்கு முன் வாழ்ந்து சென்றவர்களின் உதாரணங்களையும்,) அதாவது முந்தைய சமுதாயங்களைப் பற்றிய செய்திகள் மற்றும் அவர்கள் அல்லாஹ்வின் கட்டளைகளை மீறியபோது அவர்களுக்கு ஏற்பட்ட நிலைகள். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nفَجَعَلْنَـهُمْ سَلَفاً وَمَثَلاً لِّلاٌّخِرِينَ\n\r\n\n\r\n(எனவே நாம் அவர்களைப் பிற்காலத்தவருக்கு ஒரு முன்னோடியாகவும், உதாரணமாகவும் ஆக்கினோம்.) (43:56); நாம் அவர்களை ஒரு பாடமாக, அதாவது பாவங்களையும் விலக்கப்பட்ட செயல்களையும் செய்வதற்கான கண்டனமாக ஆக்கினோம்.\n\r\n\n\r\nوَمَوْعِظَةً لِّلْمُتَّقِينَ\n\r\n\n\r\n(மேலும் இது தக்வா (இறையச்சம்) உடையவர்களுக்கு ஓர் உபதேசமாகும்.) அதாவது அல்லாஹ்வை நினைவு கூர்ந்து அவனுக்கு அஞ்சுபவர்களுக்கு."},"35":{"html":"<strong>அல்லாஹ்வின் ஒளியின் உவமை</strong><br />\r\n<br />\r\nஅலி பின் அபீ தல்ஹா அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">نُورُ</span> <span class=\"quran-arabic-font text-success\">السَّمَوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span><br />\r\n<br />\r\n(அல்லாஹ் வானங்கள் மற்றும் பூமியின் ஒளி ஆவான்.) இதன் பொருள், வானங்கள் மற்றும் பூமியில் வசிப்பவர்களுக்கு அல்லாஹ்வே வழிகாட்டியாவான் என்பதாகும். இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: \"முஜாஹித் மற்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி, 'அல்லாஹ் வானங்கள் மற்றும் பூமியின் விவகாரங்களையும், அங்குள்ள நட்சத்திரங்கள், சூரியன் மற்றும் சந்திரனையும் நிர்வகிக்கிறான்' என்று கூறினார்கள்.\" அஸ்-ஸுத்தி அவர்கள் இந்த வசனத்தைப் பற்றி கூறும்போது, அவனுடைய ஒளியினால் வானங்களும் பூமியும் பிரகாசிக்கின்றன என்று விளக்கமளித்தார்கள். இரண்டு ஸஹீஹான நூல்களில், இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரவில் தொழுகைக்காக எழுந்தபோது, இவ்வாறு பிரார்த்தனை செய்வார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ،</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">قَيِّمُ</span> <span class=\"quran-arabic-font text-success\">السَّمَوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ،</span> <span class=\"quran-arabic-font text-success\">وَلَكَ</span> <span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">نُورُ</span> <span class=\"quran-arabic-font text-success\">السَّمَوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span>»<br />\r\n<br />\r\n(யா அல்லாஹ்! உனக்கே புகழ் அனைத்தும், நீயே வானங்களையும், பூமியையும், அவற்றுள் உள்ள அனைத்தையும் நிலைநிறுத்திப் பராமரிப்பவன். உனக்கே புகழ் அனைத்தும், நீயே வானங்கள் மற்றும் பூமியின் ஒளியாகவும், அவற்றுள் உள்ள அனைத்தின் ஒளியாகவும் இருக்கிறாய்.)\" இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள் என அறிவிக்கப்படுகிறது: \"உன் இறைவனிடத்தில் இரவோ பகலோ இல்லை; அவனது அர்ஷின் (சிம்மாசனத்தின்) ஒளி அவனது திருமுகத்தின் ஒளியிலிருந்தே கிடைக்கிறது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَثَلُ</span> <span class=\"quran-arabic-font text-success\">نُورِهِ</span><br />\r\n<br />\r\n(அவனுடைய ஒளியின் உவமை) இதில் 'அவனுடைய' எனும் பிரதிபெயர்ச்சொல் எதைக் குறிக்கிறது என்பதில் இரண்டு கருத்துக்கள் உள்ளன. முதலாவது, அது அல்லாஹ்வைக் குறிக்கிறது. அதாவது, ஒரு முஃமினின் (விசுவாசியின்) இதயத்தில் அல்லாஹ் ஏற்படுத்தியுள்ள நேர்வழியின் உவமை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمِشْكَاةٍ</span><br />\r\n<br />\r\n(ஒரு மாடக்குழி போல) என்பதாகும். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும். இரண்டாவது கருத்து, அந்தப் பிரதிபெயர்ச்சொல் முஃமினைக் குறிக்கிறது என்பதாகும். இதற்கு ஆதாரமாக உபை பின் கஅப் (ரழி) அவர்கள், 'மஸ்லூ நூரி மன் ஆமன பிஹி' (அவனை நம்பிக்கை கொண்டவரின் ஒளியின் உவமை) என்று ஓதுபவராக இருந்தார். வசனத்தின் சூழல் இதை உணர்த்துகிறது. அதாவது முஃமினின் இதயத்தில் உள்ள ஒளியின் உவமை ஒரு மாடக்குழி போன்றது. எனவே, முஃமினின் இதயம், அவனது இயல்பான நேர்வழி மற்றும் அவனது இயல்புக்கு இணக்கமான குர்ஆனிலிருந்து அவன் கற்றுக்கொண்ட விஷயங்கள் ஆகியவை - அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَمَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَيِّنَةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّهِ</span> <span class=\"quran-arabic-font text-success\">وَيَتْلُوهُ</span> <span class=\"quran-arabic-font text-success\">شَاهِدٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُ</span><br />\r\n<br />\r\n(தம் இறைவனிடமிருந்து ஒரு தெளிவான ஆதாரத்தின் மீது இருப்பவரும், அவரிடமிருந்து வரும் ஒரு சாட்சி அதனை ஓதிக் காண்பிப்பவருமான ஒருவர் (நிராகரிப்பாளர்களுக்குச் சமமாவாரா?)) <a href=\"qurandisp.php?sura=11&ayah=17\" class=\"link\">11:17</a>. முஃமினின் இதயம் அதன் தூய்மையிலும் தெளிவிலும், ஒளி ஊடுருவக்கூடிய ரத்தினக் கண்ணாடியில் உள்ள விளக்குக்கு ஒப்பிடப்படுகிறது. மேலும் அதற்கு வழிகாட்டும் குர்ஆனும் ஷரீஆவும், எந்தவிதக் கலப்படமும் கோணலும் இல்லாத தூய்மையான, பிரகாசமான எண்ணெய்க்கு ஒப்பிடப்படுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمِشْكَاةٍ</span><br />\r\n<br />\r\n(ஒரு மாடக்குழி போல) இப்னு அப்பாஸ் (ரழி), முஜாஹித், முஹம்மது பின் கஅப் மற்றும் பலர் கூறும்போது, \"இது விளக்கில் திரி வைக்கப்படும் இடத்தைக் குறிக்கிறது\" என்றனர். இதுவே நன்கு அறியப்பட்ட கருத்தாகும். அதனால்தான் அல்லாஹ் தொடர்ந்து கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِصْبَاحٌ</span><br />\r\n<br />\r\n(அதற்குள் ஒரு விளக்கு உள்ளது.) இது பிரகாசமாக எரியும் சுடரைக் குறிக்கும். அல்லது மாடக்குழி என்பது வீட்டில் உள்ள ஒரு மாடம் என்றும் கூறப்படுகிறது. இது அல்லாஹ்வுக்குக் கீழ்ப்படிவதைப் பற்றி அல்லாஹ் வழங்கும் உவமையாகும். அவன் தனக்குக் கீழ்ப்படிவதை 'ஒளி' என்று அழைக்கிறான், மேலும் அதனை இன்னும் பல பெயர்களாலும் குறிப்பிடுகிறான். உபை பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"அந்த விளக்கு என்பது ஒளி; இது முஃமினின் இதயத்தில் இருக்கும் குர்ஆனையும் ஈமானையும் (நம்பிக்கையையும்) குறிக்கிறது.\" அஸ்-ஸுத்தி அவர்கள், \"அது விளக்குதான்\" என்று கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْمِصْبَاحُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">زُجَاجَةٍ</span><br />\r\n<br />\r\n(அந்த விளக்கு ஒரு கண்ணாடியில் உள்ளது,) இதன் பொருள், இந்த ஒளி ஒரு தெளிவான கண்ணாடியில் பிரகாசிக்கிறது என்பதாகும். உபை பின் கஅப் (ரழி) அவர்கள் உள்ளிட்டோர், \"இது முஃமினின் இதயத்தின் உவமையாகும்\" என்றனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الزُّجَاجَةُ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهَا</span> <span class=\"quran-arabic-font text-success\">كَوْكَبٌ</span> <span class=\"quran-arabic-font text-success\">دُرِّىٌّ</span><br />\r\n<br />\r\n(அந்தக் கண்ணாடி துர்ரிய்யுன் நட்சத்திரத்தைப் போன்றது,) சில அறிஞர்கள் 'துர்ரிய்யுன்' என்ற சொல்லை 'தால்' எழுத்தின் மீது தம்மத்துடனும், ஹம்ஸா இல்லாமலும் ஓதுகிறார்கள். இதற்கு 'முத்துக்கள்' என்று பொருள். அதாவது அது முத்துக்களால் (துர்) செய்யப்பட்ட நட்சத்திரத்தைப் போன்றது என்பதாகும். மற்றவர்கள் இதனை 'திர்ரிஉன்' அல்லது 'துர்ரிஉன்' என்று ஓதுகிறார்கள்; இதற்கு 'பிரதிபலிப்பு' (திர்) என்று பொருள். ஏனெனில் நட்சத்திரத்தின் மீது ஏதேனும் ஒளிபட்டால், அது மற்ற நேரங்களை விட அதிகப் பிரகாசமாக மாறும். அரபிகள் தங்களுக்குத் தெரியாத பிரகாசமான நட்சத்திரங்களை 'தராரி' என்று அழைக்கிறார்கள். உபை பின் கஅப் (ரழி) அவர்கள், \"இது ஒரு பிரகாசிக்கும் நட்சத்திரம்\" என்றார். கதாதா அவர்கள், \"இது மிகப்பெரிய, பிரகாசமான மற்றும் தெளிவான நட்சத்திரம்\" என்றார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُوقَدُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَجَرَةٍ</span> <span class=\"quran-arabic-font text-success\">مُّبَـرَكَةٍ</span><br />\r\n<br />\r\n(ஒரு பாக்கியம் பெற்ற மரத்திலிருந்து அது ஏற்றப்படுகிறது,) அதாவது, அந்த விளக்கு ஒரு பாக்கியம் பெற்ற மரமான ஆலிவ் மரத்தின் எண்ணெயால் எரிக்கப்படுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">زَيْتُونَةٍ</span><br />\r\n<br />\r\n(ஒரு ஆலிவ்,) இது முன்பு குறிப்பிடப்பட்ட பாக்கியம் பெற்ற மரத்தையே குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">شَرْقِيَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">غَرْبِيَّةٍ</span><br />\r\n<br />\r\n(கிழக்கையும் சேர்ந்ததல்ல, மேற்கையும் சேர்ந்ததல்ல,) அதாவது, அது நிலத்தின் கிழக்குப் பகுதியில் மட்டும் இல்லை - அவ்வாறு இருந்தால் காலையின் ஒரு பகுதியில் அதற்குச் சூரிய ஒளி கிடைக்காமல் போகும். அது நிலத்தின் மேற்குப் பகுதியிலும் இல்லை - அவ்வாறு இருந்தால் சூரியன் மறைவதற்கு முன்பே அதன் மீது நிழல் விழுந்துவிடும். மாறாக, அது ஒரு மைய நிலையில் உள்ளது; அங்கு சூரிய உதயம் முதல் அஸ்தமனம் வரை முழுமையாகச் சூரிய ஒளி கிடைக்கிறது. எனவேதான் அதன் எண்ணெய் மிகச் சிறந்ததாகவும், தூய்மையாகவும், பிரகாசமாகவும் இருக்கிறது. இப்னு அபி ஹாதிம் அவர்கள் பதிவு செய்துள்ளபடி இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு விளக்கமளித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">زَيْتُونَةٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">شَرْقِيَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">غَرْبِيَّةٍ</span><br />\r\n<br />\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராத ஒரு ஆலிவ்,) \"இது ஒரு சமவெளியில் (பாலைவனத்தில்) உள்ள மரம். எந்த ஒரு மரமோ, மலையோ அல்லது குகையோ இதற்கு நிழல் தந்து மறைக்காது. எதாலும் மறைக்கப்படாமல் சூரிய ஒளி நேரடியாகப் படுவதால் இதன் எண்ணெய் மிகச் சிறந்ததாக அமைகிறது.\" முஜாஹித் அவர்கள் விளக்கமளிக்கும்போது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">شَرْقِيَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">غَرْبِيَّةٍ</span><br />\r\n<br />\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராதது) என்பதற்கு, \"அது கிழக்கில் இல்லை - அவ்வாறு இருந்தால் சூரியன் மறையும்போது அதற்கு ஒளி கிடைக்காது. அது மேற்கிலும் இல்லை - அவ்வாறு இருந்தால் சூரியன் உதிக்கும்போது அதற்கு ஒளி கிடைக்காது. மாறாக, சூரிய உதயம் மற்றும் அஸ்தமனம் என இரு வேளைகளிலும் ஒளி பெறும் இடத்தில் அது உள்ளது\" என்றார். ஸயீத் பின் ஜுபைர் அவர்கள் விளக்கமளித்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">زَيْتُونَةٍ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">شَرْقِيَّةٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">غَرْبِيَّةٍ</span> <span class=\"quran-arabic-font text-success\">يَكَادُ</span> <span class=\"quran-arabic-font text-success\">زَيْتُهَا</span> <span class=\"quran-arabic-font text-success\">يُضِىءُ</span><br />\r\n<br />\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராத ஒரு ஆலிவ், அதன் எண்ணெய் தானாகவே பிரகாசிக்க முற்படுகிறது,) \"இது மிகச் சிறந்த வகை எண்ணெய். சூரியன் உதிக்கும்போது கிழக்கிலிருந்தும், மறையும்போது மேற்கிலிருந்தும் அந்த மரத்தை அடைகிறது. இவ்வாறு காலை, மாலை என இருவேளையும் சூரிய ஒளி கிடைப்பதால் அது கிழக்கிலோ மேற்கிலோ உள்ளதாகக் கருதப்படுவதில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَكَادُ</span> <span class=\"quran-arabic-font text-success\">زَيْتُهَا</span> <span class=\"quran-arabic-font text-success\">يُضِىءُ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَمْسَسْهُ</span> <span class=\"quran-arabic-font text-success\">نَارٌ</span><br />\r\n<br />\r\n(நெருப்பு அதனைத் தீண்டாவிட்டாலும், அதன் எண்ணெய் தானாகவே பிரகாசிக்க முற்படுகிறது.) அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள், அந்த எண்ணெய் அதன் தூய்மையினால் தானாகவே ஜொலிக்கிறது என்று இதற்குப் பொருள் கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُّورٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نُورٍ</span><br />\r\n<br />\r\n(ஒளியின் மேல் ஒளி!) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: இதன் பொருள் ஒரு மனிதனின் ஈமானும் (நம்பிக்கை) மற்றும் அவனது நற்செயல்களும் ஆகும். அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُّورٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">نُورٍ</span><br />\r\n<br />\r\n(ஒளியின் மேல் ஒளி!) \"நெருப்பின் ஒளியும், எண்ணெயின் ஒளியும்: இவை இணையும்போது பேரொளி பிறக்கிறது. ஒன்றின்றி மற்றொன்று ஒளியைத் தராது. அதுபோலவே குர்ஆனின் ஒளியும், ஈமானின் ஒளியும் இணையும்போதுதான் பிரகாசம் உண்டாகிறது; ஒன்றின்றி மற்றொன்று அவ்வாறு செய்ய முடியாது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِنُورِهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n(அல்லாஹ் தான் நாடியவர்களைத் தன் ஒளியின் பக்கம் வழிநடத்துகிறான்.) அதாவது, அல்லாஹ் தான் தேர்ந்தெடுப்பவர்களுக்குத் தனது நேர்வழியைக் காட்டுகிறான். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்த ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظُلْمَةٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَلْقَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نُورِهِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ،</span> <span class=\"quran-arabic-font text-success\">فَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَصَابَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">نُورِهِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">اهْتَدَى</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَخْطَأَ</span> <span class=\"quran-arabic-font text-success\">ضَلَّ</span> <span class=\"quran-arabic-font text-success\">فَلِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَقُولُ</span>: <span class=\"quran-arabic-font text-success\">جَفَّ</span> <span class=\"quran-arabic-font text-success\">الْقَلَمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عِلْمِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தனது படைப்புகளை இருளில் படைத்தான். பிறகு அதே நாளில் தன் ஒளியை அவர்கள் மீது வீசினான். அன்று அவனுடைய ஒளியால் தொடப்பட்டவர் நேர்வழி பெறுவார், அதைத் தவறவிட்டவர் வழிதவறிப் போவார். இதனால்தான் நான் கூறுகிறேன்: அல்லாஹ்வுடைய அறிவின்படி விதியினை எழுதிய பேனாக்கள் காய்ந்துவிட்டன.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْأَمْثَالَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் மனிதர்களுக்கு உவமைகளைக் கூறுகிறான், மேலும் அல்லாஹ் எல்லாவற்றையும் நன்கறிந்தவன்.) முஃமினின் இதயத்தில் உள்ள தனது வழிகாட்டுதலின் ஒளியைப் பற்றி இந்த உவமையைக் குறிப்பிட்ட பிறகு, அல்லாஹ் இந்த வசனத்தை இவ்வாறு முடிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَضْرِبُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْأَمْثَالَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் மனிதர்களுக்கு உவமைகளைக் கூறுகிறான், மேலும் அல்லாஹ் எல்லாவற்றையும் நன்கறிந்தவன்.) அதாவது, நேர்வழிக்குத் தகுதியானவர் யார், வழிதவறத் தகுதியானவர் யார் என்பதை அல்லாஹ்வே மிக நன்கறிந்தவன். இமாம் அஹ்மத் அவர்கள், அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الْقُلُوبُ</span> <span class=\"quran-arabic-font text-success\">أَرْبَعَةٌ</span>: <span class=\"quran-arabic-font text-success\">قَلْبٌ</span> <span class=\"quran-arabic-font text-success\">أَجْرَدُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مِثْلُ</span> <span class=\"quran-arabic-font text-success\">السِّرَاجِ</span> <span class=\"quran-arabic-font text-success\">يُزْهِرُ،</span> <span class=\"quran-arabic-font text-success\">وَقَلْبٌ</span> <span class=\"quran-arabic-font text-success\">أَغْلَفُ</span> <span class=\"quran-arabic-font text-success\">مَرْبُوطٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">غِلَافِهِ،</span> <span class=\"quran-arabic-font text-success\">وَقَلْبٌ</span> <span class=\"quran-arabic-font text-success\">مَنْكُوسٌ،</span> <span class=\"quran-arabic-font text-success\">وَقَلْبٌ</span> <span class=\"quran-arabic-font text-success\">مُصْفَحٌ</span>. <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الْقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْأَجْرَدُ</span>: <span class=\"quran-arabic-font text-success\">فَقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِ</span> <span class=\"quran-arabic-font text-success\">سِرَاجُهُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">نُورُهُ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الْقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْأَغْلَفُ</span> <span class=\"quran-arabic-font text-success\">فَقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الْقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْمَنْكُوسُ</span> <span class=\"quran-arabic-font text-success\">فَقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْمُنَافِقِ،</span> <span class=\"quran-arabic-font text-success\">عَرَفَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنْكَرَ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الْقَلْبُ</span> <span class=\"quran-arabic-font text-success\">الْمُصْفَحُ</span> <span class=\"quran-arabic-font text-success\">فَقَلْبٌ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">إِيمَانٌ</span> <span class=\"quran-arabic-font text-success\">وَنِفَاقٌ،</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُ</span> <span class=\"quran-arabic-font text-success\">الْإِيمَانِ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الْبَقْلَةِ</span> <span class=\"quran-arabic-font text-success\">يُمِدُّهَا</span> <span class=\"quran-arabic-font text-success\">الْمَاءُ</span> <span class=\"quran-arabic-font text-success\">الطَّيِّبُ،وَمَثَلُ</span> <span class=\"quran-arabic-font text-success\">النِّفَاقِ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">الْقَرْحَةِ</span> <span class=\"quran-arabic-font text-success\">يُمِدُّهَا</span> <span class=\"quran-arabic-font text-success\">الدَّمُ</span> <span class=\"quran-arabic-font text-success\">وَالْقَيْحُ،</span> <span class=\"quran-arabic-font text-success\">فَأَيُّ</span> <span class=\"quran-arabic-font text-success\">الْمدَّتَيْنِ</span> <span class=\"quran-arabic-font text-success\">غَلَبَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأُخْرَى</span> <span class=\"quran-arabic-font text-success\">غَلَبَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span>»<br />\r\n<br />\r\n(இதயங்கள் நான்கு வகைப்படும்: 1. பிரகாசிக்கும் விளக்கு போன்ற தூய்மையான இதயம்; 2. மூடப்பட்டுக் கட்டப்பட்ட இதயம்; 3. தலைகீழான இதயம்; 4. கவசம் போன்ற இதயம். அந்தத் தூய்மையான இதயம் முஃமினுடையதாகும், அதில் ஒளியைத் தரும் விளக்கு உள்ளது. மூடப்பட்ட இதயம் என்பது காஃபிருடையதாகும். தலைகீழான இதயம் என்பது முனாஃபிக்கினுடைய (நயவஞ்சகன்) இதயம்; அவன் உண்மையை அறிந்து பின் மறுத்தவன். கவசம் போன்ற இதயத்தில் ஈமானும் நயவஞ்சகமும் கலந்திருக்கும். அதில் உள்ள ஈமானின் உவமை, நல்ல நீரால் வளர்க்கப்படும் ஒரு செடியைப் போன்றது. அதில் உள்ள நயவஞ்சகத்தின் உவமை, இரத்தம் மற்றும் சீழ் ஆகியவற்றால் வளரும் புண்ணைப் போன்றது. இவ்விரண்டில் எது மேலோங்குகிறதோ, அதுவே அந்த இதயத்தை ஆதிக்கம் செலுத்தும்.) இதன் அறிவிப்பாளர் தொடர் வலிமையானது (ஜய்யித்), ஆனால் இதனை புகாரி மற்றும் முஸ்லிம் பதிவு செய்யவில்லை.<br />\r\n<br />","text":"அல்லாஹ்வின் ஒளியின் உவமை\n\r\n\n\r\nஅலி பின் அபீ தல்ஹா அவர்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு கூறினார்கள் என அறிவிக்கிறார்கள்:\n\r\n\n\r\nاللَّهُ نُورُ السَّمَوَاتِ وَالْأَرْضِ\n\r\n\n\r\n(அல்லாஹ் வானங்கள் மற்றும் பூமியின் ஒளி ஆவான்.) இதன் பொருள், வானங்கள் மற்றும் பூமியில் வசிப்பவர்களுக்கு அல்லாஹ்வே வழிகாட்டியாவான் என்பதாகும். இப்னு ஜுரைஜ் அவர்கள் கூறினார்கள்: \"முஜாஹித் மற்றும் இப்னு அப்பாஸ் (ரழி) அவர்கள் இந்த வசனத்தைப் பற்றி, 'அல்லாஹ் வானங்கள் மற்றும் பூமியின் விவகாரங்களையும், அங்குள்ள நட்சத்திரங்கள், சூரியன் மற்றும் சந்திரனையும் நிர்வகிக்கிறான்' என்று கூறினார்கள்.\" அஸ்-ஸுத்தி அவர்கள் இந்த வசனத்தைப் பற்றி கூறும்போது, அவனுடைய ஒளியினால் வானங்களும் பூமியும் பிரகாசிக்கின்றன என்று விளக்கமளித்தார்கள். இரண்டு ஸஹீஹான நூல்களில், இப்னு அப்பாஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இரவில் தொழுகைக்காக எழுந்தபோது, இவ்வாறு பிரார்த்தனை செய்வார்கள்:\n\r\n\n\r\n«اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ قَيِّمُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ»\n\r\n\n\r\n(யா அல்லாஹ்! உனக்கே புகழ் அனைத்தும், நீயே வானங்களையும், பூமியையும், அவற்றுள் உள்ள அனைத்தையும் நிலைநிறுத்திப் பராமரிப்பவன். உனக்கே புகழ் அனைத்தும், நீயே வானங்கள் மற்றும் பூமியின் ஒளியாகவும், அவற்றுள் உள்ள அனைத்தின் ஒளியாகவும் இருக்கிறாய்.)\" இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள் என அறிவிக்கப்படுகிறது: \"உன் இறைவனிடத்தில் இரவோ பகலோ இல்லை; அவனது அர்ஷின் (சிம்மாசனத்தின்) ஒளி அவனது திருமுகத்தின் ஒளியிலிருந்தே கிடைக்கிறது.\"\n\r\n\n\r\nمَثَلُ نُورِهِ\n\r\n\n\r\n(அவனுடைய ஒளியின் உவமை) இதில் 'அவனுடைய' எனும் பிரதிபெயர்ச்சொல் எதைக் குறிக்கிறது என்பதில் இரண்டு கருத்துக்கள் உள்ளன. முதலாவது, அது அல்லாஹ்வைக் குறிக்கிறது. அதாவது, ஒரு முஃமினின் (விசுவாசியின்) இதயத்தில் அல்லாஹ் ஏற்படுத்தியுள்ள நேர்வழியின் உவமை:\n\r\n\n\r\nكَمِشْكَاةٍ\n\r\n\n\r\n(ஒரு மாடக்குழி போல) என்பதாகும். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும். இரண்டாவது கருத்து, அந்தப் பிரதிபெயர்ச்சொல் முஃமினைக் குறிக்கிறது என்பதாகும். இதற்கு ஆதாரமாக உபை பின் கஅப் (ரழி) அவர்கள், 'மஸ்லூ நூரி மன் ஆமன பிஹி' (அவனை நம்பிக்கை கொண்டவரின் ஒளியின் உவமை) என்று ஓதுபவராக இருந்தார். வசனத்தின் சூழல் இதை உணர்த்துகிறது. அதாவது முஃமினின் இதயத்தில் உள்ள ஒளியின் உவமை ஒரு மாடக்குழி போன்றது. எனவே, முஃமினின் இதயம், அவனது இயல்பான நேர்வழி மற்றும் அவனது இயல்புக்கு இணக்கமான குர்ஆனிலிருந்து அவன் கற்றுக்கொண்ட விஷயங்கள் ஆகியவை - அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nأَفَمَن كَانَ عَلَى بَيِّنَةٍ مِّن رَّبِّهِ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ\n\r\n\n\r\n(தம் இறைவனிடமிருந்து ஒரு தெளிவான ஆதாரத்தின் மீது இருப்பவரும், அவரிடமிருந்து வரும் ஒரு சாட்சி அதனை ஓதிக் காண்பிப்பவருமான ஒருவர் (நிராகரிப்பாளர்களுக்குச் சமமாவாரா?)) 11:17. முஃமினின் இதயம் அதன் தூய்மையிலும் தெளிவிலும், ஒளி ஊடுருவக்கூடிய ரத்தினக் கண்ணாடியில் உள்ள விளக்குக்கு ஒப்பிடப்படுகிறது. மேலும் அதற்கு வழிகாட்டும் குர்ஆனும் ஷரீஆவும், எந்தவிதக் கலப்படமும் கோணலும் இல்லாத தூய்மையான, பிரகாசமான எண்ணெய்க்கு ஒப்பிடப்படுகின்றன.\n\r\n\n\r\nكَمِشْكَاةٍ\n\r\n\n\r\n(ஒரு மாடக்குழி போல) இப்னு அப்பாஸ் (ரழி), முஜாஹித், முஹம்மது பின் கஅப் மற்றும் பலர் கூறும்போது, \"இது விளக்கில் திரி வைக்கப்படும் இடத்தைக் குறிக்கிறது\" என்றனர். இதுவே நன்கு அறியப்பட்ட கருத்தாகும். அதனால்தான் அல்லாஹ் தொடர்ந்து கூறுகிறான்:\n\r\n\n\r\nفِيهَا مِصْبَاحٌ\n\r\n\n\r\n(அதற்குள் ஒரு விளக்கு உள்ளது.) இது பிரகாசமாக எரியும் சுடரைக் குறிக்கும். அல்லது மாடக்குழி என்பது வீட்டில் உள்ள ஒரு மாடம் என்றும் கூறப்படுகிறது. இது அல்லாஹ்வுக்குக் கீழ்ப்படிவதைப் பற்றி அல்லாஹ் வழங்கும் உவமையாகும். அவன் தனக்குக் கீழ்ப்படிவதை 'ஒளி' என்று அழைக்கிறான், மேலும் அதனை இன்னும் பல பெயர்களாலும் குறிப்பிடுகிறான். உபை பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: \"அந்த விளக்கு என்பது ஒளி; இது முஃமினின் இதயத்தில் இருக்கும் குர்ஆனையும் ஈமானையும் (நம்பிக்கையையும்) குறிக்கிறது.\" அஸ்-ஸுத்தி அவர்கள், \"அது விளக்குதான்\" என்று கூறினார்கள்.\n\r\n\n\r\nالْمِصْبَاحُ فِى زُجَاجَةٍ\n\r\n\n\r\n(அந்த விளக்கு ஒரு கண்ணாடியில் உள்ளது,) இதன் பொருள், இந்த ஒளி ஒரு தெளிவான கண்ணாடியில் பிரகாசிக்கிறது என்பதாகும். உபை பின் கஅப் (ரழி) அவர்கள் உள்ளிட்டோர், \"இது முஃமினின் இதயத்தின் உவமையாகும்\" என்றனர்.\n\r\n\n\r\nالزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ\n\r\n\n\r\n(அந்தக் கண்ணாடி துர்ரிய்யுன் நட்சத்திரத்தைப் போன்றது,) சில அறிஞர்கள் 'துர்ரிய்யுன்' என்ற சொல்லை 'தால்' எழுத்தின் மீது தம்மத்துடனும், ஹம்ஸா இல்லாமலும் ஓதுகிறார்கள். இதற்கு 'முத்துக்கள்' என்று பொருள். அதாவது அது முத்துக்களால் (துர்) செய்யப்பட்ட நட்சத்திரத்தைப் போன்றது என்பதாகும். மற்றவர்கள் இதனை 'திர்ரிஉன்' அல்லது 'துர்ரிஉன்' என்று ஓதுகிறார்கள்; இதற்கு 'பிரதிபலிப்பு' (திர்) என்று பொருள். ஏனெனில் நட்சத்திரத்தின் மீது ஏதேனும் ஒளிபட்டால், அது மற்ற நேரங்களை விட அதிகப் பிரகாசமாக மாறும். அரபிகள் தங்களுக்குத் தெரியாத பிரகாசமான நட்சத்திரங்களை 'தராரி' என்று அழைக்கிறார்கள். உபை பின் கஅப் (ரழி) அவர்கள், \"இது ஒரு பிரகாசிக்கும் நட்சத்திரம்\" என்றார். கதாதா அவர்கள், \"இது மிகப்பெரிய, பிரகாசமான மற்றும் தெளிவான நட்சத்திரம்\" என்றார்.\n\r\n\n\r\nيُوقَدُ مِن شَجَرَةٍ مُّبَـرَكَةٍ\n\r\n\n\r\n(ஒரு பாக்கியம் பெற்ற மரத்திலிருந்து அது ஏற்றப்படுகிறது,) அதாவது, அந்த விளக்கு ஒரு பாக்கியம் பெற்ற மரமான ஆலிவ் மரத்தின் எண்ணெயால் எரிக்கப்படுகிறது.\n\r\n\n\r\nزَيْتُونَةٍ\n\r\n\n\r\n(ஒரு ஆலிவ்,) இது முன்பு குறிப்பிடப்பட்ட பாக்கியம் பெற்ற மரத்தையே குறிக்கிறது.\n\r\n\n\r\nلاَّ شَرْقِيَّةٍ وَلاَ غَرْبِيَّةٍ\n\r\n\n\r\n(கிழக்கையும் சேர்ந்ததல்ல, மேற்கையும் சேர்ந்ததல்ல,) அதாவது, அது நிலத்தின் கிழக்குப் பகுதியில் மட்டும் இல்லை - அவ்வாறு இருந்தால் காலையின் ஒரு பகுதியில் அதற்குச் சூரிய ஒளி கிடைக்காமல் போகும். அது நிலத்தின் மேற்குப் பகுதியிலும் இல்லை - அவ்வாறு இருந்தால் சூரியன் மறைவதற்கு முன்பே அதன் மீது நிழல் விழுந்துவிடும். மாறாக, அது ஒரு மைய நிலையில் உள்ளது; அங்கு சூரிய உதயம் முதல் அஸ்தமனம் வரை முழுமையாகச் சூரிய ஒளி கிடைக்கிறது. எனவேதான் அதன் எண்ணெய் மிகச் சிறந்ததாகவும், தூய்மையாகவும், பிரகாசமாகவும் இருக்கிறது. இப்னு அபி ஹாதிம் அவர்கள் பதிவு செய்துள்ளபடி இப்னு அப்பாஸ் (ரழி) அவர்கள் பின்வருமாறு விளக்கமளித்தார்கள்:\n\r\n\n\r\nزَيْتُونَةٍ لاَّ شَرْقِيَّةٍ وَلاَ غَرْبِيَّةٍ\n\r\n\n\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராத ஒரு ஆலிவ்,) \"இது ஒரு சமவெளியில் (பாலைவனத்தில்) உள்ள மரம். எந்த ஒரு மரமோ, மலையோ அல்லது குகையோ இதற்கு நிழல் தந்து மறைக்காது. எதாலும் மறைக்கப்படாமல் சூரிய ஒளி நேரடியாகப் படுவதால் இதன் எண்ணெய் மிகச் சிறந்ததாக அமைகிறது.\" முஜாஹித் அவர்கள் விளக்கமளிக்கும்போது:\n\r\n\n\r\nلاَّ شَرْقِيَّةٍ وَلاَ غَرْبِيَّةٍ\n\r\n\n\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராதது) என்பதற்கு, \"அது கிழக்கில் இல்லை - அவ்வாறு இருந்தால் சூரியன் மறையும்போது அதற்கு ஒளி கிடைக்காது. அது மேற்கிலும் இல்லை - அவ்வாறு இருந்தால் சூரியன் உதிக்கும்போது அதற்கு ஒளி கிடைக்காது. மாறாக, சூரிய உதயம் மற்றும் அஸ்தமனம் என இரு வேளைகளிலும் ஒளி பெறும் இடத்தில் அது உள்ளது\" என்றார். ஸயீத் பின் ஜுபைர் அவர்கள் விளக்கமளித்தார்கள்:\n\r\n\n\r\nزَيْتُونَةٍ لاَّ شَرْقِيَّةٍ وَلاَ غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىءُ\n\r\n\n\r\n(கிழக்கையும் சாராத, மேற்கையும் சாராத ஒரு ஆலிவ், அதன் எண்ணெய் தானாகவே பிரகாசிக்க முற்படுகிறது,) \"இது மிகச் சிறந்த வகை எண்ணெய். சூரியன் உதிக்கும்போது கிழக்கிலிருந்தும், மறையும்போது மேற்கிலிருந்தும் அந்த மரத்தை அடைகிறது. இவ்வாறு காலை, மாலை என இருவேளையும் சூரிய ஒளி கிடைப்பதால் அது கிழக்கிலோ மேற்கிலோ உள்ளதாகக் கருதப்படுவதில்லை.\"\n\r\n\n\r\nيَكَادُ زَيْتُهَا يُضِىءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ\n\r\n\n\r\n(நெருப்பு அதனைத் தீண்டாவிட்டாலும், அதன் எண்ணெய் தானாகவே பிரகாசிக்க முற்படுகிறது.) அப்துர்-ரஹ்மான் பின் ஸைத் பின் அஸ்லம் அவர்கள், அந்த எண்ணெய் அதன் தூய்மையினால் தானாகவே ஜொலிக்கிறது என்று இதற்குப் பொருள் கூறினார்கள்.\n\r\n\n\r\nنُّورٌ عَلَى نُورٍ\n\r\n\n\r\n(ஒளியின் மேல் ஒளி!) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: இதன் பொருள் ஒரு மனிதனின் ஈமானும் (நம்பிக்கை) மற்றும் அவனது நற்செயல்களும் ஆகும். அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்:\n\r\n\n\r\nنُّورٌ عَلَى نُورٍ\n\r\n\n\r\n(ஒளியின் மேல் ஒளி!) \"நெருப்பின் ஒளியும், எண்ணெயின் ஒளியும்: இவை இணையும்போது பேரொளி பிறக்கிறது. ஒன்றின்றி மற்றொன்று ஒளியைத் தராது. அதுபோலவே குர்ஆனின் ஒளியும், ஈமானின் ஒளியும் இணையும்போதுதான் பிரகாசம் உண்டாகிறது; ஒன்றின்றி மற்றொன்று அவ்வாறு செய்ய முடியாது.\"\n\r\n\n\r\nيَهْدِى اللَّهُ لِنُورِهِ مَن يَشَآءُ\n\r\n\n\r\n(அல்லாஹ் தான் நாடியவர்களைத் தன் ஒளியின் பக்கம் வழிநடத்துகிறான்.) அதாவது, அல்லாஹ் தான் தேர்ந்தெடுப்பவர்களுக்குத் தனது நேர்வழியைக் காட்டுகிறான். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) வழியாகப் பதிவு செய்த ஹதீஸில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள்:\n\r\n\n\r\n«إِنَّ اللهَ تَعَالَى خَلَقَ خَلْقَهُ فِي ظُلْمَةٍ ثُمَّ أَلْقَى عَلَيْهِمْ مِنْ نُورِهِ يَوْمَئِذٍ، فَمَنْ أَصَابَ مِنْ نُورِهِ يَوْمَئِذٍ اهْتَدَى وَمَنْ أَخْطَأَ ضَلَّ فَلِذَلِكَ أَقُولُ: جَفَّ الْقَلَمُ عَلَى عِلْمِ اللهِ عَزَّ وَجَلَّ»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தனது படைப்புகளை இருளில் படைத்தான். பிறகு அதே நாளில் தன் ஒளியை அவர்கள் மீது வீசினான். அன்று அவனுடைய ஒளியால் தொடப்பட்டவர் நேர்வழி பெறுவார், அதைத் தவறவிட்டவர் வழிதவறிப் போவார். இதனால்தான் நான் கூறுகிறேன்: அல்லாஹ்வுடைய அறிவின்படி விதியினை எழுதிய பேனாக்கள் காய்ந்துவிட்டன.)\n\r\n\n\r\nوَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ وَاللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ\n\r\n\n\r\n(மேலும் அல்லாஹ் மனிதர்களுக்கு உவமைகளைக் கூறுகிறான், மேலும் அல்லாஹ் எல்லாவற்றையும் நன்கறிந்தவன்.) முஃமினின் இதயத்தில் உள்ள தனது வழிகாட்டுதலின் ஒளியைப் பற்றி இந்த உவமையைக் குறிப்பிட்ட பிறகு, அல்லாஹ் இந்த வசனத்தை இவ்வாறு முடிக்கிறான்:\n\r\n\n\r\nوَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ وَاللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ\n\r\n\n\r\n(மேலும் அல்லாஹ் மனிதர்களுக்கு உவமைகளைக் கூறுகிறான், மேலும் அல்லாஹ் எல்லாவற்றையும் நன்கறிந்தவன்.) அதாவது, நேர்வழிக்குத் தகுதியானவர் யார், வழிதவறத் தகுதியானவர் யார் என்பதை அல்லாஹ்வே மிக நன்கறிந்தவன். இமாம் அஹ்மத் அவர்கள், அபூ ஸயீத் அல்-குத்ரி (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الْقُلُوبُ أَرْبَعَةٌ: قَلْبٌ أَجْرَدُ فِيهِ مِثْلُ السِّرَاجِ يُزْهِرُ، وَقَلْبٌ أَغْلَفُ مَرْبُوطٌ عَلَى غِلَافِهِ، وَقَلْبٌ مَنْكُوسٌ، وَقَلْبٌ مُصْفَحٌ. فَأَمَّا الْقَلْبُ الْأَجْرَدُ: فَقَلْبُ الْمُؤْمِنِ سِرَاجُهُ فِيهِ نُورُهُ، وَأَمَّا الْقَلْبُ الْأَغْلَفُ فَقَلْبُ الْكَافِرِ، وَأَمَّا الْقَلْبُ الْمَنْكُوسُ فَقَلْبُ الْمُنَافِقِ، عَرَفَ ثُمَّ أَنْكَرَ، وَأَمَّا الْقَلْبُ الْمُصْفَحُ فَقَلْبٌ فِيهِ إِيمَانٌ وَنِفَاقٌ، وَمَثَلُ الْإِيمَانِ فِيهِ كَمَثَلِ الْبَقْلَةِ يُمِدُّهَا الْمَاءُ الطَّيِّبُ،وَمَثَلُ النِّفَاقِ فِيهِ كَمَثَلِ الْقَرْحَةِ يُمِدُّهَا الدَّمُ وَالْقَيْحُ، فَأَيُّ الْمدَّتَيْنِ غَلَبَتْ عَلَى الْأُخْرَى غَلَبَتْ عَلَيْهِ»\n\r\n\n\r\n(இதயங்கள் நான்கு வகைப்படும்: 1. பிரகாசிக்கும் விளக்கு போன்ற தூய்மையான இதயம்; 2. மூடப்பட்டுக் கட்டப்பட்ட இதயம்; 3. தலைகீழான இதயம்; 4. கவசம் போன்ற இதயம். அந்தத் தூய்மையான இதயம் முஃமினுடையதாகும், அதில் ஒளியைத் தரும் விளக்கு உள்ளது. மூடப்பட்ட இதயம் என்பது காஃபிருடையதாகும். தலைகீழான இதயம் என்பது முனாஃபிக்கினுடைய (நயவஞ்சகன்) இதயம்; அவன் உண்மையை அறிந்து பின் மறுத்தவன். கவசம் போன்ற இதயத்தில் ஈமானும் நயவஞ்சகமும் கலந்திருக்கும். அதில் உள்ள ஈமானின் உவமை, நல்ல நீரால் வளர்க்கப்படும் ஒரு செடியைப் போன்றது. அதில் உள்ள நயவஞ்சகத்தின் உவமை, இரத்தம் மற்றும் சீழ் ஆகியவற்றால் வளரும் புண்ணைப் போன்றது. இவ்விரண்டில் எது மேலோங்குகிறதோ, அதுவே அந்த இதயத்தை ஆதிக்கம் செலுத்தும்.) இதன் அறிவிப்பாளர் தொடர் வலிமையானது (ஜய்யித்), ஆனால் இதனை புகாரி மற்றும் முஸ்லிம் பதிவு செய்யவில்லை."},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=38\" class=\"link\">24:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:38 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=38\" class=\"link\">24:38</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:38 ஐ பார்க்கவும்"},"38":{"html":"<strong>பள்ளிவாசல்களின் சிறப்புகள், சரியான ஒழுக்கமுறைகள் மற்றும் அவற்றைப் பராமரிப்பவர்களின் சிறப்புகள்</strong><br />\r\nஇறைநம்பிக்கையாளரின் இதயத்தையும், அதில் உள்ள நேர்வழி மற்றும் ஞானத்தையும் ஒரு தெளிவான கண்ணாடியில் நல்ல எண்ணெயால் ஏற்றப்பட்டு பிரகாசிக்கும் விளக்கிற்கு அல்லாஹ் உவமைப்படுத்தினான். அதன் பிறகு, அது எங்கு இருக்க வேண்டும் என்பதை அல்லாஹ் குறிப்பிடுகிறான். அவை பூமியில் அல்லாஹ்விற்கு மிகவும் விருப்பமான இடங்களான மஸ்ஜித்கள் (பள்ளிவாசல்கள்) ஆகும். மஸ்ஜித்கள் அவனுடைய இல்லங்கள், அங்கு அவன் மட்டுமே வணங்கப்படுகிறான். எனவே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">بُيُوتٍ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُرْفَعَ</span><br />\r\n<br />\r\n(அல்லாஹ் எந்த இல்லங்களை உயர்த்தப்பட வேண்டும் என்று கட்டளையிட்டானோ அந்த இல்லங்களில்,) அதாவது அந்த இல்லங்கள் நிறுவப்பட வேண்டும் என்றும், அசுத்தங்கள், வீண் பேச்சுகள், பொருத்தமற்ற வார்த்தைகள் அல்லது செயல்களிலிருந்து அவை தூய்மையாகப் பேணப்பட வேண்டும் என்றும் அல்லாஹ் கட்டளையிட்டுள்ளான். இந்த வசனம் குறித்து இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலீ பின் அபீ தல்ஹா (ரழி) அறிவிப்பதாவது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">بُيُوتٍ</span> <span class=\"quran-arabic-font text-success\">أَذِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُرْفَعَ</span><br />\r\n<br />\r\n(அல்லாஹ் எந்த இல்லங்களை உயர்த்தப்பட வேண்டும் என்று கட்டளையிட்டானோ அந்த இல்லங்களில்,) என்பதற்கு, \"அவற்றில் வீண் பேச்சு பேசுவதை அல்லாஹ் தடுத்துள்ளான்\" என்று அவர்கள் கூறினார்கள். இக்ரிமா, அபூ ஸாலிஹ், அத்-தஹ்ஹாக், நாஃபிஃ பின் ஜுபைர், அபூ பக்ர் பின் சுலைமான் பின் அபீ ஹஸ்மா, ஸுஃப்யான் பின் ஹுஸைன் மற்றும் இதர தஃப்ஸீர் அறிஞர்களும் இதே கருத்தைக் கொண்டுள்ளனர். மஸ்ஜித்களைக் கட்டுவது, அவற்றைக் கண்ணியப்படுத்துவது, கௌரவிப்பது, அவற்றில் நறுமணம் பரப்புவது போன்றவை தொடர்பாகப் பல ஹதீஸ்கள் அறிவிக்கப்பட்டுள்ளன. இது குறித்து பிற இடங்களில் விரிவாக விவாதிக்கப்பட்டுள்ளது. மேலும், இது தொடர்பாக நான் ஒரு தனி நூலையும் எழுதியுள்ளேன், எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே. அல்லாஹ்வின் உதவியுடன், இங்கே ஹதீஸ்கள் சிலவற்றைத் தந்துள்ளோம். அல்லாஹ்வின் மீதே நாங்கள் முழுமையாக நம்பிக்கை வைத்துள்ளோம். இறைநம்பிக்கையாளர்களின் தலைவர் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதை நான் கேட்டேன்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">مَسْجِدًا</span> <span class=\"quran-arabic-font text-success\">يَبْتَغِي</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَجْهَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِثْلَهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span>»<br />\r\n<br />\r\n(யார் அல்லாஹ்வின் திருப்பொருத்தத்தை நாடி ஒரு மஸ்ஜிதைக் கட்டுகிறாரோ, அல்லாஹ் அவருக்குச் சொர்க்கத்தில் அது போன்ற ஒன்றைக் கட்டுவான்.) இது இரு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. இப்னு மாஜா அவர்கள் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">مَسْجِدًا</span> <span class=\"quran-arabic-font text-success\">يُذْكَرُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">اسْمُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">بَنَى</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بَيْتًا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span>»<br />\r\n<br />\r\n(எந்த ஒரு மஸ்ஜிதில் அல்லாஹ்வின் பெயர் நினைவுகூரப்படுகிறதோ, அத்தகைய மஸ்ஜிதை எவர் கட்டுகிறாரோ அவருக்கு அல்லாஹ் சொர்க்கத்தில் ஓர் இல்லத்தைக் கட்டுவான்.) அன்-நஸாஈயும் இதைப் போன்ற ஒரு கருத்தைப் பதிவு செய்துள்ளனர். இது தொடர்பாக ஏராளமான ஹதீஸ்கள் உள்ளன. ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"குடியிருப்புகளுக்கு மத்தியில் மஸ்ஜித்களைக் கட்டவும், அவற்றைத் தூய்மையாக வைத்திருக்கவும், நறுமணம் பூசவும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களுக்குக் கட்டளையிட்டார்கள்.\" இதனை அஹ்மத் மற்றும் அன்-நஸாஈ தவிர்த்த இதர ஸுனன் நூலாசிரியர்கள் பதிவு செய்துள்ளனர். அஹ்மத் மற்றும் அபூ தாவூத் ஆகியோரும் ஸமுரா பின் ஜுன்துப் (ரழி) அவர்களிடமிருந்து இத்தகைய செய்தியைப் பதிவு செய்துள்ளனர். அல்-புகாரி கூறுகிறார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'மக்களை (மழை, வெயிலிலிருந்து) பாதுகாக்கும் வகையில் கட்டுங்கள். சிவப்பு அல்லது மஞ்சள் நிறங்களைப் பயன்படுத்தி அலங்காரம் செய்வதைத் தவிர்த்துக் கொள்ளுங்கள், ஏனெனில் அவை மக்களின் கவனத்தைத் திசைதிருப்பிவிடும்.'\" அபூ தாவூத் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أُمِرْتُ</span> <span class=\"quran-arabic-font text-success\">بِتَشْيِيدِ</span> <span class=\"quran-arabic-font text-success\">الْمَسَاجِدِ</span>»<br />\r\n<br />\r\n(மஸ்ஜித்களை தஷ்யீத் (உயரமாகவும் பகட்டாகவும் கட்டுவது) செய்யுமாறு நான் கட்டளையிடப்படவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"யூதர்களும் கிறிஸ்தவர்களும் செய்ததைப் போல் அவற்றை அலங்கரிப்பதாகும்.\" அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةُ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَتَبَاهَى</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْمَسَاجِدِ</span>»<br />\r\n<br />\r\n(மக்கள் மஸ்ஜித்களைக் கட்டுவதில் ஒருவருக்கொருவர் பெருமையடித்துக் கொள்ளும் வரை மறுமை நாள் வராது.) இதனை அஹ்மத் மற்றும் அத்-திர்மிதி தவிர்த்த இதர ஸுனன் நூலாசிரியர்கள் பதிவு செய்துள்ளனர். புரைதா (ரழி) அவர்கள் அறிவிப்பதாவது: ஒரு மனிதர் மஸ்ஜிதில் சத்தமிட்டு, \"சிவப்பு ஒட்டகத்தைப் பற்றி யாராவது தகவல் கூற முடியுமா?\" என்று கேட்டார். அதற்கு நபிகள் நாயகம் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">وَجَدْتَ،</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">بُنِيَتِ</span> <span class=\"quran-arabic-font text-success\">الْمَسَاجِدُ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">بُنِيَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>»<br />\r\n<br />\r\n(உனக்கு அது கிடைக்காமல் போகட்டும்! மஸ்ஜித்கள் எதற்காகக் கட்டப்பட்டதோ அதற்காக மட்டுமே அவை உள்ளன.) இதனை முஸ்லிம் அவர்கள் பதிவு செய்துள்ளனர். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَبِيعُ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَبْتَاعُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدِ،</span> <span class=\"quran-arabic-font text-success\">فَقُولُوا</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَرْبَحَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تِجَارَتَكَ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">يَنْشُدُ</span> <span class=\"quran-arabic-font text-success\">ضَالَّةً</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدِ</span> <span class=\"quran-arabic-font text-success\">فَقُولُوا</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">رَدَّهَا</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span>»<br />\r\n<br />\r\n(மஸ்ஜிதில் ஒருவர் வியாபாரம் செய்வதையோ அல்லது வாங்குவதையோ நீங்கள் கண்டால், அவருக்கு, \"அல்லாஹ் உனது வியாபாரத்தில் இலாபத்தைக் கொடுக்காமல் இருக்கட்டும்\" என்று கூறுங்கள். காணாமல் போன பொருளைப் பற்றி ஒருவர் அறிவிப்பதைக் கண்டால், \"அல்லாஹ் அதை உன்னிடம் திரும்பச் சேர்க்காமல் இருக்கட்டும்\" என்று கூறுங்கள்.) இதனை அத்-திர்மிதி பதிவு செய்து, \"ஹஸன் ஃகரீப்\" என்று குறிப்பிட்டுள்ளார்கள். அல்-புகாரியில் அஸ்-ஸாயிப் பின் யஸீத் அல்-கிந்தி அவர்கள் அறிவிப்பதாவது: \"நான் மஸ்ஜிதில் நின்று கொண்டிருந்தபோது, ஒருவர் என் மீது சிறு கற்களை எறிந்தார். நான் நிமிர்ந்து பார்த்தபோது உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் நின்றிருந்தார்கள். அவர்கள், 'நீ சென்று அந்த இரு மனிதர்களையும் என்னிடம் அழைத்து வா' என்று கூறினார்கள். நான் அவர்களை அழைத்து வந்தேன். உமர் (ரழி) அவர்கள் அவர்களிடம், 'நீங்கள் யார்?' அல்லது 'நீங்கள் எங்கிருந்து வருகிறீர்கள்?' என்று கேட்டார்கள். அதற்கு அவர்கள் 'நாங்கள் தாயிஃபிலிருந்து வருகிறோம்' என்றனர். அப்போது உமர் (ரழி) அவர்கள், 'நீங்கள் இவ்வூரைச் சேர்ந்தவர்களாக இருந்திருந்தால் உங்களைத் தண்டித்திருப்பேன், ஏனெனில் அல்லாஹ்வின் தூதருடைய (ஸல்) மஸ்ஜிதில் உங்கள் குரல்களை உயர்த்துகிறீர்கள்' என்று கூறினார்கள்.\" அன்-நஸாஈயில் இப்ராஹீம் பின் அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்கள் அறிவிப்பதாவது: \"மஸ்ஜிதில் ஒரு மனிதர் சத்தமாகப் பேசுவதை உமர் (ரழி) அவர்கள் கேட்டு, 'நீ எங்கே இருக்கிறாய் என்று உனக்குத் தெரியுமா?' என்று கேட்டார்கள்.\" இது ஸஹீஹான செய்தியாகும். ஹாஃபிழ் அபூ யஃலா அல்-மூஸிலி அவர்கள் இப்னு உமர் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: உமர் (ரழி) அவர்கள் ஒவ்வொரு வெள்ளிக்கிழமையும் அல்லாஹ்வின் தூதருடைய (ஸல்) மஸ்ஜிதில் நறுமணப் புகை காட்டுவார்கள். இதன் அறிவிப்பாளர் தொடர் 'ஹஸன்' ஆகும், இதில் எந்தக் குறையுமில்லை, அல்லாஹ்வே மிக அறிந்தவன். இரு ஸஹீஹ் நூல்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">صَلَاةُ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَمَاعَةِ</span> <span class=\"quran-arabic-font text-success\">تُضَعَّفُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صَلَاتِهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">بَيْتِهِ</span> <span class=\"quran-arabic-font text-success\">وَفِي</span> <span class=\"quran-arabic-font text-success\">سُوقِهِ</span> <span class=\"quran-arabic-font text-success\">خَمْسًا</span> <span class=\"quran-arabic-font text-success\">وَعِشْرِينَ</span> <span class=\"quran-arabic-font text-success\">ضِعْفًا</span> <span class=\"quran-arabic-font text-success\">وَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">إَذَا</span> <span class=\"quran-arabic-font text-success\">تَوَضَّأَ</span> <span class=\"quran-arabic-font text-success\">فَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">وُضُوءَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">خَرَجَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدِ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُخْرِجُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةُ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَخْطُ</span> <span class=\"quran-arabic-font text-success\">خَطْوَةً</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">رُفِعَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">دَرَجَةٌ</span> <span class=\"quran-arabic-font text-success\">وَحُطَّ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">خَطِيئَةٌ</span>. <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">صَلَّى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَزَلِ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">تُصَلِّي</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">دَامَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مُصَلَّاهُ</span>: <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">صَلِّ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ،</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">ارْحَمْهُ</span>. <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَزَالُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">صَلَاةٍ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">انْتَظَرَ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةَ</span>»<br />\r\n<br />\r\n(ஒரு மனிதர் ஜமாஅத்தாகத் (கூட்டாகத்) தொழுவது, அவர் தனது வீட்டிலோ அல்லது சந்தையிலோ தொழுவதை விட இருபத்தைந்து மடங்கு சிறந்ததாகும். ஏனெனில், ஒருவர் அழகிய முறையில் உளூச் செய்து, தொழுகையைத் தவிர வேறு எந்த நோக்கமும் இன்றி மஸ்ஜிதிற்குப் புறப்பட்டால், அவர் எடுத்து வைக்கும் ஒவ்வொரு அடிக்கும் அவரது அந்தஸ்து ஒரு படி உயர்த்தப்படுகிறது, மேலும் அவரது ஒரு பாவம் மன்னிக்கப்படுகிறது. அவர் தொழுது முடித்த பின், தான் தொழுத இடத்திலேயே இருக்கும் வரை வானவர்கள் அவருக்காகப் பிரார்த்தனை செய்து கொண்டிருப்பார்கள். அவர்கள், \"யா அல்லாஹ், இவருக்கு அருள்புரிவாயாக! யா அல்லாஹ், இவருக்குக் கருணை காட்டுவாயாக!\" என்பார்கள். மேலும் ஒருவர் தொழுகைக்காகக் காத்திருக்கும் வரை, அவர் தொழுகையிலேயே இருப்பதாகக் கருதப்படுவார்.) ஸுனன் நூல்களில் பின்வருமாறு பதிவாகியுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بَشِّرِ</span> <span class=\"quran-arabic-font text-success\">الْمَشَّائِينَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْمَسَاجِدِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الظُّلَمِ</span> <span class=\"quran-arabic-font text-success\">بِالنُّورِ</span> <span class=\"quran-arabic-font text-success\">التَّامِّ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span>»<br />\r\n<br />\r\n(இருளான நேரங்களில் மஸ்ஜித்களை நோக்கி நடப்பவர்களுக்கு, மறுமை நாளில் முழுமையான ஒளி கிடைக்கும் என்ற நற்செய்தியைக் கூறுங்கள்.) மஸ்ஜிதிற்குள் நுழையும் போது வலது காலை முதலில் வைத்து நுழைவது சுன்னத்தாகும். ஸஹீஹ் அல்-புகாரியில் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதிற்குள் நுழையும் போது இத்துஆவைக் கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَعُوذُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ</span> <span class=\"quran-arabic-font text-success\">وَبِوَجْهِهِ</span> <span class=\"quran-arabic-font text-success\">الْكَرِيمِ،</span> <span class=\"quran-arabic-font text-success\">وَسُلْطَانِهِ</span> <span class=\"quran-arabic-font text-success\">الْقَدِيمِ،</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">الرَّجِيمِ</span>»<br />\r\n<br />\r\n(மகத்தான அல்லாஹ்விடமும், அவனது கண்ணியமிக்க முகத்திடமும், அவனது நித்தியமான ஆதிக்கத்திடமும் சபிக்கப்பட்ட ஷைத்தானிடமிருந்து பாதுகாப்புத் தேடுகிறேன்.) அறிவிப்பாளர்களில் ஒருவர், \"இவ்வளவு தானா?\" என்று கேட்டார். அதற்கு, \"ஆம்\" என்று பதிலளிக்கப்பட்டது. ஒருவர் இதைக் கூறினால், ஷைத்தான், \"அவர் நாள் முழுவதும் என்னிடமிருந்து பாதுகாப்பைப் பெற்றுவிட்டார்\" என்று கூறுகிறான். முஸ்லிம் நூலில் அபூ ஹுமைத் அல்லது அபூ உஸைத் (ரழி) அறிவிப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَقُلْ</span>: <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">افْتَحْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">أَبْوَابَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَتِكَ</span>. <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">خَرَجَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَقُلْ</span>: <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">فَضْلِكَ</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் மஸ்ஜிதிற்குள் நுழையும் போது, \"யா அல்லாஹ், உனது கருணையின் வாசல்களை எனக்காகத் திறப்பாயாக\" என்று கூறட்டும். அவர் வெளியே வரும்போது, \"யா அல்லாஹ், உனது அருளை உன்னிடம் வேண்டுகிறேன்\" என்று கூறட்டும்.) அன்-நஸாஈயும் இதனைப் பதிவு செய்துள்ளனர். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دَخَلَ</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجِدَ</span> <span class=\"quran-arabic-font text-success\">فَلْيُسَلِّمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّبِيِّ</span>. <span class=\"quran-arabic-font text-success\">وَلْيَقُلِ</span>: <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">افْتَحْ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">أَبْوَابَ</span> <span class=\"quran-arabic-font text-success\">رَحْمَتِكَ،</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">خَرَجَ</span> <span class=\"quran-arabic-font text-success\">فَلْيُسَلِّمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّبِيِّ</span> <span class=\"quran-arabic-font text-success\">وَلْيَقُلِ</span>: <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">اعْصِمْنِي</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانِ</span> <span class=\"quran-arabic-font text-success\">الرَّجِيمِ</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் மஸ்ஜிதிற்குள் நுழையும் போது நபியின் மீது ஸலவாத் கூறிவிட்டு, \"யா அல்லாஹ், உனது கருணையின் வாசல்களை எனக்காகத் திறப்பாயாக\" என்று கூறட்டும். அவர் வெளியே வரும்போது நபியின் மீது ஸலவாத் கூறிவிட்டு, \"யா அல்லாஹ், சபிக்கப்பட்ட ஷைத்தானிடமிருந்து என்னைப் பாதுகாப்பாயாக\" என்று கூறட்டும்.) இதனை இப்னு மாஜா, இப்னு குஸைமா மற்றும் இப்னு ஹிப்பான் ஆகியோரும் தங்களது ஸஹீஹ் நூல்களில் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُذْكَرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">اسْمُهُ</span><br />\r\n<br />\r\n(அவற்றில் அவனது பெயர் நினைவுகூரப்படுகிறது.) அதாவது, அல்லாஹ்வின் பெயர். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـبَنِى</span> <span class=\"quran-arabic-font text-success\">ءَادَمَ</span> <span class=\"quran-arabic-font text-success\">خُذُواْ</span> <span class=\"quran-arabic-font text-success\">زِينَتَكُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">مَسْجِدٍ</span><br />\r\n<br />\r\n(ஆதமின் மக்களே! ஒவ்வொரு மஸ்ஜிதிலும் உங்கள் அலங்காரத்தை அணிந்து கொள்ளுங்கள்...) <a href=\"qurandisp.php?sura=7&ayah=31\" class=\"link\">7:31</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَقِيمُواْ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَكُمْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">مَسْجِدٍ</span> <span class=\"quran-arabic-font text-success\">وَادْعُوهُ</span> <span class=\"quran-arabic-font text-success\">مُخْلِصِينَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الدِّينَ</span><br />\r\n<br />\r\n(ஒவ்வொரு மஸ்ஜிதிலும் அவனையே நோக்கி உங்கள் முகங்களை நிலைப்படுத்துங்கள்; உங்கள் மார்க்கத்தை அவனுக்கே உரித்தாக்கி, அவனிடமே பிரார்த்தியுங்கள்.) <a href=\"qurandisp.php?sura=7&ayah=29\" class=\"link\">7:29</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَسَـجِدَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span><br />\r\n<br />\r\n(நிச்சயமாக மஸ்ஜித்கள் அல்லாஹ்வுக்கே உரியவை.) <a href=\"qurandisp.php?sura=72&ayah=18\" class=\"link\">72:18</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُذْكَرَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">اسْمُهُ</span><br />\r\n<br />\r\n(அவற்றில் அவனது பெயர் நினைவுகூரப்படுகிறது.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள், அவற்றில் அவனது வேதம் (குர்ஆன்) ஓதப்படுகிறது என்பதாகும்\" என்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">بِالْغُدُوِّ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّصَالِ</span><br />\r\n<br />\r\n(அவற்றில் காலையிலும் மாலையிலும் அவனது தூய்மையை அவர்கள் போற்றுகிறார்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رِجَالٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُلْهِيهِمْ</span> <span class=\"quran-arabic-font text-success\">تِجَـرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَيْعٌ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்) இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُلْهِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْوَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَوْلَـدُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டோரே! உங்கள் செல்வங்களோ அல்லது உங்கள் பிள்ளைகளோ உங்களை அல்லாஹ்வின் நினைவிலிருந்து திசைதிருப்பி விட வேண்டாம்.) <a href=\"qurandisp.php?sura=63&ayah=9\" class=\"link\">63:9</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">نُودِىَ</span> <span class=\"quran-arabic-font text-success\">لِلصَّلَوةِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْجُمُعَةِ</span> <span class=\"quran-arabic-font text-success\">فَاسْعَوْاْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَذَرُواْ</span> <span class=\"quran-arabic-font text-success\">الْبَيْعَ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டோரே! வெள்ளிக்கிழமை தொழுகைக்காக அழைப்பு விடுக்கப்பட்டால், அல்லாஹ்வின் நினைவின் பக்கம் விரைந்து செல்லுங்கள்; வியாபாரத்தை விட்டுவிடுங்கள்.) <a href=\"qurandisp.php?sura=62&ayah=9\" class=\"link\">62:9</a><br />\r\n<br />\r\nஇந்த உலகமும் அதன் அலங்காரங்களும், கவர்ச்சிகளும், சந்தைகளும் தங்களைப் படைத்துப் பராமரிக்கும் இறைவனை நினைவுகூருவதை விட்டும் அவர்களைத் திசைதிருப்பிவிடக் கூடாது என்று அல்லாஹ் கூறுகிறான். தங்களிடம் உள்ளதை விட அல்லாஹ்விடம் இருப்பதே சிறந்தது என்று அவர்கள் அறிவார்கள்; ஏனெனில் உலகப் பொருட்கள் அழியக்கூடியவை, அல்லாஹ்விடம் இருப்பவையோ நிலையானவை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُلْهِيهِمْ</span> <span class=\"quran-arabic-font text-success\">تِجَـرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَيْعٌ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَإِقَامِ</span> <span class=\"quran-arabic-font text-success\">الصَّلَوةِ</span> <span class=\"quran-arabic-font text-success\">وَإِيتَآءِ</span> <span class=\"quran-arabic-font text-success\">الزَّكَـوةِ</span><br />\r\n<br />\r\n(அல்லாஹ்வை நினைவுகூருவதை விட்டும், தொழுகையை நிலைநாட்டுவதை விட்டும், ஜகாத் வழங்குவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்). அதாவது, அவர்கள் தங்களுக்கு விருப்பமானவற்றை விட, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிவதற்கும், அவன் எதை விரும்புகிறானோ அதைச் செய்வதற்கும் முன்னுரிமை அளிக்கிறார்கள். சாலிம் (ரஹ்) அவர்கள் இப்னு உமர் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: அவர்கள் சந்தையில் இருந்தபோது தொழுகைக்கான இகாமத் சொல்லப்பட்டது; உடனே அவர்கள் தங்கள் கடைகளை மூடிவிட்டு மஸ்ஜிதிற்குள் நுழைந்தார்கள். இப்னு உமர் (ரழி) அவர்கள் கூறினார்கள்: \"இவர்களைக் குறித்து தான் இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رِجَالٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُلْهِيهِمْ</span> <span class=\"quran-arabic-font text-success\">تِجَـرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَيْعٌ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்).\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُلْهِيهِمْ</span> <span class=\"quran-arabic-font text-success\">تِجَـرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَيْعٌ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">ذِكْرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்). இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் கடமையாக்கப்பட்ட தொழுகைகளாகும்\" என்று கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அறிவிக்கிறார்கள். முகாதில் பின் ஹய்யான் மற்றும் அர்-ரபீஃ பின் அனஸ் ஆகியோரும் இதே கருத்தைக் கொண்டுள்ளனர். அஸ்-ஸுத்தி அவர்கள், \"ஜமாஅத் தொழுகை\" என்று குறிப்பிடுகிறார்கள். முகாதில் பின் ஹய்யான் அவர்கள் கூறுகையில், \"அல்லாஹ் கட்டளையிட்டபடி தொழுகையில் கலந்துகொள்வதிலிருந்தும், குறிப்பிட்ட நேரங்களில் அதனை நிறைவேற்றுவதிலிருந்தும், தொழுகையில் அல்லாஹ் அவர்கள் மீது கடமையாக்கிய எதையும் செய்வதிலிருந்தும் உலகம் அவர்களைத் திசைதிருப்புவதில்லை\" என்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَخَـفُونَ</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span> <span class=\"quran-arabic-font text-success\">تَتَقَلَّبُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الْقُلُوبُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّبْصَـرُ</span><br />\r\n<br />\r\n(இதயங்களும் பார்வைகளும் நிலைகுலைந்து புரளும் ஒரு நாளை அவர்கள் அஞ்சுகிறார்கள்.) அதாவது, அந்த நாளின் பயங்கரமும் அதிர்ச்சியும் கடுமையாக இருப்பதால் மக்களின் இதயங்களும் கண்களும் நிலைகுலைந்து போகும் மறுமை நாளைக் குறிக்கிறது. இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرْهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الاٌّزِفَةِ</span><br />\r\n<br />\r\n(நெருங்கி வரும் நாளைப் பற்றி அவர்களை எச்சரிப்பீராக...) <a href=\"qurandisp.php?sura=40&ayah=18\" class=\"link\">40:18</a>,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">يُؤَخِّرُهُمْ</span> <span class=\"quran-arabic-font text-success\">لِيَوْمٍ</span> <span class=\"quran-arabic-font text-success\">تَشْخَصُ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">الأَبْصَـرُ</span><br />\r\n<br />\r\n(நிச்சயமாக, கண்கள் நிலைகுத்தி நிற்கும் ஒரு நாள் வரை அவர்களுக்கு அவன் அவகாசம் அளிக்கிறான்) <a href=\"qurandisp.php?sura=14&ayah=42\" class=\"link\">14:42</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيُطْعِمُونَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">حُبِّهِ</span> <span class=\"quran-arabic-font text-success\">مِسْكِيناً</span> <span class=\"quran-arabic-font text-success\">وَيَتِيماً</span> <span class=\"quran-arabic-font text-success\">وَأَسِيراً</span> - <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">نُطْعِمُكُمْ</span> <span class=\"quran-arabic-font text-success\">لِوَجْهِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نُرِيدُ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">جَزَآءً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">شُكُوراً</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">نَخَافُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّنَا</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span> <span class=\"quran-arabic-font text-success\">عَبُوساً</span> <span class=\"quran-arabic-font text-success\">قَمْطَرِيراً</span> - <span class=\"quran-arabic-font text-success\">فَوَقَـهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">شَرَّ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">الْيَومِ</span> <span class=\"quran-arabic-font text-success\">وَلَقَّـهُمْ</span> <span class=\"quran-arabic-font text-success\">نَضْرَةً</span> <span class=\"quran-arabic-font text-success\">وَسُرُوراً</span> - <span class=\"quran-arabic-font text-success\">وَجَزَاهُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ</span> <span class=\"quran-arabic-font text-success\">جَنَّةً</span> <span class=\"quran-arabic-font text-success\">وَحَرِيراً</span><br />\r\n<br />\r\n(உணவின் மீது விருப்பம் இருந்த போதிலும், ஏழைக்கும் அநாதைக்கும் கைதிக்கும் அவர்கள் உணவளிக்கிறார்கள். \"நாங்கள் அல்லாஹ்வின் திருப்பொருத்தத்திற்காகவே உங்களுக்கு உணவளிக்கிறோம்; உங்களிடமிருந்து எந்தப் பிரதிபலனையோ நன்றியையோ நாங்கள் எதிர்பார்க்கவில்லை. நிச்சயமாக நாம் நம் இறைவனிடமிருந்து மிகக் கடுமையான, துன்பம் நிறைந்த ஒரு நாளை அஞ்சுகிறோம்\" (என்று அவர்கள் கூறுவர்). எனவே, அல்லாஹ் அவர்களை அந்த நாளின் தீமையிலிருந்து பாதுகாத்து, அவர்களுக்குப் பொலிவையும் மகிழ்ச்சியையும் வழங்கினான். அவர்கள் பொறுமையாக இருந்த காரணத்தால் அவர்களுக்குச் சொர்க்கத்தையும் பட்டு ஆடைகளையும் வெகுமதியாக வழங்கினான்.) <a href=\"qurandisp.php?sura=76&ayah=8\" class=\"link\">76:8</a>-12. மேலும் அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيَجْزِيَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span><br />\r\n<br />\r\n(அல்லாஹ் அவர்களின் நற்செயல்களில் சிறந்தவற்றிற்குப் பிரதிபலன் அளிப்பதற்காகவும்,) அதாவது \"அவர்களின் நற்செயல்களில் சிறந்தவற்றை நாம் ஏற்றுக்கொண்டு, அவர்களின் தீய செயல்களை நாம் மன்னிப்போம்\" என்று பொருள்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَزِيدَهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ</span><br />\r\n<br />\r\n(மேலும் அவனது அருளிலிருந்து அவர்களுக்கு இன்னும் அதிகமாகச் சேர்ப்பான்.) அதாவது அல்லாஹ் அவர்களின் நற்செயல்களை ஏற்றுக்கொண்டு, அவற்றுக்கான நன்மைகளை அவர்களுக்குப் பன்மடங்காக்கித் தருவான். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَظْلِمُ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் ஒரு அணுவளவும் அநீதி இழைக்கமாட்டான்.) <a href=\"qurandisp.php?sura=4&ayah=40\" class=\"link\">4:40</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَسَنَةِ</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">عَشْرُ</span> <span class=\"quran-arabic-font text-success\">أَمْثَالِهَا</span><br />\r\n<br />\r\n(யார் ஒரு நன்மையைச் செய்கிறாரோ, அவருக்கு அது போன்ற பத்து மடங்கு நன்மைகள் உண்டு.) <a href=\"qurandisp.php?sura=6&ayah=160\" class=\"link\">6:160</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">ذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُقْرِضُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">قَرْضًا</span> <span class=\"quran-arabic-font text-success\">حَسَنًا</span><br />\r\n<br />\r\n(அல்லாஹ்வுக்கு அழகிய முறையில் கடன் வழங்குபவர் யார்?) <a href=\"qurandisp.php?sura=2&ayah=245\" class=\"link\">2:245</a><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يُضَـعِفُ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n(அல்லாஹ் தான் நாடியவர்களுக்குப் பன்மடங்காகப் பெருகச் செய்கிறான்.) <a href=\"qurandisp.php?sura=2&ayah=261\" class=\"link\">2:261</a> மேலும் அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَرْزُقُ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">حِسَابٍ</span><br />\r\n<br />\r\n(மேலும் அல்லாஹ் தான் நாடியவர்களுக்குக் கணக்கின்றி வழங்குகிறான்.)<br />\r\n<br />","text":"பள்ளிவாசல்களின் சிறப்புகள், சரியான ஒழுக்கமுறைகள் மற்றும் அவற்றைப் பராமரிப்பவர்களின் சிறப்புகள்\n\r\nஇறைநம்பிக்கையாளரின் இதயத்தையும், அதில் உள்ள நேர்வழி மற்றும் ஞானத்தையும் ஒரு தெளிவான கண்ணாடியில் நல்ல எண்ணெயால் ஏற்றப்பட்டு பிரகாசிக்கும் விளக்கிற்கு அல்லாஹ் உவமைப்படுத்தினான். அதன் பிறகு, அது எங்கு இருக்க வேண்டும் என்பதை அல்லாஹ் குறிப்பிடுகிறான். அவை பூமியில் அல்லாஹ்விற்கு மிகவும் விருப்பமான இடங்களான மஸ்ஜித்கள் (பள்ளிவாசல்கள்) ஆகும். மஸ்ஜித்கள் அவனுடைய இல்லங்கள், அங்கு அவன் மட்டுமே வணங்கப்படுகிறான். எனவே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفِى بُيُوتٍ أَذِنَ اللَّهُ أَن تُرْفَعَ\n\r\n\n\r\n(அல்லாஹ் எந்த இல்லங்களை உயர்த்தப்பட வேண்டும் என்று கட்டளையிட்டானோ அந்த இல்லங்களில்,) அதாவது அந்த இல்லங்கள் நிறுவப்பட வேண்டும் என்றும், அசுத்தங்கள், வீண் பேச்சுகள், பொருத்தமற்ற வார்த்தைகள் அல்லது செயல்களிலிருந்து அவை தூய்மையாகப் பேணப்பட வேண்டும் என்றும் அல்லாஹ் கட்டளையிட்டுள்ளான். இந்த வசனம் குறித்து இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அலீ பின் அபீ தல்ஹா (ரழி) அறிவிப்பதாவது:\n\r\n\n\r\nفِى بُيُوتٍ أَذِنَ اللَّهُ أَن تُرْفَعَ\n\r\n\n\r\n(அல்லாஹ் எந்த இல்லங்களை உயர்த்தப்பட வேண்டும் என்று கட்டளையிட்டானோ அந்த இல்லங்களில்,) என்பதற்கு, \"அவற்றில் வீண் பேச்சு பேசுவதை அல்லாஹ் தடுத்துள்ளான்\" என்று அவர்கள் கூறினார்கள். இக்ரிமா, அபூ ஸாலிஹ், அத்-தஹ்ஹாக், நாஃபிஃ பின் ஜுபைர், அபூ பக்ர் பின் சுலைமான் பின் அபீ ஹஸ்மா, ஸுஃப்யான் பின் ஹுஸைன் மற்றும் இதர தஃப்ஸீர் அறிஞர்களும் இதே கருத்தைக் கொண்டுள்ளனர். மஸ்ஜித்களைக் கட்டுவது, அவற்றைக் கண்ணியப்படுத்துவது, கௌரவிப்பது, அவற்றில் நறுமணம் பரப்புவது போன்றவை தொடர்பாகப் பல ஹதீஸ்கள் அறிவிக்கப்பட்டுள்ளன. இது குறித்து பிற இடங்களில் விரிவாக விவாதிக்கப்பட்டுள்ளது. மேலும், இது தொடர்பாக நான் ஒரு தனி நூலையும் எழுதியுள்ளேன், எல்லாப் புகழும் அருளும் அல்லாஹ்வுக்கே. அல்லாஹ்வின் உதவியுடன், இங்கே ஹதீஸ்கள் சிலவற்றைத் தந்துள்ளோம். அல்லாஹ்வின் மீதே நாங்கள் முழுமையாக நம்பிக்கை வைத்துள்ளோம். இறைநம்பிக்கையாளர்களின் தலைவர் உஸ்மான் பின் அஃப்பான் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறுவதை நான் கேட்டேன்:\n\r\n\n\r\n«مَنْ بَنَى مَسْجِدًا يَبْتَغِي بِهِ وَجْهَ اللهِ بَنَى اللهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ»\n\r\n\n\r\n(யார் அல்லாஹ்வின் திருப்பொருத்தத்தை நாடி ஒரு மஸ்ஜிதைக் கட்டுகிறாரோ, அல்லாஹ் அவருக்குச் சொர்க்கத்தில் அது போன்ற ஒன்றைக் கட்டுவான்.) இது இரு ஸஹீஹ் நூல்களிலும் இடம்பெற்றுள்ளது. இப்னு மாஜா அவர்கள் உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَنْ بَنَى مَسْجِدًا يُذْكَرُ فِيهِ اسْمُ اللهِ بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ»\n\r\n\n\r\n(எந்த ஒரு மஸ்ஜிதில் அல்லாஹ்வின் பெயர் நினைவுகூரப்படுகிறதோ, அத்தகைய மஸ்ஜிதை எவர் கட்டுகிறாரோ அவருக்கு அல்லாஹ் சொர்க்கத்தில் ஓர் இல்லத்தைக் கட்டுவான்.) அன்-நஸாஈயும் இதைப் போன்ற ஒரு கருத்தைப் பதிவு செய்துள்ளனர். இது தொடர்பாக ஏராளமான ஹதீஸ்கள் உள்ளன. ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"குடியிருப்புகளுக்கு மத்தியில் மஸ்ஜித்களைக் கட்டவும், அவற்றைத் தூய்மையாக வைத்திருக்கவும், நறுமணம் பூசவும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எங்களுக்குக் கட்டளையிட்டார்கள்.\" இதனை அஹ்மத் மற்றும் அன்-நஸாஈ தவிர்த்த இதர ஸுனன் நூலாசிரியர்கள் பதிவு செய்துள்ளனர். அஹ்மத் மற்றும் அபூ தாவூத் ஆகியோரும் ஸமுரா பின் ஜுன்துப் (ரழி) அவர்களிடமிருந்து இத்தகைய செய்தியைப் பதிவு செய்துள்ளனர். அல்-புகாரி கூறுகிறார்கள்: \"உமர் (ரழி) அவர்கள் கூறினார்கள்: 'மக்களை (மழை, வெயிலிலிருந்து) பாதுகாக்கும் வகையில் கட்டுங்கள். சிவப்பு அல்லது மஞ்சள் நிறங்களைப் பயன்படுத்தி அலங்காரம் செய்வதைத் தவிர்த்துக் கொள்ளுங்கள், ஏனெனில் அவை மக்களின் கவனத்தைத் திசைதிருப்பிவிடும்.'\" அபூ தாவூத் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிப்பதாவது, \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَا أُمِرْتُ بِتَشْيِيدِ الْمَسَاجِدِ»\n\r\n\n\r\n(மஸ்ஜித்களை தஷ்யீத் (உயரமாகவும் பகட்டாகவும் கட்டுவது) செய்யுமாறு நான் கட்டளையிடப்படவில்லை.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"யூதர்களும் கிறிஸ்தவர்களும் செய்ததைப் போல் அவற்றை அலங்கரிப்பதாகும்.\" அனஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا تَقُومُ السَّاعَةُ حَتَّى يَتَبَاهَى النَّاسُ فِي الْمَسَاجِدِ»\n\r\n\n\r\n(மக்கள் மஸ்ஜித்களைக் கட்டுவதில் ஒருவருக்கொருவர் பெருமையடித்துக் கொள்ளும் வரை மறுமை நாள் வராது.) இதனை அஹ்மத் மற்றும் அத்-திர்மிதி தவிர்த்த இதர ஸுனன் நூலாசிரியர்கள் பதிவு செய்துள்ளனர். புரைதா (ரழி) அவர்கள் அறிவிப்பதாவது: ஒரு மனிதர் மஸ்ஜிதில் சத்தமிட்டு, \"சிவப்பு ஒட்டகத்தைப் பற்றி யாராவது தகவல் கூற முடியுமா?\" என்று கேட்டார். அதற்கு நபிகள் நாயகம் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَا وَجَدْتَ، إِنَّمَا بُنِيَتِ الْمَسَاجِدُ لِمَا بُنِيَتْ لَهُ»\n\r\n\n\r\n(உனக்கு அது கிடைக்காமல் போகட்டும்! மஸ்ஜித்கள் எதற்காகக் கட்டப்பட்டதோ அதற்காக மட்டுமே அவை உள்ளன.) இதனை முஸ்லிம் அவர்கள் பதிவு செய்துள்ளனர். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا رَأَيْتُمْ مَنْ يَبِيعُ أَوْ يَبْتَاعُ فِي الْمَسْجِدِ، فَقُولُوا: لَا أَرْبَحَ اللهُ تِجَارَتَكَ، وَإِذَا رَأَيْتُمْ مَنْ يَنْشُدُ ضَالَّةً فِي الْمَسْجِدِ فَقُولُوا: لَا رَدَّهَا اللهُ عَلَيْكَ»\n\r\n\n\r\n(மஸ்ஜிதில் ஒருவர் வியாபாரம் செய்வதையோ அல்லது வாங்குவதையோ நீங்கள் கண்டால், அவருக்கு, \"அல்லாஹ் உனது வியாபாரத்தில் இலாபத்தைக் கொடுக்காமல் இருக்கட்டும்\" என்று கூறுங்கள். காணாமல் போன பொருளைப் பற்றி ஒருவர் அறிவிப்பதைக் கண்டால், \"அல்லாஹ் அதை உன்னிடம் திரும்பச் சேர்க்காமல் இருக்கட்டும்\" என்று கூறுங்கள்.) இதனை அத்-திர்மிதி பதிவு செய்து, \"ஹஸன் ஃகரீப்\" என்று குறிப்பிட்டுள்ளார்கள். அல்-புகாரியில் அஸ்-ஸாயிப் பின் யஸீத் அல்-கிந்தி அவர்கள் அறிவிப்பதாவது: \"நான் மஸ்ஜிதில் நின்று கொண்டிருந்தபோது, ஒருவர் என் மீது சிறு கற்களை எறிந்தார். நான் நிமிர்ந்து பார்த்தபோது உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் நின்றிருந்தார்கள். அவர்கள், 'நீ சென்று அந்த இரு மனிதர்களையும் என்னிடம் அழைத்து வா' என்று கூறினார்கள். நான் அவர்களை அழைத்து வந்தேன். உமர் (ரழி) அவர்கள் அவர்களிடம், 'நீங்கள் யார்?' அல்லது 'நீங்கள் எங்கிருந்து வருகிறீர்கள்?' என்று கேட்டார்கள். அதற்கு அவர்கள் 'நாங்கள் தாயிஃபிலிருந்து வருகிறோம்' என்றனர். அப்போது உமர் (ரழி) அவர்கள், 'நீங்கள் இவ்வூரைச் சேர்ந்தவர்களாக இருந்திருந்தால் உங்களைத் தண்டித்திருப்பேன், ஏனெனில் அல்லாஹ்வின் தூதருடைய (ஸல்) மஸ்ஜிதில் உங்கள் குரல்களை உயர்த்துகிறீர்கள்' என்று கூறினார்கள்.\" அன்-நஸாஈயில் இப்ராஹீம் பின் அப்துர் ரஹ்மான் பின் அவ்ஃப் (ரழி) அவர்கள் அறிவிப்பதாவது: \"மஸ்ஜிதில் ஒரு மனிதர் சத்தமாகப் பேசுவதை உமர் (ரழி) அவர்கள் கேட்டு, 'நீ எங்கே இருக்கிறாய் என்று உனக்குத் தெரியுமா?' என்று கேட்டார்கள்.\" இது ஸஹீஹான செய்தியாகும். ஹாஃபிழ் அபூ யஃலா அல்-மூஸிலி அவர்கள் இப்னு உமர் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: உமர் (ரழி) அவர்கள் ஒவ்வொரு வெள்ளிக்கிழமையும் அல்லாஹ்வின் தூதருடைய (ஸல்) மஸ்ஜிதில் நறுமணப் புகை காட்டுவார்கள். இதன் அறிவிப்பாளர் தொடர் 'ஹஸன்' ஆகும், இதில் எந்தக் குறையுமில்லை, அல்லாஹ்வே மிக அறிந்தவன். இரு ஸஹீஹ் நூல்களிலும் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக உறுதிப்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\n«صَلَاةُ الرَّجُلِ فِي الْجَمَاعَةِ تُضَعَّفُ عَلَى صَلَاتِهِ فِي بَيْتِهِ وَفِي سُوقِهِ خَمْسًا وَعِشْرِينَ ضِعْفًا وَذَلِكَ أَنَّهُ إَذَا تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ لَا يُخْرِجُهُ إِلَّا الصَّلَاةُ لَمْ يَخْطُ خَطْوَةً إِلَّا رُفِعَ لَهُ بِهَا دَرَجَةٌ وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ. فَإِذَا صَلَّى لَمْ تَزَلِ الْمَلَائِكَةُ تُصَلِّي عَلَيْهِ مَا دَامَ فِي مُصَلَّاهُ: اللَّهُمَّ صَلِّ عَلَيْهِ، اللَّهُمَّ ارْحَمْهُ. وَلَا يَزَالُ فِي صَلَاةٍ مَا انْتَظَرَ الصَّلَاةَ»\n\r\n\n\r\n(ஒரு மனிதர் ஜமாஅத்தாகத் (கூட்டாகத்) தொழுவது, அவர் தனது வீட்டிலோ அல்லது சந்தையிலோ தொழுவதை விட இருபத்தைந்து மடங்கு சிறந்ததாகும். ஏனெனில், ஒருவர் அழகிய முறையில் உளூச் செய்து, தொழுகையைத் தவிர வேறு எந்த நோக்கமும் இன்றி மஸ்ஜிதிற்குப் புறப்பட்டால், அவர் எடுத்து வைக்கும் ஒவ்வொரு அடிக்கும் அவரது அந்தஸ்து ஒரு படி உயர்த்தப்படுகிறது, மேலும் அவரது ஒரு பாவம் மன்னிக்கப்படுகிறது. அவர் தொழுது முடித்த பின், தான் தொழுத இடத்திலேயே இருக்கும் வரை வானவர்கள் அவருக்காகப் பிரார்த்தனை செய்து கொண்டிருப்பார்கள். அவர்கள், \"யா அல்லாஹ், இவருக்கு அருள்புரிவாயாக! யா அல்லாஹ், இவருக்குக் கருணை காட்டுவாயாக!\" என்பார்கள். மேலும் ஒருவர் தொழுகைக்காகக் காத்திருக்கும் வரை, அவர் தொழுகையிலேயே இருப்பதாகக் கருதப்படுவார்.) ஸுனன் நூல்களில் பின்வருமாறு பதிவாகியுள்ளது:\n\r\n\n\r\n«بَشِّرِ الْمَشَّائِينَ إِلَى الْمَسَاجِدِ فِي الظُّلَمِ بِالنُّورِ التَّامِّ يَوْمَ الْقِيَامَةِ»\n\r\n\n\r\n(இருளான நேரங்களில் மஸ்ஜித்களை நோக்கி நடப்பவர்களுக்கு, மறுமை நாளில் முழுமையான ஒளி கிடைக்கும் என்ற நற்செய்தியைக் கூறுங்கள்.) மஸ்ஜிதிற்குள் நுழையும் போது வலது காலை முதலில் வைத்து நுழைவது சுன்னத்தாகும். ஸஹீஹ் அல்-புகாரியில் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மஸ்ஜிதிற்குள் நுழையும் போது இத்துஆவைக் கூறுவார்கள்:\n\r\n\n\r\n«أَعُوذُ بِاللهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ»\n\r\n\n\r\n(மகத்தான அல்லாஹ்விடமும், அவனது கண்ணியமிக்க முகத்திடமும், அவனது நித்தியமான ஆதிக்கத்திடமும் சபிக்கப்பட்ட ஷைத்தானிடமிருந்து பாதுகாப்புத் தேடுகிறேன்.) அறிவிப்பாளர்களில் ஒருவர், \"இவ்வளவு தானா?\" என்று கேட்டார். அதற்கு, \"ஆம்\" என்று பதிலளிக்கப்பட்டது. ஒருவர் இதைக் கூறினால், ஷைத்தான், \"அவர் நாள் முழுவதும் என்னிடமிருந்து பாதுகாப்பைப் பெற்றுவிட்டார்\" என்று கூறுகிறான். முஸ்லிம் நூலில் அபூ ஹுமைத் அல்லது அபூ உஸைத் (ரழி) அறிவிப்பதாவது: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَقُلْ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ. وَإِذَا خَرَجَ فَلْيَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ»\n\r\n\n\r\n(உங்களில் ஒருவர் மஸ்ஜிதிற்குள் நுழையும் போது, \"யா அல்லாஹ், உனது கருணையின் வாசல்களை எனக்காகத் திறப்பாயாக\" என்று கூறட்டும். அவர் வெளியே வரும்போது, \"யா அல்லாஹ், உனது அருளை உன்னிடம் வேண்டுகிறேன்\" என்று கூறட்டும்.) அன்-நஸாஈயும் இதனைப் பதிவு செய்துள்ளனர். அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிப்பதாவது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ. وَلْيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، وَإِذَا خَرَجَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ وَلْيَقُلِ: اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ»\n\r\n\n\r\n(உங்களில் ஒருவர் மஸ்ஜிதிற்குள் நுழையும் போது நபியின் மீது ஸலவாத் கூறிவிட்டு, \"யா அல்லாஹ், உனது கருணையின் வாசல்களை எனக்காகத் திறப்பாயாக\" என்று கூறட்டும். அவர் வெளியே வரும்போது நபியின் மீது ஸலவாத் கூறிவிட்டு, \"யா அல்லாஹ், சபிக்கப்பட்ட ஷைத்தானிடமிருந்து என்னைப் பாதுகாப்பாயாக\" என்று கூறட்டும்.) இதனை இப்னு மாஜா, இப்னு குஸைமா மற்றும் இப்னு ஹிப்பான் ஆகியோரும் தங்களது ஸஹீஹ் நூல்களில் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nوَيُذْكَرَ فِيهَا اسْمُهُ\n\r\n\n\r\n(அவற்றில் அவனது பெயர் நினைவுகூரப்படுகிறது.) அதாவது, அல்லாஹ்வின் பெயர். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nيَـبَنِى ءَادَمَ خُذُواْ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ\n\r\n\n\r\n(ஆதமின் மக்களே! ஒவ்வொரு மஸ்ஜிதிலும் உங்கள் அலங்காரத்தை அணிந்து கொள்ளுங்கள்...) 7:31\n\r\n\n\r\nوَأَقِيمُواْ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ\n\r\n\n\r\n(ஒவ்வொரு மஸ்ஜிதிலும் அவனையே நோக்கி உங்கள் முகங்களை நிலைப்படுத்துங்கள்; உங்கள் மார்க்கத்தை அவனுக்கே உரித்தாக்கி, அவனிடமே பிரார்த்தியுங்கள்.) 7:29.\n\r\n\n\r\nوَأَنَّ الْمَسَـجِدَ لِلَّهِ\n\r\n\n\r\n(நிச்சயமாக மஸ்ஜித்கள் அல்லாஹ்வுக்கே உரியவை.) 72:18.\n\r\n\n\r\nوَيُذْكَرَ فِيهَا اسْمُهُ\n\r\n\n\r\n(அவற்றில் அவனது பெயர் நினைவுகூரப்படுகிறது.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகையில், \"இதன் பொருள், அவற்றில் அவனது வேதம் (குர்ஆன்) ஓதப்படுகிறது என்பதாகும்\" என்றார்கள்.\n\r\n\n\r\nيُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالاٌّصَالِ\n\r\n\n\r\n(அவற்றில் காலையிலும் மாலையிலும் அவனது தூய்மையை அவர்கள் போற்றுகிறார்கள்.)\n\r\n\n\r\nرِجَالٌ لاَّ تُلْهِيهِمْ تِجَـرَةٌ وَلاَ بَيْعٌ عَن ذِكْرِ اللَّهِ\n\r\n\n\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்) இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تُلْهِكُمْ أَمْوَلُكُمْ وَلاَ أَوْلَـدُكُمْ عَن ذِكْرِ اللَّهِ\n\r\n\n\r\n(நம்பிக்கை கொண்டோரே! உங்கள் செல்வங்களோ அல்லது உங்கள் பிள்ளைகளோ உங்களை அல்லாஹ்வின் நினைவிலிருந்து திசைதிருப்பி விட வேண்டாம்.) 63:9\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ إِذَا نُودِىَ لِلصَّلَوةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْاْ إِلَى ذِكْرِ اللَّهِ وَذَرُواْ الْبَيْعَ\n\r\n\n\r\n(நம்பிக்கை கொண்டோரே! வெள்ளிக்கிழமை தொழுகைக்காக அழைப்பு விடுக்கப்பட்டால், அல்லாஹ்வின் நினைவின் பக்கம் விரைந்து செல்லுங்கள்; வியாபாரத்தை விட்டுவிடுங்கள்.) 62:9\n\r\n\n\r\nஇந்த உலகமும் அதன் அலங்காரங்களும், கவர்ச்சிகளும், சந்தைகளும் தங்களைப் படைத்துப் பராமரிக்கும் இறைவனை நினைவுகூருவதை விட்டும் அவர்களைத் திசைதிருப்பிவிடக் கூடாது என்று அல்லாஹ் கூறுகிறான். தங்களிடம் உள்ளதை விட அல்லாஹ்விடம் இருப்பதே சிறந்தது என்று அவர்கள் அறிவார்கள்; ஏனெனில் உலகப் பொருட்கள் அழியக்கூடியவை, அல்லாஹ்விடம் இருப்பவையோ நிலையானவை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلاَّ تُلْهِيهِمْ تِجَـرَةٌ وَلاَ بَيْعٌ عَن ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَوةِ وَإِيتَآءِ الزَّكَـوةِ\n\r\n\n\r\n(அல்லாஹ்வை நினைவுகூருவதை விட்டும், தொழுகையை நிலைநாட்டுவதை விட்டும், ஜகாத் வழங்குவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்). அதாவது, அவர்கள் தங்களுக்கு விருப்பமானவற்றை விட, அல்லாஹ்வின் கட்டளைகளுக்குக் கீழ்ப்படிவதற்கும், அவன் எதை விரும்புகிறானோ அதைச் செய்வதற்கும் முன்னுரிமை அளிக்கிறார்கள். சாலிம் (ரஹ்) அவர்கள் இப்னு உமர் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: அவர்கள் சந்தையில் இருந்தபோது தொழுகைக்கான இகாமத் சொல்லப்பட்டது; உடனே அவர்கள் தங்கள் கடைகளை மூடிவிட்டு மஸ்ஜிதிற்குள் நுழைந்தார்கள். இப்னு உமர் (ரழி) அவர்கள் கூறினார்கள்: \"இவர்களைக் குறித்து தான் இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\nرِجَالٌ لاَّ تُلْهِيهِمْ تِجَـرَةٌ وَلاَ بَيْعٌ عَن ذِكْرِ اللَّهِ\n\r\n\n\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்).\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nلاَّ تُلْهِيهِمْ تِجَـرَةٌ وَلاَ بَيْعٌ عَن ذِكْرِ اللَّهِ\n\r\n\n\r\n(இறைவனை நினைவுகூருவதை விட்டும் வர்த்தகமோ அல்லது வியாபாரமோ திசைதிருப்பாத ஆண்கள்). இப்னு அப்பாஸ் (ரழி) அவர்கள், \"இதன் பொருள் கடமையாக்கப்பட்ட தொழுகைகளாகும்\" என்று கூறியதாக அலீ பின் அபீ தல்ஹா (ரழி) அறிவிக்கிறார்கள். முகாதில் பின் ஹய்யான் மற்றும் அர்-ரபீஃ பின் அனஸ் ஆகியோரும் இதே கருத்தைக் கொண்டுள்ளனர். அஸ்-ஸுத்தி அவர்கள், \"ஜமாஅத் தொழுகை\" என்று குறிப்பிடுகிறார்கள். முகாதில் பின் ஹய்யான் அவர்கள் கூறுகையில், \"அல்லாஹ் கட்டளையிட்டபடி தொழுகையில் கலந்துகொள்வதிலிருந்தும், குறிப்பிட்ட நேரங்களில் அதனை நிறைவேற்றுவதிலிருந்தும், தொழுகையில் அல்லாஹ் அவர்கள் மீது கடமையாக்கிய எதையும் செய்வதிலிருந்தும் உலகம் அவர்களைத் திசைதிருப்புவதில்லை\" என்றார்கள்.\n\r\n\n\r\nيَخَـفُونَ يَوْماً تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالاٌّبْصَـرُ\n\r\n\n\r\n(இதயங்களும் பார்வைகளும் நிலைகுலைந்து புரளும் ஒரு நாளை அவர்கள் அஞ்சுகிறார்கள்.) அதாவது, அந்த நாளின் பயங்கரமும் அதிர்ச்சியும் கடுமையாக இருப்பதால் மக்களின் இதயங்களும் கண்களும் நிலைகுலைந்து போகும் மறுமை நாளைக் குறிக்கிறது. இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nوَأَنذِرْهُمْ يَوْمَ الاٌّزِفَةِ\n\r\n\n\r\n(நெருங்கி வரும் நாளைப் பற்றி அவர்களை எச்சரிப்பீராக...) 40:18,\n\r\n\n\r\nإِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الأَبْصَـرُ\n\r\n\n\r\n(நிச்சயமாக, கண்கள் நிலைகுத்தி நிற்கும் ஒரு நாள் வரை அவர்களுக்கு அவன் அவகாசம் அளிக்கிறான்) 14:42.\n\r\n\n\r\nوَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ مِسْكِيناً وَيَتِيماً وَأَسِيراً - إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللَّهِ لاَ نُرِيدُ مِنكُمْ جَزَآءً وَلاَ شُكُوراً - إِنَّا نَخَافُ مِن رَّبِّنَا يَوْماً عَبُوساً قَمْطَرِيراً - فَوَقَـهُمُ اللَّهُ شَرَّ ذَلِكَ الْيَومِ وَلَقَّـهُمْ نَضْرَةً وَسُرُوراً - وَجَزَاهُمْ بِمَا صَبَرُواْ جَنَّةً وَحَرِيراً\n\r\n\n\r\n(உணவின் மீது விருப்பம் இருந்த போதிலும், ஏழைக்கும் அநாதைக்கும் கைதிக்கும் அவர்கள் உணவளிக்கிறார்கள். \"நாங்கள் அல்லாஹ்வின் திருப்பொருத்தத்திற்காகவே உங்களுக்கு உணவளிக்கிறோம்; உங்களிடமிருந்து எந்தப் பிரதிபலனையோ நன்றியையோ நாங்கள் எதிர்பார்க்கவில்லை. நிச்சயமாக நாம் நம் இறைவனிடமிருந்து மிகக் கடுமையான, துன்பம் நிறைந்த ஒரு நாளை அஞ்சுகிறோம்\" (என்று அவர்கள் கூறுவர்). எனவே, அல்லாஹ் அவர்களை அந்த நாளின் தீமையிலிருந்து பாதுகாத்து, அவர்களுக்குப் பொலிவையும் மகிழ்ச்சியையும் வழங்கினான். அவர்கள் பொறுமையாக இருந்த காரணத்தால் அவர்களுக்குச் சொர்க்கத்தையும் பட்டு ஆடைகளையும் வெகுமதியாக வழங்கினான்.) 76:8-12. மேலும் அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nلِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُواْ\n\r\n\n\r\n(அல்லாஹ் அவர்களின் நற்செயல்களில் சிறந்தவற்றிற்குப் பிரதிபலன் அளிப்பதற்காகவும்,) அதாவது \"அவர்களின் நற்செயல்களில் சிறந்தவற்றை நாம் ஏற்றுக்கொண்டு, அவர்களின் தீய செயல்களை நாம் மன்னிப்போம்\" என்று பொருள்படும்.\n\r\n\n\r\nوَيَزِيدَهُم مِّن فَضْلِهِ\n\r\n\n\r\n(மேலும் அவனது அருளிலிருந்து அவர்களுக்கு இன்னும் அதிகமாகச் சேர்ப்பான்.) அதாவது அல்லாஹ் அவர்களின் நற்செயல்களை ஏற்றுக்கொண்டு, அவற்றுக்கான நன்மைகளை அவர்களுக்குப் பன்மடங்காக்கித் தருவான். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\nإِنَّ اللَّهَ لاَ يَظْلِمُ مِثْقَالَ ذَرَّةٍ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் ஒரு அணுவளவும் அநீதி இழைக்கமாட்டான்.) 4:40\n\r\n\n\r\nمَن جَآءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا\n\r\n\n\r\n(யார் ஒரு நன்மையைச் செய்கிறாரோ, அவருக்கு அது போன்ற பத்து மடங்கு நன்மைகள் உண்டு.) 6:160\n\r\n\n\r\nمَّن ذَا الَّذِى يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا\n\r\n\n\r\n(அல்லாஹ்வுக்கு அழகிய முறையில் கடன் வழங்குபவர் யார்?) 2:245\n\r\n\n\r\nوَاللَّهُ يُضَـعِفُ لِمَن يَشَآءُ\n\r\n\n\r\n(அல்லாஹ் தான் நாடியவர்களுக்குப் பன்மடங்காகப் பெருகச் செய்கிறான்.) 2:261 மேலும் அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nوَاللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ\n\r\n\n\r\n(மேலும் அல்லாஹ் தான் நாடியவர்களுக்குக் கணக்கின்றி வழங்குகிறான்.)"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=40\" class=\"link\">24:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:40 ஐ பார்க்கவும்"},"40":{"html":"<strong>இரண்டு வகையான நிராகரிப்பாளர்களைப் பற்றிய இரண்டு உதாரணங்கள்</strong><br />\r\n<br />\r\nஇவை அல்லாஹ் இரண்டு வகையான நிராகரிப்பாளர்களுக்குக் கூறும் இரண்டு உதாரணங்களாகும். இதைப் போலவே, ஸூரதுல் பகராவின் ஆரம்பத்தில் நயவஞ்சகர்களுக்காக இரண்டு உவமைகளை அவன் கூறுகிறான்: ஒன்று நெருப்பைச் சார்ந்தது, மற்றொன்று நீரைச் சார்ந்தது. இதேபோல், ஸூரத்துர் ரஃத் அத்தியாயத்தில் இதயத்தில் பதியவைக்கப்படும் நேர்வழி மற்றும் ஞானத்தைப் பற்றி இரண்டு உவமைகளை அவன் கூறுகிறான்; அவையும் நெருப்பு மற்றும் நீர் சம்பந்தப்பட்டவை. நாம் அவை ஒவ்வொன்றையும் அதற்குரிய இடங்களில் விளக்கியுள்ளோம், எனவே அதை மீண்டும் இங்கே கூறத் தேவையில்லை, எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />\r\nஇந்த இரண்டு உதாரணங்களில் முதலாவது, தாங்கள் செய்வது நற்செயல்கள் என்றும் நல்ல கொள்கைகள் என்றும் எண்ணிக்கொண்டு, மற்றவர்களையும் தங்கள் நிராகரிப்பின் பக்கம் அழைக்கும் நிராகரிப்பாளர்களைப் பற்றியது. ஆனால் உண்மையில் நிலைமை அப்படி இல்லை. <span class=\"quran-arabic-font text-success\">﴾أَعْمَالُهُمْ</span> <span class=\"quran-arabic-font text-success\">كَسَرَابٍ</span> <span class=\"quran-arabic-font text-success\">بِقِيعَةٍ﴿</span> அவர்களுடைய உவமை, பாலைவனத்தில் காணப்படும் கானல் நீரைப் போன்றது; தூரத்திலிருந்து பார்ப்பவருக்கு அது ஒரு ஆழ்கடல் போலத் தோன்றும். 'கீஆ' (Qi`ah) என்பது கானல் நீர் தோன்றக்கூடிய ஒரு பரந்த, சமமான சமவெளிப் பகுதியைக் குறிக்கும். கானல் நீரில் பல வகைகள் உள்ளன. ஒன்று நண்பகலுக்குப் பிறகு தோன்றும், மற்றொன்று காலையில் தோன்றி வானத்திற்கும் பூமிக்கும் இடையில் தண்ணீர் இருப்பது போல் காட்சியளிக்கும். <span class=\"quran-arabic-font text-success\">﴾يَحْسَبُهُ</span> <span class=\"quran-arabic-font text-success\">الظَّمْآنُ</span> <span class=\"quran-arabic-font text-success\">مَآءً﴿</span> தண்ணீர் தேவைப்படுபவர் கானல் நீரைக் கண்டால், அது தண்ணீர் என்று நினைத்து அதைக் குடிப்பதற்காக அதை நோக்கிச் செல்கிறார். ஆனால் <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُ﴿</span> அவர் அதை அடைந்ததும், <span class=\"quran-arabic-font text-success\">﴾لَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدْهُ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً﴿</span> (அவர் அங்கே எதையும் காணமாட்டார்).<br />\r\n<br />\r\nஇதேபோன்றுதான் நிராகரிப்பாளர் தான் ஏதோ ஒரு நல்ல காரியத்தைச் செய்வதாகவும், எதையோ சாதித்துவிட்டதாகவும் நினைக்கிறார். ஆனால், மறுமை நாளில் அல்லாஹ் அவருக்குத் தீர்ப்பளித்து, அவரது கணக்கைச் சரிபார்த்து, அவரது செயல்களை ஆய்வு செய்யும்போது, தூய்மையான நம்பிக்கை இல்லாததாலோ அல்லது அவர் ஷரீஅத்தின் (மார்க்கச் சட்டத்தின்) சரியான முறைகளைப் பின்பற்றாததாலோ, அவரது செயல்கள் எதுவும் அங்கீகரிக்கப்படவில்லை என்பதைக் காண்பார். அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾وَقَدِمْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span> <span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">هَبَآءً</span> <span class=\"quran-arabic-font text-success\">مَّنثُوراً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (அவர்கள் செய்த செயல்களை நாம் கவனித்து, அவற்றைச் சிதறிய தூசிகளாக ஆக்கிவிடுவோம்.) <a href=\"qurandisp.php?sura=25&ayah=23\" class=\"link\">25:23</a>. மேலும் அல்லாஹ் இங்கே கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَوَجَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">عِندَهُ</span> <span class=\"quran-arabic-font text-success\">فَوَفَّاهُ</span> <span class=\"quran-arabic-font text-success\">حِسَابَهُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَرِيعُ</span> <span class=\"quran-arabic-font text-success\">الْحِسَابِ﴿</span> (ஆனால், அவர் அங்கே அல்லாஹ்வைக் காண்பார், அவன் அவருடைய கணக்கைத் தீர்ப்பான். மேலும் அல்லாஹ் கணக்குத் தீர்ப்பதில் மிக விரைவானவன்.)<br />\r\n<br />\r\nஉபை பின் கஅப் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித், கதாதா மற்றும் பலரிடமிருந்தும் இதேபோன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) நூல்களில் அறிவிக்கப்பட்டுள்ளதாவது: மறுமை நாளில் யூதர்களிடம், “நீங்கள் எதை வணங்கிக் கொண்டிருந்தீர்கள்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “நாங்கள் அல்லாஹ்வின் மகன் உஸைரை வணங்கிக் கொண்டிருந்தோம்” என்பார்கள். அப்போது அவர்களிடம், “நீங்கள் பொய் சொல்கிறீர்கள். அல்லாஹ் எவரையும் மகனாகப் பெறவில்லை. இப்போது உங்களுக்கு என்ன வேண்டும்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “இறைவா! நாங்கள் தாகமாக இருக்கிறோம், எங்களுக்குக் குடிக்க ஏதாவது கொடு” என்பார்கள். “நீங்கள் (அங்கே) செல்லமாட்டீர்களா?” என்று அவர்களிடம் கேட்கப்படும். பிறகு கிறிஸ்தவர்களிடம், “நீங்கள் எதை வணங்கிக் கொண்டிருந்தீர்கள்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “நாங்கள் அல்லாஹ்வின் மகன் மஸீஹை (ஈஸாவை) வணங்கிக் கொண்டிருந்தோம்” என்பார்கள். அப்போது அவர்களிடம், “நீங்கள் பொய் சொல்கிறீர்கள். அல்லாஹ் எவரையும் மகனாகப் பெறவில்லை. இப்போது உங்களுக்கு என்ன வேண்டும்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “இறைவா! நாங்கள் தாகமாக இருக்கிறோம், எங்களுக்குக் குடிக்க ஏதாவது கொடு” என்பார்கள். “நீங்கள் (அங்கே) செல்லமாட்டீர்களா?” என்று அவர்களிடம் கேட்கப்படும். பிறகு, நரகம் அவர்களுக்கு ஒரு கானல் நீரைப் போலக் காட்டப்படும். அதன் ஒரு பகுதி மற்றொரு பகுதியை விழுங்கிக் கொண்டிருக்கும். அவர்கள் அங்கே சென்று அதில் விழுவார்கள்.<br />\r\n<br />\r\nஇது அறியாமை மிகவும் ஆழமாகவும் முதிர்ந்த நிலையிலும் இருப்பவர்களின் உவமையாகும். யாரிடம் எளிமையான அறியாமை இருக்கிறதோ, அதாவது கல்வியறிவற்றவர்களாகவும், முட்டாள்களாகவும் இருந்து, எதையும் ஆராயாமல் நிராகரிப்பின் தலைவர்களைக் கண்மூடித்தனமாகப் பின்பற்றுகிறார்களோ, அவர்களின் உவமையை அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">كَظُلُمَاتٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">بَحْرٍ</span> <span class=\"quran-arabic-font text-success\">لُّجِّىٍّ</span> <span class=\"quran-arabic-font text-success\">يَغْشَاهُ</span> <span class=\"quran-arabic-font text-success\">مَوْجٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فَوْقِهِ</span> <span class=\"quran-arabic-font text-success\">مَوْجٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">فَوْقِهِ</span> <span class=\"quran-arabic-font text-success\">سَحَابٌ</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتٌ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهَا</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَخْرَجَ</span> <span class=\"quran-arabic-font text-success\">يَدَهُ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَكَدْ</span> <span class=\"quran-arabic-font text-success\">يَرَاهَا﴿</span> (அல்லது, ஒரு பெரும் ஆழ்கடலில் உள்ள இருள்களைப் போன்றது; அதை ஓர் அலை மூடுகிறது, அதன் மேல் மற்றொரு அலை, அதற்கு மேல் கார்மேகங்கள்; இருள்களுக்கு மேல் இருள்கள்! ஒருவன் தன் கையை நீட்டினால், அவனால் அதைக் கூடப் பார்க்க முடியாது!) அதாவது, அங்கு இருள் அவ்வளவு அடர்த்தியாக இருப்பதால் அவனால் அதைப் பார்க்க இயலாது.<br />\r\n<br />\r\nஇது எளிமையான அறியாமை கொண்ட நிராகரிப்பாளரின் இதயத்திற்குரிய உவமையாகும். அவர் கண்மூடித்தனமாகப் பின்பற்றுகிறாரே தவிர, தான் யாரைப் பின்பற்றுகிறோம் அல்லது எங்கே செல்கிறோம் என்பதை அவர் அறியமாட்டார். அவர் எப்படிப்பட்டவர் என்றால், ஒரு அறியாமை கொண்ட மனிதரிடம், “நீங்கள் எங்கே போகிறீர்கள்?” என்று கேட்கப்பட்டபோது, அதற்கு அவர், “அவர்களுடன் (போகிறேன்)” என்றார். “அவர்கள் எங்கே போகிறார்கள்?” என்று கேட்டபோது, “எனக்குத் தெரியாது” என்று பதிலளித்தாரே அவரைப் போன்றவர். <span class=\"quran-arabic-font text-success\">﴾ظُلُمَاتٌ</span> <span class=\"quran-arabic-font text-success\">بَعْضُهَا</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ﴿</span> (இருள்களுக்கு மேல் இருள்கள்). உபை பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: “அவர் ஐந்து வகையான இருள்களால் சூழப்பட்டுள்ளார்: அவருடைய பேச்சு இருள், அவரது செயல் இருள், அவர் உள்ளே வருவது இருள், அவர் வெளியே செல்வது இருள், மறுமை நாளில் அவரது முடிவு நரக நெருப்பின் இருளாக இருக்கும்.” அஸ்-ஸுத்தி மற்றும் அர்-ரபீஃ பின் அனஸ் ஆகியோரும் இதையே கூறியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَجْعَلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">نُوراً</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">نُورٍ﴿</span> (யாருக்கு அல்லாஹ் ஒளியை ஏற்படுத்தவில்லையோ, அவருக்கு எந்த ஒளியும் இருக்காது). அல்லாஹ் யாருக்கு நேர்வழி காட்டவில்லையோ அவர் அறியாமையில் மூழ்கியவர், அழிவுக்குரியவர், முற்றிலும் நஷ்டமடைந்த நிராகரிப்பாளர் ஆவார். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾مَن</span> <span class=\"quran-arabic-font text-success\">يُضْلِلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">هَادِيَ</span> <span class=\"quran-arabic-font text-success\">لَهُ﴿</span> (அல்லாஹ் யாரை வழிகேட்டில் விடுகிறானோ, அவருக்கு நேர்வழி காட்டுபவர் எவருமில்லை) <a href=\"qurandisp.php?sura=7&ayah=186\" class=\"link\">7:186</a>. இது நம்பிக்கையாளர்களைப் பற்றி அல்லாஹ் கூறுவதற்கு நேர்மாறானது: <span class=\"quran-arabic-font text-success\">﴾يَهْدِى</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لِنُورِهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span> (அல்லாஹ் தான் நாடியவரைத் தன் ஒளியின் பக்கம் வழிநடத்துகிறான்.) <a href=\"qurandisp.php?sura=24&ayah=35\" class=\"link\">24:35</a>.<br />\r\n<br />\r\nஎங்கள் இதயங்களில் ஒளியை ஏற்படுத்துமாறும், எங்களது வலதுபுறத்திலும் இடதுபுறத்திலும் ஒளியைத் தந்து, எங்களது ஒளியை மென்மேலும் அதிகப்படுத்துமாறும் எல்லாம் வல்ல அல்லாஹ்விடம் நாம் பிரார்த்திக்கிறோம்.<br />\r\n<br />","text":"இரண்டு வகையான நிராகரிப்பாளர்களைப் பற்றிய இரண்டு உதாரணங்கள்\n\r\n\n\r\nஇவை அல்லாஹ் இரண்டு வகையான நிராகரிப்பாளர்களுக்குக் கூறும் இரண்டு உதாரணங்களாகும். இதைப் போலவே, ஸூரதுல் பகராவின் ஆரம்பத்தில் நயவஞ்சகர்களுக்காக இரண்டு உவமைகளை அவன் கூறுகிறான்: ஒன்று நெருப்பைச் சார்ந்தது, மற்றொன்று நீரைச் சார்ந்தது. இதேபோல், ஸூரத்துர் ரஃத் அத்தியாயத்தில் இதயத்தில் பதியவைக்கப்படும் நேர்வழி மற்றும் ஞானத்தைப் பற்றி இரண்டு உவமைகளை அவன் கூறுகிறான்; அவையும் நெருப்பு மற்றும் நீர் சம்பந்தப்பட்டவை. நாம் அவை ஒவ்வொன்றையும் அதற்குரிய இடங்களில் விளக்கியுள்ளோம், எனவே அதை மீண்டும் இங்கே கூறத் தேவையில்லை, எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியது.\n\r\n\n\r\nஇந்த இரண்டு உதாரணங்களில் முதலாவது, தாங்கள் செய்வது நற்செயல்கள் என்றும் நல்ல கொள்கைகள் என்றும் எண்ணிக்கொண்டு, மற்றவர்களையும் தங்கள் நிராகரிப்பின் பக்கம் அழைக்கும் நிராகரிப்பாளர்களைப் பற்றியது. ஆனால் உண்மையில் நிலைமை அப்படி இல்லை. ﴾أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ﴿ அவர்களுடைய உவமை, பாலைவனத்தில் காணப்படும் கானல் நீரைப் போன்றது; தூரத்திலிருந்து பார்ப்பவருக்கு அது ஒரு ஆழ்கடல் போலத் தோன்றும். 'கீஆ' (Qi`ah) என்பது கானல் நீர் தோன்றக்கூடிய ஒரு பரந்த, சமமான சமவெளிப் பகுதியைக் குறிக்கும். கானல் நீரில் பல வகைகள் உள்ளன. ஒன்று நண்பகலுக்குப் பிறகு தோன்றும், மற்றொன்று காலையில் தோன்றி வானத்திற்கும் பூமிக்கும் இடையில் தண்ணீர் இருப்பது போல் காட்சியளிக்கும். ﴾يَحْسَبُهُ الظَّمْآنُ مَآءً﴿ தண்ணீர் தேவைப்படுபவர் கானல் நீரைக் கண்டால், அது தண்ணீர் என்று நினைத்து அதைக் குடிப்பதற்காக அதை நோக்கிச் செல்கிறார். ஆனால் ﴾حَتَّى إِذَا جَآءَهُ﴿ அவர் அதை அடைந்ததும், ﴾لَمْ يَجِدْهُ شَيْئاً﴿ (அவர் அங்கே எதையும் காணமாட்டார்).\n\r\n\n\r\nஇதேபோன்றுதான் நிராகரிப்பாளர் தான் ஏதோ ஒரு நல்ல காரியத்தைச் செய்வதாகவும், எதையோ சாதித்துவிட்டதாகவும் நினைக்கிறார். ஆனால், மறுமை நாளில் அல்லாஹ் அவருக்குத் தீர்ப்பளித்து, அவரது கணக்கைச் சரிபார்த்து, அவரது செயல்களை ஆய்வு செய்யும்போது, தூய்மையான நம்பிக்கை இல்லாததாலோ அல்லது அவர் ஷரீஅத்தின் (மார்க்கச் சட்டத்தின்) சரியான முறைகளைப் பின்பற்றாததாலோ, அவரது செயல்கள் எதுவும் அங்கீகரிக்கப்படவில்லை என்பதைக் காண்பார். அல்லாஹ் கூறுவது போல்: ﴾وَقَدِمْنَآ إِلَى مَا عَمِلُواْ مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَآءً مَّنثُوراً ﴿ (அவர்கள் செய்த செயல்களை நாம் கவனித்து, அவற்றைச் சிதறிய தூசிகளாக ஆக்கிவிடுவோம்.) 25:23. மேலும் அல்லாஹ் இங்கே கூறுகிறான்: ﴾وَوَجَدَ اللَّهَ عِندَهُ فَوَفَّاهُ حِسَابَهُ وَاللَّهُ سَرِيعُ الْحِسَابِ﴿ (ஆனால், அவர் அங்கே அல்லாஹ்வைக் காண்பார், அவன் அவருடைய கணக்கைத் தீர்ப்பான். மேலும் அல்லாஹ் கணக்குத் தீர்ப்பதில் மிக விரைவானவன்.)\n\r\n\n\r\nஉபை பின் கஅப் (ரழி), இப்னு அப்பாஸ் (ரழி), முஜாஹித், கதாதா மற்றும் பலரிடமிருந்தும் இதேபோன்ற கருத்து அறிவிக்கப்பட்டுள்ளது. ஸஹீஹைன் (புகாரி மற்றும் முஸ்லிம்) நூல்களில் அறிவிக்கப்பட்டுள்ளதாவது: மறுமை நாளில் யூதர்களிடம், “நீங்கள் எதை வணங்கிக் கொண்டிருந்தீர்கள்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “நாங்கள் அல்லாஹ்வின் மகன் உஸைரை வணங்கிக் கொண்டிருந்தோம்” என்பார்கள். அப்போது அவர்களிடம், “நீங்கள் பொய் சொல்கிறீர்கள். அல்லாஹ் எவரையும் மகனாகப் பெறவில்லை. இப்போது உங்களுக்கு என்ன வேண்டும்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “இறைவா! நாங்கள் தாகமாக இருக்கிறோம், எங்களுக்குக் குடிக்க ஏதாவது கொடு” என்பார்கள். “நீங்கள் (அங்கே) செல்லமாட்டீர்களா?” என்று அவர்களிடம் கேட்கப்படும். பிறகு கிறிஸ்தவர்களிடம், “நீங்கள் எதை வணங்கிக் கொண்டிருந்தீர்கள்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “நாங்கள் அல்லாஹ்வின் மகன் மஸீஹை (ஈஸாவை) வணங்கிக் கொண்டிருந்தோம்” என்பார்கள். அப்போது அவர்களிடம், “நீங்கள் பொய் சொல்கிறீர்கள். அல்லாஹ் எவரையும் மகனாகப் பெறவில்லை. இப்போது உங்களுக்கு என்ன வேண்டும்?” என்று கேட்கப்படும். அதற்கு அவர்கள், “இறைவா! நாங்கள் தாகமாக இருக்கிறோம், எங்களுக்குக் குடிக்க ஏதாவது கொடு” என்பார்கள். “நீங்கள் (அங்கே) செல்லமாட்டீர்களா?” என்று அவர்களிடம் கேட்கப்படும். பிறகு, நரகம் அவர்களுக்கு ஒரு கானல் நீரைப் போலக் காட்டப்படும். அதன் ஒரு பகுதி மற்றொரு பகுதியை விழுங்கிக் கொண்டிருக்கும். அவர்கள் அங்கே சென்று அதில் விழுவார்கள்.\n\r\n\n\r\nஇது அறியாமை மிகவும் ஆழமாகவும் முதிர்ந்த நிலையிலும் இருப்பவர்களின் உவமையாகும். யாரிடம் எளிமையான அறியாமை இருக்கிறதோ, அதாவது கல்வியறிவற்றவர்களாகவும், முட்டாள்களாகவும் இருந்து, எதையும் ஆராயாமல் நிராகரிப்பின் தலைவர்களைக் கண்மூடித்தனமாகப் பின்பற்றுகிறார்களோ, அவர்களின் உவமையை அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾أَوْ كَظُلُمَاتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَاهُ مَوْجٌ مِّن فَوْقِهِ مَوْجٌ مِّن فَوْقِهِ سَحَابٌ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا﴿ (அல்லது, ஒரு பெரும் ஆழ்கடலில் உள்ள இருள்களைப் போன்றது; அதை ஓர் அலை மூடுகிறது, அதன் மேல் மற்றொரு அலை, அதற்கு மேல் கார்மேகங்கள்; இருள்களுக்கு மேல் இருள்கள்! ஒருவன் தன் கையை நீட்டினால், அவனால் அதைக் கூடப் பார்க்க முடியாது!) அதாவது, அங்கு இருள் அவ்வளவு அடர்த்தியாக இருப்பதால் அவனால் அதைப் பார்க்க இயலாது.\n\r\n\n\r\nஇது எளிமையான அறியாமை கொண்ட நிராகரிப்பாளரின் இதயத்திற்குரிய உவமையாகும். அவர் கண்மூடித்தனமாகப் பின்பற்றுகிறாரே தவிர, தான் யாரைப் பின்பற்றுகிறோம் அல்லது எங்கே செல்கிறோம் என்பதை அவர் அறியமாட்டார். அவர் எப்படிப்பட்டவர் என்றால், ஒரு அறியாமை கொண்ட மனிதரிடம், “நீங்கள் எங்கே போகிறீர்கள்?” என்று கேட்கப்பட்டபோது, அதற்கு அவர், “அவர்களுடன் (போகிறேன்)” என்றார். “அவர்கள் எங்கே போகிறார்கள்?” என்று கேட்டபோது, “எனக்குத் தெரியாது” என்று பதிலளித்தாரே அவரைப் போன்றவர். ﴾ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ﴿ (இருள்களுக்கு மேல் இருள்கள்). உபை பின் கஅப் (ரழி) அவர்கள் கூறினார்கள்: “அவர் ஐந்து வகையான இருள்களால் சூழப்பட்டுள்ளார்: அவருடைய பேச்சு இருள், அவரது செயல் இருள், அவர் உள்ளே வருவது இருள், அவர் வெளியே செல்வது இருள், மறுமை நாளில் அவரது முடிவு நரக நெருப்பின் இருளாக இருக்கும்.” அஸ்-ஸுத்தி மற்றும் அர்-ரபீஃ பின் அனஸ் ஆகியோரும் இதையே கூறியுள்ளனர்.\n\r\n\n\r\n﴾وَمَن لَّمْ يَجْعَلِ اللَّهُ لَهُ نُوراً فَمَا لَهُ مِن نُورٍ﴿ (யாருக்கு அல்லாஹ் ஒளியை ஏற்படுத்தவில்லையோ, அவருக்கு எந்த ஒளியும் இருக்காது). அல்லாஹ் யாருக்கு நேர்வழி காட்டவில்லையோ அவர் அறியாமையில் மூழ்கியவர், அழிவுக்குரியவர், முற்றிலும் நஷ்டமடைந்த நிராகரிப்பாளர் ஆவார். இது பின்வரும் வசனத்தைப் போன்றது: ﴾مَن يُضْلِلِ اللَّهُ فَلاَ هَادِيَ لَهُ﴿ (அல்லாஹ் யாரை வழிகேட்டில் விடுகிறானோ, அவருக்கு நேர்வழி காட்டுபவர் எவருமில்லை) 7:186. இது நம்பிக்கையாளர்களைப் பற்றி அல்லாஹ் கூறுவதற்கு நேர்மாறானது: ﴾يَهْدِى اللَّهُ لِنُورِهِ مَن يَشَآءُ﴿ (அல்லாஹ் தான் நாடியவரைத் தன் ஒளியின் பக்கம் வழிநடத்துகிறான்.) 24:35.\n\r\n\n\r\nஎங்கள் இதயங்களில் ஒளியை ஏற்படுத்துமாறும், எங்களது வலதுபுறத்திலும் இடதுபுறத்திலும் ஒளியைத் தந்து, எங்களது ஒளியை மென்மேலும் அதிகப்படுத்துமாறும் எல்லாம் வல்ல அல்லாஹ்விடம் நாம் பிரார்த்திக்கிறோம்."},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=42\" class=\"link\">24:42</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:42 ஐ பார்க்கவும்"},"42":{"html":"<strong>அனைத்தும் கண்ணியமிக்க அல்லாஹ்வைத் துதிக்கின்றன, அவனுக்கே அதிகாரம் (ஆட்சி) உரியது</strong><br />\r\n<br />\r\nவானங்களிலும் பூமியிலும் உள்ளவை, அதாவது வானவர்கள், மனிதர்கள், ஜின்கள், விலங்குகள் மற்றும் உயிரற்ற பொருட்கள் உட்பட அனைத்தும் அல்லாஹ்வைத் துதிக்கின்றன என்று அவன் நமக்குக் கூறுகிறான். இது இந்த இறைவசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾تُسَبِّحُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">السَّبْعُ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ﴿</span> (ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன) <a href=\"qurandisp.php?sura=17&ayah=44\" class=\"link\">17:44</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالطَّيْرُ</span> <span class=\"quran-arabic-font text-success\">صَافَّاتٍ﴿</span> (இறக்கைகளை விரித்துப் பறக்கும் பறவைகளும்) என்பது, அவை பறக்கும்போது தங்களுக்கு வஹீ (இறைச்செய்தி) மூலம் அறிவிக்கப்பட்ட மற்றும் வழிகாட்டப்பட்ட முறைப்படி தங்கள் இறைவனைத் துதித்து வணங்குகின்றன என்பதைக் குறிக்கிறது. அவை என்ன செய்கின்றன என்பதை அல்லாஹ் நன்கறிவான். அதனால்தான் அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾كُلٌّ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">عَلِمَ</span> <span class=\"quran-arabic-font text-success\">صَلاَتَهُ</span> <span class=\"quran-arabic-font text-success\">وَتَسْبِيحَهُ﴿</span> (ஒவ்வொன்றும் தனது தொழுகையையும் தனது துதியையும் நிச்சயமாக அறிந்துள்ளன;)<br />\r\n<br />\r\nஅதாவது, கண்ணியமிக்க அல்லாஹ்வை வணங்குவதற்கு ஒவ்வொரு படைப்பிற்கும் அவன் ஒரு வழியைக் காட்டியுள்ளான். பிறகு, இவை அனைத்தையும் தான் அறிவதாகவும், அவனிடமிருந்து எதுவும் மறைக்கப்படவில்லை என்றும் அல்லாஹ் கூறுகிறான். அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ﴿</span> (மேலும், அவர்கள் செய்வதை அல்லாஹ் நன்கறிந்தவன்.)<br />\r\n<br />\r\nபின்னர், அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ﴿</span> (வானங்கள் மற்றும் பூமியின் ஆட்சி அல்லாஹ்வுக்கே உரியது.) அவனே ஆட்சியாளனும் அனைத்தையும் கட்டுப்படுத்துபவனும் ஆவான். அவனே வணக்கத்திற்குரிய இறைவன்; அவனைத் தவிர வேறு எவரும் வணக்கத்திற்குரியவர் இல்லை. அவனது தீர்ப்பைத் தடுத்து நிறுத்துபவர் எவருமில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ﴿</span> (மேலும் அல்லாஹ்விடமே மீளுதல் உள்ளது) என்பது, மறுமை நாளில் அவன் நாடியபடி தீர்ப்பளிப்பதைக் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾لِيَجْزِىَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَسَاءُواْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ﴿</span> (தீமை செய்தவர்களுக்கு அவர்கள் செய்தவற்றிற்காக அவன் கூலி கொடுப்பான்...) <a href=\"qurandisp.php?sura=53&ayah=31\" class=\"link\">53:31</a> அவனே படைப்பாளனும் பேரரசனும் ஆவான். நிச்சயமாக இவ்வுலகிலும் மறுமையிலும் அதிகாரம் அவனுக்கே உரியது. ஆரம்பத்திலும் முடிவிலும் எல்லாப் புகழும் அவனுக்கே உரித்தாகட்டும்.<br />\r\n<br />","text":"அனைத்தும் கண்ணியமிக்க அல்லாஹ்வைத் துதிக்கின்றன, அவனுக்கே அதிகாரம் (ஆட்சி) உரியது\n\r\n\n\r\nவானங்களிலும் பூமியிலும் உள்ளவை, அதாவது வானவர்கள், மனிதர்கள், ஜின்கள், விலங்குகள் மற்றும் உயிரற்ற பொருட்கள் உட்பட அனைத்தும் அல்லாஹ்வைத் துதிக்கின்றன என்று அவன் நமக்குக் கூறுகிறான். இது இந்த இறைவசனத்தைப் போன்றது: ﴾تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَن فِيهِنَّ﴿ (ஏழு வானங்களும், பூமியும், அவற்றில் உள்ளவைகளும் அவனைத் துதிக்கின்றன) 17:44.\n\r\n\n\r\n﴾وَالطَّيْرُ صَافَّاتٍ﴿ (இறக்கைகளை விரித்துப் பறக்கும் பறவைகளும்) என்பது, அவை பறக்கும்போது தங்களுக்கு வஹீ (இறைச்செய்தி) மூலம் அறிவிக்கப்பட்ட மற்றும் வழிகாட்டப்பட்ட முறைப்படி தங்கள் இறைவனைத் துதித்து வணங்குகின்றன என்பதைக் குறிக்கிறது. அவை என்ன செய்கின்றன என்பதை அல்லாஹ் நன்கறிவான். அதனால்தான் அவன் கூறுகிறான்: ﴾كُلٌّ قَدْ عَلِمَ صَلاَتَهُ وَتَسْبِيحَهُ﴿ (ஒவ்வொன்றும் தனது தொழுகையையும் தனது துதியையும் நிச்சயமாக அறிந்துள்ளன;)\n\r\n\n\r\nஅதாவது, கண்ணியமிக்க அல்லாஹ்வை வணங்குவதற்கு ஒவ்வொரு படைப்பிற்கும் அவன் ஒரு வழியைக் காட்டியுள்ளான். பிறகு, இவை அனைத்தையும் தான் அறிவதாகவும், அவனிடமிருந்து எதுவும் மறைக்கப்படவில்லை என்றும் அல்லாஹ் கூறுகிறான். அவன் கூறுகிறான்: ﴾وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ﴿ (மேலும், அவர்கள் செய்வதை அல்லாஹ் நன்கறிந்தவன்.)\n\r\n\n\r\nபின்னர், அல்லாஹ் கூறுகிறான்: ﴾وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴿ (வானங்கள் மற்றும் பூமியின் ஆட்சி அல்லாஹ்வுக்கே உரியது.) அவனே ஆட்சியாளனும் அனைத்தையும் கட்டுப்படுத்துபவனும் ஆவான். அவனே வணக்கத்திற்குரிய இறைவன்; அவனைத் தவிர வேறு எவரும் வணக்கத்திற்குரியவர் இல்லை. அவனது தீர்ப்பைத் தடுத்து நிறுத்துபவர் எவருமில்லை.\n\r\n\n\r\n﴾وَإِلَى اللَّهِ الْمَصِيرُ﴿ (மேலும் அல்லாஹ்விடமே மீளுதல் உள்ளது) என்பது, மறுமை நாளில் அவன் நாடியபடி தீர்ப்பளிப்பதைக் குறிக்கிறது. ﴾لِيَجْزِىَ الَّذِينَ أَسَاءُواْ بِمَا عَمِلُواْ﴿ (தீமை செய்தவர்களுக்கு அவர்கள் செய்தவற்றிற்காக அவன் கூலி கொடுப்பான்...) 53:31 அவனே படைப்பாளனும் பேரரசனும் ஆவான். நிச்சயமாக இவ்வுலகிலும் மறுமையிலும் அதிகாரம் அவனுக்கே உரியது. ஆரம்பத்திலும் முடிவிலும் எல்லாப் புகழும் அவனுக்கே உரித்தாகட்டும்."},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=44\" class=\"link\">24:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:44 ஐ பார்க்கவும்"},"44":{"html":"<strong>மேகங்களையும் அவற்றிலிருந்து உருவாவவற்றையும் படைப்பதில் அல்லாஹ்விற்குள்ள ஆற்றல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُزْجِى</span> <span class=\"quran-arabic-font text-success\">سَحَاباً﴿</span><br />\r\n<br />\r\nமேகங்கள் உருவாகி இன்னும் பலவீனமாக இருக்கும் ஆரம்ப நிலையிலிருந்தே அவற்றை அல்லாஹ் ஓட்டிச் செல்வதாக அவன் நமக்குக் கூறுகிறான். இதுவே \"மென்மையான ஓட்டுதல்\" என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُؤَلِّفُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُ﴿</span><br />\r\n<br />\r\n(பிறகு அவற்றை ஒன்றிணைக்கிறான்,) அதாவது, அவை சிதறிக் கிடந்த பிறகு அவற்றை அவன் ஒன்று சேர்க்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَجْعَلُهُ</span> <span class=\"quran-arabic-font text-success\">رُكَاماً﴿</span><br />\r\n<br />\r\n(பிறகு அவற்றை அடுக்கடுக்கான குவியலாக ஆக்குகிறான்,) அதாவது, அவற்றை ஒன்றன் மேல் ஒன்றாக அவன் அடுக்குகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْوَدْقَ﴿</span><br />\r\n<br />\r\n(மேலும் 'வத்க்'கை நீங்கள் காண்கிறீர்கள்,) அதாவது மழையை,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خِلاَلِهِ﴿</span><br />\r\n<br />\r\n(அவற்றின் இடைவெளிகளிலிருந்து அது வெளிவருகிறது;) அதாவது, மேகங்களுக்கு இடையிலுள்ள பிளவுகளிலிருந்து மழை வெளிப்படுவதைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி) மற்றும் அத்-தஹ்ஹாக் அவர்களும் இதனை இவ்வாறுதான் புரிந்து கொண்டார்கள். உபைது பின் உமைர் அல்-லைதீ அவர்கள் கூறுகையில்: \"அல்லாஹ் சிதறடிக்கும் காற்றை அனுப்புகிறான், அது பூமியின் மேற்பரப்பில் உள்ளவற்றைத் தட்டி எழுப்புகிறது. பிறகு அவன் மேகங்களை உருவாக்கும் காற்றை அனுப்புகிறான். பிறகு அவன் மேகங்களை ஒன்றிணைக்கும் காற்றை அனுப்புகிறான், அது அவற்றை ஒன்று சேர்க்கிறது. அதன் பிறகு அவன் மேகங்களைக் கருவுறச் செய்யும் (Fertilizer) காற்றை அனுப்புகிறான்.\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">جِبَالٍ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَرَدٍ﴿</span><br />\r\n<br />\r\n(மேலும் அவன் வானத்திலிருந்து, அதிலுள்ள மலைகளிலிருந்து ஆலங்கட்டியை இறக்குகிறான்,) சில இலக்கண அறிஞர்கள் கூறுகையில், முதல் 'மின்' (Min) என்பது அது புறப்படும் இடத்தையும், இரண்டாவது வானத்தின் எந்தப் பகுதியிலிருந்து வருகிறது என்பதையும், மூன்றாவது அதன் வகையைக் குறிப்பதாகவும் அமையும் என்கின்றனர். தஃப்ஸீர் அறிஞர்களின் கருத்தின் அடிப்படையில்: <span class=\"quran-arabic-font text-success\">﴾مِن</span> <span class=\"quran-arabic-font text-success\">جِبَالٍ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَرَدٍ﴿</span> (அதிலுள்ள மலைகளிலிருந்து ஆலங்கட்டியை) என்பது, வானத்தில் ஆலங்கட்டி மலைகள் உள்ளன, அவற்றிலிருந்தே அல்லாஹ் பனிக்கட்டியை இறக்குகிறான் என்பதைக் குறிக்கும். \"மலைகள்\" என்பது மேகங்களுக்கான ஒரு உருவகம் என்று கருதுபவர்களைப் பொறுத்தவரை, இரண்டாவது 'மின்' என்பதும் பனிக்கட்டி வரும் இடத்தையே குறிப்பதாகக் கருதுகின்றனர், எனவே அது முதல் 'மின்' என்பதற்கு மாற்றாகப் பயன்படுத்தப்பட்டுள்ளது. அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَيُصِيبُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">وَيَصْرِفُهُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span><br />\r\n<br />\r\n(அதைக் கொண்டு அவன் நாடியவர்களைத் தாக்குகிறான்; இன்னும் அவன் நாடியவர்களை விட்டும் அதனைத் திருப்புகிறான்.) <span class=\"quran-arabic-font text-success\">﴾فَيُصِيبُ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span> (அதைக் கொண்டு தாக்குகிறான்) எனும் சொற்றொடர், வானத்திலிருந்து அவன் இறக்கும் பல்வேறு வகையான மழை மற்றும் ஆலங்கட்டிகளைக் குறிக்கலாம். எனவே, <span class=\"quran-arabic-font text-success\">﴾فَيُصِيبُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span> (அதைக் கொண்டு அவன் நாடியவர்களைத் தாக்குகிறான்) என்பது அவர்கள் மீது காட்டப்படும் அவனது கருணையைக் குறிக்கலாம். மேலும் <span class=\"quran-arabic-font text-success\">﴾وَيَصْرِفُهُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span> (அவன் நாடியவர்களை விட்டும் அதைத் திருப்புகிறான்) என்பது அவர்களிடமிருந்து மழையைத் தடுத்துக் கொள்வதைக் குறிக்கலாம். அல்லது, <span class=\"quran-arabic-font text-success\">﴾فَيُصِيبُ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span> (அதைக் கொண்டு தாக்குகிறான்) என்பது ஆலங்கட்டியைக் கொண்டு அவன் நாடியவர்களுக்குத் தண்டனை அளிப்பதைக் குறிக்கலாம்; இது அவர்களின் கனிகளைத் தாக்கி, பயிர்களையும் மரங்களையும் அழித்துவிடும். மேலும், அவன் நாடியவர்களிடமிருந்து அதைத் திருப்புவது அவர்கள் மீதான அவனது கருணையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَكَادُ</span> <span class=\"quran-arabic-font text-success\">سَنَا</span> <span class=\"quran-arabic-font text-success\">بَرْقِهِ</span> <span class=\"quran-arabic-font text-success\">يَذْهَبُ</span> <span class=\"quran-arabic-font text-success\">بِالْأَبْصَارِ﴿</span><br />\r\n<br />\r\n(அதன் மின்னலின் பிரகாசமான ஒளி பார்வையைப் பறித்துவிடும் நிலையை நெருங்குகிறது.) அதன் மின்னலின் பிரகாசத்தை கண்கள் பின்தொடர்ந்து பார்க்க முயன்றால், அது பார்வையையே பறித்துவிடும் நிலையை எட்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يُقَلِّبُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّيْلَ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارَ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக வரச் செய்கிறான்.) அவன் அவற்றை நிர்வகிக்கிறான்; ஒன்றின் நீளத்திலிருந்து ஒரு பகுதியை எடுத்து மற்றொன்றோடு சேர்க்கிறான். இவ்வாறு குறுகியதாக இருந்த ஒன்று நீளமாகவும், நீளமாக இருந்தது குறுகியதாகவும் மாறி இரண்டும் சமமாகும் வரை அவன் செய்கிறான். அல்லாஹ் தனது கட்டளை, பேராற்றல், வல்லமை மற்றும் ஞானத்தினால் இவற்றைக் கட்டுப்படுத்துகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَعِبْرَةً</span> <span class=\"quran-arabic-font text-success\">لِّأُوْلِي</span> <span class=\"quran-arabic-font text-success\">الْأَبْصَارِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, இதில் அகப்பார்வை உடையவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.) அதாவது, இது அவனது மகத்துவத்திற்கான ஓர் அடையாளமாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">خَلْقِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَاخْتِلَافِ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">لَآيَاتٍ</span> <span class=\"quran-arabic-font text-success\">لِّأُوْلِي</span> <span class=\"quran-arabic-font text-success\">الْأَلْبَابِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, வானங்கள் மற்றும் பூமியின் படைப்பிலும், இரவு மற்றும் பகல் மாறி மாறி வருவதிலும் அறிவுடையவர்களுக்குப் பல அத்தாட்சிகள் உள்ளன.) (<a href=\"qurandisp.php?sura=3&ayah=190\" class=\"link\">3:190</a> மற்றும் அதற்குப் பிந்தைய வசனங்கள்).<br />\r\n<br />","text":"மேகங்களையும் அவற்றிலிருந்து உருவாவவற்றையும் படைப்பதில் அல்லாஹ்விற்குள்ள ஆற்றல்\n\r\n\n\r\n﴾أَلَمْ تَرَ أَنَّ اللَّهَ يُزْجِى سَحَاباً﴿\n\r\n\n\r\nமேகங்கள் உருவாகி இன்னும் பலவீனமாக இருக்கும் ஆரம்ப நிலையிலிருந்தே அவற்றை அல்லாஹ் ஓட்டிச் செல்வதாக அவன் நமக்குக் கூறுகிறான். இதுவே \"மென்மையான ஓட்டுதல்\" என்பதாகும்.\n\r\n\n\r\n﴾ثُمَّ يُؤَلِّفُ بَيْنَهُ﴿\n\r\n\n\r\n(பிறகு அவற்றை ஒன்றிணைக்கிறான்,) அதாவது, அவை சிதறிக் கிடந்த பிறகு அவற்றை அவன் ஒன்று சேர்க்கிறான்.\n\r\n\n\r\n﴾ثُمَّ يَجْعَلُهُ رُكَاماً﴿\n\r\n\n\r\n(பிறகு அவற்றை அடுக்கடுக்கான குவியலாக ஆக்குகிறான்,) அதாவது, அவற்றை ஒன்றன் மேல் ஒன்றாக அவன் அடுக்குகிறான்.\n\r\n\n\r\n﴾فَتَرَى الْوَدْقَ﴿\n\r\n\n\r\n(மேலும் 'வத்க்'கை நீங்கள் காண்கிறீர்கள்,) அதாவது மழையை,\n\r\n\n\r\n﴾يَخْرُجُ مِنْ خِلاَلِهِ﴿\n\r\n\n\r\n(அவற்றின் இடைவெளிகளிலிருந்து அது வெளிவருகிறது;) அதாவது, மேகங்களுக்கு இடையிலுள்ள பிளவுகளிலிருந்து மழை வெளிப்படுவதைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி) மற்றும் அத்-தஹ்ஹாக் அவர்களும் இதனை இவ்வாறுதான் புரிந்து கொண்டார்கள். உபைது பின் உமைர் அல்-லைதீ அவர்கள் கூறுகையில்: \"அல்லாஹ் சிதறடிக்கும் காற்றை அனுப்புகிறான், அது பூமியின் மேற்பரப்பில் உள்ளவற்றைத் தட்டி எழுப்புகிறது. பிறகு அவன் மேகங்களை உருவாக்கும் காற்றை அனுப்புகிறான். பிறகு அவன் மேகங்களை ஒன்றிணைக்கும் காற்றை அனுப்புகிறான், அது அவற்றை ஒன்று சேர்க்கிறது. அதன் பிறகு அவன் மேகங்களைக் கருவுறச் செய்யும் (Fertilizer) காற்றை அனுப்புகிறான்.\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.\n\r\n\n\r\n﴾وَيُنَزِّلُ مِنَ السَّمَآءِ مِن جِبَالٍ فِيهَا مِن بَرَدٍ﴿\n\r\n\n\r\n(மேலும் அவன் வானத்திலிருந்து, அதிலுள்ள மலைகளிலிருந்து ஆலங்கட்டியை இறக்குகிறான்,) சில இலக்கண அறிஞர்கள் கூறுகையில், முதல் 'மின்' (Min) என்பது அது புறப்படும் இடத்தையும், இரண்டாவது வானத்தின் எந்தப் பகுதியிலிருந்து வருகிறது என்பதையும், மூன்றாவது அதன் வகையைக் குறிப்பதாகவும் அமையும் என்கின்றனர். தஃப்ஸீர் அறிஞர்களின் கருத்தின் அடிப்படையில்: ﴾مِن جِبَالٍ فِيهَا مِن بَرَدٍ﴿ (அதிலுள்ள மலைகளிலிருந்து ஆலங்கட்டியை) என்பது, வானத்தில் ஆலங்கட்டி மலைகள் உள்ளன, அவற்றிலிருந்தே அல்லாஹ் பனிக்கட்டியை இறக்குகிறான் என்பதைக் குறிக்கும். \"மலைகள்\" என்பது மேகங்களுக்கான ஒரு உருவகம் என்று கருதுபவர்களைப் பொறுத்தவரை, இரண்டாவது 'மின்' என்பதும் பனிக்கட்டி வரும் இடத்தையே குறிப்பதாகக் கருதுகின்றனர், எனவே அது முதல் 'மின்' என்பதற்கு மாற்றாகப் பயன்படுத்தப்பட்டுள்ளது. அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\n﴾فَيُصِيبُ بِهِ مَن يَشَآءُ وَيَصْرِفُهُ عَن مَّن يَشَآءُ﴿\n\r\n\n\r\n(அதைக் கொண்டு அவன் நாடியவர்களைத் தாக்குகிறான்; இன்னும் அவன் நாடியவர்களை விட்டும் அதனைத் திருப்புகிறான்.) ﴾فَيُصِيبُ بِهِ﴿ (அதைக் கொண்டு தாக்குகிறான்) எனும் சொற்றொடர், வானத்திலிருந்து அவன் இறக்கும் பல்வேறு வகையான மழை மற்றும் ஆலங்கட்டிகளைக் குறிக்கலாம். எனவே, ﴾فَيُصِيبُ بِهِ مَن يَشَآءُ﴿ (அதைக் கொண்டு அவன் நாடியவர்களைத் தாக்குகிறான்) என்பது அவர்கள் மீது காட்டப்படும் அவனது கருணையைக் குறிக்கலாம். மேலும் ﴾وَيَصْرِفُهُ عَن مَّن يَشَآءُ﴿ (அவன் நாடியவர்களை விட்டும் அதைத் திருப்புகிறான்) என்பது அவர்களிடமிருந்து மழையைத் தடுத்துக் கொள்வதைக் குறிக்கலாம். அல்லது, ﴾فَيُصِيبُ بِهِ﴿ (அதைக் கொண்டு தாக்குகிறான்) என்பது ஆலங்கட்டியைக் கொண்டு அவன் நாடியவர்களுக்குத் தண்டனை அளிப்பதைக் குறிக்கலாம்; இது அவர்களின் கனிகளைத் தாக்கி, பயிர்களையும் மரங்களையும் அழித்துவிடும். மேலும், அவன் நாடியவர்களிடமிருந்து அதைத் திருப்புவது அவர்கள் மீதான அவனது கருணையாகும்.\n\r\n\n\r\n﴾يَكَادُ سَنَا بَرْقِهِ يَذْهَبُ بِالْأَبْصَارِ﴿\n\r\n\n\r\n(அதன் மின்னலின் பிரகாசமான ஒளி பார்வையைப் பறித்துவிடும் நிலையை நெருங்குகிறது.) அதன் மின்னலின் பிரகாசத்தை கண்கள் பின்தொடர்ந்து பார்க்க முயன்றால், அது பார்வையையே பறித்துவிடும் நிலையை எட்டும்.\n\r\n\n\r\n﴾يُقَلِّبُ اللَّهُ الَّيْلَ وَالنَّهَارَ﴿\n\r\n\n\r\n(அல்லாஹ் இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக வரச் செய்கிறான்.) அவன் அவற்றை நிர்வகிக்கிறான்; ஒன்றின் நீளத்திலிருந்து ஒரு பகுதியை எடுத்து மற்றொன்றோடு சேர்க்கிறான். இவ்வாறு குறுகியதாக இருந்த ஒன்று நீளமாகவும், நீளமாக இருந்தது குறுகியதாகவும் மாறி இரண்டும் சமமாகும் வரை அவன் செய்கிறான். அல்லாஹ் தனது கட்டளை, பேராற்றல், வல்லமை மற்றும் ஞானத்தினால் இவற்றைக் கட்டுப்படுத்துகிறான்.\n\r\n\n\r\n﴾إِنَّ فِي ذَلِكَ لَعِبْرَةً لِّأُوْلِي الْأَبْصَارِ﴿\n\r\n\n\r\n(நிச்சயமாக, இதில் அகப்பார்வை உடையவர்களுக்கு ஒரு படிப்பினை இருக்கிறது.) அதாவது, இது அவனது மகத்துவத்திற்கான ஓர் அடையாளமாகும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n﴾إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُوْلِي الْأَلْبَابِ﴿\n\r\n\n\r\n(நிச்சயமாக, வானங்கள் மற்றும் பூமியின் படைப்பிலும், இரவு மற்றும் பகல் மாறி மாறி வருவதிலும் அறிவுடையவர்களுக்குப் பல அத்தாட்சிகள் உள்ளன.) (3:190 மற்றும் அதற்குப் பிந்தைய வசனங்கள்)."},"45":{"html":"<strong>விலங்குகளைப் படைப்பதில் அல்லாஹ்வின் பேராற்றல்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">دَآبَّةٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">مَّآءٍ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் ஒவ்வொரு உயிரினத்தையும் நீரிலிருந்து படைத்தான்.)<br />\r\n<br />\r\nஒரே வகையான நீரிலிருந்து, பல்வேறு வடிவங்கள், நிறங்கள் மற்றும் அவை இயங்கும், நிற்கும் விதங்களுடன் கூடிய பலவிதமான விலங்கினங்களைப் படைக்கும் தனது முழுமையான மற்றும் மகத்தான பேராற்றலை அல்லாஹ் குறிப்பிடுகிறான்.<span class=\"quran-arabic-font text-success\">﴾فَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَمْشِي</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَطْنِهِ﴿</span><br />\r\n<br />\r\n(அவற்றில் சில, தங்கள் வயிற்றால் ஊர்ந்து செல்பவை,) பாம்புகள் மற்றும் அது போன்ற உயிரினங்களைப் போல;<span class=\"quran-arabic-font text-success\">﴾وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَمْشِي</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رِجْلَيْنِ﴿</span><br />\r\n<br />\r\n(இன்னும் சில, இரண்டு கால்களால் நடப்பவை,) மனிதர்கள் மற்றும் பறவைகளைப் போல;<span class=\"quran-arabic-font text-success\">﴾وَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَمْشِي</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَرْبَعٍ﴿</span><br />\r\n<br />\r\n(மேலும் சில, நான்கு கால்களால் நடப்பவை,) கால்நடைகள் மற்றும் அனைத்து வகையான விலங்கினங்களைப் போல. அல்லாஹ் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾يَخْلُقُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் தான் நாடுவதைப் படைக்கிறான்.) அதாவது தனது பேராற்றலால்; ஏனெனில் அவன் நாடுவது நடக்கும், அவன் நாடாதது நடக்காது. எனவே அவன் கூறுகிறான்:<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">قَدِيرٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"விலங்குகளைப் படைப்பதில் அல்லாஹ்வின் பேராற்றல்\n\r\n\n\r\n﴾وَاللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ﴿\n\r\n\n\r\n(அல்லாஹ் ஒவ்வொரு உயிரினத்தையும் நீரிலிருந்து படைத்தான்.)\n\r\n\n\r\nஒரே வகையான நீரிலிருந்து, பல்வேறு வடிவங்கள், நிறங்கள் மற்றும் அவை இயங்கும், நிற்கும் விதங்களுடன் கூடிய பலவிதமான விலங்கினங்களைப் படைக்கும் தனது முழுமையான மற்றும் மகத்தான பேராற்றலை அல்லாஹ் குறிப்பிடுகிறான்.﴾فَمِنْهُمْ مَّن يَمْشِي عَلَى بَطْنِهِ﴿\n\r\n\n\r\n(அவற்றில் சில, தங்கள் வயிற்றால் ஊர்ந்து செல்பவை,) பாம்புகள் மற்றும் அது போன்ற உயிரினங்களைப் போல;﴾وَمِنْهُمْ مَّن يَمْشِي عَلَى رِجْلَيْنِ﴿\n\r\n\n\r\n(இன்னும் சில, இரண்டு கால்களால் நடப்பவை,) மனிதர்கள் மற்றும் பறவைகளைப் போல;﴾وَمِنْهُمْ مَّن يَمْشِي عَلَى أَرْبَعٍ﴿\n\r\n\n\r\n(மேலும் சில, நான்கு கால்களால் நடப்பவை,) கால்நடைகள் மற்றும் அனைத்து வகையான விலங்கினங்களைப் போல. அல்லாஹ் கூறுகிறான்:﴾يَخْلُقُ اللَّهُ مَا يَشَآءُ﴿\n\r\n\n\r\n(அல்லாஹ் தான் நாடுவதைப் படைக்கிறான்.) அதாவது தனது பேராற்றலால்; ஏனெனில் அவன் நாடுவது நடக்கும், அவன் நாடாதது நடக்காது. எனவே அவன் கூறுகிறான்:﴾إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴿\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ் அனைத்துப் பொருட்கள் மீதும் பேராற்றல் உடையவன்.)"},"46":{"html":"<span class=\"quran-arabic-font text-success\">﴾لَّقَدْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتٍ</span> <span class=\"quran-arabic-font text-success\">مُّبَيِّنَـتٍ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">صِرَاطٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ﴿</span><br />\r\n<br />\r\n(திண்ணமாக நாம் தெளிவான வசனங்களை இறக்கி அருளியுள்ளோம்; மேலும் அல்லாஹ், தான் நாடியவர்களை நேரான பாதையின் பக்கம் வழிகாட்டுகிறான்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"﴾لَّقَدْ أَنزَلْنَآ ءَايَـتٍ مُّبَيِّنَـتٍ وَاللَّهُ يَهْدِى مَن يَشَآءُ إِلَى صِرَاطٍ مُّسْتَقِيمٍ﴿\n\r\n\n\r\n(திண்ணமாக நாம் தெளிவான வசனங்களை இறக்கி அருளியுள்ளோம்; மேலும் அல்லாஹ், தான் நாடியவர்களை நேரான பாதையின் பக்கம் வழிகாட்டுகிறான்.)"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=52\" class=\"link\">24:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:52 ஐ பார்க்கவும்"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=52\" class=\"link\">24:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:52 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=52\" class=\"link\">24:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:52 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=52\" class=\"link\">24:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:52 ஐ பார்க்கவும்"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=52\" class=\"link\">24:52</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:52 ஐ பார்க்கவும்"},"52":{"html":"<strong>நயவஞ்சகர்களின் துரோகமும் நம்பிக்கையாளர்களின் அணுகுமுறையும்</strong><br />\r\n<br />\r\nஒன்றைக் காட்டி மற்றொன்றை மறைக்கும் நயவஞ்சகர்களின் குணாதிசயங்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் தங்கள் நாவுகளால், <span class=\"quran-arabic-font text-success\">﴾آمَنَّا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَبِالرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">وَأَطَعْنَا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَتَوَلَّى</span> <span class=\"quran-arabic-font text-success\">فَرِيقٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ﴿</span> (\"நாங்கள் அல்லாஹ்வையும் அவனது தூதரையும் ஈமான் கொண்டோம், மேலும் நாங்கள் கீழ்ப்படிந்தோம்\" என்று கூறிவிட்டு, அதன் பிறகு அவர்களில் ஒரு பிரிவினர் புறக்கணித்துச் செல்கின்றனர்) என்று கூறுகிறார்கள். அதாவது, அவர்களின் செயல்கள் அவர்களின் சொல்லுக்கு முரணாக இருக்கின்றன. அவர்கள் செய்யாதவற்றையே கூறுகிறார்கள். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">بِالْمُؤْمِنِينَ﴿</span> (இத்தகையவர்கள் நம்பிக்கையாளர்கள் அல்லர்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">دُعُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">لِيَحْكُمَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ﴿</span> (அவர்களுக்கிடையே தீர்ப்பளிப்பதற்காக அல்லாஹ்விடமும் அவனது தூதரிடமும் அவர்கள் அழைக்கப்படும்போது...) இதன் பொருள், அல்லாஹ் தனது தூதருக்கு (ஸல்) வஹீயாக (இறைச்செய்தியாக) அருளிய நேர்வழியைப் பின்பற்றுமாறு அவர்கள் அழைக்கப்படும்போது, அவர்கள் அதைப் புறக்கணிக்கிறார்கள்; மேலும் அவரைப் பின்பற்றுவதற்குப் பெருமையடித்துக் கொள்கிறார்கள். இது இந்த வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَزْعُمُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">بِمَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ﴿</span> (உமக்கு அருளப்பட்டதையும், உமக்கு முன்னால் அருளப்பட்டதையும் தாங்கள் ஈமான் கொண்டிருப்பதாகக் கூறிக்கொள்பவர்களை நீர் பார்க்கவில்லையா?) அவனது இந்தத் திருவசனம் வரை: <span class=\"quran-arabic-font text-success\">﴾رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">الْمُنَافِقِينَ</span> <span class=\"quran-arabic-font text-success\">يَصُدُّونَ</span> <span class=\"quran-arabic-font text-success\">عَنكَ</span> <span class=\"quran-arabic-font text-success\">صُدُوداً﴿</span> (அந்த நயவஞ்சகர்கள் உம்மை விட்டும் முற்றிலும் புறக்கணித்துச் செல்வதை நீர் காண்பீர்) 4: 60-61.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">لَّهُمُ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">يَأْتُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مُذْعِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (ஆனால், உண்மை அவர்களுக்குச் சாதகமாக இருந்தால், அவர்கள் அவரிடம் விருப்பத்துடன் பணிந்து வருவார்கள்.) இதன் பொருள், தீர்ப்பு அவர்களுக்குச் சாதகமாக இருக்கும் பட்சத்தில், அவர்கள் செவிசாய்த்து கீழ்ப்படிவார்கள். <span class=\"quran-arabic-font text-success\">﴾مُذْعِنِينَ﴿</span> (விருப்பத்துடன் பணிந்து) என்ற சொல்லின் பொருள் இதுவே. ஆனால், தீர்ப்பு தங்களுக்கு எதிராக அமையும் எனத் தெரிந்தால், அவர்கள் புறக்கணித்துவிட்டு உண்மைக்கு மாறான ஒன்றைக் கோருவார்கள். தனது பொய்யான வாதங்கள் வெற்றி பெற வேண்டும் என்பதற்காக நபி (ஸல்) அவர்களைத் தவிர மற்றவர்களிடம் தீர்ப்புக்காகச் செல்ல விரும்புவார்கள். ஆரம்பத்தில் அவர் நபி (ஸல்) அவர்களிடம் வரச் சம்மதித்தது அதுதான் உண்மை என்று அவர் நம்பியதால் அல்ல, மாறாக அது அவரது மனோ இச்சைக்கு ஏற்ப இருந்ததால்தான். எனவே, உண்மை அவரது விருப்பத்திற்கு எதிராகச் சென்றபோது, அவர் அதைப் புறக்கணித்துவிட்டார். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَفِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">مَّرَضٌ﴿</span> (அவர்களின் உள்ளங்களில் நோய் இருக்கிறதா...) அதாவது, அவர்களது நிலை வேறெதுவுமாக இருக்க முடியாது. அவர்களின் உள்ளங்களில் நிச்சயம் ஒரு நோய் இருக்க வேண்டும், அல்லது மார்க்கத்தில் அவர்களுக்கு சந்தேகம் இருக்க வேண்டும், அல்லது அல்லாஹ்வும் அவனது தூதரும் தங்களுக்கு அநீதி இழைத்து விடுவார்கள் என்று அவர்கள் அஞ்ச வேண்டும். எதுவாக இருந்தாலும், அது தெளிவான குஃப்ர் (நிராகரிப்பு) ஆகும். அவர்களில் ஒவ்வொருவரிடமும் இத்தகைய குணங்களில் எது காணப்படுகிறது என்பதை அல்லாஹ் நன்கு அறிவான். <span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمُونَ﴿</span> (மாறாக, அவர்களே அநியாயக்காரர்கள்.) அதாவது, அவர்களே அநீதி இழைக்கும் தீயவர்கள். அவர்கள் கற்பனை செய்யும் அநீதியிலிருந்தும் பக்கச்சார்பிலிருந்தும் அல்லாஹ்வும் அவனது தூதரும் முற்றிலும் தூய்மையானவர்கள்; அவர்கள் அத்தகைய குறைகளுக்கு அப்பாற்பட்டவர்கள்.<br />\r\n<br />\r\nபின்னர், அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கட்டுப்பட்டு, அல்லாஹ்வின் வேதத்தையும் அவனது தூதரின் சுன்னாவையும் தவிர வேறு எதையும் நாடாத நம்பிக்கையாளர்களின் பண்புகளைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">قَوْلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">دُعُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">لِيَحْكُمَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">وَأَطَعْنَا﴿</span> (நம்பிக்கையாளர்கள், அவர்களுக்கிடையே தீர்ப்பளிப்பதற்காக அல்லாஹ்விடமும் அவனது தூதரிடமும் அழைக்கப்படும்போது, அவர்களது ஒரே கூற்று: \"நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்\" என்பதாகவே இருக்கும்.) அதாவது, கீழ்ப்படிவதற்காகவே செவிமடுப்பது. அவர்கள் வெற்றியை அடைந்தவர்கள் என அல்லாஹ் வர்ணிக்கிறான். வெற்றி என்பது ஒருவர் விரும்புவதை அடைவதும், அஞ்சுவதிலிருந்து பாதுகாப்புப் பெறுவதும் ஆகும். எனவே அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْمُفْلِحُونَ﴿</span> (இவர்களே வெற்றி பெற்றவர்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">يَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">سَمِعْنَا</span> <span class=\"quran-arabic-font text-success\">وَأَطَعْنَا﴿</span> (அவர்கள் கூறுகிறார்கள்: \"நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்\") என்ற வசனத்தைப் பற்றி கதாதா (ரஹ்) கூறினார்கள்: \"அகபாவிலும் பத்ரிலும் கலந்து கொண்டவரும், அன்சாரிகளின் தலைவர்களில் ஒருவருமான உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் மரணத் தருவாயில் இருந்தபோது, அவர்கள் தனது மருமகன் ஜுனாதா பின் அபீ உமய்யாவிடம்: 'நாங்கள் அல்லாஹ்வின் தூதரிடம் (ஸல்) செய்த பைஅத் (சத்தியப் பிரமாணம்) பற்றி உமக்கு அறிவிக்கட்டுமா?' என்று கேட்டார்கள். அவர், 'ஆம்' என்றார். அதற்கு உபாதா (ரழி) அவர்கள் கூறினார்கள்: 'நீர் வசதியாக இருக்கும்போதும், சிரமத்தில் இருக்கும்போதும், சுறுசுறுப்பாக இருக்கும்போதும், விருப்பமில்லாத போதும், சுயநலம் மேலோங்கும்போதும் நீர் செவியேற்றுக் கீழ்ப்படிய வேண்டும். உமது நாவை உண்மையை மட்டுமே பேசப் பழக்கப்படுத்த வேண்டும். அவர்கள் பகிரங்கமாக அல்லாஹ்வுக்கு மாறு செய்யுமாறு கட்டளையிட்டால் தவிர, அதிகாரத்தில் உள்ளவர்களை எதிர்க்காதீர். அல்லாஹ்வின் வேதத்திற்கு முரணான எதையேனும் செய்யுமாறு உமக்குக் கட்டளையிடப்பட்டால், அப்போது அல்லாஹ்வின் வேதத்தையே பின்பற்றுவீராக.'\"<br />\r\n<br />\r\nகதாதா (ரஹ்) கூறினார்கள்: அபுத் தர்தா (ரழி) அவர்கள் பின்வருமாறு கூறியதாக எங்களுக்குச் சொல்லப்பட்டது: \"அல்லாஹ்வுக்குக் கீழ்ப்படிவதன் மூலமே தவிர இஸ்லாம் என்பது இல்லை. ஜமாஅத்தோடு (கூட்டாக) இருப்பதிலேயே அனைத்து நன்மைகளும் உள்ளன. அல்லாஹ்வுக்கும், அவனது தூதருக்கும் (ஸல்), கலீஃபாவுக்கும் மற்றும் அனைத்து முஃமின்களுக்கும் (நம்பிக்கையாளர்களுக்கும்) நலம் நாடுவது அவசியமாகும்.\" மேலும், உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் இவ்வாறு கூறுபவர்களாக இருந்தார்கள் என்று எங்களுக்கு அறிவிக்கப்பட்டுள்ளது: \" 'லா இலாஹ இல்லல்லாஹ்' எனும் திருக்கலிமா, தொழுகையை நிலைநாட்டுதல், ஜகாத் வழங்குதல் மற்றும் முஸ்லிம்களின் விவகாரங்களுக்கு அல்லாஹ் அதிகாரம் வழங்கியவர்களுக்குக் கீழ்ப்படிதல் ஆகியவையே இஸ்லாத்தின் பிணைப்புகளாகும்.\" இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் வேதம், அவனது தூதரின் சுன்னா, நேர்வழி பெற்ற கலீஃபாக்கள் மற்றும் இமாம்கள் ஆகியோர் அல்லாஹ்வுக்குக் கீழ்ப்படியுமாறு கட்டளையிடும்போது, அவர்களுக்குக் கீழ்ப்படிவது கடமை என்பதை வலியுறுத்தும் எண்ணற்ற ஹதீஸ்களும் செய்திகளும் உள்ளன; அவை அனைத்தையும் இங்கே விவரிப்பது கடினம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يُطِعِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَرَسُولَهُ﴿</span> (மேலும், யார் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கீழ்ப்படிகிறாரோ) அவர் கட்டளையிட்டவற்றைச் செய்தும், தடுத்தவற்றைத் தவிர்த்தும் வாழ்கிறாரோ, <span class=\"quran-arabic-font text-success\">﴾وَيَخْشَ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ﴿</span> (மேலும் அல்லாஹ்வுக்கு அஞ்சுகிறாரோ) அதாவது தனது கடந்த காலப் பாவங்களுக்காக அஞ்சுபவர், <span class=\"quran-arabic-font text-success\">﴾وَيَتَّقْهِ﴿</span> (இன்னும் அவனிடம் தக்வா (பேணுதல்) கொள்கிறாரோ) இனி வரும் காலங்களில் பாவங்கள் செய்யாமல் தன்னைத் தற்காத்துக் கொள்கிறாரோ, <span class=\"quran-arabic-font text-success\">﴾فَأُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَائِزُونَ﴿</span> (அவர்களே வெற்றி பெற்றவர்கள்.) அதாவது, இவ்வுலகிலும் மறுமையிலும் அனைத்து நன்மைகளையும் அடைந்து, அனைத்துத் தீமைகளிலிருந்தும் தப்பியவர்கள் இவர்களே.<br />\r\n<br />","text":"நயவஞ்சகர்களின் துரோகமும் நம்பிக்கையாளர்களின் அணுகுமுறையும்\n\r\n\n\r\nஒன்றைக் காட்டி மற்றொன்றை மறைக்கும் நயவஞ்சகர்களின் குணாதிசயங்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் தங்கள் நாவுகளால், ﴾آمَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّى فَرِيقٌ مِّنْهُمْ مِّن بَعْدِ ذَلِكَ﴿ (\"நாங்கள் அல்லாஹ்வையும் அவனது தூதரையும் ஈமான் கொண்டோம், மேலும் நாங்கள் கீழ்ப்படிந்தோம்\" என்று கூறிவிட்டு, அதன் பிறகு அவர்களில் ஒரு பிரிவினர் புறக்கணித்துச் செல்கின்றனர்) என்று கூறுகிறார்கள். அதாவது, அவர்களின் செயல்கள் அவர்களின் சொல்லுக்கு முரணாக இருக்கின்றன. அவர்கள் செய்யாதவற்றையே கூறுகிறார்கள். அல்லாஹ் கூறுகிறான்: ﴾وَمَآ أُولَئِكَ بِالْمُؤْمِنِينَ﴿ (இத்தகையவர்கள் நம்பிக்கையாளர்கள் அல்லர்.)\n\r\n\n\r\n﴾وَإِذَا دُعُواْ إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ﴿ (அவர்களுக்கிடையே தீர்ப்பளிப்பதற்காக அல்லாஹ்விடமும் அவனது தூதரிடமும் அவர்கள் அழைக்கப்படும்போது...) இதன் பொருள், அல்லாஹ் தனது தூதருக்கு (ஸல்) வஹீயாக (இறைச்செய்தியாக) அருளிய நேர்வழியைப் பின்பற்றுமாறு அவர்கள் அழைக்கப்படும்போது, அவர்கள் அதைப் புறக்கணிக்கிறார்கள்; மேலும் அவரைப் பின்பற்றுவதற்குப் பெருமையடித்துக் கொள்கிறார்கள். இது இந்த வசனத்தைப் போன்றது: ﴾أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ﴿ (உமக்கு அருளப்பட்டதையும், உமக்கு முன்னால் அருளப்பட்டதையும் தாங்கள் ஈமான் கொண்டிருப்பதாகக் கூறிக்கொள்பவர்களை நீர் பார்க்கவில்லையா?) அவனது இந்தத் திருவசனம் வரை: ﴾رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنكَ صُدُوداً﴿ (அந்த நயவஞ்சகர்கள் உம்மை விட்டும் முற்றிலும் புறக்கணித்துச் செல்வதை நீர் காண்பீர்) 4: 60-61.\n\r\n\n\r\n﴾وَإِن يَكُنْ لَّهُمُ الْحَقُّ يَأْتُواْ إِلَيْهِ مُذْعِنِينَ ﴿ (ஆனால், உண்மை அவர்களுக்குச் சாதகமாக இருந்தால், அவர்கள் அவரிடம் விருப்பத்துடன் பணிந்து வருவார்கள்.) இதன் பொருள், தீர்ப்பு அவர்களுக்குச் சாதகமாக இருக்கும் பட்சத்தில், அவர்கள் செவிசாய்த்து கீழ்ப்படிவார்கள். ﴾مُذْعِنِينَ﴿ (விருப்பத்துடன் பணிந்து) என்ற சொல்லின் பொருள் இதுவே. ஆனால், தீர்ப்பு தங்களுக்கு எதிராக அமையும் எனத் தெரிந்தால், அவர்கள் புறக்கணித்துவிட்டு உண்மைக்கு மாறான ஒன்றைக் கோருவார்கள். தனது பொய்யான வாதங்கள் வெற்றி பெற வேண்டும் என்பதற்காக நபி (ஸல்) அவர்களைத் தவிர மற்றவர்களிடம் தீர்ப்புக்காகச் செல்ல விரும்புவார்கள். ஆரம்பத்தில் அவர் நபி (ஸல்) அவர்களிடம் வரச் சம்மதித்தது அதுதான் உண்மை என்று அவர் நம்பியதால் அல்ல, மாறாக அது அவரது மனோ இச்சைக்கு ஏற்ப இருந்ததால்தான். எனவே, உண்மை அவரது விருப்பத்திற்கு எதிராகச் சென்றபோது, அவர் அதைப் புறக்கணித்துவிட்டார். அல்லாஹ் கூறுகிறான்: ﴾أَفِى قُلُوبِهِمْ مَّرَضٌ﴿ (அவர்களின் உள்ளங்களில் நோய் இருக்கிறதா...) அதாவது, அவர்களது நிலை வேறெதுவுமாக இருக்க முடியாது. அவர்களின் உள்ளங்களில் நிச்சயம் ஒரு நோய் இருக்க வேண்டும், அல்லது மார்க்கத்தில் அவர்களுக்கு சந்தேகம் இருக்க வேண்டும், அல்லது அல்லாஹ்வும் அவனது தூதரும் தங்களுக்கு அநீதி இழைத்து விடுவார்கள் என்று அவர்கள் அஞ்ச வேண்டும். எதுவாக இருந்தாலும், அது தெளிவான குஃப்ர் (நிராகரிப்பு) ஆகும். அவர்களில் ஒவ்வொருவரிடமும் இத்தகைய குணங்களில் எது காணப்படுகிறது என்பதை அல்லாஹ் நன்கு அறிவான். ﴾بَلْ أُولَئِكَ هُمُ الظَّالِمُونَ﴿ (மாறாக, அவர்களே அநியாயக்காரர்கள்.) அதாவது, அவர்களே அநீதி இழைக்கும் தீயவர்கள். அவர்கள் கற்பனை செய்யும் அநீதியிலிருந்தும் பக்கச்சார்பிலிருந்தும் அல்லாஹ்வும் அவனது தூதரும் முற்றிலும் தூய்மையானவர்கள்; அவர்கள் அத்தகைய குறைகளுக்கு அப்பாற்பட்டவர்கள்.\n\r\n\n\r\nபின்னர், அல்லாஹ்வுக்கும் அவனது தூதருக்கும் (ஸல்) கட்டுப்பட்டு, அல்லாஹ்வின் வேதத்தையும் அவனது தூதரின் சுன்னாவையும் தவிர வேறு எதையும் நாடாத நம்பிக்கையாளர்களின் பண்புகளைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்: ﴾إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُواْ إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُواْ سَمِعْنَا وَأَطَعْنَا﴿ (நம்பிக்கையாளர்கள், அவர்களுக்கிடையே தீர்ப்பளிப்பதற்காக அல்லாஹ்விடமும் அவனது தூதரிடமும் அழைக்கப்படும்போது, அவர்களது ஒரே கூற்று: \"நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்\" என்பதாகவே இருக்கும்.) அதாவது, கீழ்ப்படிவதற்காகவே செவிமடுப்பது. அவர்கள் வெற்றியை அடைந்தவர்கள் என அல்லாஹ் வர்ணிக்கிறான். வெற்றி என்பது ஒருவர் விரும்புவதை அடைவதும், அஞ்சுவதிலிருந்து பாதுகாப்புப் பெறுவதும் ஆகும். எனவே அல்லாஹ் கூறுகிறான்: ﴾وَأُولَئِكَ هُمُ الْمُفْلِحُونَ﴿ (இவர்களே வெற்றி பெற்றவர்கள்.)\n\r\n\n\r\n﴾أَن يَقُولُواْ سَمِعْنَا وَأَطَعْنَا﴿ (அவர்கள் கூறுகிறார்கள்: \"நாங்கள் செவியேற்றோம், கீழ்ப்படிந்தோம்\") என்ற வசனத்தைப் பற்றி கதாதா (ரஹ்) கூறினார்கள்: \"அகபாவிலும் பத்ரிலும் கலந்து கொண்டவரும், அன்சாரிகளின் தலைவர்களில் ஒருவருமான உபாதா பின் அஸ்-ஸாமித் (ரழி) அவர்கள் மரணத் தருவாயில் இருந்தபோது, அவர்கள் தனது மருமகன் ஜுனாதா பின் அபீ உமய்யாவிடம்: 'நாங்கள் அல்லாஹ்வின் தூதரிடம் (ஸல்) செய்த பைஅத் (சத்தியப் பிரமாணம்) பற்றி உமக்கு அறிவிக்கட்டுமா?' என்று கேட்டார்கள். அவர், 'ஆம்' என்றார். அதற்கு உபாதா (ரழி) அவர்கள் கூறினார்கள்: 'நீர் வசதியாக இருக்கும்போதும், சிரமத்தில் இருக்கும்போதும், சுறுசுறுப்பாக இருக்கும்போதும், விருப்பமில்லாத போதும், சுயநலம் மேலோங்கும்போதும் நீர் செவியேற்றுக் கீழ்ப்படிய வேண்டும். உமது நாவை உண்மையை மட்டுமே பேசப் பழக்கப்படுத்த வேண்டும். அவர்கள் பகிரங்கமாக அல்லாஹ்வுக்கு மாறு செய்யுமாறு கட்டளையிட்டால் தவிர, அதிகாரத்தில் உள்ளவர்களை எதிர்க்காதீர். அல்லாஹ்வின் வேதத்திற்கு முரணான எதையேனும் செய்யுமாறு உமக்குக் கட்டளையிடப்பட்டால், அப்போது அல்லாஹ்வின் வேதத்தையே பின்பற்றுவீராக.'\"\n\r\n\n\r\nகதாதா (ரஹ்) கூறினார்கள்: அபுத் தர்தா (ரழி) அவர்கள் பின்வருமாறு கூறியதாக எங்களுக்குச் சொல்லப்பட்டது: \"அல்லாஹ்வுக்குக் கீழ்ப்படிவதன் மூலமே தவிர இஸ்லாம் என்பது இல்லை. ஜமாஅத்தோடு (கூட்டாக) இருப்பதிலேயே அனைத்து நன்மைகளும் உள்ளன. அல்லாஹ்வுக்கும், அவனது தூதருக்கும் (ஸல்), கலீஃபாவுக்கும் மற்றும் அனைத்து முஃமின்களுக்கும் (நம்பிக்கையாளர்களுக்கும்) நலம் நாடுவது அவசியமாகும்.\" மேலும், உமர் பின் அல்-கத்தாப் (ரழி) அவர்கள் இவ்வாறு கூறுபவர்களாக இருந்தார்கள் என்று எங்களுக்கு அறிவிக்கப்பட்டுள்ளது: \" 'லா இலாஹ இல்லல்லாஹ்' எனும் திருக்கலிமா, தொழுகையை நிலைநாட்டுதல், ஜகாத் வழங்குதல் மற்றும் முஸ்லிம்களின் விவகாரங்களுக்கு அல்லாஹ் அதிகாரம் வழங்கியவர்களுக்குக் கீழ்ப்படிதல் ஆகியவையே இஸ்லாத்தின் பிணைப்புகளாகும்.\" இதனை இப்னு அபீ ஹாதிம் பதிவு செய்துள்ளார்கள். அல்லாஹ்வின் வேதம், அவனது தூதரின் சுன்னா, நேர்வழி பெற்ற கலீஃபாக்கள் மற்றும் இமாம்கள் ஆகியோர் அல்லாஹ்வுக்குக் கீழ்ப்படியுமாறு கட்டளையிடும்போது, அவர்களுக்குக் கீழ்ப்படிவது கடமை என்பதை வலியுறுத்தும் எண்ணற்ற ஹதீஸ்களும் செய்திகளும் உள்ளன; அவை அனைத்தையும் இங்கே விவரிப்பது கடினம்.\n\r\n\n\r\n﴾وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ﴿ (மேலும், யார் அல்லாஹ்வுக்கும் அவனது தூதருக்கும் கீழ்ப்படிகிறாரோ) அவர் கட்டளையிட்டவற்றைச் செய்தும், தடுத்தவற்றைத் தவிர்த்தும் வாழ்கிறாரோ, ﴾وَيَخْشَ اللَّهَ﴿ (மேலும் அல்லாஹ்வுக்கு அஞ்சுகிறாரோ) அதாவது தனது கடந்த காலப் பாவங்களுக்காக அஞ்சுபவர், ﴾وَيَتَّقْهِ﴿ (இன்னும் அவனிடம் தக்வா (பேணுதல்) கொள்கிறாரோ) இனி வரும் காலங்களில் பாவங்கள் செய்யாமல் தன்னைத் தற்காத்துக் கொள்கிறாரோ, ﴾فَأُولَئِكَ هُمُ الْفَائِزُونَ﴿ (அவர்களே வெற்றி பெற்றவர்கள்.) அதாவது, இவ்வுலகிலும் மறுமையிலும் அனைத்து நன்மைகளையும் அடைந்து, அனைத்துத் தீமைகளிலிருந்தும் தப்பியவர்கள் இவர்களே."},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=54\" class=\"link\">24:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:54 ஐ பார்க்கவும்"},"54":{"html":"<span class=\"quran-arabic-font text-success\">﴾قُل</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تُقْسِمُواْ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் சத்தியம் செய்யாதீர்கள்\" என்று நபியே!) கூறுவீராக. அதாவது, இத்தகைய சத்தியங்களைச் செய்யாதீர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾طَاعَةٌ</span> <span class=\"quran-arabic-font text-success\">مَّعْرُوفَةٌ﴿</span><br />\r\n<br />\r\n(உங்களது கீழ்ப்படிதல் அறியப்பட்டதே.) இதன் பொருள், உங்களது கீழ்ப்படிதல் எத்தகையது என்பது அறியப்பட்டதே; அதாவது, உங்களது கீழ்ப்படிதல் வெறும் வாய்வார்த்தை மட்டுமே, அது செயலோடு கூடியதல்ல என்பது தெரிந்ததே எனக் கூறப்படுகிறது. நீங்கள் ஒவ்வொரு முறை சத்தியம் செய்யும்போதும் பொய் கூறுகிறீர்கள். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَحْلِفُونَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">لِتَرْضَوْاْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ﴿</span><br />\r\n<br />\r\n(நீங்கள் அவர்களைக் குறித்துத் திருப்தியடைவதற்காக அவர்கள் உங்களிடம் சத்தியம் செய்கிறார்கள்...) (<a href=\"qurandisp.php?sura=9&ayah=96\" class=\"link\">9:96</a>).<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾اتَّخَذْواْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَـنَهُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَّةً﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்களின் சத்தியங்களைத் தற்காப்புக்கான கேடயமாக ஆக்கிக்கொண்டார்கள்.) (<a href=\"qurandisp.php?sura=58&ayah=16\" class=\"link\">58:16</a>).<br />\r\n<br />\r\nஅவர்கள் தாமாகத் தேர்ந்தெடுத்துக் கூறும் விஷயங்களில்கூட பொய் சொல்வது அவர்களது சுபாவமாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">نَـفَقُواْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لإِخْوَانِهِمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">لَئِنْ</span> <span class=\"quran-arabic-font text-success\">أُخْرِجْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَخْرُجَنَّ</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُطِيعُ</span> <span class=\"quran-arabic-font text-success\">فيكُمْ</span> <span class=\"quran-arabic-font text-success\">أَحَداً</span> <span class=\"quran-arabic-font text-success\">أَبَداً</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">قُوتِلْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَنصُرَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَكَـذِبُونَ</span> - <span class=\"quran-arabic-font text-success\">لَئِنْ</span> <span class=\"quran-arabic-font text-success\">أُخْرِجُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَخْرُجُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَئِن</span> <span class=\"quran-arabic-font text-success\">قُوتِلُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنصُرُونَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَئِن</span> <span class=\"quran-arabic-font text-success\">نَّصَرُوهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيُوَلُّنَّ</span> <span class=\"quran-arabic-font text-success\">الاٌّدْبَـرَ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(வேதமுடையோர்களில் நிராகரித்தவர்களான தங்கள் நண்பர்களிடம், \"நீங்கள் வெளியேற்றப்பட்டால், நாங்களும் உங்களுடன் நிச்சயமாக வெளியேறுவோம்; உங்களுக்கு எதிராக நாங்கள் யாருக்கும் ஒருபோதும் கீழ்ப்படிய மாட்டோம்; நீங்கள் தாக்கப்பட்டால், நிச்சயமாக நாங்கள் உங்களுக்கு உதவுவோம்\" என்று கூறும் அந்த நயவஞ்சகர்களை (நபியே!) நீர் பார்க்கவில்லையா? ஆனால், அவர்கள் நிச்சயமாகப் பொய்யர்கள் என்பதற்கு அல்லாஹ்வே சாட்சி பகர்கிறான். நிச்சயமாக அவர்கள் வெளியேற்றப்பட்டால், இவர்கள் அவர்களுடன் வெளியேற மாட்டார்கள்; அவர்கள் தாக்கப்பட்டால், இவர்கள் அவர்களுக்கு உதவ மாட்டார்கள். ஒருவேளை இவர்கள் அவர்களுக்கு உதவினாலும், இவர்கள் புறமுதுகு காட்டி ஓடிவிடுவார்கள்; பின்னர் அவர்களுக்கு எவ்வித உதவியும் கிடைக்காது.) (<a href=\"qurandisp.php?sura=59&ayah=11\" class=\"link\">59:11</a>-12).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் நீங்கள் செய்பவற்றை நன்கறிந்தவன்.) அதாவது, உங்களது அந்தரங்கத்தையும் பகிரங்கத்தையும் அறிந்தவன்; அதற்கேற்ப அவன் உங்களுக்குக் கூலி வழங்குவான்.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">أَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ﴿</span><br />\r\n<br />\r\n(\"அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள்; இன்னும் இத்தூதருக்கும் (ஸல்) கீழ்ப்படியுங்கள்\" என்று கூறுவீராக.) அதாவது, அல்லாஹ்வின் வேதத்தையும் அவனது தூதரின் (ஸல்) சுன்னாவையும் பின்பற்றுங்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِن</span> <span class=\"quran-arabic-font text-success\">تَوَلَّوْاْ﴿</span><br />\r\n<br />\r\n(ஆனால் நீங்கள் புறக்கணித்தால்,) அதாவது அவர்கள் உங்களுக்குக் கொண்டு வந்ததை நீங்கள் புறக்கணித்தால்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حُمِّلَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் (ஸல்) மீது சுமத்தப்பட்ட கடமைக்கு மட்டுமே அவர்கள் (ஸல்) பொறுப்பாவார்கள்.) அதாவது, தூதுச்செய்தியை எத்திவைப்பதும், அமானிதத்தை (ஒப்படைக்கப்பட்ட பொறுப்பை) நிறைவேற்றுவதுமே அவர்களது கடமையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَعَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">حُمِّلْتُمْ﴿</span><br />\r\n<br />\r\n(உங்கள் மீது சுமத்தப்பட்ட கடமைக்கு நீங்களே பொறுப்பாவீர்கள்.) அதாவது, அத்தூதுச் செய்தியை ஏற்றுக்கொள்வதும், அதை மேன்மைப்படுத்துவதும், கட்டளையிடப்பட்டபடி செயல்படுவதும் உங்கள் மீதான கடமையாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِن</span> <span class=\"quran-arabic-font text-success\">تُطِيعُوهُ</span> <span class=\"quran-arabic-font text-success\">تَهْتَدُواْ﴿</span><br />\r\n<br />\r\n(நீங்கள் அவர்களுக்கு (ஸல்) கீழ்ப்படிந்தால், நீங்கள் நேர்வழி பெறுவீர்கள்.) ஏனெனில், அவர்கள் (ஸல்) நேரான பாதையின் பக்கமே அழைக்கிறார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾صِرَطِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ﴿</span><br />\r\n<br />\r\n(வானங்களில் உள்ளவையும் பூமியில் உள்ளவையும் யாருக்குச் சொந்தமானவையோ அந்த அல்லாஹ்வின் பாதை இதுவாகும்.) (<a href=\"qurandisp.php?sura=42&ayah=53\" class=\"link\">42:53</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْبَلَـغُ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينُ﴿</span><br />\r\n<br />\r\n(தெளிவாக எத்திவைப்பதைத் தவிர இத்தூதர் (ஸல்) மீது வேறு கடமை இல்லை.) இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكَ</span> <span class=\"quran-arabic-font text-success\">الْبَلَـغُ</span> <span class=\"quran-arabic-font text-success\">وَعَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">الْحِسَابُ﴿</span><br />\r\n<br />\r\n((நபியே!) எத்திவைப்பது மட்டுமே உமது கடமை; கணக்குக் கேட்பது நம்மிடமே உள்ளது.) (<a href=\"qurandisp.php?sura=13&ayah=40\" class=\"link\">13:40</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَذَكِّرْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مُذَكِّرٌ</span> - <span class=\"quran-arabic-font text-success\">لَّسْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">بِمُسَيْطِرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே நீர் நினைவூட்டுவீராக! நீர் நினைவூட்டுபவர் மட்டுமே. நீர் அவர்கள் மீது அதிகாரம் செலுத்துபவர் அல்ல.) (<a href=\"qurandisp.php?sura=88&ayah=21\" class=\"link\">88:21</a>-22).<br />\r\n<br />\r\n<br />\r\n<br />","text":"﴾قُل لاَّ تُقْسِمُواْ﴿\n\r\n\n\r\n(\"நீங்கள் சத்தியம் செய்யாதீர்கள்\" என்று நபியே!) கூறுவீராக. அதாவது, இத்தகைய சத்தியங்களைச் செய்யாதீர்கள்.\n\r\n\n\r\n﴾طَاعَةٌ مَّعْرُوفَةٌ﴿\n\r\n\n\r\n(உங்களது கீழ்ப்படிதல் அறியப்பட்டதே.) இதன் பொருள், உங்களது கீழ்ப்படிதல் எத்தகையது என்பது அறியப்பட்டதே; அதாவது, உங்களது கீழ்ப்படிதல் வெறும் வாய்வார்த்தை மட்டுமே, அது செயலோடு கூடியதல்ல என்பது தெரிந்ததே எனக் கூறப்படுகிறது. நீங்கள் ஒவ்வொரு முறை சத்தியம் செய்யும்போதும் பொய் கூறுகிறீர்கள். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾يَحْلِفُونَ لَكُمْ لِتَرْضَوْاْ عَنْهُمْ﴿\n\r\n\n\r\n(நீங்கள் அவர்களைக் குறித்துத் திருப்தியடைவதற்காக அவர்கள் உங்களிடம் சத்தியம் செய்கிறார்கள்...) (9:96).\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾اتَّخَذْواْ أَيْمَـنَهُمْ جُنَّةً﴿\n\r\n\n\r\n(அவர்கள் தங்களின் சத்தியங்களைத் தற்காப்புக்கான கேடயமாக ஆக்கிக்கொண்டார்கள்.) (58:16).\n\r\n\n\r\nஅவர்கள் தாமாகத் தேர்ந்தெடுத்துக் கூறும் விஷயங்களில்கூட பொய் சொல்வது அவர்களது சுபாவமாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾أَلَمْ تَرَ إِلَى الَّذِينَ نَـفَقُواْ يَقُولُونَ لإِخْوَانِهِمُ الَّذِينَ كَفَرُواْ مِنْ أَهْلِ الْكِتَـبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلاَ نُطِيعُ فيكُمْ أَحَداً أَبَداً وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـذِبُونَ - لَئِنْ أُخْرِجُواْ لاَ يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُواْ لاَ يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ الاٌّدْبَـرَ ثُمَّ لاَ يُنصَرُونَ ﴿\n\r\n\n\r\n(வேதமுடையோர்களில் நிராகரித்தவர்களான தங்கள் நண்பர்களிடம், \"நீங்கள் வெளியேற்றப்பட்டால், நாங்களும் உங்களுடன் நிச்சயமாக வெளியேறுவோம்; உங்களுக்கு எதிராக நாங்கள் யாருக்கும் ஒருபோதும் கீழ்ப்படிய மாட்டோம்; நீங்கள் தாக்கப்பட்டால், நிச்சயமாக நாங்கள் உங்களுக்கு உதவுவோம்\" என்று கூறும் அந்த நயவஞ்சகர்களை (நபியே!) நீர் பார்க்கவில்லையா? ஆனால், அவர்கள் நிச்சயமாகப் பொய்யர்கள் என்பதற்கு அல்லாஹ்வே சாட்சி பகர்கிறான். நிச்சயமாக அவர்கள் வெளியேற்றப்பட்டால், இவர்கள் அவர்களுடன் வெளியேற மாட்டார்கள்; அவர்கள் தாக்கப்பட்டால், இவர்கள் அவர்களுக்கு உதவ மாட்டார்கள். ஒருவேளை இவர்கள் அவர்களுக்கு உதவினாலும், இவர்கள் புறமுதுகு காட்டி ஓடிவிடுவார்கள்; பின்னர் அவர்களுக்கு எவ்வித உதவியும் கிடைக்காது.) (59:11-12).\n\r\n\n\r\n﴾إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴿\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் நீங்கள் செய்பவற்றை நன்கறிந்தவன்.) அதாவது, உங்களது அந்தரங்கத்தையும் பகிரங்கத்தையும் அறிந்தவன்; அதற்கேற்ப அவன் உங்களுக்குக் கூலி வழங்குவான்.\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾قُلْ أَطِيعُواْ اللَّهَ وَأَطِيعُواْ الرَّسُولَ﴿\n\r\n\n\r\n(\"அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள்; இன்னும் இத்தூதருக்கும் (ஸல்) கீழ்ப்படியுங்கள்\" என்று கூறுவீராக.) அதாவது, அல்லாஹ்வின் வேதத்தையும் அவனது தூதரின் (ஸல்) சுன்னாவையும் பின்பற்றுங்கள்.\n\r\n\n\r\n﴾فَإِن تَوَلَّوْاْ﴿\n\r\n\n\r\n(ஆனால் நீங்கள் புறக்கணித்தால்,) அதாவது அவர்கள் உங்களுக்குக் கொண்டு வந்ததை நீங்கள் புறக்கணித்தால்,\n\r\n\n\r\n﴾فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ﴿\n\r\n\n\r\n(நிச்சயமாக அவர்கள் (ஸல்) மீது சுமத்தப்பட்ட கடமைக்கு மட்டுமே அவர்கள் (ஸல்) பொறுப்பாவார்கள்.) அதாவது, தூதுச்செய்தியை எத்திவைப்பதும், அமானிதத்தை (ஒப்படைக்கப்பட்ட பொறுப்பை) நிறைவேற்றுவதுமே அவர்களது கடமையாகும்.\n\r\n\n\r\n﴾وَعَلَيْكُمْ مَّا حُمِّلْتُمْ﴿\n\r\n\n\r\n(உங்கள் மீது சுமத்தப்பட்ட கடமைக்கு நீங்களே பொறுப்பாவீர்கள்.) அதாவது, அத்தூதுச் செய்தியை ஏற்றுக்கொள்வதும், அதை மேன்மைப்படுத்துவதும், கட்டளையிடப்பட்டபடி செயல்படுவதும் உங்கள் மீதான கடமையாகும்.\n\r\n\n\r\n﴾وَإِن تُطِيعُوهُ تَهْتَدُواْ﴿\n\r\n\n\r\n(நீங்கள் அவர்களுக்கு (ஸல்) கீழ்ப்படிந்தால், நீங்கள் நேர்வழி பெறுவீர்கள்.) ஏனெனில், அவர்கள் (ஸல்) நேரான பாதையின் பக்கமே அழைக்கிறார்கள்.\n\r\n\n\r\n﴾صِرَطِ اللَّهِ الَّذِى لَهُ مَا فِى السَّمَـوَتِ وَمَا فِى الاٌّرْضِ﴿\n\r\n\n\r\n(வானங்களில் உள்ளவையும் பூமியில் உள்ளவையும் யாருக்குச் சொந்தமானவையோ அந்த அல்லாஹ்வின் பாதை இதுவாகும்.) (42:53).\n\r\n\n\r\n﴾وَمَا عَلَى الرَّسُولِ إِلاَّ الْبَلَـغُ الْمُبِينُ﴿\n\r\n\n\r\n(தெளிவாக எத்திவைப்பதைத் தவிர இத்தூதர் (ஸல்) மீது வேறு கடமை இல்லை.) இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\n﴾فَإِنَّمَا عَلَيْكَ الْبَلَـغُ وَعَلَيْنَا الْحِسَابُ﴿\n\r\n\n\r\n((நபியே!) எத்திவைப்பது மட்டுமே உமது கடமை; கணக்குக் கேட்பது நம்மிடமே உள்ளது.) (13:40).\n\r\n\n\r\n﴾فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ - لَّسْتَ عَلَيْهِم بِمُسَيْطِرٍ ﴿\n\r\n\n\r\n(எனவே நீர் நினைவூட்டுவீராக! நீர் நினைவூட்டுபவர் மட்டுமே. நீர் அவர்கள் மீது அதிகாரம் செலுத்துபவர் அல்ல.) (88:21-22)."},"55":{"html":"<strong>விசுவாசிகளுக்குப் பூமியில் பிரதிநிதித்துவத்தை வழங்குவதாக அல்லாஹ் அளித்த வாக்குறுதி</strong><br />\r\n<br />\r\nஇது அல்லாஹ் தனது தூதருக்கு (ஸல்) அளித்த வாக்குறுதியாகும். இதன்படி, அவனது உம்மத்தைப் பூமியில் அவன் பிரதிநிதிகளாக ஆக்குவான்; அதாவது, அவர்கள் மனிதகுலத்தின் தலைவர்களாகவும் ஆட்சியாளர்களாகவும் திகழ்வார்கள். அவர்கள் மூலமாக அல்லாஹ் உலகைச் சீர்திருத்துவான், மக்கள் அவர்களுக்குக் கீழ்ப்படிவார்கள். இதன் மூலம் அவர்களின் அச்சத்திற்குப் பதிலாகப் பாதுகாப்பான நிலையை அவன் வழங்குவான். இதையே அல்லாஹ் உண்மையில் செய்தான். அவன் தூயவன், மிக உயர்ந்தவன். புகழும் அருளும் அவனுக்கே உரியது. மக்கா, கைபர், பஹ்ரைன், ஒட்டுமொத்த அரேபிய தீபகற்பம் மற்றும் யமன் ஆகியவற்றை வெற்றிகொள்ளச் செய்யும் வரை அல்லாஹ் தனது தூதரை (ஸல்) மரணிக்கச் செய்யவில்லை. மேலும், ஹஜர் பகுதியில் வாழ்ந்த ஸொராஸ்டிரியர்களிடமிருந்தும், சிரியாவின் சில எல்லைப் பகுதிகளிலிருந்தும் அவர்கள் (ஸல்) ஜிஸ்யா வரியைப் பெற்றார்கள். பைசாந்திய மன்னர் ஹெராக்ளியஸ், எகிப்து மற்றும் அலெக்ஸாந்திரியாவின் ஆட்சியாளர் முகவ்கிஸ், ஓமன் மன்னர்கள் மற்றும் அபீசீனிய மன்னர் அன்-நஜாஷி ஆகியோருடன் அவர்கள் (ஸல்) அன்பளிப்புகளைப் பரிமாறிக் கொண்டார்கள். அஸ்ஹமா எனும் பெயருடைய அந்த நஜாஷி மீது அல்லாஹ் கருணை பொழிந்து, அவருக்குக் கண்ணியத்தை வழங்குவானாக.<br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணித்த பிறகு, அவர்களுடைய வாரிசான (கலீஃபா) அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் ஆட்சிப் பொறுப்பை ஏற்று, உம்மத்தைப் பிளவுபடாமல் தடுத்து ஒன்றிணைத்தார்கள். அவர்கள் முழு அரேபிய தீபகற்பத்தையும் தங்கள் கட்டுப்பாட்டிற்குள் கொண்டு வந்தார்கள். மேலும், காலித் பின் அல்-வலீத் (ரழி) அவர்களின் தலைமையில் இஸ்லாமியப் படைகளைப் பாரசீகத்திற்கு அனுப்பினார்கள். அவர் பாரசீகத்தின் ஒரு பகுதியைக் கைப்பற்றி, அங்கு எதிர்ப்பாளர்களை முறியடித்தார். அவர்கள் அபூ உபைதா (ரழி) அவர்களின் தலைமையின் கீழும், அவருக்குப் பின் வந்த தளபதிகளின் தலைமையிலும் சிரியாவிற்குப் படைகளை அனுப்பினார்கள். மேலும், அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்களின் தலைமையில் மூன்றாவது படையை எகிப்திற்கு அனுப்பினார்கள். சிரியாவிற்கு அனுப்பப்பட்ட படை புஸ்ரா, டமாஸ்கஸ் மற்றும் அதன் மாகாணங்களான ஹவ்ரான் போன்ற சுற்றுப்புறப் பகுதிகளைக் கைப்பற்ற அல்லாஹ் வழிவகை செய்தான். பின்னர், அபூபக்ர் (ரழி) அவர்களைத் தன்னிடம் அழைத்து கண்ணியப்படுத்த அல்லாஹ் நாடினான், அவ்வாறே அவர்கள் மரணித்தார்கள். அஸ்-ஸித்தீக் (ரழி) அவர்கள் தமக்கு அடுத்து உமர் அல்-ஃபாரூக் (ரழி) அவர்களை வாரிசாக நியமிக்கத் தூண்டப்பட்டது இஸ்லாமிய மக்களுக்குக் கிடைத்த நற்பேறாகும். எனவே, அவர்களுக்குப் பிறகு ஆட்சிப் பொறுப்பை ஏற்ற உமர் (ரழி) அவர்கள் அதை மிகச் சிறப்பாகச் செய்தார்கள். நபிமார்களுக்குப் பிறகு, சிறந்த நடத்தை மற்றும் பூரண நீதியில் உமர் (ரழி) அவர்களைப் போன்ற ஒருவரை உலகம் கண்டதில்லை.<br />\r\n<br />\r\nஉமர் (ரழி) அவர்களின் காலத்தில், சிரியா மற்றும் எகிப்தின் எஞ்சிய பகுதிகளும், பாரசீகத்தின் பெரும்பகுதியும் கைப்பற்றப்பட்டன. கிஸ்ரா தோற்கடிக்கப்பட்டு, முற்றிலும் அவமானப்படுத்தப்பட்டான். அவன் தனது பேரரசின் தொலைதூரப் பகுதிக்குத் தப்பியோடினான். வலிமைமிக்க சீசர் வீழ்த்தப்பட்டான், சிரியாவின் மீதான அவனது ஆட்சி முடிவுக்கு வந்தது, அவன் கான்ஸ்டான்டினோப்பிளுக்குப் பின்வாங்கினான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் முன்னறிவிப்புச் செய்து வாக்குறுதி அளித்தபடியே, அவர்களின் செல்வம் அல்லாஹ்வின் பாதையில் செலவிடப்பட்டது. அண்ணல் நபி (ஸல்) அவர்கள் மீது அல்லாஹ்வின் முழுமையான சாந்தியும், தூய்மையான அருளும் உண்டாவதாக.<br />\r\n<br />\r\nஉத்மான் (ரழி) அவர்களின் ஆட்சியின் போது, இஸ்லாமியப் பேரரசு பூமியின் கிழக்கு மற்றும் மேற்கு மூலைகளுக்குப் பரவியது. மேற்கில் சைப்ரஸ், அண்டலூசியா, கைரௌவான் மற்றும் அட்லாண்டிக் பெருங்கடலை ஒட்டியுள்ள செப்டா வரை நாடுகள் கைப்பற்றப்பட்டன. கிழக்குப் பகுதியில், வெற்றிகள் சீனா வரை நீடித்தன. கிஸ்ரா கொல்லப்பட்டான், அவனது ராஜ்ஜியம் முற்றிலுமாக அழிக்கப்பட்டது. ஈராக், குராசான் மற்றும் அல்-அஹ்வாஸ் நகரங்கள் கைப்பற்றப்பட்டன. முஸ்லிம்கள் பெருமளவிலான துருக்கியர்களை வீழ்த்தினர், அல்லாஹ் அவர்களின் பெரும் மன்னனான காகானை அவமானப்படுத்தினான். கிழக்கிலிருந்தும் மேற்கிலிருந்தும் வரிகள் வசூலிக்கப்பட்டு, விசுவாசிகளின் தலைவர் உத்மான் பின் அஃப்பான் (ரழி) அவர்களிடம் கொண்டு வரப்பட்டன. இது, அவர்கள் குர்ஆனை ஓதி, அதைப் படித்து, அதைப் பாதுகாப்பதற்காகவும் பேணுவதற்காகவும் உம்மத்தை ஒன்றிணைத்ததன் மூலம் கிடைத்த ஒரு பாக்கியமாகும். ஸஹீஹ் நூலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">زَوَى</span> <span class=\"quran-arabic-font text-success\">لِيَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">فَرَأَيْتُ</span> <span class=\"quran-arabic-font text-success\">مَشَارِقَهَا</span> <span class=\"quran-arabic-font text-success\">وَمَغَارِبَهَا،</span> <span class=\"quran-arabic-font text-success\">وَسَيَبْلُغُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">زُوِيَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span>»<br />\r\n<br />\r\n(அல்லாஹ் எனக்குப் பூமியைச் சுருக்கிக் காட்டினான், நான் அதன் கிழக்கையும் மேற்கையும் பார்த்தேன். எனக்குச் சுருக்கிக் காட்டப்பட்ட எல்லா இடங்களுக்கும் எனது உம்மத்தின் ஆட்சி சென்றடையும்.) அல்லாஹ்வும் அவனது தூதரும் (ஸல்) எங்களுக்கு வாக்குறுதி அளித்ததை இப்போது நாங்கள் அனுபவித்து வருகிறோம், ஏனெனில் அல்லாஹ்வும் அவனது தூதரும் உண்மையே கூறினார்கள். அல்லாஹ்வையும் அவனது தூதரையும் முழுமையாக விசுவாசிக்கவும், அவனது திருப்தியைப் பெற்றுத்தரும் விதத்தில் அவனுக்கு நன்றி செலுத்தவும் எங்களுக்கு உதவ அல்லாஹ்விடம் நாங்கள் பிரார்த்திக்கிறோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَدَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّـلِحَاتِ</span> <span class=\"quran-arabic-font text-success\">لَيَسْتَخْلِفَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَخْلَفَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلَيُمَكِّنَنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">دِينَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ارْتَضَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَيُبَدِّلَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">مّن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">خَوْفِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَمْناً</span><br />\r\n<br />\r\n(உங்களில் விசுவாசம் கொண்டு, நற்செயல்களைச் செய்பவர்களுக்கு அல்லாஹ் வாக்குறுதி அளித்துள்ளான்: நிச்சயமாக அவர்களுக்கு முன்னிருந்தவர்களுக்குப் பூமியில் பிரதிநிதித்துவத்தை வழங்கியதைப் போலவே, அவர்களுக்கும் வழங்குவான்; மேலும் அவர்களுக்காக அவன் பொருந்திக் கொண்ட மார்க்கத்தில் நிலைபெற அவர்களுக்கு அதிகாரம் வழங்குவான்; அவர்களுடைய அச்சத்திற்குப் பிறகு நிச்சயமாக அவர்களுக்குப் பாதுகாப்பான நிலையை மாற்றிக் கொடுப்பான்...)<br />\r\n<br />\r\nஅர்-ரபீஃ பின் அனஸ் அறிவிக்கிறார்: அபுல் ஆலியா கூறினார்கள், \"நபி (ஸல்) அவர்களும் அவர்களுடைய தோழர்களும் மக்காவில் ஏறக்குறைய பத்து ஆண்டுகள் இருந்தார்கள்; இணையற்ற அல்லாஹ்வை மட்டுமே வணங்கும்படி இரகசியமாக மக்களை அழைத்தார்கள். அவர்கள் அச்ச நிலையிலேயே இருந்தார்கள். மதீனாவிற்கு ஹிஜ்ரத் செய்யக் கட்டளையிடப்படும் வரை போரிட அவர்களுக்கு அனுமதி அளிக்கப்படவில்லை. அவர்கள் மதீனாவிற்கு வந்தபோது, அல்லாஹ் அவர்களுக்குப் போரிடுமாறு கட்டளையிட்டான். மதீனாவிலும் அவர்கள் அச்சத்திலேயே இருந்தனர், காலையிலும் மாலையிலும் தங்கள் ஆயுதங்களை ஏந்தியவாறே இருந்தனர். அல்லாஹ் நாடிய காலம் வரை அவர்கள் இவ்வாறே நீடித்தனர்...\" பின்னர் அல்லாஹ் இந்த வசனத்தை இறக்கினான். அவன் தனது நபியை (ஸல்) அரேபிய தீபகற்பத்தில் வெற்றிபெறச் செய்தான்; பின்னர் அவர்கள் பாதுகாப்பை உணர்ந்து தங்கள் ஆயுதங்களைக் கீழே வைத்தார்கள். பிறகு அல்லாஹ் தனது நபியைத் (ஸல்) தன்னிடம் அழைத்துக்கொண்டான். அபூபக்ர் (ரழி), உமர் (ரழி) மற்றும் உத்மான் (ரழி) ஆகியோரின் காலம் முழுவதும் அவர்கள் பாதுகாப்பாக இருந்தார்கள். பிறகு நடக்க வேண்டிய பிணக்குகள் நடந்தபோது, மீண்டும் அச்சம் நிலவியது. எனவே அவர்கள் காவல் படையையும் காவலர்களையும் நியமித்தார்கள். அவர்கள் தங்களை மாற்றிக் கொண்டபோது, அவர்களின் நிலையும் மாறியது.<br />\r\n<br />\r\nமுன்னோர்களில் (ஸலஃப்) ஒருவர் கூறினார்: \"அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரின் கிலாஃபத் உண்மையானது, அது அல்லாஹ்வின் வேதத்தைப் பின்பற்றியே அமைந்திருந்தது.\" பின்னர் அவர் இந்த வசனத்தை ஓதிக் காட்டினார். அல்-பராஃ பின் ஆஸிப் (ரழி) கூறினார்கள்: \"நாங்கள் கடும் அச்ச நிலையில் இருந்தபோது இந்த வசனம் இறக்கப்பட்டது.\" இந்த வசனம் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاذْكُرُواْ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَضْعَفُونَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(நீங்கள் பூமியில் சிலராகவும், பலவீனமானவர்களாகவும் கருதப்பட்ட நேரத்தை நினைவுகூருங்கள்.) (அல்குர்ஆன் <a href=\"qurandisp.php?sura=8&ayah=26\" class=\"link\">8:26</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَشْكُرُونَ</span><br />\r\n<br />\r\n(அதனால் நீங்கள் நன்றி செலுத்துவீர்கள்.) (அல்குர்ஆன் <a href=\"qurandisp.php?sura=8&ayah=26\" class=\"link\">8:26</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَخْلَفَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ</span><br />\r\n<br />\r\n(அவர்களுக்கு முன்னிருந்தவர்களுக்கு அவன் பிரதிநிதித்துவத்தை வழங்கியதைப் போல,)<br />\r\n<br />\r\nஇது மூஸா (அலை) அவர்கள் தனது மக்களிடம் கூறியதாக அல்லாஹ் குறிப்பிடும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَسَى</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُهْلِكَ</span> <span class=\"quran-arabic-font text-success\">عَدُوَّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَيَسْتَخْلِفَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(\"உங்கள் இறைவன் உங்கள் எதிரியை அழித்து, உங்களைப் பூமியில் பிரதிநிதிகளாக ஆக்கக்கூடும்...\") (அல்குர்ஆன் <a href=\"qurandisp.php?sura=7&ayah=129\" class=\"link\">7:129</a>).<br />\r\n<br />\r\nமேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّمُنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتُضْعِفُواْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(மேலும், பூமியில் பலவீனப்படுத்தப்பட்டவர்களுக்கு அருள் புரிய நாம் விரும்பினோம்.) அதற்கடுத்த இரண்டு வசனங்கள் வரை. (அல்குர்ஆன் <a href=\"qurandisp.php?sura=28&ayah=5\" class=\"link\">28:5</a>-6).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَيُمَكِّنَنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">دِينَهُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ارْتَضَى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(மேலும், அவர்களுக்காக அவன் பொருந்திக் கொண்ட மார்க்கத்தில் நிலைபெற அவர்களுக்கு அதிகாரம் வழங்குவான்...)<br />\r\n<br />\r\nஅதிய் பின் ஹாதிம் (ரழி) அவர்கள் ஒரு தூதுக்குழுவாக அல்லாஹ்வின் தூதரிடம் (ஸல்) வந்தபோது, நபியவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَتَعْرِفُ</span> <span class=\"quran-arabic-font text-success\">الْحِيرَةَ؟</span>»<br />\r\n<br />\r\n(உனக்கு அல்-ஹீராவைத் தெரியுமா?)<br />\r\n<br />\r\nஅதற்கு அவர், \"எனக்கு அதைத் தெரியாது, ஆனால் அதைக் கேள்விப்பட்டிருக்கிறேன்\" என்றார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَوَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَيُتِمَّنَّ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْأَمْرَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَخْرُجَ</span> <span class=\"quran-arabic-font text-success\">الظَّعِينَةُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحِيرَةِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَطُوفَ</span> <span class=\"quran-arabic-font text-success\">بِالْبَيْتِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">غَيْرِ</span> <span class=\"quran-arabic-font text-success\">جِوَارِ</span> <span class=\"quran-arabic-font text-success\">أَحَدٍ،</span> <span class=\"quran-arabic-font text-success\">وَلَتَفْتَحُنَّ</span> <span class=\"quran-arabic-font text-success\">كُنُوزَ</span> <span class=\"quran-arabic-font text-success\">كِسْرَى</span> <span class=\"quran-arabic-font text-success\">بْنِ</span> <span class=\"quran-arabic-font text-success\">هُرْمُزَ</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, அல்லாஹ் இந்த இஸ்லாமிய மார்க்கத்தைப் பூரணப்படுத்துவான். எந்தவொரு பாதுகாப்பும் தேவையின்றி, ஒட்டகத்தில் பயணிக்கும் ஒரு பெண் அல்-ஹீராவிலிருந்து வந்து கஃபாவை தவாஃப் செய்வாள். மேலும், கிஸ்ரா பின் ஹுர்முஸின் புதையல்கள் வெற்றிகொள்ளப்படும்.)<br />\r\n<br />\r\nஅவர், \"கிஸ்ரா பின் ஹுர்முஸின் புதையல்களா?\" என்று கேட்டார். அதற்கு நபியவர்கள்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">نَعَمْ،</span> <span class=\"quran-arabic-font text-success\">كِسْرَى</span> <span class=\"quran-arabic-font text-success\">بْنُ</span> <span class=\"quran-arabic-font text-success\">هُرْمُزَ،</span> <span class=\"quran-arabic-font text-success\">وَلَيُبْذَلَنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَالُ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَقْبَلَهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span>»<br />\r\n<br />\r\n(ஆம், கிஸ்ரா பின் ஹுர்முஸ்தான். மேலும், செல்வம் மிக அதிகமாக வழங்கப்பட்டு, அதை ஏற்றுக்கொள்பவர் எவரும் இருக்கமாட்டார்கள்.) என்றார்கள்.<br />\r\n<br />\r\nஅதிய் பின் ஹாதிம் (ரழி) கூறினார்கள்: \"ஒட்டகத்தில் பயணிக்கும் ஒரு பெண் அல்-ஹீராவிலிருந்து வந்து எந்தப் பாதுகாப்பும் இன்றி கஃபாவைத் தவாஃப் செய்வது இப்போது நடந்துகொண்டிருக்கிறது. மேலும், கிஸ்ரா பின் ஹுர்முஸின் புதையலை வெற்றிகொண்டவர்களில் நானும் ஒருவனாக இருந்தேன். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, மூன்றாவது விஷயமும் நிச்சயமாக நடக்கும், ஏனெனில் அதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியிருக்கிறார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَعْبُدُونَنِي</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُونَ</span> <span class=\"quran-arabic-font text-success\">بِى</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span><br />\r\n<br />\r\n(அவர்கள் என்னையே வணங்குவார்கள், எனக்கு எதையும் இணையாக்க மாட்டார்கள்.)<br />\r\n<br />\r\nஇமாம் அஹ்மத் பதிவு செய்கிறார்: அனஸ் (ரழி) மூலம் முஆத் பின் ஜபல் (ரழி) அவர்கள் அறிவிக்கிறார்கள், \"நான் நபி (ஸல்) அவர்களுக்குப் பின்னால் ஒரு கழுதையில் சவாரி செய்துகொண்டிருந்தேன். எனக்கும் அவர்களுக்குமிடையில் அந்தச் சேணத்தின் பின்பகுதியைத் தவிர வேறெதுவும் இல்லை. அப்போது அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُعَاذُ</span> <span class=\"quran-arabic-font text-success\">بْنَ</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span>»<br />\r\n<br />\r\n(முஆத் பின் ஜபலே!)<br />\r\n<br />\r\nஅதற்கு நான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். சிறிது நேரம் கழித்து மீண்டும்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُعَاذُ</span> <span class=\"quran-arabic-font text-success\">بْنَ</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span>»<br />\r\n<br />\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.<br />\r\n<br />\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். மீண்டும் சிறிது நேரம் கழித்து,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُعَاذُ</span> <span class=\"quran-arabic-font text-success\">بْنَ</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span>»<br />\r\n<br />\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.<br />\r\n<br />\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். அப்போது அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">تَدْرِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حَقُّ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ؟</span>»<br />\r\n<br />\r\n(அடியார்கள் மீது அல்லாஹ்வுக்குள்ள உரிமை என்னவென்று உனக்குத் தெரியுமா?)<br />\r\n<br />\r\nநான், 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றேன். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُوهُ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُشْرِكُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span>»<br />\r\n<br />\r\n(அடியார்கள் அல்லாஹ்வை மட்டுமே வணங்குவதும், அவனுக்கு எதையும் இணையாக்காமல் இருப்பதுமே அல்லாஹ்வுக்கு அவர்கள் மீதுள்ள உரிமையாகும்.)<br />\r\n<br />\r\nசிறிது நேரம் கழித்து மீண்டும்,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُعَاذُ</span> <span class=\"quran-arabic-font text-success\">بْنَ</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span>»<br />\r\n<br />\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.<br />\r\n<br />\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَهَلْ</span> <span class=\"quran-arabic-font text-success\">تَدْرِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حَقُّ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">فَعَلُوا</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ؟</span>»<br />\r\n<br />\r\n(அவர்கள் அவ்வாறு செய்தால், அடியார்களுக்கு அல்லாஹ்விடம் உள்ள உரிமை என்னவென்று உனக்குத் தெரியுமா?)<br />\r\n<br />\r\nநான், 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றேன். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُعَذِّبَهُمْ</span>»<br />\r\n<br />\r\n(அடியார்களுக்கு அல்லாஹ்விடம் உள்ள உரிமை, அவர்களை அவன் தண்டிக்காமல் இருப்பதேயாகும்.)\"<br />\r\n<br />\r\nஇந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">كَفَرَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَـسِقُونَ</span><br />\r\n<br />\r\n(இதற்குப் பிறகும் எவர் நிராகரிக்கிறாரோ, அவர்களே பாவியாவார்கள்.)<br />\r\n<br />\r\nஇதன் பொருள்: \"இதற்குப் பிறகும் யாரேனும் எனக்குக் கீழ்ப்படிவதை விடுத்து மாறுசெய்தால், அவர் தனது இறைவனின் கட்டளையை மீறியவராவார்; அது மிகப்பெரிய பாவமாகும்.\"<br />\r\n<br />\r\nநபித்தோழர்கள் (ரழி), நபி (ஸல்) அவர்களுக்குப் பிறகு அல்லாஹ்வின் கட்டளைகளைப் பின்பற்றுவதில் மிகவும் அர்ப்பணிப்புடனும், கீழ்ப்படிதலுடனும் இருந்தனர். அவர்களின் அர்ப்பணிப்பிற்கு ஏற்பவே அவர்களுக்கு வெற்றியும் கிடைத்தது. அவர்கள் கிழக்கிலும் மேற்கிலும் அல்லாஹ்வின் கலிமாவை மேலோங்கச் செய்தார்கள். அல்லாஹ் அவர்களுக்குப் பேரளவு உதவியதால், அவர்கள் பல நாடுகளையும் மக்களையும் ஆட்சி செய்தனர். பிற்காலத்தில் மக்கள் சில கட்டளைகளைப் பேணுவதில் குறை செய்தபோது, அதற்கேற்ப அவர்களின் வலிமையும் வெற்றியும் குறைந்தது. இருப்பினும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக ஒன்றுக்கு மேற்பட்ட அறிவிப்புகள் புகாரி மற்றும் முஸ்லிம் நூல்களில் இடம்பெற்றுள்ளன:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَزَالُ</span> <span class=\"quran-arabic-font text-success\">طَائِفَةٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أُمَّتِي</span> <span class=\"quran-arabic-font text-success\">ظَاهِرِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَضُرُّهُمْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">خَذَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">خَالَفَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span>»<br />\r\n<br />\r\n(எனது உம்மத்தில் ஒரு குழுவினர் மறுமை நாள் வரை சத்தியத்தின் மீது நிலைத்திருப்பார்கள். அவர்களைக் கைவிடுபவர்களோ அல்லது அவர்களுக்கு மாறு செய்பவர்களோ அவர்களுக்கு எந்தத் தீங்கும் இழைக்க முடியாது.)<br />\r\n<br />\r\nமற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَ</span> <span class=\"quran-arabic-font text-success\">أَمْرُ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span>»<br />\r\n<br />\r\n(...அல்லாஹ்வின் கட்டளை வரும் வரை அவர்கள் அப்படியே இருப்பார்கள்.)<br />\r\n<br />\r\nமற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُقَاتِلُوا</span> <span class=\"quran-arabic-font text-success\">الدَّجَّالَ</span>»<br />\r\n<br />\r\n(...அவர்கள் தஜ்ஜாலுடன் போர் புரியும் வரை.)<br />\r\n<br />\r\nமற்றொரு அறிவிப்பில்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَنْزِلَ</span> <span class=\"quran-arabic-font text-success\">عِيسَى</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">ظَاهِرُونَ</span>»<br />\r\n<br />\r\n(...ஈஸா பின் மர்யம் (அலை) அவர்கள் இறங்கி வரும்போது அவர்கள் மேலோங்கிய நிலையில் இருப்பார்கள்.)<br />\r\n<br />\r\nஇந்த அறிவிப்புகள் அனைத்தும் ஸஹீஹானவை, அவற்றுக்கிடையே எந்த முரண்பாடும் இல்லை.<br />\r\n<br />\r\n<br />\r\n<br />","text":"விசுவாசிகளுக்குப் பூமியில் பிரதிநிதித்துவத்தை வழங்குவதாக அல்லாஹ் அளித்த வாக்குறுதி\n\r\n\n\r\nஇது அல்லாஹ் தனது தூதருக்கு (ஸல்) அளித்த வாக்குறுதியாகும். இதன்படி, அவனது உம்மத்தைப் பூமியில் அவன் பிரதிநிதிகளாக ஆக்குவான்; அதாவது, அவர்கள் மனிதகுலத்தின் தலைவர்களாகவும் ஆட்சியாளர்களாகவும் திகழ்வார்கள். அவர்கள் மூலமாக அல்லாஹ் உலகைச் சீர்திருத்துவான், மக்கள் அவர்களுக்குக் கீழ்ப்படிவார்கள். இதன் மூலம் அவர்களின் அச்சத்திற்குப் பதிலாகப் பாதுகாப்பான நிலையை அவன் வழங்குவான். இதையே அல்லாஹ் உண்மையில் செய்தான். அவன் தூயவன், மிக உயர்ந்தவன். புகழும் அருளும் அவனுக்கே உரியது. மக்கா, கைபர், பஹ்ரைன், ஒட்டுமொத்த அரேபிய தீபகற்பம் மற்றும் யமன் ஆகியவற்றை வெற்றிகொள்ளச் செய்யும் வரை அல்லாஹ் தனது தூதரை (ஸல்) மரணிக்கச் செய்யவில்லை. மேலும், ஹஜர் பகுதியில் வாழ்ந்த ஸொராஸ்டிரியர்களிடமிருந்தும், சிரியாவின் சில எல்லைப் பகுதிகளிலிருந்தும் அவர்கள் (ஸல்) ஜிஸ்யா வரியைப் பெற்றார்கள். பைசாந்திய மன்னர் ஹெராக்ளியஸ், எகிப்து மற்றும் அலெக்ஸாந்திரியாவின் ஆட்சியாளர் முகவ்கிஸ், ஓமன் மன்னர்கள் மற்றும் அபீசீனிய மன்னர் அன்-நஜாஷி ஆகியோருடன் அவர்கள் (ஸல்) அன்பளிப்புகளைப் பரிமாறிக் கொண்டார்கள். அஸ்ஹமா எனும் பெயருடைய அந்த நஜாஷி மீது அல்லாஹ் கருணை பொழிந்து, அவருக்குக் கண்ணியத்தை வழங்குவானாக.\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மரணித்த பிறகு, அவர்களுடைய வாரிசான (கலீஃபா) அபூபக்ர் அஸ்-ஸித்தீக் (ரழி) அவர்கள் ஆட்சிப் பொறுப்பை ஏற்று, உம்மத்தைப் பிளவுபடாமல் தடுத்து ஒன்றிணைத்தார்கள். அவர்கள் முழு அரேபிய தீபகற்பத்தையும் தங்கள் கட்டுப்பாட்டிற்குள் கொண்டு வந்தார்கள். மேலும், காலித் பின் அல்-வலீத் (ரழி) அவர்களின் தலைமையில் இஸ்லாமியப் படைகளைப் பாரசீகத்திற்கு அனுப்பினார்கள். அவர் பாரசீகத்தின் ஒரு பகுதியைக் கைப்பற்றி, அங்கு எதிர்ப்பாளர்களை முறியடித்தார். அவர்கள் அபூ உபைதா (ரழி) அவர்களின் தலைமையின் கீழும், அவருக்குப் பின் வந்த தளபதிகளின் தலைமையிலும் சிரியாவிற்குப் படைகளை அனுப்பினார்கள். மேலும், அம்ர் பின் அல்-ஆஸ் (ரழி) அவர்களின் தலைமையில் மூன்றாவது படையை எகிப்திற்கு அனுப்பினார்கள். சிரியாவிற்கு அனுப்பப்பட்ட படை புஸ்ரா, டமாஸ்கஸ் மற்றும் அதன் மாகாணங்களான ஹவ்ரான் போன்ற சுற்றுப்புறப் பகுதிகளைக் கைப்பற்ற அல்லாஹ் வழிவகை செய்தான். பின்னர், அபூபக்ர் (ரழி) அவர்களைத் தன்னிடம் அழைத்து கண்ணியப்படுத்த அல்லாஹ் நாடினான், அவ்வாறே அவர்கள் மரணித்தார்கள். அஸ்-ஸித்தீக் (ரழி) அவர்கள் தமக்கு அடுத்து உமர் அல்-ஃபாரூக் (ரழி) அவர்களை வாரிசாக நியமிக்கத் தூண்டப்பட்டது இஸ்லாமிய மக்களுக்குக் கிடைத்த நற்பேறாகும். எனவே, அவர்களுக்குப் பிறகு ஆட்சிப் பொறுப்பை ஏற்ற உமர் (ரழி) அவர்கள் அதை மிகச் சிறப்பாகச் செய்தார்கள். நபிமார்களுக்குப் பிறகு, சிறந்த நடத்தை மற்றும் பூரண நீதியில் உமர் (ரழி) அவர்களைப் போன்ற ஒருவரை உலகம் கண்டதில்லை.\n\r\n\n\r\nஉமர் (ரழி) அவர்களின் காலத்தில், சிரியா மற்றும் எகிப்தின் எஞ்சிய பகுதிகளும், பாரசீகத்தின் பெரும்பகுதியும் கைப்பற்றப்பட்டன. கிஸ்ரா தோற்கடிக்கப்பட்டு, முற்றிலும் அவமானப்படுத்தப்பட்டான். அவன் தனது பேரரசின் தொலைதூரப் பகுதிக்குத் தப்பியோடினான். வலிமைமிக்க சீசர் வீழ்த்தப்பட்டான், சிரியாவின் மீதான அவனது ஆட்சி முடிவுக்கு வந்தது, அவன் கான்ஸ்டான்டினோப்பிளுக்குப் பின்வாங்கினான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் முன்னறிவிப்புச் செய்து வாக்குறுதி அளித்தபடியே, அவர்களின் செல்வம் அல்லாஹ்வின் பாதையில் செலவிடப்பட்டது. அண்ணல் நபி (ஸல்) அவர்கள் மீது அல்லாஹ்வின் முழுமையான சாந்தியும், தூய்மையான அருளும் உண்டாவதாக.\n\r\n\n\r\nஉத்மான் (ரழி) அவர்களின் ஆட்சியின் போது, இஸ்லாமியப் பேரரசு பூமியின் கிழக்கு மற்றும் மேற்கு மூலைகளுக்குப் பரவியது. மேற்கில் சைப்ரஸ், அண்டலூசியா, கைரௌவான் மற்றும் அட்லாண்டிக் பெருங்கடலை ஒட்டியுள்ள செப்டா வரை நாடுகள் கைப்பற்றப்பட்டன. கிழக்குப் பகுதியில், வெற்றிகள் சீனா வரை நீடித்தன. கிஸ்ரா கொல்லப்பட்டான், அவனது ராஜ்ஜியம் முற்றிலுமாக அழிக்கப்பட்டது. ஈராக், குராசான் மற்றும் அல்-அஹ்வாஸ் நகரங்கள் கைப்பற்றப்பட்டன. முஸ்லிம்கள் பெருமளவிலான துருக்கியர்களை வீழ்த்தினர், அல்லாஹ் அவர்களின் பெரும் மன்னனான காகானை அவமானப்படுத்தினான். கிழக்கிலிருந்தும் மேற்கிலிருந்தும் வரிகள் வசூலிக்கப்பட்டு, விசுவாசிகளின் தலைவர் உத்மான் பின் அஃப்பான் (ரழி) அவர்களிடம் கொண்டு வரப்பட்டன. இது, அவர்கள் குர்ஆனை ஓதி, அதைப் படித்து, அதைப் பாதுகாப்பதற்காகவும் பேணுவதற்காகவும் உம்மத்தை ஒன்றிணைத்ததன் மூலம் கிடைத்த ஒரு பாக்கியமாகும். ஸஹீஹ் நூலில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் பின்வருமாறு கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«إِنَّ اللهَ زَوَى لِيَ الْأَرْضَ فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا، وَسَيَبْلُغُ مُلْكُ أُمَّتِي مَا زُوِيَ لِي مِنْهَا»\n\r\n\n\r\n(அல்லாஹ் எனக்குப் பூமியைச் சுருக்கிக் காட்டினான், நான் அதன் கிழக்கையும் மேற்கையும் பார்த்தேன். எனக்குச் சுருக்கிக் காட்டப்பட்ட எல்லா இடங்களுக்கும் எனது உம்மத்தின் ஆட்சி சென்றடையும்.) அல்லாஹ்வும் அவனது தூதரும் (ஸல்) எங்களுக்கு வாக்குறுதி அளித்ததை இப்போது நாங்கள் அனுபவித்து வருகிறோம், ஏனெனில் அல்லாஹ்வும் அவனது தூதரும் உண்மையே கூறினார்கள். அல்லாஹ்வையும் அவனது தூதரையும் முழுமையாக விசுவாசிக்கவும், அவனது திருப்தியைப் பெற்றுத்தரும் விதத்தில் அவனுக்கு நன்றி செலுத்தவும் எங்களுக்கு உதவ அல்லாஹ்விடம் நாங்கள் பிரார்த்திக்கிறோம்.\n\r\n\n\r\nوَعَدَ اللَّهُ الَّذِينَ ءامَنُواْ مِنْكُمْ وَعَمِلُواْ الصَّـلِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِى ارْتَضَى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مّن بَعْدِ خَوْفِهِمْ أَمْناً\n\r\n\n\r\n(உங்களில் விசுவாசம் கொண்டு, நற்செயல்களைச் செய்பவர்களுக்கு அல்லாஹ் வாக்குறுதி அளித்துள்ளான்: நிச்சயமாக அவர்களுக்கு முன்னிருந்தவர்களுக்குப் பூமியில் பிரதிநிதித்துவத்தை வழங்கியதைப் போலவே, அவர்களுக்கும் வழங்குவான்; மேலும் அவர்களுக்காக அவன் பொருந்திக் கொண்ட மார்க்கத்தில் நிலைபெற அவர்களுக்கு அதிகாரம் வழங்குவான்; அவர்களுடைய அச்சத்திற்குப் பிறகு நிச்சயமாக அவர்களுக்குப் பாதுகாப்பான நிலையை மாற்றிக் கொடுப்பான்...)\n\r\n\n\r\nஅர்-ரபீஃ பின் அனஸ் அறிவிக்கிறார்: அபுல் ஆலியா கூறினார்கள், \"நபி (ஸல்) அவர்களும் அவர்களுடைய தோழர்களும் மக்காவில் ஏறக்குறைய பத்து ஆண்டுகள் இருந்தார்கள்; இணையற்ற அல்லாஹ்வை மட்டுமே வணங்கும்படி இரகசியமாக மக்களை அழைத்தார்கள். அவர்கள் அச்ச நிலையிலேயே இருந்தார்கள். மதீனாவிற்கு ஹிஜ்ரத் செய்யக் கட்டளையிடப்படும் வரை போரிட அவர்களுக்கு அனுமதி அளிக்கப்படவில்லை. அவர்கள் மதீனாவிற்கு வந்தபோது, அல்லாஹ் அவர்களுக்குப் போரிடுமாறு கட்டளையிட்டான். மதீனாவிலும் அவர்கள் அச்சத்திலேயே இருந்தனர், காலையிலும் மாலையிலும் தங்கள் ஆயுதங்களை ஏந்தியவாறே இருந்தனர். அல்லாஹ் நாடிய காலம் வரை அவர்கள் இவ்வாறே நீடித்தனர்...\" பின்னர் அல்லாஹ் இந்த வசனத்தை இறக்கினான். அவன் தனது நபியை (ஸல்) அரேபிய தீபகற்பத்தில் வெற்றிபெறச் செய்தான்; பின்னர் அவர்கள் பாதுகாப்பை உணர்ந்து தங்கள் ஆயுதங்களைக் கீழே வைத்தார்கள். பிறகு அல்லாஹ் தனது நபியைத் (ஸல்) தன்னிடம் அழைத்துக்கொண்டான். அபூபக்ர் (ரழி), உமர் (ரழி) மற்றும் உத்மான் (ரழி) ஆகியோரின் காலம் முழுவதும் அவர்கள் பாதுகாப்பாக இருந்தார்கள். பிறகு நடக்க வேண்டிய பிணக்குகள் நடந்தபோது, மீண்டும் அச்சம் நிலவியது. எனவே அவர்கள் காவல் படையையும் காவலர்களையும் நியமித்தார்கள். அவர்கள் தங்களை மாற்றிக் கொண்டபோது, அவர்களின் நிலையும் மாறியது.\n\r\n\n\r\nமுன்னோர்களில் (ஸலஃப்) ஒருவர் கூறினார்: \"அபூபக்ர் (ரழி) மற்றும் உமர் (ரழி) ஆகியோரின் கிலாஃபத் உண்மையானது, அது அல்லாஹ்வின் வேதத்தைப் பின்பற்றியே அமைந்திருந்தது.\" பின்னர் அவர் இந்த வசனத்தை ஓதிக் காட்டினார். அல்-பராஃ பின் ஆஸிப் (ரழி) கூறினார்கள்: \"நாங்கள் கடும் அச்ச நிலையில் இருந்தபோது இந்த வசனம் இறக்கப்பட்டது.\" இந்த வசனம் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَاذْكُرُواْ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِي الْأَرْضِ\n\r\n\n\r\n(நீங்கள் பூமியில் சிலராகவும், பலவீனமானவர்களாகவும் கருதப்பட்ட நேரத்தை நினைவுகூருங்கள்.) (அல்குர்ஆன் 8:26)\n\r\n\n\r\nلَعَلَّكُمْ تَشْكُرُونَ\n\r\n\n\r\n(அதனால் நீங்கள் நன்றி செலுத்துவீர்கள்.) (அல்குர்ஆன் 8:26).\n\r\n\n\r\nكَمَا اسْتَخْلَفَ الَّذِينَ مِن قَبْلِهِمْ\n\r\n\n\r\n(அவர்களுக்கு முன்னிருந்தவர்களுக்கு அவன் பிரதிநிதித்துவத்தை வழங்கியதைப் போல,)\n\r\n\n\r\nஇது மூஸா (அலை) அவர்கள் தனது மக்களிடம் கூறியதாக அல்லாஹ் குறிப்பிடும் வசனத்தைப் போன்றது:\n\r\n\n\r\nعَسَى رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِي الْأَرْضِ\n\r\n\n\r\n(\"உங்கள் இறைவன் உங்கள் எதிரியை அழித்து, உங்களைப் பூமியில் பிரதிநிதிகளாக ஆக்கக்கூடும்...\") (அல்குர்ஆன் 7:129).\n\r\n\n\r\nமேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُواْ فِي الْأَرْضِ\n\r\n\n\r\n(மேலும், பூமியில் பலவீனப்படுத்தப்பட்டவர்களுக்கு அருள் புரிய நாம் விரும்பினோம்.) அதற்கடுத்த இரண்டு வசனங்கள் வரை. (அல்குர்ஆன் 28:5-6).\n\r\n\n\r\nوَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِى ارْتَضَى لَهُمْ\n\r\n\n\r\n(மேலும், அவர்களுக்காக அவன் பொருந்திக் கொண்ட மார்க்கத்தில் நிலைபெற அவர்களுக்கு அதிகாரம் வழங்குவான்...)\n\r\n\n\r\nஅதிய் பின் ஹாதிம் (ரழி) அவர்கள் ஒரு தூதுக்குழுவாக அல்லாஹ்வின் தூதரிடம் (ஸல்) வந்தபோது, நபியவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«أَتَعْرِفُ الْحِيرَةَ؟»\n\r\n\n\r\n(உனக்கு அல்-ஹீராவைத் தெரியுமா?)\n\r\n\n\r\nஅதற்கு அவர், \"எனக்கு அதைத் தெரியாது, ஆனால் அதைக் கேள்விப்பட்டிருக்கிறேன்\" என்றார். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَوَالَّذِي نَفْسِي بِيَدِهِ لَيُتِمَّنَّ اللهُ هَذَا الْأَمْرَ حَتَّى تَخْرُجَ الظَّعِينَةُ مِنَ الْحِيرَةِ حَتَّى تَطُوفَ بِالْبَيْتِ فِي غَيْرِ جِوَارِ أَحَدٍ، وَلَتَفْتَحُنَّ كُنُوزَ كِسْرَى بْنِ هُرْمُزَ»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, அல்லாஹ் இந்த இஸ்லாமிய மார்க்கத்தைப் பூரணப்படுத்துவான். எந்தவொரு பாதுகாப்பும் தேவையின்றி, ஒட்டகத்தில் பயணிக்கும் ஒரு பெண் அல்-ஹீராவிலிருந்து வந்து கஃபாவை தவாஃப் செய்வாள். மேலும், கிஸ்ரா பின் ஹுர்முஸின் புதையல்கள் வெற்றிகொள்ளப்படும்.)\n\r\n\n\r\nஅவர், \"கிஸ்ரா பின் ஹுர்முஸின் புதையல்களா?\" என்று கேட்டார். அதற்கு நபியவர்கள்,\n\r\n\n\r\n«نَعَمْ، كِسْرَى بْنُ هُرْمُزَ، وَلَيُبْذَلَنَّ الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ»\n\r\n\n\r\n(ஆம், கிஸ்ரா பின் ஹுர்முஸ்தான். மேலும், செல்வம் மிக அதிகமாக வழங்கப்பட்டு, அதை ஏற்றுக்கொள்பவர் எவரும் இருக்கமாட்டார்கள்.) என்றார்கள்.\n\r\n\n\r\nஅதிய் பின் ஹாதிம் (ரழி) கூறினார்கள்: \"ஒட்டகத்தில் பயணிக்கும் ஒரு பெண் அல்-ஹீராவிலிருந்து வந்து எந்தப் பாதுகாப்பும் இன்றி கஃபாவைத் தவாஃப் செய்வது இப்போது நடந்துகொண்டிருக்கிறது. மேலும், கிஸ்ரா பின் ஹுர்முஸின் புதையலை வெற்றிகொண்டவர்களில் நானும் ஒருவனாக இருந்தேன். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, மூன்றாவது விஷயமும் நிச்சயமாக நடக்கும், ஏனெனில் அதை அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியிருக்கிறார்கள்.\"\n\r\n\n\r\nيَعْبُدُونَنِي لاَ يُشْرِكُونَ بِى شَيْئاً\n\r\n\n\r\n(அவர்கள் என்னையே வணங்குவார்கள், எனக்கு எதையும் இணையாக்க மாட்டார்கள்.)\n\r\n\n\r\nஇமாம் அஹ்மத் பதிவு செய்கிறார்: அனஸ் (ரழி) மூலம் முஆத் பின் ஜபல் (ரழி) அவர்கள் அறிவிக்கிறார்கள், \"நான் நபி (ஸல்) அவர்களுக்குப் பின்னால் ஒரு கழுதையில் சவாரி செய்துகொண்டிருந்தேன். எனக்கும் அவர்களுக்குமிடையில் அந்தச் சேணத்தின் பின்பகுதியைத் தவிர வேறெதுவும் இல்லை. அப்போது அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا مُعَاذُ بْنَ جَبَلٍ»\n\r\n\n\r\n(முஆத் பின் ஜபலே!)\n\r\n\n\r\nஅதற்கு நான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். சிறிது நேரம் கழித்து மீண்டும்,\n\r\n\n\r\n«يَا مُعَاذُ بْنَ جَبَلٍ»\n\r\n\n\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.\n\r\n\n\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். மீண்டும் சிறிது நேரம் கழித்து,\n\r\n\n\r\n«يَا مُعَاذُ بْنَ جَبَلٍ»\n\r\n\n\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.\n\r\n\n\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். அப்போது அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«هَلْ تَدْرِي مَا حَقُّ اللهِ عَلَى الْعِبَادِ؟»\n\r\n\n\r\n(அடியார்கள் மீது அல்லாஹ்வுக்குள்ள உரிமை என்னவென்று உனக்குத் தெரியுமா?)\n\r\n\n\r\nநான், 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றேன். அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَإِنَّ حَقَّ اللهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا»\n\r\n\n\r\n(அடியார்கள் அல்லாஹ்வை மட்டுமே வணங்குவதும், அவனுக்கு எதையும் இணையாக்காமல் இருப்பதுமே அல்லாஹ்வுக்கு அவர்கள் மீதுள்ள உரிமையாகும்.)\n\r\n\n\r\nசிறிது நேரம் கழித்து மீண்டும்,\n\r\n\n\r\n«يَا مُعَاذُ بْنَ جَبَلٍ»\n\r\n\n\r\n(முஆத் பின் ஜபலே!) என்றார்கள்.\n\r\n\n\r\nநான், 'இதோ உங்கள் சேவையில் இருக்கிறேன், அல்லாஹ்வின் தூதரே!' என்றேன். அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«فَهَلْ تَدْرِي مَا حَقُّ الْعِبَادِ عَلَى اللهِ إِذَا فَعَلُوا ذَلِكَ؟»\n\r\n\n\r\n(அவர்கள் அவ்வாறு செய்தால், அடியார்களுக்கு அல்லாஹ்விடம் உள்ள உரிமை என்னவென்று உனக்குத் தெரியுமா?)\n\r\n\n\r\nநான், 'அல்லாஹ்வும் அவனது தூதருமே நன்கறிந்தவர்கள்' என்றேன். அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَإِنَّ حَقَّ الْعِبَادِ عَلَى اللهِ أَنْ لَا يُعَذِّبَهُمْ»\n\r\n\n\r\n(அடியார்களுக்கு அல்லாஹ்விடம் உள்ள உரிமை, அவர்களை அவன் தண்டிக்காமல் இருப்பதேயாகும்.)\"\n\r\n\n\r\nஇந்த ஹதீஸ் புகாரி மற்றும் முஸ்லிம் ஆகிய இரு நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது.\n\r\n\n\r\nوَمَن كَفَرَ بَعْدَ ذلِكَ فَأُوْلَـئِكَ هُمُ الْفَـسِقُونَ\n\r\n\n\r\n(இதற்குப் பிறகும் எவர் நிராகரிக்கிறாரோ, அவர்களே பாவியாவார்கள்.)\n\r\n\n\r\nஇதன் பொருள்: \"இதற்குப் பிறகும் யாரேனும் எனக்குக் கீழ்ப்படிவதை விடுத்து மாறுசெய்தால், அவர் தனது இறைவனின் கட்டளையை மீறியவராவார்; அது மிகப்பெரிய பாவமாகும்.\"\n\r\n\n\r\nநபித்தோழர்கள் (ரழி), நபி (ஸல்) அவர்களுக்குப் பிறகு அல்லாஹ்வின் கட்டளைகளைப் பின்பற்றுவதில் மிகவும் அர்ப்பணிப்புடனும், கீழ்ப்படிதலுடனும் இருந்தனர். அவர்களின் அர்ப்பணிப்பிற்கு ஏற்பவே அவர்களுக்கு வெற்றியும் கிடைத்தது. அவர்கள் கிழக்கிலும் மேற்கிலும் அல்லாஹ்வின் கலிமாவை மேலோங்கச் செய்தார்கள். அல்லாஹ் அவர்களுக்குப் பேரளவு உதவியதால், அவர்கள் பல நாடுகளையும் மக்களையும் ஆட்சி செய்தனர். பிற்காலத்தில் மக்கள் சில கட்டளைகளைப் பேணுவதில் குறை செய்தபோது, அதற்கேற்ப அவர்களின் வலிமையும் வெற்றியும் குறைந்தது. இருப்பினும், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாக ஒன்றுக்கு மேற்பட்ட அறிவிப்புகள் புகாரி மற்றும் முஸ்லிம் நூல்களில் இடம்பெற்றுள்ளன:\n\r\n\n\r\n«لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ وَلَا مَنْ خَالَفَهُمْ إِلَى يَوْمِ الْقِيَامَةِ»\n\r\n\n\r\n(எனது உம்மத்தில் ஒரு குழுவினர் மறுமை நாள் வரை சத்தியத்தின் மீது நிலைத்திருப்பார்கள். அவர்களைக் கைவிடுபவர்களோ அல்லது அவர்களுக்கு மாறு செய்பவர்களோ அவர்களுக்கு எந்தத் தீங்கும் இழைக்க முடியாது.)\n\r\n\n\r\nமற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«حَتَّى يَأْتِيَ أَمْرُ اللهِ وَهُمْ كَذَلِكَ»\n\r\n\n\r\n(...அல்லாஹ்வின் கட்டளை வரும் வரை அவர்கள் அப்படியே இருப்பார்கள்.)\n\r\n\n\r\nமற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«حَتَّى يُقَاتِلُوا الدَّجَّالَ»\n\r\n\n\r\n(...அவர்கள் தஜ்ஜாலுடன் போர் புரியும் வரை.)\n\r\n\n\r\nமற்றொரு அறிவிப்பில்:\n\r\n\n\r\n«حَتَّى يَنْزِلَ عِيسَى ابْنُ مَرْيَمَ وَهُمْ ظَاهِرُونَ»\n\r\n\n\r\n(...ஈஸா பின் மர்யம் (அலை) அவர்கள் இறங்கி வரும்போது அவர்கள் மேலோங்கிய நிலையில் இருப்பார்கள்.)\n\r\n\n\r\nஇந்த அறிவிப்புகள் அனைத்தும் ஸஹீஹானவை, அவற்றுக்கிடையே எந்த முரண்பாடும் இல்லை."},"56":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=57\" class=\"link\">24:57</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:57 ஐ பார்க்கவும்"},"57":{"html":"<strong>தொழுகையை நிலைநாட்டவும், ஸகாத் வழங்கவும், தூதர் (ஸல்) அவர்களுக்குக் கீழ்ப்படியவும் விடுக்கப்பட்ட கட்டளை; நிராகரிப்பாளர்கள் தப்பிக்க இயலாமையும், அவர்களின் இறுதி முடிவும்</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் மீது நம்பிக்கை கொண்ட அடியார்களுக்கு, தொழுகையை நிலைநாட்டும்படி கட்டளையிடுகிறான். அதாவது, எவ்வித இணைதுணையும் இன்றி அல்லாஹ்வை மட்டுமே வணங்குவதாகும்; மேலும் ஸகாத் வழங்குமாறும் கட்டளையிடுகிறான், இது அவனது ஏழை எளிய மற்றும் பலவீனமான படைப்புகளுக்குச் செய்யப்படும் ஒரு கருணைச் செயலாகும்; இவற்றின் மூலம் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குக் கீழ்ப்படியுமாறும், அதாவது அவர்கள் கட்டளையிடுவதைச் செய்யவும், அவர்கள் தடுப்பவற்றைத் தவிர்க்குமாறும் அல்லாஹ் பணிக்கிறான். இதன் மூலம் அல்லாஹ் அவர்கள் மீது கருணை காட்டுவான். எவர் இவற்றுக்குக் கீழ்ப்படிகிறாரோ, அவர் மீது அல்லாஹ் நிச்சயமாகக் கருணை காட்டுவான். இதனை அல்லாஹ் மற்றொரு வசனத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أُولَٰئِكَ</span> <span class=\"quran-arabic-font text-success\">سَيَرْحَمُهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span><br />\r\n<br />\r\n(அல்லாஹ் அவர்களுக்குத் தனது அருளைப் புரிவான்) <a href=\"qurandisp.php?sura=9&ayah=71\" class=\"link\">9:71</a>.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَحْسَبَنَّ</span><br />\r\n<br />\r\n(நீர் எண்ண வேண்டாம்) இதன் பொருள், \"முஹம்மதே (ஸல்)! நீர் இவ்வாறு நினைக்க வேண்டாம்\" என்பதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span><br />\r\n<br />\r\n(நிராகரிப்பாளர்கள்) அதாவது உம்மை எதிர்த்து, உம்மைப் பொய்ப்பித்தவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مُعْجِزِينَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span><br />\r\n<br />\r\n(பூமியில் நம்மைத் தோற்கடித்துத் தப்பித்துவிடக் கூடியவர்கள் என்று.) அதாவது, அவர்களால் அல்லாஹ்விடமிருந்து தப்பி ஓட முடியும் என்று எண்ண வேண்டாம். அவ்வாறில்லை, அல்லாஹ் அவர்களைத் தண்டிப்பதற்கு ஆற்றல் மிக்கவன்; அவர்களின் செயலுக்காக அவன் அவர்களை மிகக் கடுமையாகத் தண்டிப்பான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَأْوَاهُمُ</span><br />\r\n<br />\r\n(அவர்களின் தங்குமிடம்) அதாவது மறுமையில்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">النَّارُ</span> <span class=\"quran-arabic-font text-success\">وَلَبِئْسَ</span> <span class=\"quran-arabic-font text-success\">الْمَصِيرُ</span><br />\r\n<br />\r\n(நரக நெருப்பாகும் - அந்தச் சேருமிடம் மிகவும் கெட்டது.) அதாவது நிராகரிப்பாளர்களின் இறுதி முடிவு எவ்வளவு கொடியது, அவர்கள் தங்குமிடம் எவ்வளவு தீயது, அவர்கள் ஓய்வெடுக்கும் இடம் எவ்வளவு மோசமானது என்பதைக் குறிக்கிறது.<br />\r\n<br />","text":"தொழுகையை நிலைநாட்டவும், ஸகாத் வழங்கவும், தூதர் (ஸல்) அவர்களுக்குக் கீழ்ப்படியவும் விடுக்கப்பட்ட கட்டளை; நிராகரிப்பாளர்கள் தப்பிக்க இயலாமையும், அவர்களின் இறுதி முடிவும்\n\r\n\n\r\nஅல்லாஹ் தன் மீது நம்பிக்கை கொண்ட அடியார்களுக்கு, தொழுகையை நிலைநாட்டும்படி கட்டளையிடுகிறான். அதாவது, எவ்வித இணைதுணையும் இன்றி அல்லாஹ்வை மட்டுமே வணங்குவதாகும்; மேலும் ஸகாத் வழங்குமாறும் கட்டளையிடுகிறான், இது அவனது ஏழை எளிய மற்றும் பலவீனமான படைப்புகளுக்குச் செய்யப்படும் ஒரு கருணைச் செயலாகும்; இவற்றின் மூலம் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுக்குக் கீழ்ப்படியுமாறும், அதாவது அவர்கள் கட்டளையிடுவதைச் செய்யவும், அவர்கள் தடுப்பவற்றைத் தவிர்க்குமாறும் அல்லாஹ் பணிக்கிறான். இதன் மூலம் அல்லாஹ் அவர்கள் மீது கருணை காட்டுவான். எவர் இவற்றுக்குக் கீழ்ப்படிகிறாரோ, அவர் மீது அல்லாஹ் நிச்சயமாகக் கருணை காட்டுவான். இதனை அல்லாஹ் மற்றொரு வசனத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nأُولَٰئِكَ سَيَرْحَمُهُمُ اللَّهُ\n\r\n\n\r\n(அல்லாஹ் அவர்களுக்குத் தனது அருளைப் புரிவான்) 9:71.\n\r\n\n\r\nلاَ تَحْسَبَنَّ\n\r\n\n\r\n(நீர் எண்ண வேண்டாம்) இதன் பொருள், \"முஹம்மதே (ஸல்)! நீர் இவ்வாறு நினைக்க வேண்டாம்\" என்பதாகும்:\n\r\n\n\r\nالَّذِينَ كَفَرُواْ\n\r\n\n\r\n(நிராகரிப்பாளர்கள்) அதாவது உம்மை எதிர்த்து, உம்மைப் பொய்ப்பித்தவர்கள்,\n\r\n\n\r\nمُعْجِزِينَ فِي الْأَرْضِ\n\r\n\n\r\n(பூமியில் நம்மைத் தோற்கடித்துத் தப்பித்துவிடக் கூடியவர்கள் என்று.) அதாவது, அவர்களால் அல்லாஹ்விடமிருந்து தப்பி ஓட முடியும் என்று எண்ண வேண்டாம். அவ்வாறில்லை, அல்லாஹ் அவர்களைத் தண்டிப்பதற்கு ஆற்றல் மிக்கவன்; அவர்களின் செயலுக்காக அவன் அவர்களை மிகக் கடுமையாகத் தண்டிப்பான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَأْوَاهُمُ\n\r\n\n\r\n(அவர்களின் தங்குமிடம்) அதாவது மறுமையில்,\n\r\n\n\r\nالنَّارُ وَلَبِئْسَ الْمَصِيرُ\n\r\n\n\r\n(நரக நெருப்பாகும் - அந்தச் சேருமிடம் மிகவும் கெட்டது.) அதாவது நிராகரிப்பாளர்களின் இறுதி முடிவு எவ்வளவு கொடியது, அவர்கள் தங்குமிடம் எவ்வளவு தீயது, அவர்கள் ஓய்வெடுக்கும் இடம் எவ்வளவு மோசமானது என்பதைக் குறிக்கிறது."},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=60\" class=\"link\">24:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:60 ஐ பார்க்கவும்"},"59":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=24&ayah=60\" class=\"link\">24:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 24:60 ஐ பார்க்கவும்"},"60":{"html":"<strong>பணியாளர்களும் சிறு குழந்தைகளும் அனுமதி கேட்க வேண்டிய நேரங்கள்</strong><br />\r\n<br />\r\nஇந்த வசனங்கள் நெருங்கிய உறவினர்கள் ஒருவருக்கொருவர் உள்ளே நுழையும்போது எப்படி அனுமதி கேட்க வேண்டும் என்பதைப் பற்றி விளக்குகின்றன. இந்தச் சூராவின் முந்தைய பகுதியில், அந்நியர்கள் ஒருவருக்கொருவர் அனுமதி கேட்பது குறித்துக் கூறப்பட்டிருந்தது. அல்லாஹ் முஃமின்களுக்கு, அவர்களின் பணியாளர்களும், பருவ வயதை அடையாத சிறுவர்களும் மூன்று நேரங்களில் அனுமதி கேட்க வேண்டும் என்று கட்டளையிட்டான்: முதலாவது ஃபஜ்ர் தொழுகைக்கு முன்பு <span class=\"quran-arabic-font text-success\">﴾مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">صَـلَوةِ</span> <span class=\"quran-arabic-font text-success\">الْفَجْرِ﴿</span>; ஏனெனில் அந்த நேரத்தில் மக்கள் தங்கள் படுக்கைகளில் உறங்கிக் கொண்டிருப்பார்கள். <span class=\"quran-arabic-font text-success\">﴾وَحِينَ</span> <span class=\"quran-arabic-font text-success\">تَضَعُونَ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الظَّهِيرَةِ﴿</span><br />\r\n<br />\r\n(மற்றும் நண்பகலில் உங்கள் ஆடைகளைக் களைந்திருக்கும் நேரத்திலும்,) அதாவது ஓய்வெடுக்கும் நேரமாகும்; ஏனெனில் அந்த நேரத்தில் ஒரு ஆண் தன் மனைவியுடன் தாம்பத்திய உறவுக்காக (தனிமையில்) ஆடையின்றி இருக்கக்கூடும். <span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">صَلَوةِ</span> <span class=\"quran-arabic-font text-success\">الْعِشَآءِ﴿</span><br />\r\n<br />\r\n(மற்றும் இஷா தொழுகைக்குப் பிறகும்.) ஏனெனில் இது உறங்கும் நேரமாகும். இந்த நேரங்களில் பணியாளர்களும் குழந்தைகளும் வீட்டு உறுப்பினர்களின் அறைக்குள் நுழையக்கூடாது என்று கட்டளையிடப்பட்டுள்ளது. ஏனெனில், ஒரு ஆண் தனது மனைவியுடன் அந்தரங்கமான தாம்பத்திய சூழலில் இருக்கக்கூடும் என்று அஞ்சப்படுவதே இதற்குக் காரணமாகும். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾ثَلاَثُ</span> <span class=\"quran-arabic-font text-success\">عَوْرَاتٍ</span> <span class=\"quran-arabic-font text-success\">لَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">بَعْدَهُنَّ﴿</span><br />\r\n<br />\r\n((இவை) மூன்றும் உங்களுக்குரிய அந்தரங்க நேரங்களாகும்; இந்த நேரங்கள் அல்லாத மற்ற நேரங்களில் (அவர்கள் நுழைவதால்) உங்கள் மீதோ அல்லது அவர்கள் மீதோ எந்தக் குற்றமும் இல்லை.) இந்த நேரங்கள் அல்லாத மற்ற சமயங்களில் அவர்கள் நுழைந்தால், அவர்களை அனுமதிப்பதில் உங்கள் மீது எவ்விதக் குற்றமும் இல்லை; மேலும் அவர்கள் எதையாவது பார்த்துவிட்டாலும் அவர்கள் மீதும் குற்றமில்லை. அவர்கள் உங்களுக்குப் பணிவிடை செய்வதற்காக வீட்டில் அடிக்கடி நடமாட வேண்டியவர்கள் <span class=\"quran-arabic-font text-success\">﴾طَوَّافُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ﴿</span> என்பதால், அவர்களுக்குத் தற்செயலாக உள்ளே நுழைய அனுமதி அளிக்கப்பட்டுள்ளது. எனவே, மற்றவர்களுக்கு மன்னிக்கப்படாத சில விஷயங்கள் இவர்களுக்கு மன்னிக்கப்படலாம். இந்த வசனம் மிகவும் தெளிவாக இருப்பதோடு, இது மாற்றப்படவும் (மன்சூக்) இல்லை. இருப்பினும், மக்கள் இதனை அரிதாகவே பின்பற்றுகிறார்கள். இதற்காக இப்னு அப்பாஸ் (ரழி) அவர்கள் மக்களைக் கண்டித்தார்கள். அபூ தாவூத் பதிவு செய்துள்ள செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகிறார்கள்: \"பெரும்பாலான மக்கள் அனுமதி கேட்பது தொடர்பான இந்த வசனத்தைப் பின்பற்றுவதில்லை, ஆனால் நான் எனது பணிப்பெண்ணிடம் அனுமதி கேட்டுவிட்டு உள்ளே வருமாறு கூறுகிறேன்.\" அதாஃ அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்கள் இவ்வாறு கட்டளையிட்டதாக அறிவிக்கிறார்கள். அத்-தவ்ரீ அவர்கள் அறிவிக்கும் செய்தியில் மூஸா பின் அபீ ஆயிஷா கூறுகிறார்கள்: \"நான் அஷ்-ஷஅபீ அவர்களிடம், <span class=\"quran-arabic-font text-success\">﴾لِيَسْتَأْذِنكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مَلَكَتْ</span> <span class=\"quran-arabic-font text-success\">أَيْمَانُكُمْ﴿</span> (உங்கள் அடிமைகளும் அடிமைப் பெண்களும் உங்களிடம் அனுமதி கேட்கட்டும்) என்ற வசனத்தைப் பற்றிக் கேட்டேன். அதற்கு அவர், ‘அது ரத்து செய்யப்படவில்லை’ என்று கூறினார். நான், ‘ஆனால் மக்கள் அவ்வாறு செய்வதில்லையே?’ என்றேன். அதற்கு அவர், ‘அல்லாஹ் அவர்களுக்கு உதவட்டும்’ என்று கூறினார்.\"<br />\r\n<br />\r\nபின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span> <span class=\"quran-arabic-font text-success\">الاٌّطْفَالُ</span> <span class=\"quran-arabic-font text-success\">مِنكُمُ</span> <span class=\"quran-arabic-font text-success\">الْحُلُمَ</span> <span class=\"quran-arabic-font text-success\">فَلْيَسْتَأْذِنُواْ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">اسْتَأْذَنَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِهِمْ﴿</span><br />\r\n<br />\r\n(மேலும், உங்களில் உள்ள குழந்தைகள் பருவ வயதை அடைந்துவிட்டால், அவர்களுக்கு மூத்தவர்கள் அனுமதி கேட்பது போலவே அவர்களும் அனுமதி கேட்கட்டும்.) அதாவது: அந்த மூன்று அந்தரங்க நேரங்களில் மட்டும் அனுமதி கேட்டு வந்த சிறுவர்கள், பருவ வயதை அடைந்த பிறகு எல்லா நேரங்களிலும் அனுமதி கேட்க வேண்டும். அதாவது, அந்நியர்களிடம் அனுமதி கேட்பது போன்றும், ஒரு ஆண் தன் மனைவியுடன் தனிமையில் இருக்கக்கூடிய நேரங்களிலும் - அது மேலே கூறப்பட்ட மூன்று நேரங்களாக இல்லாவிட்டாலும் - அவர்கள் அனுமதி கேட்பது அவசியமாகும்.<br />\r\n<br />\r\n<strong>வயதான பெண்கள் தங்கள் மேலாடையைக் களைந்து கொள்வதில் குற்றமில்லை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالْقَوَاعِدُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النِّسَآءِ﴿</span><br />\r\n<br />\r\n(மேலும் பெண்களில் உள்ள 'கவாஇத்' என்பவர்கள்.) இவர்கள் இனி குழந்தை பெற்றுக்கொள்ள முடியாது என்று கருதும் வயதான பெண்கள் என்று ஸயீத் பின் ஜுபைர், முகாத்தில் பின் ஹய்யான், அத்-தஹ்ஹாக் மற்றும் கத்தாதா ஆகியோர் கூறுகின்றனர். <span class=\"quran-arabic-font text-success\">﴾اللَّاتِي</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَرْجُونَ</span> <span class=\"quran-arabic-font text-success\">نِكَاحاً﴿</span><br />\r\n<br />\r\n(திருமணத்தை எதிர்பார்க்காதவர்கள்,) அதாவது, அவர்களுக்கு திருமணத்தின் மீது எவ்வித விருப்பமும் இருக்காது. <span class=\"quran-arabic-font text-success\">﴾فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِنَّ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَضَعْنَ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُنَّ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مُتَبَرِّجَاتٍ</span> <span class=\"quran-arabic-font text-success\">بِزِينَةٍ﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் அலங்காரத்தை வெளிப்படுத்தாத நிலையில், தமது (மேல்) ஆடைகளைக் களைந்து கொள்வது அவர்கள் மீது குற்றமாகாது.) அதாவது, மற்ற இளம் பெண்கள் தங்களை மறைத்துக் கொள்வது போன்று இவர்கள் தங்களை மறைக்க வேண்டிய அவசியமில்லை. \"முஃமினான பெண்களிடம் அவர்களின் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக\" (<a href=\"qurandisp.php?sura=24&ayah=31\" class=\"link\">24:31</a>) <span class=\"quran-arabic-font text-success\">﴾وَقُل</span> <span class=\"quran-arabic-font text-success\">لِّلْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">يَغْضُضْنَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارِهِنَّ﴿</span> என்ற வசனத்திலிருந்து, <span class=\"quran-arabic-font text-success\">﴾وَالْقَوَاعِدُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النِّسَآءِ</span> <span class=\"quran-arabic-font text-success\">اللَّاتِي</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَرْجُونَ</span> <span class=\"quran-arabic-font text-success\">نِكَاحاً﴿</span> (திருமண ஆசையற்ற, முதிர்ந்த வயதுடைய பெண்களுக்கு) விதிவிலக்கு அளிக்கப்பட்டுள்ளது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அபூ தாவூத் பதிவு செய்துள்ளார். <span class=\"quran-arabic-font text-success\">﴾فَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِنَّ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَضَعْنَ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُنَّ﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் (மேல்) ஆடைகளைக் களைந்து கொள்வது அவர்கள் மீது குற்றமாகாது.) இங்கு 'மேல் ஆடை' என்பது ஜில்பாப் அல்லது ரிதா (மேலங்கி) போன்றதைக் குறிக்கும் என்று இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள். இதே போன்ற கருத்து இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), முஜாஹித், ஸயீத் பின் ஜுபைர், அபூ அஷ்-ஷஃதா, இப்ராஹீம் அன்-நகாஈ, அல்-ஹஸன், கத்தாதா, அஸ்-ஸுஹ்ரீ, அல்-அவ்ஸாஈ மற்றும் பலரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. <span class=\"quran-arabic-font text-success\">﴾غَيْرَ</span> <span class=\"quran-arabic-font text-success\">مُتَبَرِّجَاتٍ</span> <span class=\"quran-arabic-font text-success\">بِزِينَةٍ﴿</span><br />\r\n<br />\r\n(தங்கள் அலங்காரத்தை வெளிப்படுத்தாத நிலையில்.) ஸயீத் பின் ஜுபைர் அவர்கள் கூறுகிறார்கள்: \"அவர்கள் தங்கள் மேலாடையை அகற்றுவதன் மூலம், தங்கள் அலங்காரம் தெரியும்படி அநாகரிகமான முறையில் தங்களை வெளிப்படுத்திக் கொள்ளக் கூடாது.\" <span class=\"quran-arabic-font text-success\">﴾وَأَن</span> <span class=\"quran-arabic-font text-success\">يَسْتَعْفِفْنَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">لَّهُنَّ﴿</span><br />\r\n<br />\r\n(எனினும், அவர்கள் பேணுதலாக இருப்பது அவர்களுக்கு இன்னும் சிறந்தது.) அதாவது, மேலாடையை அகற்றுவதற்கு அவர்களுக்கு அனுமதி அளிக்கப்பட்டிருந்தாலும், அதை அகற்றாமல் இருப்பதே அவர்களுக்கு மிகவும் சிறந்தது. <span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் யாவற்றையும் செவியேற்பவன், நன்கறிந்தவன்.)<br />\r\n<br />","text":"பணியாளர்களும் சிறு குழந்தைகளும் அனுமதி கேட்க வேண்டிய நேரங்கள்\n\r\n\n\r\nஇந்த வசனங்கள் நெருங்கிய உறவினர்கள் ஒருவருக்கொருவர் உள்ளே நுழையும்போது எப்படி அனுமதி கேட்க வேண்டும் என்பதைப் பற்றி விளக்குகின்றன. இந்தச் சூராவின் முந்தைய பகுதியில், அந்நியர்கள் ஒருவருக்கொருவர் அனுமதி கேட்பது குறித்துக் கூறப்பட்டிருந்தது. அல்லாஹ் முஃமின்களுக்கு, அவர்களின் பணியாளர்களும், பருவ வயதை அடையாத சிறுவர்களும் மூன்று நேரங்களில் அனுமதி கேட்க வேண்டும் என்று கட்டளையிட்டான்: முதலாவது ஃபஜ்ர் தொழுகைக்கு முன்பு ﴾مِن قَبْلِ صَـلَوةِ الْفَجْرِ﴿; ஏனெனில் அந்த நேரத்தில் மக்கள் தங்கள் படுக்கைகளில் உறங்கிக் கொண்டிருப்பார்கள். ﴾وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِّنَ الظَّهِيرَةِ﴿\n\r\n\n\r\n(மற்றும் நண்பகலில் உங்கள் ஆடைகளைக் களைந்திருக்கும் நேரத்திலும்,) அதாவது ஓய்வெடுக்கும் நேரமாகும்; ஏனெனில் அந்த நேரத்தில் ஒரு ஆண் தன் மனைவியுடன் தாம்பத்திய உறவுக்காக (தனிமையில்) ஆடையின்றி இருக்கக்கூடும். ﴾وَمِن بَعْدِ صَلَوةِ الْعِشَآءِ﴿\n\r\n\n\r\n(மற்றும் இஷா தொழுகைக்குப் பிறகும்.) ஏனெனில் இது உறங்கும் நேரமாகும். இந்த நேரங்களில் பணியாளர்களும் குழந்தைகளும் வீட்டு உறுப்பினர்களின் அறைக்குள் நுழையக்கூடாது என்று கட்டளையிடப்பட்டுள்ளது. ஏனெனில், ஒரு ஆண் தனது மனைவியுடன் அந்தரங்கமான தாம்பத்திய சூழலில் இருக்கக்கூடும் என்று அஞ்சப்படுவதே இதற்குக் காரணமாகும். அல்லாஹ் கூறுகிறான்: ﴾ثَلاَثُ عَوْرَاتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلاَ عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ﴿\n\r\n\n\r\n((இவை) மூன்றும் உங்களுக்குரிய அந்தரங்க நேரங்களாகும்; இந்த நேரங்கள் அல்லாத மற்ற நேரங்களில் (அவர்கள் நுழைவதால்) உங்கள் மீதோ அல்லது அவர்கள் மீதோ எந்தக் குற்றமும் இல்லை.) இந்த நேரங்கள் அல்லாத மற்ற சமயங்களில் அவர்கள் நுழைந்தால், அவர்களை அனுமதிப்பதில் உங்கள் மீது எவ்விதக் குற்றமும் இல்லை; மேலும் அவர்கள் எதையாவது பார்த்துவிட்டாலும் அவர்கள் மீதும் குற்றமில்லை. அவர்கள் உங்களுக்குப் பணிவிடை செய்வதற்காக வீட்டில் அடிக்கடி நடமாட வேண்டியவர்கள் ﴾طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ﴿ என்பதால், அவர்களுக்குத் தற்செயலாக உள்ளே நுழைய அனுமதி அளிக்கப்பட்டுள்ளது. எனவே, மற்றவர்களுக்கு மன்னிக்கப்படாத சில விஷயங்கள் இவர்களுக்கு மன்னிக்கப்படலாம். இந்த வசனம் மிகவும் தெளிவாக இருப்பதோடு, இது மாற்றப்படவும் (மன்சூக்) இல்லை. இருப்பினும், மக்கள் இதனை அரிதாகவே பின்பற்றுகிறார்கள். இதற்காக இப்னு அப்பாஸ் (ரழி) அவர்கள் மக்களைக் கண்டித்தார்கள். அபூ தாவூத் பதிவு செய்துள்ள செய்தியில் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறுகிறார்கள்: \"பெரும்பாலான மக்கள் அனுமதி கேட்பது தொடர்பான இந்த வசனத்தைப் பின்பற்றுவதில்லை, ஆனால் நான் எனது பணிப்பெண்ணிடம் அனுமதி கேட்டுவிட்டு உள்ளே வருமாறு கூறுகிறேன்.\" அதாஃ அவர்களும் இப்னு அப்பாஸ் (ரழி) அவர்கள் இவ்வாறு கட்டளையிட்டதாக அறிவிக்கிறார்கள். அத்-தவ்ரீ அவர்கள் அறிவிக்கும் செய்தியில் மூஸா பின் அபீ ஆயிஷா கூறுகிறார்கள்: \"நான் அஷ்-ஷஅபீ அவர்களிடம், ﴾لِيَسْتَأْذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ﴿ (உங்கள் அடிமைகளும் அடிமைப் பெண்களும் உங்களிடம் அனுமதி கேட்கட்டும்) என்ற வசனத்தைப் பற்றிக் கேட்டேன். அதற்கு அவர், ‘அது ரத்து செய்யப்படவில்லை’ என்று கூறினார். நான், ‘ஆனால் மக்கள் அவ்வாறு செய்வதில்லையே?’ என்றேன். அதற்கு அவர், ‘அல்லாஹ் அவர்களுக்கு உதவட்டும்’ என்று கூறினார்.\"\n\r\n\n\r\nபின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَإِذَا بَلَغَ الاٌّطْفَالُ مِنكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُواْ كَمَا اسْتَأْذَنَ الَّذِينَ مِن قَبْلِهِمْ﴿\n\r\n\n\r\n(மேலும், உங்களில் உள்ள குழந்தைகள் பருவ வயதை அடைந்துவிட்டால், அவர்களுக்கு மூத்தவர்கள் அனுமதி கேட்பது போலவே அவர்களும் அனுமதி கேட்கட்டும்.) அதாவது: அந்த மூன்று அந்தரங்க நேரங்களில் மட்டும் அனுமதி கேட்டு வந்த சிறுவர்கள், பருவ வயதை அடைந்த பிறகு எல்லா நேரங்களிலும் அனுமதி கேட்க வேண்டும். அதாவது, அந்நியர்களிடம் அனுமதி கேட்பது போன்றும், ஒரு ஆண் தன் மனைவியுடன் தனிமையில் இருக்கக்கூடிய நேரங்களிலும் - அது மேலே கூறப்பட்ட மூன்று நேரங்களாக இல்லாவிட்டாலும் - அவர்கள் அனுமதி கேட்பது அவசியமாகும்.\n\r\n\n\r\nவயதான பெண்கள் தங்கள் மேலாடையைக் களைந்து கொள்வதில் குற்றமில்லை\n\r\n\n\r\n﴾وَالْقَوَاعِدُ مِنَ النِّسَآءِ﴿\n\r\n\n\r\n(மேலும் பெண்களில் உள்ள 'கவாஇத்' என்பவர்கள்.) இவர்கள் இனி குழந்தை பெற்றுக்கொள்ள முடியாது என்று கருதும் வயதான பெண்கள் என்று ஸயீத் பின் ஜுபைர், முகாத்தில் பின் ஹய்யான், அத்-தஹ்ஹாக் மற்றும் கத்தாதா ஆகியோர் கூறுகின்றனர். ﴾اللَّاتِي لاَ يَرْجُونَ نِكَاحاً﴿\n\r\n\n\r\n(திருமணத்தை எதிர்பார்க்காதவர்கள்,) அதாவது, அவர்களுக்கு திருமணத்தின் மீது எவ்வித விருப்பமும் இருக்காது. ﴾فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ﴿\n\r\n\n\r\n(அவர்கள் தங்கள் அலங்காரத்தை வெளிப்படுத்தாத நிலையில், தமது (மேல்) ஆடைகளைக் களைந்து கொள்வது அவர்கள் மீது குற்றமாகாது.) அதாவது, மற்ற இளம் பெண்கள் தங்களை மறைத்துக் கொள்வது போன்று இவர்கள் தங்களை மறைக்க வேண்டிய அவசியமில்லை. \"முஃமினான பெண்களிடம் அவர்களின் பார்வைகளைத் தாழ்த்திக் கொள்ளுமாறு கூறுவீராக\" (24:31) ﴾وَقُل لِّلْمُؤْمِنَـتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ﴿ என்ற வசனத்திலிருந்து, ﴾وَالْقَوَاعِدُ مِنَ النِّسَآءِ اللَّاتِي لاَ يَرْجُونَ نِكَاحاً﴿ (திருமண ஆசையற்ற, முதிர்ந்த வயதுடைய பெண்களுக்கு) விதிவிலக்கு அளிக்கப்பட்டுள்ளது என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அபூ தாவூத் பதிவு செய்துள்ளார். ﴾فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ﴿\n\r\n\n\r\n(அவர்கள் தங்கள் (மேல்) ஆடைகளைக் களைந்து கொள்வது அவர்கள் மீது குற்றமாகாது.) இங்கு 'மேல் ஆடை' என்பது ஜில்பாப் அல்லது ரிதா (மேலங்கி) போன்றதைக் குறிக்கும் என்று இப்னு மஸ்ஊத் (ரழி) அவர்கள் கூறினார்கள். இதே போன்ற கருத்து இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), முஜாஹித், ஸயீத் பின் ஜுபைர், அபூ அஷ்-ஷஃதா, இப்ராஹீம் அன்-நகாஈ, அல்-ஹஸன், கத்தாதா, அஸ்-ஸுஹ்ரீ, அல்-அவ்ஸாஈ மற்றும் பலரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. ﴾غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ﴿\n\r\n\n\r\n(தங்கள் அலங்காரத்தை வெளிப்படுத்தாத நிலையில்.) ஸயீத் பின் ஜுபைர் அவர்கள் கூறுகிறார்கள்: \"அவர்கள் தங்கள் மேலாடையை அகற்றுவதன் மூலம், தங்கள் அலங்காரம் தெரியும்படி அநாகரிகமான முறையில் தங்களை வெளிப்படுத்திக் கொள்ளக் கூடாது.\" ﴾وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ﴿\n\r\n\n\r\n(எனினும், அவர்கள் பேணுதலாக இருப்பது அவர்களுக்கு இன்னும் சிறந்தது.) அதாவது, மேலாடையை அகற்றுவதற்கு அவர்களுக்கு அனுமதி அளிக்கப்பட்டிருந்தாலும், அதை அகற்றாமல் இருப்பதே அவர்களுக்கு மிகவும் சிறந்தது. ﴾وَاللَّهُ سَمِيعٌ عَلِيمٌ﴿\n\r\n\n\r\n(அல்லாஹ் யாவற்றையும் செவியேற்பவன், நன்கறிந்தவன்.)"},"61":{"html":"<strong>உறவினர்களின் வீடுகளில் இருந்து உண்பது</strong><br />\r\n<br />\r\nஇங்கு குறிப்பிடப்படுவது என்னவென்றால், பார்வையற்றவர்களுடன் இணைந்து உண்பதற்கு அவர்கள் மிகவும் சங்கடப்பட்டார்கள். ஏனெனில், அவர்களால் உணவையோ அல்லது உணவில் சிறந்த பகுதிகள் எங்கு உள்ளன என்பதையோ பார்க்க முடியாது; இதனால் தங்களுக்கு முன்னதாகவே மற்றவர்கள் சிறந்த துண்டுகளை எடுத்துவிடுவார்களோ என்று அவர்கள் கூச்சப்பட்டார்கள். முடவர்களால் வசதியாக அமர முடியாது என்பதாலும், அவர்களுடன் இருப்பவர்கள் அதைத் தங்களுக்குச் சாதகமாகப் பயன்படுத்திக் கொள்வார்களோ என்பதாலும் அவர்களுடன் அமர்ந்து உண்ணவும் அவர்கள் சங்கடப்பட்டார்கள். அவ்வாறே நோயாளிகளுடன் உண்பதற்கும் அவர்கள் சங்கடப்பட்டார்கள், ஏனெனில் அவர்கள் மற்றவர்களைப் போல் அதிக அளவு உண்ண மாட்டார்கள். எனவே, ஏதேனும் ஒரு வகையில் அவர்களுக்கு அநீதி இழைத்துவிடுவோமோ என்று அஞ்சி, அவர்களுடன் சேர்ந்து உண்ண அவர்கள் அஞ்சினார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை (ஆயத்தை) அருளி, இவ்விஷயத்தில் அவர்களுக்கு ஒரு சலுகையை வழங்கினான். இது ஸஈத் பின் ஜுபைர் (ரழி) மற்றும் மிக்ஸம் (ரழி) ஆகியோரின் கருத்தாகும். அத்-தஹ்ஹாக் (ரழி) கூறினார்கள்: \"நபியவர்களின் தூதுத்துவப் பணிக்கு (நுபுவ்வத்) முன்னதாக, இம்மக்களுக்கு உதவ வேண்டியிருக்குமோ என்ற எண்ணத்தில், அவர்களுடன் சேர்ந்து உண்பதற்கு அவர்கள் கர்வமாகவும் மிகவும் சங்கடமாகவும் உணர்ந்தனர். எனவே அல்லாஹ் இந்த வசனத்தை அருளினான்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَىٰ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْرَجِ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْمَرِيضِ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span><br />\r\n<br />\r\n<br />\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை; முடவர் மீதும் குற்றமில்லை; நோயாளியின் மீதும் குற்றமில்லை.) அப்துர்-ரஸ்ஸாக் (ரஹ்) அவர்கள் முஜாஹித் (ரழி) கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஒருவர், பார்வையற்ற, முடமான அல்லது நோயுற்ற ஒருவரைத் தனது சகோதரன், சகோதரி அல்லது அத்தையின் வீட்டிற்கு அழைத்துச் செல்வார். அந்த ஊனமுற்றவர்கள் அதைப் பற்றி வெட்கப்பட்டு, 'அவர்கள் எங்களை மற்றவர்களின் வீடுகளுக்கு அழைத்துச் செல்கிறார்கள்' என்று கூறுவார்கள். எனவே இந்த வசனம் அதற்கு அனுமதி வழங்கி அருளப்பட்டது.\" அஸ்-ஸுத்தி (ரழி) கூறினார்கள்: \"ஒருவர் தனது தந்தை, சகோதரன் அல்லது மகனின் வீட்டிற்குள் நுழைவார். அந்த வீட்டின் பெண்மணி அவருக்குச் சிறிதளவு உணவு கொண்டு வருவார். ஆனால், வீட்டின் உரிமையாளர் அங்கு இல்லாததால் அவர் சாப்பிடத் தயங்குவார். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَىٰ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span><br />\r\n<br />\r\n<br />\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை. ..)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بُيُوتِكُمْ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது உங்கள் வீடுகளில் நீங்கள் உண்பது உங்கள் மீதும் குற்றமில்லை,) இது வெளிப்படையாகத் தெரிந்தாலும், மற்றவர்களின் வீடுகளைப் பற்றிக் குறிப்பிடுவதற்கு ஒரு தொடக்கப் புள்ளியாக இங்கு கூறப்பட்டுள்ளது. மேலும், இதற்குப் பின்வரும் விஷயங்களுக்கும் இந்தச் சட்டம் சமமாகப் பொருந்தும் என்பதைத் தெளிவுபடுத்துவதற்காகவும் இவ்வாறு கூறப்பட்டுள்ளது. மகன்களின் வீடுகள் இதில் பெயர் குறிப்பிடப்படாவிட்டாலும் அவையும் இதில் அடங்கும். மகனின் செல்வம் தந்தையின் செல்வத்தைப் போன்றதே என்று கருதுபவர்களுக்கு இது ஒரு ஆதாரமாகப் பயன்படுத்தப்படுகிறது. முஸ்னத் மற்றும் சுனன் நூல்களில், பல அறிவிப்பாளர் தொடர்கள் வழியாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْتَ</span> <span class=\"quran-arabic-font text-success\">وَمَالُكَ</span> <span class=\"quran-arabic-font text-success\">لِأَبِيكَ</span>»<br />\r\n<br />\r\n<br />\r\n(நீயும் உனது செல்வமும் உனது தந்தைக்குரியவர்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">أُمَّهَـتِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">إِخْوَانِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">أَخَوَاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">أَعْمَامِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">عَمَّاتِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">أَخْوَالِكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتِ</span> <span class=\"quran-arabic-font text-success\">خَالَاتِكُمْ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது உங்கள் தந்தையரின் வீடுகள், அல்லது உங்கள் அன்னையரின் வீடுகள், அல்லது உங்கள் சகோதரர்களின் வீடுகள், அல்லது உங்கள் சகோதரிகளின் வீடுகள், அல்லது உங்கள் தந்தையின் சகோதரர்களுடைய வீடுகள், அல்லது உங்கள் தந்தையின் சகோதரிகளுடைய வீடுகள், அல்லது உங்கள் தாயின் சகோதரர்களுடைய வீடுகள், அல்லது உங்கள் தாயின் சகோதரிகளுடைய வீடுகள்,)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكْتُم</span> <span class=\"quran-arabic-font text-success\">مَّفَاتِحَهُ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்),) இது வெளிப்படையானது. உறவினர்கள் ஒருவருக்கொருவர் செலவழிக்க வேண்டியது கட்டாயம் என்று கருதுபவர்களுக்கு இது ஒரு ஆதாரமாகப் பயன்படுத்தப்படுகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكْتُم</span> <span class=\"quran-arabic-font text-success\">مَّفَاتِحَهُ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்),) ஸஈத் பின் ஜுபைர் (ரழி) மற்றும் அஸ்-ஸுத்தி (ரழி) ஆகியோர் கூறினார்கள்: \"இது மக்களின் பணியாட்களைக் குறிக்கிறது, அவர்கள் அடிமைகளாக இருந்தாலும் சரி அல்லது வேறு யாராக இருந்தாலும் சரி. அவர்களிடம் ஒப்படைக்கப்பட்டுள்ள உணவிலிருந்து, நியாயமான அளவிற்கு அவர்கள் உண்பதில் தவறில்லை.\" அஸ்-ஸுஹ்ரி (ரழி) அவர்கள் உர்வா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"முஸ்லிம்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் அறப்போர்களுக்குச் செல்வது வழக்கம். அப்போது அவர்கள் தங்களுக்கு நம்பிக்கையானவர்களிடம் சாவிகளைக் கொடுத்துவிட்டு, 'உங்களுக்குத் தேவையானவற்றை உண்ண நாங்கள் உங்களுக்கு அனுமதி அளிக்கிறோம்' என்று கூறுவார்கள். ஆனால் அவர்களோ, 'நாங்கள் உண்பது அனுமதிக்கப்பட்டதல்ல; அவர்கள் விருப்பமில்லாமலேயே நமக்கு அனுமதி அளித்துள்ளார்கள், நாங்கள் வெறும் காப்பாளர்கள் (அமானிததாரர்கள்) மட்டுமே' என்று கூறுவார்கள். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">مَلَكْتُم</span> <span class=\"quran-arabic-font text-success\">مَّفَاتِحَهُ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்)).\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">صَدِيقِكُمْ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது ஒரு நண்பனின் (வீட்டிலிருந்தும்).) அதாவது, அவர்களுடைய வீடுகளில் இருந்து நீங்கள் உண்பதால் உங்கள் மீது எந்தப் பாவமும் இல்லை; இது அவர்களுக்கு வருத்தத்தை ஏற்படுத்தாது என்றும், அவர்கள் இதை வெறுக்க மாட்டார்கள் என்றும் நீங்கள் அறிந்திருக்கும் வரை இது அனுமதிக்கப்பட்டதே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُواْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَشْتَاتاً</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.) இந்த வசனத்தைப் பற்றி அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அல்லாஹ் இந்த வசனத்தை அருளியபோது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">أَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُوا</span> <span class=\"quran-arabic-font text-success\">أَمْوَالَكُم</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُم</span> <span class=\"quran-arabic-font text-success\">بِالْبَاطِلِ</span><br />\r\n<br />\r\n<br />\r\n(ஈமான் கொண்டவர்களே! உங்களுடைய சொத்துக்களை உங்களுக்கிடையில் அநியாயமான முறையில் உண்ணாதீர்கள்) <a href=\"qurandisp.php?sura=4&ayah=29\" class=\"link\">4:29</a>, முஸ்லிம்கள் கூறினார்கள்: 'நமக்கு மத்தியில் அநியாயமான முறையில் சொத்துக்களை உண்பதை அல்லாஹ் தடை செய்துள்ளான். உணவோ செல்வங்களில் மிகச் சிறந்தது. எனவே, நம்மில் யாரும் மற்றவரின் வீட்டில் உண்பது அனுமதிக்கப்பட்டதல்ல.' இதனால் மக்கள் மற்றவர் வீட்டில் உண்பதைத் தவிர்த்தனர். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَعْمَىٰ</span> <span class=\"quran-arabic-font text-success\">حَرَجٌ</span><br />\r\n<br />\r\n<br />\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை,) அவனது கூற்றான... என்பது வரை;<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">صَدِيقِكُمْ</span><br />\r\n<br />\r\n<br />\r\n(அல்லது ஒரு நண்பனின் (வீட்டிலிருந்தும்).) மேலும் ஒரு மனிதர் தனியாகச் சாப்பிடவும் சங்கடப்பட்டு, வேறு யாராவது வரும் வரை காத்திருப்பார். ஆனால் அல்லாஹ் அவர்களுக்கு இந்த விஷயத்தை எளிதாக்கி கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُواْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَشْتَاتاً</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.)\" கதாதா (ரழி) கூறினார்கள்: \"ஜாஹிலிய்யா (அறியாமைக் காலம்) காலத்தில், பனூ கினானா கோத்திரத்தைச் சேர்ந்த ஒரு பிரிவினர் தனியாக உண்பதை ஒரு அவமானமாகக் கருதினர். எந்த அளவிற்கு என்றால், ஒரு மனிதன் பசியோடு இருந்தாலும், தன்னுடன் சேர்ந்து உண்ணவும் குடிக்கவும் எவரையாவது கண்டுபிடிக்கும் வரை தனது சுமை ஏற்றிய ஒட்டகத்தைச் செலுத்திக் கொண்டே இருப்பான். அப்போது அல்லாஹ் அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَاحٌ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُواْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَشْتَاتاً</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.) இது அல்லாஹ்விடமிருந்து வழங்கப்பட்ட ஒரு சலுகையாகும். மக்கள் தனியாகவோ அல்லது மற்றவர்களுடனோ சாப்பிட இது அனுமதி அளிக்கிறது. எனினும் மற்றவர்களுடன் சேர்ந்து உண்பது அதிக அருள் (பரக்கத்) வாய்ந்தது மற்றும் சிறந்தது ஆகும். இமாம் அஹ்மத் (ரஹ்) அவர்கள் வஹ்ஷி பின் ஹர்ப் (ரழி) அவர்கள் தனது தந்தை வழியாகத் தனது பாட்டனாரிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: ஒரு மனிதர் நபி (ஸல்) அவர்களிடம், 'நாங்கள் உண்கிறோம், ஆனால் எங்களுக்குத் திருப்தி ஏற்படுவதில்லை' என்று கூறினார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">مُتَفَرِّقِينَ،</span> <span class=\"quran-arabic-font text-success\">اجْتَمِعُوا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">طَعَامِكُمْ،</span> <span class=\"quran-arabic-font text-success\">وَاذْكُرُوا</span> <span class=\"quran-arabic-font text-success\">اسْمَ</span> <span class=\"quran-arabic-font text-success\">اللهِ،</span> <span class=\"quran-arabic-font text-success\">يُبَارَكْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span>»<br />\r\n<br />\r\n<br />\r\n(ஒருவேளை நீங்கள் தனித்தனியாக உண்ணக்கூடும். நீங்கள் ஒன்று சேர்ந்து உங்கள் உணவை உண்ணுங்கள், மேலும் அல்லாஹ்வின் திருப்பெயரைக் கூறுங்கள்; அவன் அந்த உணவில் உங்களுக்கு அருள் (பரக்கத்) செய்வான்.) இது அபூ தாவூத் மற்றும் இப்னு மாஜா ஆகிய நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது. இப்னு மாஜா அவர்களும், ஸாலிம் (ரழி) தனது தந்தை வழியாக உமர் (ரழி) அவர்களிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كُلُوا</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">تَفَرَّقُوا،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الْبَرَكَةَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">الْجَمَاعَةِ</span>»<br />\r\n<br />\r\n<br />\r\n(நீங்கள் ஒன்றாகச் சேர்ந்து உண்ணுங்கள், தனித்தனியாகப் பிரியாதீர்கள்; ஏனெனில் அருள் (பரக்கத்) என்பது கூட்டாக இருப்பதில்தான் உள்ளது.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">دَخَلْتُمْ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">فَسَلِّمُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِكُمْ</span><br />\r\n<br />\r\n<br />\r\n(ஆனால், நீங்கள் வீடுகளுக்குள் நுழையும்போது, ஒருவருக்கொருவர் ஸலாம் சொல்லிக் கொள்ளுங்கள்) ஸஈத் பின் ஜுபைர், அல்-ஹஸன் அல்-பஸரி, கதாதா மற்றும் அஸ்-ஸுஹ்ரி (ரழி) ஆகியோர், \"இதன் பொருள், ஒருவருக்கொருவர் ஸலாம் கூறி முகமன் தெரிவிப்பதாகும்\" என்று கூறினார்கள். இப்னு ஜுரைஜ் (ரழி) கூறினார்கள்: அபூ அஸ்-ஸுபைர் (ரழி) கூறினார்கள், \"ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள், 'நீங்கள் உங்கள் குடும்பத்தாரிடம் செல்லும்போது, அல்லாஹ்விடமிருந்து வழங்கப்பட்ட அருள்பெற்ற, நன்மையான வாழ்த்தைக் கூறி அவர்களுக்கு ஸலாம் சொல்லுங்கள்' என்று கூற நான் கேட்டேன். அவர் மேலும், 'இது கடமையான ஒன்றைத் தவிர வேறில்லை என்று நான் கருதுகிறேன்' என்றும் கூறினார்கள்.\" இப்னு ஜுரைஜ் (ரழி) மேலும் கூறினார்கள்: \"ஜியாத் (ரழி) அவர்கள், இப்னு தாவூஸ் (ரழி) அவர்கள் இவ்வாறு கூறுவார்கள் என்று சொன்னார்கள்: 'உங்களில் ஒருவர் தனது வீட்டிற்குள் நுழையும்போது, அவர் ஸலாம் கூறட்டும்.'\" முஜாஹித் (ரழி) கூறினார்கள்: \"நீங்கள் மஸ்ஜிதிற்குள் நுழையும்போது, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மீது சாந்தி உண்டாவதாக' என்று கூறுங்கள். உங்கள் குடும்பத்தினரிடம் செல்லும்போது அவர்களுக்கு ஸலாம் கூறுங்கள். எவருமில்லாத வீட்டிற்குள் நுழையும்போது, 'அஸ்ஸலாமு அலைனா வஅலா இபாதில்லாஹிஸ் ஸாலிஹீன்' (எங்கள் மீதும் அல்லாஹ்வின் நல்லடியார்கள் மீதும் சாந்தி உண்டாவதாக) என்று கூறுங்கள். இவ்வாறு செய்யவே ஒருவருக்குக் கட்டளையிடப்பட்டுள்ளது. மேலும் வானவர்கள் அந்த ஸலாமிற்குப் பதிலளிப்பார்கள் என்று எங்களுக்கு அறிவிக்கப்பட்டுள்ளது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يُبَيِّنُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْآيَاتِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ</span><br />\r\n<br />\r\n<br />\r\n(நீங்கள் புரிந்து கொள்வதற்காக அல்லாஹ் இவ்வாறு உங்களுக்குத் தனது வசனங்களை (ஆயத்களை) தெளிவுபடுத்துகிறான்.) இந்தச் சூராவில் இடம்பெற்றுள்ள ஞானமிக்க தீர்ப்புகளையும், நியாயமான மற்றும் நேர்த்தியாகக் கட்டமைக்கப்பட்ட சட்டங்களையும் குறிப்பிட்ட பிறகு, அல்லாஹ் தனது அடியார்களுக்குத் தனது வசனங்களைத் தெளிவாக விளக்குகிறான்; அவர்கள் அவற்றைச் சிந்தித்து அதன் அர்த்தங்களைப் புரிந்து கொள்வதற்காகவே இவ்வாறு சுட்டிக்காட்டுகிறான்.<br />\r\n<br />","text":"உறவினர்களின் வீடுகளில் இருந்து உண்பது\n\r\n\n\r\nஇங்கு குறிப்பிடப்படுவது என்னவென்றால், பார்வையற்றவர்களுடன் இணைந்து உண்பதற்கு அவர்கள் மிகவும் சங்கடப்பட்டார்கள். ஏனெனில், அவர்களால் உணவையோ அல்லது உணவில் சிறந்த பகுதிகள் எங்கு உள்ளன என்பதையோ பார்க்க முடியாது; இதனால் தங்களுக்கு முன்னதாகவே மற்றவர்கள் சிறந்த துண்டுகளை எடுத்துவிடுவார்களோ என்று அவர்கள் கூச்சப்பட்டார்கள். முடவர்களால் வசதியாக அமர முடியாது என்பதாலும், அவர்களுடன் இருப்பவர்கள் அதைத் தங்களுக்குச் சாதகமாகப் பயன்படுத்திக் கொள்வார்களோ என்பதாலும் அவர்களுடன் அமர்ந்து உண்ணவும் அவர்கள் சங்கடப்பட்டார்கள். அவ்வாறே நோயாளிகளுடன் உண்பதற்கும் அவர்கள் சங்கடப்பட்டார்கள், ஏனெனில் அவர்கள் மற்றவர்களைப் போல் அதிக அளவு உண்ண மாட்டார்கள். எனவே, ஏதேனும் ஒரு வகையில் அவர்களுக்கு அநீதி இழைத்துவிடுவோமோ என்று அஞ்சி, அவர்களுடன் சேர்ந்து உண்ண அவர்கள் அஞ்சினார்கள். அப்போது அல்லாஹ் இந்த வசனத்தை (ஆயத்தை) அருளி, இவ்விஷயத்தில் அவர்களுக்கு ஒரு சலுகையை வழங்கினான். இது ஸஈத் பின் ஜுபைர் (ரழி) மற்றும் மிக்ஸம் (ரழி) ஆகியோரின் கருத்தாகும். அத்-தஹ்ஹாக் (ரழி) கூறினார்கள்: \"நபியவர்களின் தூதுத்துவப் பணிக்கு (நுபுவ்வத்) முன்னதாக, இம்மக்களுக்கு உதவ வேண்டியிருக்குமோ என்ற எண்ணத்தில், அவர்களுடன் சேர்ந்து உண்பதற்கு அவர்கள் கர்வமாகவும் மிகவும் சங்கடமாகவும் உணர்ந்தனர். எனவே அல்லாஹ் இந்த வசனத்தை அருளினான்.\"\n\r\n\n\r\nلَّيْسَ عَلَى الْأَعْمَىٰ حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ\n\r\n\n\r\n\n\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை; முடவர் மீதும் குற்றமில்லை; நோயாளியின் மீதும் குற்றமில்லை.) அப்துர்-ரஸ்ஸாக் (ரஹ்) அவர்கள் முஜாஹித் (ரழி) கூறியதாகப் பதிவு செய்துள்ளார்கள்: \"ஒருவர், பார்வையற்ற, முடமான அல்லது நோயுற்ற ஒருவரைத் தனது சகோதரன், சகோதரி அல்லது அத்தையின் வீட்டிற்கு அழைத்துச் செல்வார். அந்த ஊனமுற்றவர்கள் அதைப் பற்றி வெட்கப்பட்டு, 'அவர்கள் எங்களை மற்றவர்களின் வீடுகளுக்கு அழைத்துச் செல்கிறார்கள்' என்று கூறுவார்கள். எனவே இந்த வசனம் அதற்கு அனுமதி வழங்கி அருளப்பட்டது.\" அஸ்-ஸுத்தி (ரழி) கூறினார்கள்: \"ஒருவர் தனது தந்தை, சகோதரன் அல்லது மகனின் வீட்டிற்குள் நுழைவார். அந்த வீட்டின் பெண்மணி அவருக்குச் சிறிதளவு உணவு கொண்டு வருவார். ஆனால், வீட்டின் உரிமையாளர் அங்கு இல்லாததால் அவர் சாப்பிடத் தயங்குவார். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nلَّيْسَ عَلَى الْأَعْمَىٰ حَرَجٌ\n\r\n\n\r\n\n\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை. ..)\n\r\n\n\r\nوَلاَ عَلَى أَنفُسِكُمْ أَن تَأْكُلُواْ مِن بُيُوتِكُمْ\n\r\n\n\r\n\n\r\n(அல்லது உங்கள் வீடுகளில் நீங்கள் உண்பது உங்கள் மீதும் குற்றமில்லை,) இது வெளிப்படையாகத் தெரிந்தாலும், மற்றவர்களின் வீடுகளைப் பற்றிக் குறிப்பிடுவதற்கு ஒரு தொடக்கப் புள்ளியாக இங்கு கூறப்பட்டுள்ளது. மேலும், இதற்குப் பின்வரும் விஷயங்களுக்கும் இந்தச் சட்டம் சமமாகப் பொருந்தும் என்பதைத் தெளிவுபடுத்துவதற்காகவும் இவ்வாறு கூறப்பட்டுள்ளது. மகன்களின் வீடுகள் இதில் பெயர் குறிப்பிடப்படாவிட்டாலும் அவையும் இதில் அடங்கும். மகனின் செல்வம் தந்தையின் செல்வத்தைப் போன்றதே என்று கருதுபவர்களுக்கு இது ஒரு ஆதாரமாகப் பயன்படுத்தப்படுகிறது. முஸ்னத் மற்றும் சுனன் நூல்களில், பல அறிவிப்பாளர் தொடர்கள் வழியாக அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«أَنْتَ وَمَالُكَ لِأَبِيكَ»\n\r\n\n\r\n\n\r\n(நீயும் உனது செல்வமும் உனது தந்தைக்குரியவர்கள்.)\n\r\n\n\r\nأَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَـتِكُمْ أَوْ بُيُوتِ إِخْوَانِكُمْ أَوْ بُيُوتِ أَخَوَاتِكُمْ أَوْ بُيُوتِ أَعْمَامِكُمْ أَوْ بُيُوتِ عَمَّاتِكُمْ أَوْ بُيُوتِ أَخْوَالِكُمْ أَوْ بُيُوتِ خَالَاتِكُمْ\n\r\n\n\r\n\n\r\n(அல்லது உங்கள் தந்தையரின் வீடுகள், அல்லது உங்கள் அன்னையரின் வீடுகள், அல்லது உங்கள் சகோதரர்களின் வீடுகள், அல்லது உங்கள் சகோதரிகளின் வீடுகள், அல்லது உங்கள் தந்தையின் சகோதரர்களுடைய வீடுகள், அல்லது உங்கள் தந்தையின் சகோதரிகளுடைய வீடுகள், அல்லது உங்கள் தாயின் சகோதரர்களுடைய வீடுகள், அல்லது உங்கள் தாயின் சகோதரிகளுடைய வீடுகள்,)\n\r\n\n\r\nأَوْ مَا مَلَكْتُم مَّفَاتِحَهُ\n\r\n\n\r\n\n\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்),) இது வெளிப்படையானது. உறவினர்கள் ஒருவருக்கொருவர் செலவழிக்க வேண்டியது கட்டாயம் என்று கருதுபவர்களுக்கு இது ஒரு ஆதாரமாகப் பயன்படுத்தப்படுகிறது.\n\r\n\n\r\nأَوْ مَا مَلَكْتُم مَّفَاتِحَهُ\n\r\n\n\r\n\n\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்),) ஸஈத் பின் ஜுபைர் (ரழி) மற்றும் அஸ்-ஸுத்தி (ரழி) ஆகியோர் கூறினார்கள்: \"இது மக்களின் பணியாட்களைக் குறிக்கிறது, அவர்கள் அடிமைகளாக இருந்தாலும் சரி அல்லது வேறு யாராக இருந்தாலும் சரி. அவர்களிடம் ஒப்படைக்கப்பட்டுள்ள உணவிலிருந்து, நியாயமான அளவிற்கு அவர்கள் உண்பதில் தவறில்லை.\" அஸ்-ஸுஹ்ரி (ரழி) அவர்கள் உர்வா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"முஸ்லிம்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் அறப்போர்களுக்குச் செல்வது வழக்கம். அப்போது அவர்கள் தங்களுக்கு நம்பிக்கையானவர்களிடம் சாவிகளைக் கொடுத்துவிட்டு, 'உங்களுக்குத் தேவையானவற்றை உண்ண நாங்கள் உங்களுக்கு அனுமதி அளிக்கிறோம்' என்று கூறுவார்கள். ஆனால் அவர்களோ, 'நாங்கள் உண்பது அனுமதிக்கப்பட்டதல்ல; அவர்கள் விருப்பமில்லாமலேயே நமக்கு அனுமதி அளித்துள்ளார்கள், நாங்கள் வெறும் காப்பாளர்கள் (அமானிததாரர்கள்) மட்டுமே' என்று கூறுவார்கள். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nأَوْ مَا مَلَكْتُم مَّفَاتِحَهُ\n\r\n\n\r\n\n\r\n(அல்லது எவற்றின் சாவிகளை நீங்கள் கைவசம் வைத்துள்ளீர்களோ (அந்த வீடுகளிலிருந்தும்)).\"\n\r\n\n\r\nأَوْ صَدِيقِكُمْ\n\r\n\n\r\n\n\r\n(அல்லது ஒரு நண்பனின் (வீட்டிலிருந்தும்).) அதாவது, அவர்களுடைய வீடுகளில் இருந்து நீங்கள் உண்பதால் உங்கள் மீது எந்தப் பாவமும் இல்லை; இது அவர்களுக்கு வருத்தத்தை ஏற்படுத்தாது என்றும், அவர்கள் இதை வெறுக்க மாட்டார்கள் என்றும் நீங்கள் அறிந்திருக்கும் வரை இது அனுமதிக்கப்பட்டதே.\n\r\n\n\r\nلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُواْ جَمِيعاً أَوْ أَشْتَاتاً\n\r\n\n\r\n\n\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.) இந்த வசனத்தைப் பற்றி அலீ பின் அபீ தல்ஹா (ரழி) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அல்லாஹ் இந்த வசனத்தை அருளியபோது:\n\r\n\n\r\nيَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ\n\r\n\n\r\n\n\r\n(ஈமான் கொண்டவர்களே! உங்களுடைய சொத்துக்களை உங்களுக்கிடையில் அநியாயமான முறையில் உண்ணாதீர்கள்) 4:29, முஸ்லிம்கள் கூறினார்கள்: 'நமக்கு மத்தியில் அநியாயமான முறையில் சொத்துக்களை உண்பதை அல்லாஹ் தடை செய்துள்ளான். உணவோ செல்வங்களில் மிகச் சிறந்தது. எனவே, நம்மில் யாரும் மற்றவரின் வீட்டில் உண்பது அனுமதிக்கப்பட்டதல்ல.' இதனால் மக்கள் மற்றவர் வீட்டில் உண்பதைத் தவிர்த்தனர். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nلَّيْسَ عَلَى الْأَعْمَىٰ حَرَجٌ\n\r\n\n\r\n\n\r\n(பார்வையற்றவர் மீது எந்தக் கட்டுப்பாடும் இல்லை,) அவனது கூற்றான... என்பது வரை;\n\r\n\n\r\nأَوْ صَدِيقِكُمْ\n\r\n\n\r\n\n\r\n(அல்லது ஒரு நண்பனின் (வீட்டிலிருந்தும்).) மேலும் ஒரு மனிதர் தனியாகச் சாப்பிடவும் சங்கடப்பட்டு, வேறு யாராவது வரும் வரை காத்திருப்பார். ஆனால் அல்லாஹ் அவர்களுக்கு இந்த விஷயத்தை எளிதாக்கி கூறினான்:\n\r\n\n\r\nلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُواْ جَمِيعاً أَوْ أَشْتَاتاً\n\r\n\n\r\n\n\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.)\" கதாதா (ரழி) கூறினார்கள்: \"ஜாஹிலிய்யா (அறியாமைக் காலம்) காலத்தில், பனூ கினானா கோத்திரத்தைச் சேர்ந்த ஒரு பிரிவினர் தனியாக உண்பதை ஒரு அவமானமாகக் கருதினர். எந்த அளவிற்கு என்றால், ஒரு மனிதன் பசியோடு இருந்தாலும், தன்னுடன் சேர்ந்து உண்ணவும் குடிக்கவும் எவரையாவது கண்டுபிடிக்கும் வரை தனது சுமை ஏற்றிய ஒட்டகத்தைச் செலுத்திக் கொண்டே இருப்பான். அப்போது அல்லாஹ் அருளினான்:\n\r\n\n\r\nلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُواْ جَمِيعاً أَوْ أَشْتَاتاً\n\r\n\n\r\n\n\r\n(நீங்கள் ஒன்று கூடி உண்டாலும் சரி, அல்லது தனித்தனியாக உண்டாலும் சரி, உங்கள் மீது எந்தக் குற்றமும் இல்லை.) இது அல்லாஹ்விடமிருந்து வழங்கப்பட்ட ஒரு சலுகையாகும். மக்கள் தனியாகவோ அல்லது மற்றவர்களுடனோ சாப்பிட இது அனுமதி அளிக்கிறது. எனினும் மற்றவர்களுடன் சேர்ந்து உண்பது அதிக அருள் (பரக்கத்) வாய்ந்தது மற்றும் சிறந்தது ஆகும். இமாம் அஹ்மத் (ரஹ்) அவர்கள் வஹ்ஷி பின் ஹர்ப் (ரழி) அவர்கள் தனது தந்தை வழியாகத் தனது பாட்டனாரிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: ஒரு மனிதர் நபி (ஸல்) அவர்களிடம், 'நாங்கள் உண்கிறோம், ஆனால் எங்களுக்குத் திருப்தி ஏற்படுவதில்லை' என்று கூறினார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«لَعَلَّكُمْ تَأْكُلُونَ مُتَفَرِّقِينَ، اجْتَمِعُوا عَلَى طَعَامِكُمْ، وَاذْكُرُوا اسْمَ اللهِ، يُبَارَكْ لَكُمْ فِيهِ»\n\r\n\n\r\n\n\r\n(ஒருவேளை நீங்கள் தனித்தனியாக உண்ணக்கூடும். நீங்கள் ஒன்று சேர்ந்து உங்கள் உணவை உண்ணுங்கள், மேலும் அல்லாஹ்வின் திருப்பெயரைக் கூறுங்கள்; அவன் அந்த உணவில் உங்களுக்கு அருள் (பரக்கத்) செய்வான்.) இது அபூ தாவூத் மற்றும் இப்னு மாஜா ஆகிய நூல்களிலும் பதிவு செய்யப்பட்டுள்ளது. இப்னு மாஜா அவர்களும், ஸாலிம் (ரழி) தனது தந்தை வழியாக உமர் (ரழி) அவர்களிடமிருந்து அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«كُلُوا جَمِيعًا، وَلَا تَفَرَّقُوا، فَإِنَّ الْبَرَكَةَ مَعَ الْجَمَاعَةِ»\n\r\n\n\r\n\n\r\n(நீங்கள் ஒன்றாகச் சேர்ந்து உண்ணுங்கள், தனித்தனியாகப் பிரியாதீர்கள்; ஏனெனில் அருள் (பரக்கத்) என்பது கூட்டாக இருப்பதில்தான் உள்ளது.)\n\r\n\n\r\nفَإِذَا دَخَلْتُمْ بُيُوتاً فَسَلِّمُواْ عَلَى أَنفُسِكُمْ\n\r\n\n\r\n\n\r\n(ஆனால், நீங்கள் வீடுகளுக்குள் நுழையும்போது, ஒருவருக்கொருவர் ஸலாம் சொல்லிக் கொள்ளுங்கள்) ஸஈத் பின் ஜுபைர், அல்-ஹஸன் அல்-பஸரி, கதாதா மற்றும் அஸ்-ஸுஹ்ரி (ரழி) ஆகியோர், \"இதன் பொருள், ஒருவருக்கொருவர் ஸலாம் கூறி முகமன் தெரிவிப்பதாகும்\" என்று கூறினார்கள். இப்னு ஜுரைஜ் (ரழி) கூறினார்கள்: அபூ அஸ்-ஸுபைர் (ரழி) கூறினார்கள், \"ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள், 'நீங்கள் உங்கள் குடும்பத்தாரிடம் செல்லும்போது, அல்லாஹ்விடமிருந்து வழங்கப்பட்ட அருள்பெற்ற, நன்மையான வாழ்த்தைக் கூறி அவர்களுக்கு ஸலாம் சொல்லுங்கள்' என்று கூற நான் கேட்டேன். அவர் மேலும், 'இது கடமையான ஒன்றைத் தவிர வேறில்லை என்று நான் கருதுகிறேன்' என்றும் கூறினார்கள்.\" இப்னு ஜுரைஜ் (ரழி) மேலும் கூறினார்கள்: \"ஜியாத் (ரழி) அவர்கள், இப்னு தாவூஸ் (ரழி) அவர்கள் இவ்வாறு கூறுவார்கள் என்று சொன்னார்கள்: 'உங்களில் ஒருவர் தனது வீட்டிற்குள் நுழையும்போது, அவர் ஸலாம் கூறட்டும்.'\" முஜாஹித் (ரழி) கூறினார்கள்: \"நீங்கள் மஸ்ஜிதிற்குள் நுழையும்போது, 'அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மீது சாந்தி உண்டாவதாக' என்று கூறுங்கள். உங்கள் குடும்பத்தினரிடம் செல்லும்போது அவர்களுக்கு ஸலாம் கூறுங்கள். எவருமில்லாத வீட்டிற்குள் நுழையும்போது, 'அஸ்ஸலாமு அலைனா வஅலா இபாதில்லாஹிஸ் ஸாலிஹீன்' (எங்கள் மீதும் அல்லாஹ்வின் நல்லடியார்கள் மீதும் சாந்தி உண்டாவதாக) என்று கூறுங்கள். இவ்வாறு செய்யவே ஒருவருக்குக் கட்டளையிடப்பட்டுள்ளது. மேலும் வானவர்கள் அந்த ஸலாமிற்குப் பதிலளிப்பார்கள் என்று எங்களுக்கு அறிவிக்கப்பட்டுள்ளது.\"\n\r\n\n\r\nكَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَعْقِلُونَ\n\r\n\n\r\n\n\r\n(நீங்கள் புரிந்து கொள்வதற்காக அல்லாஹ் இவ்வாறு உங்களுக்குத் தனது வசனங்களை (ஆயத்களை) தெளிவுபடுத்துகிறான்.) இந்தச் சூராவில் இடம்பெற்றுள்ள ஞானமிக்க தீர்ப்புகளையும், நியாயமான மற்றும் நேர்த்தியாகக் கட்டமைக்கப்பட்ட சட்டங்களையும் குறிப்பிட்ட பிறகு, அல்லாஹ் தனது அடியார்களுக்குத் தனது வசனங்களைத் தெளிவாக விளக்குகிறான்; அவர்கள் அவற்றைச் சிந்தித்து அதன் அர்த்தங்களைப் புரிந்து கொள்வதற்காகவே இவ்வாறு சுட்டிக்காட்டுகிறான்."},"62":{"html":"<strong>பொதுவான காரியங்களில் ஒன்றாக இருக்கும்போது வெளியேற அனுமதி கோருதல்</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் இறைநம்பிக்கையுள்ள அடியார்களுக்குக் கற்றுக்கொடுத்த மற்றுமொரு ஒழுக்கமுறை இதுவாகும். உள்ளே நுழையும்போது அனுமதி கேட்க வேண்டும் என்று அவன் கட்டளையிட்டது போலவே, அங்கிருந்து வெளியேறும்போதும் அனுமதி கேட்க வேண்டும் என்று அல்லாஹ் கட்டளையிட்டான். குறிப்பாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஜும்ஆ, பெருநாள், ஜமாஅத் தொழுகைகள் அல்லது ஆலோசனைக் கூட்டங்கள் போன்ற காரியங்களில் ஒன்றாக ஈடுபட்டிருக்கும்போது இது மிக அவசியமாகும். இத்தகைய சூழல்களில், அவரிடம் அனுமதி பெறாமல் அவரை விட்டுச் செல்ல வேண்டாம் என்று அல்லாஹ் அவர்களுக்குக் கட்டளையிட்டான். அவர்கள் இவ்வாறு செய்தால், அவர்களே உண்மையான இறைநம்பிக்கையாளர்கள் ஆவர். பின்னர், எவராவது அனுமதி கேட்டால், அவர்களில் தான் விரும்பியவர்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதி வழங்கலாம் என்று அல்லாஹ் கட்டளையிட்டான். அவன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأْذَن</span> <span class=\"quran-arabic-font text-success\">لِّمَن</span> <span class=\"quran-arabic-font text-success\">شِئْتَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span><br />\r\n<br />\r\n(அவர்களில் நீர் விரும்பியவர்களுக்கு அனுமதி அளிப்பீராக; மேலும் அவர்களுக்காக அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவீராக.)<br />\r\n<br />\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக அபூ தாவூத் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">انْتَهَى</span> <span class=\"quran-arabic-font text-success\">أَحَدُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْمَجْلِسِ</span> <span class=\"quran-arabic-font text-success\">فَلْيُسَلِّمْ،</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَقُومَ</span> <span class=\"quran-arabic-font text-success\">فَلْيُسَلِّمْ،</span> <span class=\"quran-arabic-font text-success\">فَلَيْسَتِ</span> <span class=\"quran-arabic-font text-success\">الْأُولَى</span> <span class=\"quran-arabic-font text-success\">بِأَحَقَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةِ</span>»<br />\r\n<br />\r\n(உங்களில் ஒருவர் ஒரு சபைக்கு வந்தால் ஸலாம் கூறட்டும்; அவர் அங்கிருந்து கிளம்ப விரும்பினாலும் ஸலாம் கூறட்டும். ஏனெனில், முதலாவது ஸலாம் பிந்தையதை விட அதிக முக்கியத்துவம் வாய்ந்தது அல்ல.)\" இதனை திர்மிதீ மற்றும் நஸயீ ஆகியோரும் பதிவு செய்துள்ளனர். \"இது ஒரு ஹஸன் ஹதீஸ்\" என்று திர்மிதீ அவர்கள் கூறினார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"பொதுவான காரியங்களில் ஒன்றாக இருக்கும்போது வெளியேற அனுமதி கோருதல்\n\r\n\n\r\nஅல்லாஹ் தன் இறைநம்பிக்கையுள்ள அடியார்களுக்குக் கற்றுக்கொடுத்த மற்றுமொரு ஒழுக்கமுறை இதுவாகும். உள்ளே நுழையும்போது அனுமதி கேட்க வேண்டும் என்று அவன் கட்டளையிட்டது போலவே, அங்கிருந்து வெளியேறும்போதும் அனுமதி கேட்க வேண்டும் என்று அல்லாஹ் கட்டளையிட்டான். குறிப்பாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஜும்ஆ, பெருநாள், ஜமாஅத் தொழுகைகள் அல்லது ஆலோசனைக் கூட்டங்கள் போன்ற காரியங்களில் ஒன்றாக ஈடுபட்டிருக்கும்போது இது மிக அவசியமாகும். இத்தகைய சூழல்களில், அவரிடம் அனுமதி பெறாமல் அவரை விட்டுச் செல்ல வேண்டாம் என்று அல்லாஹ் அவர்களுக்குக் கட்டளையிட்டான். அவர்கள் இவ்வாறு செய்தால், அவர்களே உண்மையான இறைநம்பிக்கையாளர்கள் ஆவர். பின்னர், எவராவது அனுமதி கேட்டால், அவர்களில் தான் விரும்பியவர்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதி வழங்கலாம் என்று அல்லாஹ் கட்டளையிட்டான். அவன் கூறினான்:\n\r\n\n\r\nفَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللَّهَ\n\r\n\n\r\n(அவர்களில் நீர் விரும்பியவர்களுக்கு அனுமதி அளிப்பீராக; மேலும் அவர்களுக்காக அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவீராக.)\n\r\n\n\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாக அபூ தாவூத் பதிவு செய்துள்ளார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا انْتَهَى أَحَدُكُمْ إِلَى الْمَجْلِسِ فَلْيُسَلِّمْ، فَإِذَا أَرَادَ أَنْ يَقُومَ فَلْيُسَلِّمْ، فَلَيْسَتِ الْأُولَى بِأَحَقَّ مِنَ الْآخِرَةِ»\n\r\n\n\r\n(உங்களில் ஒருவர் ஒரு சபைக்கு வந்தால் ஸலாம் கூறட்டும்; அவர் அங்கிருந்து கிளம்ப விரும்பினாலும் ஸலாம் கூறட்டும். ஏனெனில், முதலாவது ஸலாம் பிந்தையதை விட அதிக முக்கியத்துவம் வாய்ந்தது அல்ல.)\" இதனை திர்மிதீ மற்றும் நஸயீ ஆகியோரும் பதிவு செய்துள்ளனர். \"இது ஒரு ஹஸன் ஹதீஸ்\" என்று திர்மிதீ அவர்கள் கூறினார்கள்."},"63":{"html":"<strong>நபியவர்களை அழைக்கும் ஒழுங்குமுறை</strong><br />\r\n<br />\r\nஅத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"மக்கள் (முன்பு) 'யா முஹம்மத்' அல்லது 'யா அபுல் காசிம்' என்று அழைத்து வந்தனர். ஆனால் அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்குக் கண்ணியம் அளிக்கும் விதமாக அவ்வாறு அழைப்பதைத் தடுத்தான். மேலும், 'யா நபியல்லாஹ் (அல்லாஹ்வின் நபியே)', 'யா ரசூலல்லாஹ் (அல்லாஹ்வின் தூதரே)' என்று அழைக்குமாறு அவர்களுக்குக் கட்டளையிட்டான்.\" இதுவே முஜாஹித் மற்றும் ஸஈத் பின் ஜுபைர் ஆகியோரின் கருத்துமாகும். கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ் தனது நபி (ஸல்) அவர்களைக் கண்ணியத்துடனும் மரியாதையுடனும் நடத்தப்பட வேண்டும் என்றும், அவர்கள் ஒரு தலைவராக மதிக்கப்பட வேண்டும் என்றும் கட்டளையிட்டான்.\" முகாத்தில் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறும்போது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلُواْ</span> <span class=\"quran-arabic-font text-success\">دُعَآءَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">كَدُعَآءِ</span> <span class=\"quran-arabic-font text-success\">بَعْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span><br />\r\n<br />\r\n(உங்களிடையே தூதரை அழைப்பதை, உங்களில் ஒருவர் மற்றவரை அழைப்பதைப் போன்று ஆக்காதீர்கள்.) \"நீங்கள் அவர்களை அழைக்கும்போது, 'யா முஹம்மத்' என்றோ அல்லது 'யா இப்னு அப்தில்லாஹ் (அப்துல்லாஹ்வின் மகனே)' என்றோ கூறாதீர்கள்; மாறாக, அவர்களுக்குக் கண்ணியம் அளித்து 'யா நபியல்லாஹ்' அல்லது 'யா ரசூலல்லாஹ்' என்று கூறுங்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَجْعَلُواْ</span> <span class=\"quran-arabic-font text-success\">دُعَآءَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">بَيْنَكُمْ</span> <span class=\"quran-arabic-font text-success\">كَدُعَآءِ</span> <span class=\"quran-arabic-font text-success\">بَعْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">بَعْضاً</span><br />\r\n<br />\r\n(உங்களிடையே தூதரை அழைப்பதை, உங்களில் ஒருவர் மற்றவரை அழைப்பதைப் போன்று ஆக்காதீர்கள்.) இந்த வசனத்திற்குச் சொல்லப்பட்ட இரண்டாவது கருத்து என்னவென்றால், \"அவர்கள் உங்களுக்கு எதிராகப் பிரார்த்தித்தால் (துஆச் செய்தால்), அது மற்றவர்கள் உங்களுக்கு எதிராகப் பிரார்த்திப்பதைப் போன்றது என்று எண்ணாதீர்கள்; ஏனெனில் அவர்களின் பிரார்த்தனைக்கு அல்லாஹ்விடம் பதில் அளிக்கப்படும். எனவே, அவர்கள் உங்களுக்கு எதிராகப் பிரார்த்தித்து, நீங்கள் அழிந்துவிட நேரிடும் என்பதில் எச்சரிக்கையாக இருங்கள்.\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன் அல்-பஸ்ரீ மற்றும் அதிய்யா அல்-அவ்ஃபீ ஆகியோரிடமிருந்து பதிவு செய்துள்ளார்கள். அல்லாஹ்வே மிக அறிந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَتَسَلَّلُونَ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">لِوَاذاً</span><br />\r\n<br />\r\n(உங்களிலிருந்து மறைந்து நழுவிச் செல்பவர்களைத் திண்ணமாக அல்லாஹ் அறிவான்.) முகாத்தில் பின் ஹய்யான் அவர்கள் கூறினார்கள்: \"இது வெள்ளிக்கிழமை குத்பாவைக் (சொற்பொழிவை) கேட்பதைச் சிரமமாகக் கருதிய நயவஞ்சகர்களைக் குறிக்கிறது. அவர்கள் முஹம்மது (ஸல்) அவர்களின் ஸஹாபாக்களில் சிலருக்குப் பின்னால் ஒளிந்துகொண்டு மஸ்ஜிதை விட்டு நழுவிச் செல்வார்கள். வெள்ளிக்கிழமைகளில் குத்பா தொடங்கிவிட்டால், நபி (ஸல்) அவர்களிடம் அனுமதி பெறாமல் ஒரு மனிதர் வெளியேறுவது முறையானதல்ல. அவர்களில் எவரேனும் வெளியேற விரும்பினால், அவர் நபி (ஸல்) அவர்களுக்குத் தனது விரலால் சைகை காட்டுவார்; அந்த மனிதர் பேசாமலேயே நபி (ஸல்) அவர்கள் அனுமதி அளிப்பார்கள். ஏனெனில், நபி (ஸல்) அவர்கள் குத்பா நிகழ்த்திக் கொண்டிருக்கும்போது யாரேனும் பேசினால், அது அவரது ஜும்ஆ தொழுகையைச் செல்லாததாக்கிவிடும்.\" அஸ்-ஸுத்தீ அவர்கள் கூறினார்கள்: \"அவர்கள் ஜமாஅத் தொழுகையில் இருக்கும்போது, நபி (ஸல்) அவர்கள் தங்களைக் காணாதவாறு ஒருவருக்கொருவர் பின்னால் ஒளிந்து கொள்வார்கள்.\"<br />\r\n<br />\r\n<strong>தூதரின் கட்டளைக்கு மாறு செய்வதற்கான தடை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلْيَحْذَرِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُخَالِفُونَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">أَمْرِهِ</span><br />\r\n<br />\r\n(தூதரின் கட்டளைக்கு மாறு செய்பவர்கள் எச்சரிக்கையாக இருக்கட்டும்.) இதன் பொருள் நபி (ஸல்) அவர்களின் கட்டளைக்கு, அதாவது அவர்களின் வழிமுறை, நெறிமுறை மற்றும் சுன்னாவிற்கு மாறு செய்வதாகும். அனைத்துக் கருத்துகளும் செயல்களும் நபி (ஸல்) அவர்களின் வாக்குகள் மற்றும் செயல்களுடன்தான் ஒப்பிடப்படும். அவற்றுடன் இணங்குபவை மட்டுமே ஏற்றுக்கொள்ளப்படும். அவ்வாறு பொருந்தாதவை, அதைச் செய்தவர் எவராக இருந்தாலும் அவை நிராகரிக்கப்படும். ஸஹீஹைன் (புகாரி, முஸ்லிம்) மற்றும் இதர நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">عَمَلًا</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَا</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">رَدٌّ</span>»<br />\r\n<br />\r\n(நமது இந்த மார்க்க விவகாரத்தில் இல்லாத ஒரு செயலை யார் செய்கிறாரோ, அது நிராகரிக்கப்படும்.) அதாவது, தூதரின் ஷரீஆவிற்கு (மார்க்க சட்டத்திற்கு) இரகசியமாகவும் வெளிப்படையாகவும் மாறு செய்பவர்கள் எச்சரிக்கையாக இருக்கட்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُصِيبَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةٌ</span><br />\r\n<br />\r\n(ஏதேனும் ஃபித்னா அவர்களைப் பிடித்துக்கொள்ளும் என்பதற்காக), அதாவது இறைநிராகரிப்பு, நயவஞ்சகம் அல்லது பித்அத் (மார்க்கத்தில் புதுமை) போன்றவை அவர்களின் இதயங்களில் நுழைந்துவிடும் என்பதை அவர்கள் அஞ்சட்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يُصِيبَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span><br />\r\n<br />\r\n(அல்லது ஒரு துன்புறுத்தும் வேதனை அவர்களைப் பிடித்துக்கொள்ளும்.) இதன் பொருள் இவ்வுலகிலேயே அவர்களுக்கு மரண தண்டனை, குற்றவியல் தண்டனைகள், சிறைவாசம் அல்லது அது போன்ற சோதனைகள் ஏற்படக்கூடும் என்பதாகும். இமாம் அஹ்மத் அவர்கள் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَثَلِي</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">كَمَثَلِ</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">اسْتَوْقَدَ</span> <span class=\"quran-arabic-font text-success\">نَارًا</span> <span class=\"quran-arabic-font text-success\">فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">أَضَاءَتْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">حَوْلَهَا</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">الْفَرَاشُ</span> <span class=\"quran-arabic-font text-success\">وَهَذِهِ</span> <span class=\"quran-arabic-font text-success\">الدَّوَابُّ</span> <span class=\"quran-arabic-font text-success\">اللَّائِي</span> <span class=\"quran-arabic-font text-success\">يَقَعْنَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">يَقَعْنَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا،</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">يَحْجُزُهُنَّ</span> <span class=\"quran-arabic-font text-success\">وَيَغْلِبْنَهُ</span> <span class=\"quran-arabic-font text-success\">فَيَقْتَحِمْنَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">فَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">مَثَلِي</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُكُمْ،</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">آخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِحُجَزِكُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">هَلُمَّ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">فَتَغْلِبُونِي</span> <span class=\"quran-arabic-font text-success\">وَتَقْتَحِمُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span>»<br />\r\n<br />\r\n(எனக்கும் உங்களுக்குமான உதாரணம், ஒரு மனிதர் நெருப்பை மூட்டியதைப் போன்றதாகும். அந்த நெருப்பு தன்னைச் சுற்றியுள்ளவற்றை ஒளிரச் செய்தபோது, விட்டில் பூச்சிகளும் மற்றப் பூச்சிகளும் அந்த நெருப்பில் வந்து விழத் தொடங்கின. அவர் அவற்றைத் தடுக்க முயன்றார், ஆனால் அவை அவரை மீறி நெருப்புக்குள் விழுந்தன. இதுவே எனக்கும் உங்களுக்குமான உதாரணம். நான் உங்களைக் கட்டுப்படுத்தி நெருப்பிலிருந்து விலக்கி வைக்க முயற்சிக்கிறேன், ஆனால் நீங்களோ என்னை மீறி அதில் போய் விழுகிறீர்கள்.) இதனைப் புகாரி மற்றும் முஸ்லிம் ஆகியோரும் அறிவித்துள்ளனர். இத்துடன் அன்-நூர் அத்தியாயத்தின் விரிவுரை நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியன.<br />\r\n<br />","text":"நபியவர்களை அழைக்கும் ஒழுங்குமுறை\n\r\n\n\r\nஅத்-தஹ்ஹாக் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிப்பதாவது: \"மக்கள் (முன்பு) 'யா முஹம்மத்' அல்லது 'யா அபுல் காசிம்' என்று அழைத்து வந்தனர். ஆனால் அல்லாஹ் தனது நபி (ஸல்) அவர்களுக்குக் கண்ணியம் அளிக்கும் விதமாக அவ்வாறு அழைப்பதைத் தடுத்தான். மேலும், 'யா நபியல்லாஹ் (அல்லாஹ்வின் நபியே)', 'யா ரசூலல்லாஹ் (அல்லாஹ்வின் தூதரே)' என்று அழைக்குமாறு அவர்களுக்குக் கட்டளையிட்டான்.\" இதுவே முஜாஹித் மற்றும் ஸஈத் பின் ஜுபைர் ஆகியோரின் கருத்துமாகும். கத்தாதா அவர்கள் கூறினார்கள்: \"அல்லாஹ் தனது நபி (ஸல்) அவர்களைக் கண்ணியத்துடனும் மரியாதையுடனும் நடத்தப்பட வேண்டும் என்றும், அவர்கள் ஒரு தலைவராக மதிக்கப்பட வேண்டும் என்றும் கட்டளையிட்டான்.\" முகாத்தில் அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறும்போது:\n\r\n\n\r\nلَا تَجْعَلُواْ دُعَآءَ الرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُمْ بَعْضاً\n\r\n\n\r\n(உங்களிடையே தூதரை அழைப்பதை, உங்களில் ஒருவர் மற்றவரை அழைப்பதைப் போன்று ஆக்காதீர்கள்.) \"நீங்கள் அவர்களை அழைக்கும்போது, 'யா முஹம்மத்' என்றோ அல்லது 'யா இப்னு அப்தில்லாஹ் (அப்துல்லாஹ்வின் மகனே)' என்றோ கூறாதீர்கள்; மாறாக, அவர்களுக்குக் கண்ணியம் அளித்து 'யா நபியல்லாஹ்' அல்லது 'யா ரசூலல்லாஹ்' என்று கூறுங்கள்.\"\n\r\n\n\r\nلَا تَجْعَلُواْ دُعَآءَ الرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُمْ بَعْضاً\n\r\n\n\r\n(உங்களிடையே தூதரை அழைப்பதை, உங்களில் ஒருவர் மற்றவரை அழைப்பதைப் போன்று ஆக்காதீர்கள்.) இந்த வசனத்திற்குச் சொல்லப்பட்ட இரண்டாவது கருத்து என்னவென்றால், \"அவர்கள் உங்களுக்கு எதிராகப் பிரார்த்தித்தால் (துஆச் செய்தால்), அது மற்றவர்கள் உங்களுக்கு எதிராகப் பிரார்த்திப்பதைப் போன்றது என்று எண்ணாதீர்கள்; ஏனெனில் அவர்களின் பிரார்த்தனைக்கு அல்லாஹ்விடம் பதில் அளிக்கப்படும். எனவே, அவர்கள் உங்களுக்கு எதிராகப் பிரார்த்தித்து, நீங்கள் அழிந்துவிட நேரிடும் என்பதில் எச்சரிக்கையாக இருங்கள்.\" இதனை இப்னு அபீ ஹாதிம் அவர்கள் இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன் அல்-பஸ்ரீ மற்றும் அதிய்யா அல்-அவ்ஃபீ ஆகியோரிடமிருந்து பதிவு செய்துள்ளார்கள். அல்லாஹ்வே மிக அறிந்தவன்.\n\r\n\n\r\nقَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذاً\n\r\n\n\r\n(உங்களிலிருந்து மறைந்து நழுவிச் செல்பவர்களைத் திண்ணமாக அல்லாஹ் அறிவான்.) முகாத்தில் பின் ஹய்யான் அவர்கள் கூறினார்கள்: \"இது வெள்ளிக்கிழமை குத்பாவைக் (சொற்பொழிவை) கேட்பதைச் சிரமமாகக் கருதிய நயவஞ்சகர்களைக் குறிக்கிறது. அவர்கள் முஹம்மது (ஸல்) அவர்களின் ஸஹாபாக்களில் சிலருக்குப் பின்னால் ஒளிந்துகொண்டு மஸ்ஜிதை விட்டு நழுவிச் செல்வார்கள். வெள்ளிக்கிழமைகளில் குத்பா தொடங்கிவிட்டால், நபி (ஸல்) அவர்களிடம் அனுமதி பெறாமல் ஒரு மனிதர் வெளியேறுவது முறையானதல்ல. அவர்களில் எவரேனும் வெளியேற விரும்பினால், அவர் நபி (ஸல்) அவர்களுக்குத் தனது விரலால் சைகை காட்டுவார்; அந்த மனிதர் பேசாமலேயே நபி (ஸல்) அவர்கள் அனுமதி அளிப்பார்கள். ஏனெனில், நபி (ஸல்) அவர்கள் குத்பா நிகழ்த்திக் கொண்டிருக்கும்போது யாரேனும் பேசினால், அது அவரது ஜும்ஆ தொழுகையைச் செல்லாததாக்கிவிடும்.\" அஸ்-ஸுத்தீ அவர்கள் கூறினார்கள்: \"அவர்கள் ஜமாஅத் தொழுகையில் இருக்கும்போது, நபி (ஸல்) அவர்கள் தங்களைக் காணாதவாறு ஒருவருக்கொருவர் பின்னால் ஒளிந்து கொள்வார்கள்.\"\n\r\n\n\r\nதூதரின் கட்டளைக்கு மாறு செய்வதற்கான தடை\n\r\n\n\r\nفَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ\n\r\n\n\r\n(தூதரின் கட்டளைக்கு மாறு செய்பவர்கள் எச்சரிக்கையாக இருக்கட்டும்.) இதன் பொருள் நபி (ஸல்) அவர்களின் கட்டளைக்கு, அதாவது அவர்களின் வழிமுறை, நெறிமுறை மற்றும் சுன்னாவிற்கு மாறு செய்வதாகும். அனைத்துக் கருத்துகளும் செயல்களும் நபி (ஸல்) அவர்களின் வாக்குகள் மற்றும் செயல்களுடன்தான் ஒப்பிடப்படும். அவற்றுடன் இணங்குபவை மட்டுமே ஏற்றுக்கொள்ளப்படும். அவ்வாறு பொருந்தாதவை, அதைச் செய்தவர் எவராக இருந்தாலும் அவை நிராகரிக்கப்படும். ஸஹீஹைன் (புகாரி, முஸ்லிம்) மற்றும் இதர நூல்களில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ»\n\r\n\n\r\n(நமது இந்த மார்க்க விவகாரத்தில் இல்லாத ஒரு செயலை யார் செய்கிறாரோ, அது நிராகரிக்கப்படும்.) அதாவது, தூதரின் ஷரீஆவிற்கு (மார்க்க சட்டத்திற்கு) இரகசியமாகவும் வெளிப்படையாகவும் மாறு செய்பவர்கள் எச்சரிக்கையாக இருக்கட்டும்.\n\r\n\n\r\nأَن تُصِيبَهُمْ فِتْنَةٌ\n\r\n\n\r\n(ஏதேனும் ஃபித்னா அவர்களைப் பிடித்துக்கொள்ளும் என்பதற்காக), அதாவது இறைநிராகரிப்பு, நயவஞ்சகம் அல்லது பித்அத் (மார்க்கத்தில் புதுமை) போன்றவை அவர்களின் இதயங்களில் நுழைந்துவிடும் என்பதை அவர்கள் அஞ்சட்டும்.\n\r\n\n\r\nأَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ\n\r\n\n\r\n(அல்லது ஒரு துன்புறுத்தும் வேதனை அவர்களைப் பிடித்துக்கொள்ளும்.) இதன் பொருள் இவ்வுலகிலேயே அவர்களுக்கு மரண தண்டனை, குற்றவியல் தண்டனைகள், சிறைவாசம் அல்லது அது போன்ற சோதனைகள் ஏற்படக்கூடும் என்பதாகும். இமாம் அஹ்மத் அவர்கள் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«مَثَلِي وَمَثَلُكُمْ كَمَثَلِ رَجُلٍ اسْتَوْقَدَ نَارًا فَلَمَّا أَضَاءَتْ مَا حَوْلَهَا جَعَلَ الْفَرَاشُ وَهَذِهِ الدَّوَابُّ اللَّائِي يَقَعْنَ فِي النَّارِ يَقَعْنَ فِيهَا، وَجَعَلَ يَحْجُزُهُنَّ وَيَغْلِبْنَهُ فَيَقْتَحِمْنَ فِيهَا قَالَ: فَذَلِكَ مَثَلِي وَمَثَلُكُمْ، أَنَا آخِذٌ بِحُجَزِكُمْ عَنِ النَّارِ هَلُمَّ عَنِ النَّارِ، فَتَغْلِبُونِي وَتَقْتَحِمُونَ فِيهَا»\n\r\n\n\r\n(எனக்கும் உங்களுக்குமான உதாரணம், ஒரு மனிதர் நெருப்பை மூட்டியதைப் போன்றதாகும். அந்த நெருப்பு தன்னைச் சுற்றியுள்ளவற்றை ஒளிரச் செய்தபோது, விட்டில் பூச்சிகளும் மற்றப் பூச்சிகளும் அந்த நெருப்பில் வந்து விழத் தொடங்கின. அவர் அவற்றைத் தடுக்க முயன்றார், ஆனால் அவை அவரை மீறி நெருப்புக்குள் விழுந்தன. இதுவே எனக்கும் உங்களுக்குமான உதாரணம். நான் உங்களைக் கட்டுப்படுத்தி நெருப்பிலிருந்து விலக்கி வைக்க முயற்சிக்கிறேன், ஆனால் நீங்களோ என்னை மீறி அதில் போய் விழுகிறீர்கள்.) இதனைப் புகாரி மற்றும் முஸ்லிம் ஆகியோரும் அறிவித்துள்ளனர். இத்துடன் அன்-நூர் அத்தியாயத்தின் விரிவுரை நிறைவுற்றது. எல்லாப் புகழும் அல்லாஹ்வுக்கே உரியன."},"64":{"html":"<strong>அல்லாஹ் உங்கள் நிலையை அறிவான்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلاَ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ﴿</span><br />\r\n<br />\r\n(அறிந்து கொள்க! நிச்சயமாக வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அல்லாஹ்வுக்கே உரியன)<br />\r\n<br />\r\nவானங்கள் மற்றும் பூமியின் அதிபதி (மாலிக்) அவனே என்றும், அவன் மறைவானவற்றையும் வெளிப்படையானவற்றையும் அறிவான் என்றும் அல்லாஹ் நமக்குக் கூறுகிறான். தன் அடியார்கள் இரகசியமாகவும் பகிரங்கமாகவும் செய்வதை அவன் அறிவான். எனவே அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவன் உங்கள் நிலையை அறிவான்) அவன் அதை அறிகிறான்; அது அவனுக்குத் தெளிவாகத் தெரிகிறது, ஓர் அணுவளவும் அவனுக்குத் தெரியாமல் மறைந்திருப்பதில்லை. இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَتَوَكَّلْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(யாவற்றையும் மிகைத்தவனும், நிகரற்ற அன்புடையவனுமான அல்லாஹ்வின் மீது உமது பொறுப்பை ஒப்படைப்பீராக!) அவன் இவ்வாறு கூறும் வரை; <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவன், அவனே யாவற்றையும் செவியுறுபவன், மிக அறிந்தவன்) <a href=\"qurandisp.php?sura=26&ayah=217\" class=\"link\">26:217</a>-220. <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">شَأْنٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَتْلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قُرْءَانٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">شُهُودًا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تُفِيضُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَعْزُبُ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">مِّثْقَالِ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَصْغَرَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَلا</span> <span class=\"quran-arabic-font text-success\">أَكْبَرَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீர் எந்த நிலையில் இருந்தாலும், குர்ஆனிலிருந்து எதை ஓதினாலும், நீங்கள் எந்தச் செயலைச் செய்தாலும், நீங்கள் அதில் ஈடுபட்டிருக்கும்போது நாம் உங்களுக்குச் சாட்சியாகவே இருக்கிறோம். உமது இறைவனிடமிருந்து பூமியிலோ அல்லது வானத்திலோ உள்ள ஓர் அணுவளவும் மறைந்திருப்பதில்லை. அதைவிடச் சிறியதோ அல்லது பெரியதோ எதுவாக இருந்தாலும், அவை ஒரு தெளிவான பதிவேட்டில் இல்லாமல் இல்லை.) <a href=\"qurandisp.php?sura=10&ayah=61\" class=\"link\">10:61</a> <span class=\"quran-arabic-font text-success\">﴾أَفَمَنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَآئِمٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">نَفْسٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَسَبَتْ﴿</span><br />\r\n<br />\r\n(ஒவ்வோர் ஆத்மாவும் சம்பாதித்ததைக் கண்காணிப்பவன் (அல்லாஹ்), பிறருக்குச் சமமாவானா?) <a href=\"qurandisp.php?sura=13&ayah=33\" class=\"link\">13:33</a> தன் அடியார்கள் செய்யும் நன்மை மற்றும் தீமை என அனைத்தையும் அவன் காண்கிறான். மேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَلا</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَغْشُونَ</span> <span class=\"quran-arabic-font text-success\">ثِيَابَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يُسِرُّونَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يُعْلِنُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் தங்கள் ஆடைகளால் தங்களை மூடிக்கொள்ளும்போதும், அவர்கள் இரகசியமாக வைப்பதையும் பகிரங்கமாக வெளிப்படுத்துவதையும் அவன் அறிவான்) <a href=\"qurandisp.php?sura=11&ayah=5\" class=\"link\">11:5</a>. <span class=\"quran-arabic-font text-success\">﴾سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّنْ</span> <span class=\"quran-arabic-font text-success\">أَسَرَّ</span> <span class=\"quran-arabic-font text-success\">الْقَوْلَ</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">جَهَرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(உங்களில் எவரேனும் தனது பேச்சை இரகசியமாக வைத்தாலும் அல்லது பகிரங்கமாக வெளிப்படுத்தினாலும் (அவனுக்கு) அது சமமே) <a href=\"qurandisp.php?sura=13&ayah=10\" class=\"link\">13:10</a>. <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَآبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">رِزْقُهَا</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرَّهَا</span> <span class=\"quran-arabic-font text-success\">وَمُسْتَوْدَعَهَا</span> <span class=\"quran-arabic-font text-success\">كُلٌّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَابٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமும் அல்லாஹ்விடமிருந்து அதன் வாழ்வாதாரம் கிடைக்காமல் இல்லை. அதன் வசிப்பிடத்தையும் அது ஒப்படைக்கப்படும் இடத்தையும் அவன் அறிவான். இவை அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.) <a href=\"qurandisp.php?sura=11&ayah=6\" class=\"link\">11:6</a> <span class=\"quran-arabic-font text-success\">﴾وَعِندَهُ</span> <span class=\"quran-arabic-font text-success\">مَفَاتِحُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْبِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">وَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبَرِّ</span> <span class=\"quran-arabic-font text-success\">وَالْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْقُطُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَقَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُهَا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">حَبَّةٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ظُلُمَـتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">رَطْبٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَابِسٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كِتَـبٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மறைவானவற்றின் சாவிகள் அவனிடமே உள்ளன; அவனைத் தவிர வேறு யாரும் அவற்றை அறியமாட்டார்கள். நிலத்திலும் கடலிலும் உள்ளவற்றை அவன் அறிவான்; ஓர் இலை உதிர்ந்தாலும் அதை அவன் அறியாமல் இருப்பதில்லை. பூமியின் இருள்களில் உள்ள ஒரு தானியமோ, ஈரமானதோ அல்லது காய்ந்ததோ எதுவாக இருந்தாலும், அவை ஒரு தெளிவான பதிவேட்டில் இல்லாமல் இல்லை.) <a href=\"qurandisp.php?sura=6&ayah=59\" class=\"link\">6:59</a> இது போன்ற கருத்துகளைக் கூறும் இன்னும் பல வசனங்களும் ஹதீஸ்களும் உள்ளன. <span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُرْجَعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ﴿</span><br />\r\n<br />\r\n(அவர்கள் அவனிடம் திரும்பக் கொண்டுவரப்படும் நாளில்,) என்பது, அனைத்துப் படைப்புகளும் அல்லாஹ்விடம் திரும்பக் கொண்டுவரப்படும் மறுமை நாளைக் குறிக்கிறது. <span class=\"quran-arabic-font text-success\">﴾فَيُنَبِّئُهُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ﴿</span><br />\r\n<br />\r\n(பிறகு அவர்கள் செய்தவற்றை அவன் அவர்களுக்கு அறிவிப்பான்.) அதாவது, அவர்கள் இவ்வுலக வாழ்வில் செய்த சிறியது, பெரியது, முக்கியமானது, அற்பமானது என அனைத்தையும் அவன் அவர்களுக்கு எடுத்துரைப்பான். அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾يُنَبَّأُ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">قَدَّمَ</span> <span class=\"quran-arabic-font text-success\">وَأَخَّرَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில் மனிதன் எதை முற்படுத்தினான், எதைப் பின்னுக்குத் தள்ளினான் என்பது குறித்து அவனுக்கு அறிவிக்கப்படும்.) <a href=\"qurandisp.php?sura=75&ayah=13\" class=\"link\">75:13</a> <span class=\"quran-arabic-font text-success\">﴾وَوُضِعَ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبُ</span> <span class=\"quran-arabic-font text-success\">فَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">مُشْفِقِينَ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">وَيْلَتَنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُغَادِرُ</span> <span class=\"quran-arabic-font text-success\">صَغِيرَةً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">كَبِيرَةً</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَحْصَاهَا</span> <span class=\"quran-arabic-font text-success\">وَوَجَدُواْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">حَاضِرًا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَظْلِمُ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">أَحَدًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அங்கு பதிவேடு வைக்கப்படும். அப்போது குற்றவாளிகள் அதில் உள்ளவற்றைக் கண்டு அச்சமடைவதை நீர் காண்பீர். \"எங்களுக்கு ஏற்பட்ட கேட்டையே! இது என்ன புத்தகம்? சிறியதையோ பெரியதையோ விட்டுவைக்காமல் அனைத்தையும் கணக்கிட்டுப் பதிவு செய்துள்ளதே!\" என்று அவர்கள் கூறுவார்கள். மேலும் அவர்கள் செய்தவை அனைத்தும் தங்களுக்கு முன்னால் வைக்கப்பட்டிருப்பதைக் காண்பார்கள். உமது இறைவன் எவருக்கும் அநீதி இழைக்கமாட்டான்.) <a href=\"qurandisp.php?sura=18&ayah=49\" class=\"link\">18:49</a> அல்லாஹ் இங்கே கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُرْجَعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فَيُنَبِّئُهُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمُ﴿</span><br />\r\n<br />\r\n(அவர்கள் அவனிடம் திரும்பக் கொண்டுவரப்படும் நாளில், அவர்கள் செய்தவற்றை அவன் அவர்களுக்கு அறிவிப்பான். மேலும் அல்லாஹ் அனைத்துப் பொருட்களையும் மிக அறிந்தவன்.)<br />\r\n<br />\r\nஅகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே எல்லாப் புகழும். பரிபூரண நிலையை அடைய எங்களுக்கு உதவுமாறு அவனிடம் வேண்டுகிறோம். ஸூரத்துந் நூர் தஃப்ஸீர் இத்துடன் நிறைவடைந்தது. அல்லாஹ்வுக்கே புகழும் நன்றியும் உரித்தாகட்டும்.<br />\r\n<br />","text":"அல்லாஹ் உங்கள் நிலையை அறிவான்\n\r\n\n\r\n﴾أَلاَ إِنَّ لِلَّهِ مَا فِى السَّمَـوَتِ وَالْأَرْضِ﴿\n\r\n\n\r\n(அறிந்து கொள்க! நிச்சயமாக வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அல்லாஹ்வுக்கே உரியன)\n\r\n\n\r\nவானங்கள் மற்றும் பூமியின் அதிபதி (மாலிக்) அவனே என்றும், அவன் மறைவானவற்றையும் வெளிப்படையானவற்றையும் அறிவான் என்றும் அல்லாஹ் நமக்குக் கூறுகிறான். தன் அடியார்கள் இரகசியமாகவும் பகிரங்கமாகவும் செய்வதை அவன் அறிவான். எனவே அவன் கூறுகிறான்: ﴾قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ﴿\n\r\n\n\r\n(நிச்சயமாக, அவன் உங்கள் நிலையை அறிவான்) அவன் அதை அறிகிறான்; அது அவனுக்குத் தெளிவாகத் தெரிகிறது, ஓர் அணுவளவும் அவனுக்குத் தெரியாமல் மறைந்திருப்பதில்லை. இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ ﴿\n\r\n\n\r\n(யாவற்றையும் மிகைத்தவனும், நிகரற்ற அன்புடையவனுமான அல்லாஹ்வின் மீது உமது பொறுப்பை ஒப்படைப்பீராக!) அவன் இவ்வாறு கூறும் வரை; ﴾إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ ﴿\n\r\n\n\r\n(நிச்சயமாக அவன், அவனே யாவற்றையும் செவியுறுபவன், மிக அறிந்தவன்) 26:217-220. ﴾وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُواْ مِنْهُ مِن قُرْءَانٍ وَلاَ تَعْمَلُونَ مِنْ عَمَلٍ إِلاَّ كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِي الْأَرْضِ وَلاَ فِى السَّمَآءِ وَلاَ أَصْغَرَ مِن ذَلِكَ وَلا أَكْبَرَ إِلاَّ فِى كِتَابٍ مُّبِينٍ ﴿\n\r\n\n\r\n(நீர் எந்த நிலையில் இருந்தாலும், குர்ஆனிலிருந்து எதை ஓதினாலும், நீங்கள் எந்தச் செயலைச் செய்தாலும், நீங்கள் அதில் ஈடுபட்டிருக்கும்போது நாம் உங்களுக்குச் சாட்சியாகவே இருக்கிறோம். உமது இறைவனிடமிருந்து பூமியிலோ அல்லது வானத்திலோ உள்ள ஓர் அணுவளவும் மறைந்திருப்பதில்லை. அதைவிடச் சிறியதோ அல்லது பெரியதோ எதுவாக இருந்தாலும், அவை ஒரு தெளிவான பதிவேட்டில் இல்லாமல் இல்லை.) 10:61 ﴾أَفَمَنْ هُوَ قَآئِمٌ عَلَى كُلِّ نَفْسٍ بِمَا كَسَبَتْ﴿\n\r\n\n\r\n(ஒவ்வோர் ஆத்மாவும் சம்பாதித்ததைக் கண்காணிப்பவன் (அல்லாஹ்), பிறருக்குச் சமமாவானா?) 13:33 தன் அடியார்கள் செய்யும் நன்மை மற்றும் தீமை என அனைத்தையும் அவன் காண்கிறான். மேலும் அல்லாஹ் கூறுகிறான்: ﴾أَلا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ﴿\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் தங்கள் ஆடைகளால் தங்களை மூடிக்கொள்ளும்போதும், அவர்கள் இரகசியமாக வைப்பதையும் பகிரங்கமாக வெளிப்படுத்துவதையும் அவன் அறிவான்) 11:5. ﴾سَوَآءٌ مِّنْكُمْ مَّنْ أَسَرَّ الْقَوْلَ وَمَنْ جَهَرَ بِهِ﴿\n\r\n\n\r\n(உங்களில் எவரேனும் தனது பேச்சை இரகசியமாக வைத்தாலும் அல்லது பகிரங்கமாக வெளிப்படுத்தினாலும் (அவனுக்கு) அது சமமே) 13:10. ﴾وَمَا مِن دَآبَّةٍ فِي الْأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَابٍ مُّبِينٍ ﴿\n\r\n\n\r\n(பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமும் அல்லாஹ்விடமிருந்து அதன் வாழ்வாதாரம் கிடைக்காமல் இல்லை. அதன் வசிப்பிடத்தையும் அது ஒப்படைக்கப்படும் இடத்தையும் அவன் அறிவான். இவை அனைத்தும் ஒரு தெளிவான பதிவேட்டில் உள்ளன.) 11:6 ﴾وَعِندَهُ مَفَاتِحُ الْغَيْبِ لاَ يَعْلَمُهَآ إِلاَّ هُوَ وَيَعْلَمُ مَا فِى الْبَرِّ وَالْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلاَّ يَعْلَمُهَا وَلاَ حَبَّةٍ فِى ظُلُمَـتِ الْأَرْضِ وَلاَ رَطْبٍ وَلاَ يَابِسٍ إِلاَّ فِى كِتَـبٍ مُّبِينٍ ﴿\n\r\n\n\r\n(மறைவானவற்றின் சாவிகள் அவனிடமே உள்ளன; அவனைத் தவிர வேறு யாரும் அவற்றை அறியமாட்டார்கள். நிலத்திலும் கடலிலும் உள்ளவற்றை அவன் அறிவான்; ஓர் இலை உதிர்ந்தாலும் அதை அவன் அறியாமல் இருப்பதில்லை. பூமியின் இருள்களில் உள்ள ஒரு தானியமோ, ஈரமானதோ அல்லது காய்ந்ததோ எதுவாக இருந்தாலும், அவை ஒரு தெளிவான பதிவேட்டில் இல்லாமல் இல்லை.) 6:59 இது போன்ற கருத்துகளைக் கூறும் இன்னும் பல வசனங்களும் ஹதீஸ்களும் உள்ளன. ﴾وَيَوْمَ يُرْجَعُونَ إِلَيْهِ﴿\n\r\n\n\r\n(அவர்கள் அவனிடம் திரும்பக் கொண்டுவரப்படும் நாளில்,) என்பது, அனைத்துப் படைப்புகளும் அல்லாஹ்விடம் திரும்பக் கொண்டுவரப்படும் மறுமை நாளைக் குறிக்கிறது. ﴾فَيُنَبِّئُهُمْ بِمَا عَمِلُواْ﴿\n\r\n\n\r\n(பிறகு அவர்கள் செய்தவற்றை அவன் அவர்களுக்கு அறிவிப்பான்.) அதாவது, அவர்கள் இவ்வுலக வாழ்வில் செய்த சிறியது, பெரியது, முக்கியமானது, அற்பமானது என அனைத்தையும் அவன் அவர்களுக்கு எடுத்துரைப்பான். அல்லாஹ் கூறுவது போல்: ﴾يُنَبَّأُ الإِنسَـنُ يَوْمَئِذِ بِمَا قَدَّمَ وَأَخَّرَ ﴿\n\r\n\n\r\n(அந்நாளில் மனிதன் எதை முற்படுத்தினான், எதைப் பின்னுக்குத் தள்ளினான் என்பது குறித்து அவனுக்கு அறிவிக்கப்படும்.) 75:13 ﴾وَوُضِعَ الْكِتَـبُ فَتَرَى الْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَا وَيْلَتَنَا مَا لِهَـذَا الْكِتَـبِ لاَ يُغَادِرُ صَغِيرَةً وَلاَ كَبِيرَةً إِلاَّ أَحْصَاهَا وَوَجَدُواْ مَا عَمِلُواْ حَاضِرًا وَلاَ يَظْلِمُ رَبُّكَ أَحَدًا ﴿\n\r\n\n\r\n(அங்கு பதிவேடு வைக்கப்படும். அப்போது குற்றவாளிகள் அதில் உள்ளவற்றைக் கண்டு அச்சமடைவதை நீர் காண்பீர். \"எங்களுக்கு ஏற்பட்ட கேட்டையே! இது என்ன புத்தகம்? சிறியதையோ பெரியதையோ விட்டுவைக்காமல் அனைத்தையும் கணக்கிட்டுப் பதிவு செய்துள்ளதே!\" என்று அவர்கள் கூறுவார்கள். மேலும் அவர்கள் செய்தவை அனைத்தும் தங்களுக்கு முன்னால் வைக்கப்பட்டிருப்பதைக் காண்பார்கள். உமது இறைவன் எவருக்கும் அநீதி இழைக்கமாட்டான்.) 18:49 அல்லாஹ் இங்கே கூறுகிறான்: ﴾وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُمْ بِمَا عَمِلُواْ وَاللَّهُ بِكُلِّ شَىْءٍ عَلِيمُ﴿\n\r\n\n\r\n(அவர்கள் அவனிடம் திரும்பக் கொண்டுவரப்படும் நாளில், அவர்கள் செய்தவற்றை அவன் அவர்களுக்கு அறிவிப்பான். மேலும் அல்லாஹ் அனைத்துப் பொருட்களையும் மிக அறிந்தவன்.)\n\r\n\n\r\nஅகிலங்களின் இறைவனாகிய அல்லாஹ்வுக்கே எல்லாப் புகழும். பரிபூரண நிலையை அடைய எங்களுக்கு உதவுமாறு அவனிடம் வேண்டுகிறோம். ஸூரத்துந் நூர் தஃப்ஸீர் இத்துடன் நிறைவடைந்தது. அல்லாஹ்வுக்கே புகழும் நன்றியும் உரித்தாகட்டும்."}}};})(self);
